window.ESS={"checked":"2026-10-08","cats":[{"k":"grocery","en":"Groceries","zh":"买菜超市","c":"#008300","cd":"#008300","g":"cart","gc":"#fff","gcd":"#fff"},{"k":"campus","en":"Campus services","zh":"学校办事","c":"#2a78d6","cd":"#3987e5","g":"columns","gc":"#fff","gcd":"#fff"},{"k":"health","en":"Health","zh":"医疗健康","c":"#e34948","cd":"#e66767","g":"cross","gc":"#fff","gcd":"#fff"},{"k":"fitness","en":"Fitness","zh":"运动健身","c":"#eb6834","cd":"#d95926","g":"dumbbell","gc":"#fff","gcd":"#fff"},{"k":"study","en":"Study & tech","zh":"学习与电脑","c":"#4a3aa7","cd":"#9085e9","g":"book","gc":"#fff","gcd":"#fff"},{"k":"shop","en":"Shopping","zh":"日用购物","c":"#eda100","cd":"#c98500","g":"bag","gc":"#1a1a19","gcd":"#1a1a19"},{"k":"transport","en":"Getting around","zh":"交通出行","c":"#1baf7a","cd":"#199e70","g":"bus","gc":"#fff","gcd":"#fff"},{"k":"money","en":"Banks & mail","zh":"银行与寄件","c":"#52514e","cd":"#c3c2b7","g":"dollar","gc":"#fff","gcd":"#1a1a19"},{"k":"help","en":"IDs, safety & help","zh":"证件、安全与求助","c":"#0b0b0b","cd":"#ffffff","g":"shield","gc":"#fff","gcd":"#1a1a19"},{"k":"fun","en":"Free time","zh":"休闲去处","c":"#e87ba4","cd":"#d55181","g":"star","gc":"#1a1a19","gcd":"#fff"}],"places":[{"id":"aldi-lien-road","cat":"grocery","n":{"en":"ALDI (Lien Road)","zh":"ALDI 奥乐齐超市（Lien Road 店）"},"kind":{"en":"Discount grocery","zh":"折扣超市"},"addr":"3925 Lien Rd, Madison, WI 53704","phone":"(855) 955-2534","web":"https://info.aldi.us/stores/l/wi/madison/3925-lien-road/f730","h":{"Mo":[[540,1200]],"Tu":[[540,1200]],"We":[[540,1200]],"Th":[[540,1200]],"Fr":[[540,1200]],"Sa":[[540,1200]],"Su":[[540,1200]]},"ht":{"en":"Fall 2026: open every day 9 a.m.–8 p.m.","zh":"2026 年秋季：每天 9:00–20:00。"},"sum":{"en":"East-side ALDI discount grocery: mostly ALDI-brand food at low prices. Bring a quarter for the cart and your own bags.","zh":"东边的 ALDI 折扣超市，主要卖自有品牌，价格低。推车要投 25 美分硬币，购物袋自己带。"},"kw":["ALDI","奥乐齐","discount","折扣","cheap","便宜","grocery","超市","quarter","硬币","curbside","路边取货","Lien Road","East Towne"],"sec":{"about":{"en":["ALDI is a discount grocery chain with small stores and mostly its own private-label brands. It sells fresh meat and seafood, produce, ready-made deli items, baked goods, frozen food and some home goods. Madison has two ALDI stores: this one on Lien Road on the east side, and one at 8222 Watts Road on the west side."],"zh":["ALDI 是一家折扣连锁超市，店面不大，大部分是自有品牌。卖新鲜肉类海鲜、蔬果、现成熟食、烘焙、冷冻食品和部分家居用品。麦迪逊有两家 ALDI：东边 Lien Road 这家，和西边 8222 Watts Road 那家。"]},"offers":{"en":["Fresh meat and seafood, produce, deli items, baked goods and frozen food","ALDI Finds: limited-time products that change every week","Beer and wine","Online orders for curbside pickup or home delivery","Parking lot"],"zh":["新鲜肉类海鲜、蔬果、熟食、烘焙和冷冻食品","ALDI Finds：每周换的限时商品","啤酒和葡萄酒","网上下单，路边取货或送货上门","有停车场"]},"howto":{"en":["Bring a quarter (25-cent coin) to unlock a shopping cart. When you return the cart and lock it, you get the quarter back.","Bring your own bags. ALDI has no plastic bags; if you forget yours, you can buy cloth bags in the store.","Payment: Visa, Mastercard, American Express, Discover, Apple Pay, Google Pay, other contactless payments, and cash."],"zh":["准备一个 25 美分硬币（quarter）开推车，推车还回去锁好，硬币会退出来。","自己带购物袋。ALDI 没有塑料袋，忘带的话店里可以买布袋。","付款：Visa、Mastercard、American Express、Discover、Apple Pay、Google Pay 等感应支付，以及现金。"]},"cost":{"en":["The cart costs nothing: the quarter is a deposit you get back.","Online delivery orders need no quarter; you pick a delivery window and pay online.","The weekly ad lists ALDI Finds and Price Drops on regular items."],"zh":["推车不花钱，25 美分只是押金，还车就退。","网上下单送货不用硬币，选好送货时间段，在网上付款。","每周广告会列出 ALDI Finds 和常规商品的降价（Price Drops）。"]},"tips":{"en":["ALDI Finds are sold for a limited time only, so buy them when you see them.","The store page lists a toll-free 855 number, not a local 608 number."],"zh":["ALDI Finds 只限时卖，看到想要的就买。","店铺页面上留的是 855 开头的免费客服号，不是 608 本地号码。"]},"intl":{"en":["All major card brands and phone wallets are accepted, so a foreign Visa or Mastercard usually works here."],"zh":["各大卡组织和手机支付都收，国外的 Visa 或 Mastercard 一般能用。"]}},"src":[["ALDI 3925 Lien Road - store page","https://info.aldi.us/stores/l/wi/madison/3925-lien-road/f730"],["ALDI - stores in Madison, WI","https://info.aldi.us/stores/l/wi/madison"],["ALDI - About ALDI / in-store experience (cart system)","https://www.aldi.us/about-aldi/in-store-experience"],["CNN via WRDW - Aldi eliminates plastic shopping bags in all US stores (Jan 2024)","https://www.wrdw.com/2024/01/17/aldi-eliminates-plastic-shopping-bags-all-2300-us-grocery-stores"]],"unv":[],"chk":"2026-10-08","lat":43.121013,"lng":-89.317575,"stops":[["E Washington at Mendota",363,"60"],["Thierer-Portage",363,"A"],["Mendota",369,"A"]]},{"id":"asian-midway-foods","cat":"grocery","n":{"en":"Asian Midway Foods","zh":"Asian Midway Foods 亚洲超市"},"kind":{"en":"Asian grocery","zh":"亚洲超市"},"addr":"301 S Park St, Madison, WI 53715","phone":"(608) 255-5864","web":"","h":{"Mo":[[540,1200]],"Tu":[[540,1200]],"We":[[540,1200]],"Th":[[540,1200]],"Fr":[[540,1200]],"Sa":[[540,1200]],"Su":[[540,1200]]},"ht":{"en":"Fall 2026: Apple Maps and Yahoo list every day 9 a.m.–8 p.m. Older listings show a 9 p.m. close Monday–Saturday, so call to confirm before an evening trip.","zh":"2026 年秋季：Apple Maps 和 Yahoo 写的是每天 9:00–20:00。一些较旧的网上信息写周一到周六开到 21:00，晚上去之前最好打电话确认。"},"sum":{"en":"Asian grocery on South Park Street: Chinese and Korean staples, noodles, sauces, dumplings, fresh produce and seafood.","zh":"S Park St 上的亚洲超市，中餐和韩餐食材、面条酱料、饺子、蔬菜和海鲜都有。"},"kw":["Asian Midway","Midway Asian Foods","亚洲超市","中国超市","韩国食品","Chinese grocery","Asian grocery","dumplings","饺子","noodles","面条","seafood","海鲜","Park Street"],"sec":{"about":{"en":["Asian Midway Foods is an Asian supermarket on South Park Street. Customer reviews describe a broad range of Chinese and Korean ingredients, including noodles, sauces, spices and rice, plus fresh produce, seafood and a large dumpling selection.","A 2015 Badger Herald review praised the seafood (fresh fish, clams, live lobsters) and noted dried shredded squid on the shelf next to Doritos. Shoppers also say it stocks normal grocery items, so one trip can cover a lot, and that variety outside Chinese food is thinner."],"zh":["Asian Midway Foods 是 S Park St 上的亚洲超市。顾客评价里提到中餐和韩餐食材很全：面条、酱料、香料、大米，另外有新鲜蔬果、海鲜，饺子的种类也多。","2015 年 Badger Herald 的评测夸过它的海鲜（鲜鱼、蛤蜊、活龙虾），还提到鱿鱼丝和多力多滋 (Doritos) 摆在相邻的货架。顾客还说店里也有普通的美国杂货，一趟能买不少东西，但中餐以外的品类相对少。"]},"offers":{"en":["Chinese and Korean pantry staples: noodles, sauces, spices, rice","Dumplings (reviews mention a large selection)","Fresh produce","Seafood: a 2015 review lists fresh fish, clams and live lobsters","Some everyday American grocery items, according to shoppers"],"zh":["中餐和韩餐常备食材：面条、酱料、香料、大米","饺子（评价提到种类多）","新鲜蔬果","海鲜：2015 年的评测提到鲜鱼、蛤蜊和活龙虾","按顾客的说法，也有一些美国日常杂货"]},"howto":{"en":["Payment: listings show credit and debit cards, Apple Pay and other tap-to-pay, and SNAP/EBT.","Parking: listings show a free parking lot and free street parking.","No official website found. Call (608) 255-5864 for hours or to ask about an item."],"zh":["付款：网上信息写的是信用卡、借记卡、Apple Pay 等感应支付，以及 SNAP/EBT。","停车：网上信息写的是有免费停车场，也可以免费路边停车。","没找到官方网站。想问营业时间或有没有某样东西，可以打 (608) 255-5864。"]},"cost":{"en":["Reviews say spices are especially cheap and many prices are low, while a few shoppers found some items pricier than at other local stores.","The Too Good To Go app lists a $21 surprise bag from this store for $6.99 (snacks, produce or other grocery items, contents not guaranteed). It showed \"Nothing today\" on Oct 8, 2026, so availability varies."],"zh":["评价说香料特别便宜、不少东西价格低，也有顾客觉得有些东西比本地别的店贵。","Too Good To Go App 上这家店有一个标价 $21 的惊喜袋 (surprise bag)，卖 $6.99（零食、蔬果或其他杂货，内容不保证）。2026 年 10 月 8 日查看时显示“今天没有”，所以不一定每天都有。"]},"tips":{"en":["Reviews mention narrow, crowded aisles and stock that varies, so allow extra time.","Listings disagree on the closing time (8 p.m. or 9 p.m. Monday–Saturday). Call before an evening trip.","Reviews say variety outside Chinese products is limited; look elsewhere for Southeast Asian specialties."],"zh":["评价提到过道窄、有时挤，货架上的东西也不一定每次都有，多留点时间。","不同网站写的关门时间不一样（周一到周六 20:00 或 21:00），晚上去之前先打电话。","评价说中餐以外的品类有限，想买东南亚的特色食材要去别家看看。"]},"intl":{"en":["Apple Pay and other contactless payments are listed, which helps if a foreign card fails at the terminal."],"zh":["网上信息写了 Apple Pay 等感应支付，国外的卡刷不了时可以用手机支付试试。"]}},"src":[["UW Bridge to the Chemistry Doctorate - Ethnic Grocery Stores in the Madison Area","https://bridge.chem.wisc.edu/local-info-2/ethnic-grocery-stores-in-the-madison-area/"],["Asian Midway Foods - Apple Maps","https://maps.apple.com/place?place-id=I3B6D6F6384F4898"],["Asian Midway Foods - Yahoo Local","https://local.yahoo.com/info-16792208-asian-midway-foods-madison/"],["Asian Midway Food - Yellow Pages","https://www.yellowpages.com/madison-wi/mip/asian-midway-foods-1461604"],["Asian Midway Foods - Wheree listing","https://asian-midway-foods.wheree.com/"],["The Badger Herald (2015) - Fresh perspective: grocery alternatives to Fresh Madison Market","https://badgerherald.com/banter/2015/09/25/fresh-perspective-grocery-alternatives-to-fresh-madison-market/"],["Asian Midway Foods surprise bag - Too Good To Go","https://www.toogoodtogo.com/en-us/find/madison/asianmidwayfoods/groceries/21surprisebagpleasereaddescriptionbeforepurchasing-159181452714326721"]],"unv":["hours"],"chk":"2026-10-08","lat":43.063834,"lng":-89.400281,"stops":[["S Park at W Washington",27,"B 63 64"],["S Park at Meriter",151,"B 63 64"],["Drake at S Mills",383,"O"]]},{"id":"capitol-centre-market","cat":"grocery","n":{"en":"Capitol Centre Market","zh":"Capitol Centre Market 超市"},"kind":{"en":"Neighborhood grocery","zh":"社区超市"},"addr":"111 N Broom St, Madison, WI 53703","phone":"(608) 255-2616","web":"https://www.capcentremarket.com/","h":{"Mo":[[420,1440]],"Tu":[[420,1440]],"We":[[420,1440]],"Th":[[420,1440]],"Fr":[[420,1440]],"Sa":[[420,1440]],"Su":[[420,1440]]},"ht":{"en":"Fall 2026: open every day 7 a.m.–midnight.","zh":"2026 年秋季：每天 7:00–24:00。"},"sum":{"en":"Locally owned downtown grocery near the Capitol Square with a deli, hot food and sushi; open every day until midnight.","zh":"Capitol 广场附近的本地超市，有熟食、热菜和寿司，每天开到午夜。"},"kw":["grocery","超市","买菜","downtown","市中心","late night","营业到深夜","deli","熟食","sushi","寿司","delivery","送货"],"sec":{"about":{"en":["Capitol Centre Market is a locally owned grocery store downtown, near the Capitol Square, in business since January 1983. A 2018 expansion added a new deli, a larger hot food section, an on-site sushi bar, a bigger produce department and self-checkouts."],"zh":["Capitol Centre Market 是市中心一家本地人开的超市，在 Capitol 广场附近，1983 年 1 月开业。2018 年扩建后新增了熟食柜台、更大的热菜区、店内寿司吧、更大的蔬果区和自助收银。"]},"offers":{"en":["Produce, meat, seafood, dairy, frozen food and bakery items","Deli with hot food, rotisserie chicken, salads and sandwiches","Sushi made at the on-site sushi bar","Babcock Dairy ice cream and cheese, made by UW–Madison's own dairy plant","A walk-in beer cooler","Online grocery ordering with delivery"],"zh":["蔬果、肉类、海鲜、奶制品、冷冻食品和烘焙","熟食柜台：热菜、烤鸡、沙拉、三明治","店内寿司吧现做的寿司","Babcock Dairy（UW–Madison 自己的乳品厂）的冰淇淋和奶酪","可以走进去挑的啤酒冷柜","网上下单送货"]},"howto":{"en":["Order online on the store website for delivery. Online prices are the same as in the store.","No car? Shop in person, leave your bags at the store, and they deliver them to you for free.","Self-checkouts are available."],"zh":["在超市官网下单可以送货，网上价格和店里一样。","没车的话，可以在店里买完把东西留下，超市免费给你送到家。","店里有自助收银。"]},"cost":{"en":["Online orders have no extra markup over shelf prices.","Delivery is free when you shop in the store and leave your purchases for delivery.","The website has a weekly ad and digital coupons."],"zh":["网上下单不加价，和货架价格一样。","在店里买完留下让超市送，送货免费。","官网有每周特价广告和电子优惠券。"]},"tips":{"en":["Open until midnight every day (fall 2026), so it works for a late grocery run after evening classes.","You can buy Babcock ice cream here without a trip to the Babcock Dairy Store on campus."],"zh":["每天开到午夜（2026 年秋季），晚课下课后去买菜也来得及。","想吃 Babcock 冰淇淋不用专门跑校内的 Babcock Dairy Store，这里就有。"]}},"src":[["Capitol Centre Market - store website (hours, address, departments)","https://www.capcentremarket.com/"],["Capitol Centre Market - Our Story","https://shop.capcentremarket.com/our-story"],["UW Babcock Dairy Store - where to buy: Capitol Centre Market","https://babcockdairystore.wisc.edu/locations/capitol-centre-market"]],"unv":[],"chk":"2026-10-08","lat":43.072763,"lng":-89.390168,"stops":[["N Broom at W Dayton",81,"C 38 65 81"],["W Johnson at N Broom",138,"D R 28"],["N Broom at W Washington",156,"C 38 65 81"]]},{"id":"costco-middleton","cat":"grocery","n":{"en":"Costco Middleton Warehouse","zh":"Costco 开市客（Middleton 店）"},"kind":{"en":"Membership warehouse club","zh":"会员制仓储超市"},"addr":"2150 Deming Way, Middleton, WI 53562","phone":"(608) 824-3950","web":"https://www.costco.com/warehouse-locations/middleton-wi-1020.html","h":{"Mo":[[600,1230]],"Tu":[[600,1230]],"We":[[600,1230]],"Th":[[600,1230]],"Fr":[[600,1230]],"Sa":[[570,1140]],"Su":[[600,1080]]},"ht":{"en":"Fall 2026, Gold Star members: Mon–Fri 10 a.m.–8:30 p.m., Sat 9:30 a.m.–7 p.m., Sun 10 a.m.–6 p.m. Executive members may enter from 9 a.m. every day. Pharmacy: Mon–Fri 9 a.m.–7 p.m., Sat 9 a.m.–6 p.m., Sun closed. Gas station: Mon–Fri 6 a.m.–10 p.m., Sat 6 a.m.–8:30 p.m., Sun 6 a.m.–7:30 p.m.","zh":"2026 年秋季，普通（Gold Star）会员：周一到周五 10:00–20:30，周六 9:30–19:00，周日 10:00–18:00；Executive 会员每天 9:00 就能进。药房：周一到周五 9:00–19:00，周六 9:00–18:00，周日关门。加油站：周一到周五 6:00–22:00，周六 6:00–20:30，周日 6:00–19:30。"},"sum":{"en":"Membership warehouse in Middleton for bulk groceries, meat, produce and cheap gas. Membership $65/yr; a passport works as ID.","zh":"Middleton 的会员制仓储超市，大包装食品、肉、蔬果和便宜汽油。会员 $65/年，护照可办卡。"},"kw":["Costco","开市客","好市多","bulk","大包装","membership","会员","warehouse","仓储超市","pharmacy","药房","gas","加油","Middleton"],"sec":{"about":{"en":["Costco is a membership warehouse club: you pay a yearly fee and buy groceries and household goods in large packages. The Middleton warehouse, open since 2008, has fresh meat, produce, a bakery, a deli and rotisserie chicken, plus a pharmacy, optical department, hearing aid center, tire center, food court and gas station."],"zh":["Costco 是会员制仓储超市：每年交会员费，然后买大包装的食品和日用品。Middleton 这家 2008 年开业，有新鲜肉类、蔬果、面包房、熟食和烤鸡，另外有药房、眼镜部、助听器中心、轮胎中心、美食区和加油站。"]},"offers":{"en":["Bulk groceries: fresh meat, fresh produce, bakery and deli","Rotisserie chicken","Gas station (pumps take Visa, debit cards and Costco Shop Cards)","Pharmacy, phone (608) 824-3959","Optical department and hearing aid center","Food court, phone (608) 824-3965","Same-day delivery through SameDay.Costco.com, powered by Instacart"],"zh":["大包装食品：新鲜肉类、蔬果、面包和熟食","烤鸡","加油站（加油机收 Visa、借记卡和 Costco Shop Card）","药房，电话 (608) 824-3959","眼镜部和助听器中心","美食区（food court），电话 (608) 824-3965","通过 SameDay.Costco.com（Instacart 承运）当天送货"]},"howto":{"en":["Sign up at the membership counter or on costco.com. You need a valid photo ID: a US or Canadian government ID, or any valid passport.","Scan your membership card at the entrance and show it at the register. Photos or copies of the card are not accepted.","Members can bring up to two guests, but only members can pay for items."],"zh":["在会员柜台或 costco.com 办卡，需要有效带照片证件：美国或加拿大政府证件，或者任何有效护照都行。","进门要扫会员卡，结账时出示会员卡，卡的照片或复印件不算。","会员可以带最多两位客人进店，但只有会员本人能付款买东西。"]},"cost":{"en":["Gold Star membership: $65 a year. Executive: $130 a year (adds a 2% annual reward). Both plus sales tax, and both include a second card for one household member aged 16+ living at the same address.","Non-members can still use the pharmacy, since prescription drugs may be bought by non-members where the law requires it. Anyone can spend a Costco Shop Card (gift card), but only members can buy or reload one.","Non-members can buy some items on costco.com but pay 5% more than members."],"zh":["Gold Star 普通会员每年 $65，Executive 会员每年 $130（多 2% 年度返现），都另加销售税，都包含一张给同住址、16 岁以上家庭成员的副卡。","非会员也能用药房：法律要求的地方，处方药非会员也可以买。任何人都能用 Costco Shop Card（礼品卡）消费，但只有会员能买卡或充值。","非会员可以在 costco.com 买部分商品，但比会员贵 5%。"]},"tips":{"en":["The pharmacy may close for 30 minutes between 1:30 and 2:30 p.m. when only one pharmacist is on duty.","Executive members get in an hour earlier on weekdays and Sundays, and half an hour earlier on Saturdays."],"zh":["只有一位药剂师值班时，药房可能在 13:30–14:30 之间关 30 分钟。","Executive 会员工作日和周日能早 1 小时进，周六早半小时。"]},"intl":{"en":["A passport is accepted as ID to sign up; you do not need a US ID.","In the warehouse the only credit cards accepted are Visa; debit/ATM cards, cash and checks also work. Costco.com also takes Mastercard."],"zh":["办卡用护照就行，不需要美国证件。","店里信用卡只收 Visa，借记卡、现金和支票也可以；costco.com 网上还收 Mastercard。"]}},"src":[["Costco - Middleton Warehouse page","https://www.costco.com/warehouse-locations/middleton-wi-1020.html"],["Costco - Member Privileges & Conditions","https://www.costco.com/member-privileges-conditions.html"],["Costco - Join Costco (membership fees)","https://www.costco.com/join-costco.html"]],"unv":[],"chk":"2026-10-08","lat":43.099468,"lng":-89.52303,"stops":[["Deming at Murphy",163,"F"],["Murphy at Eagle",375,"F"],["Deming at Terrace",447,"F"]]},{"id":"dane-county-farmers-market","cat":"grocery","n":{"en":"Dane County Farmers' Market","zh":"Dane County Farmers' Market 农夫市集"},"kind":{"en":"Farmers' market","zh":"农夫市集"},"addr":"2 E Main St, Madison, WI 53702","phone":"(608) 455-1999","web":"https://dcfm.org/markets/saturday-on-the-square","h":null,"ht":{"en":"Fall 2026: Saturday on the Square, Sat 6:15 a.m.–1:45 p.m. through Nov 14. Wednesday Market, Wed 8:30 a.m.–1:15 p.m. through Nov 4. Then the indoor Holiday Market at Monona Terrace, Sat 7:30 a.m.–noon on Nov 21, Dec 5 (until 1 p.m.), Dec 12 and Dec 19. Winter Market at Garver Feed Mill, Sat 8 a.m.–noon, Jan 2–Apr 3, 2027.","zh":"2026 年秋季：Saturday on the Square 每周六 6:15–13:45，到 11 月 14 日；周三市集每周三 8:30–13:15，到 11 月 4 日。之后是 Monona Terrace 的室内假日市集（周六 7:30–12:00，日期 11/21、12/5、12/12、12/19，12/5 开到 13:00），以及 Garver Feed Mill 的冬季市集（周六 8:00–12:00，2027 年 1/2–4/3）。"},"sum":{"en":"Producer-only farmers' market around the Capitol: Saturdays to Nov 14, Wednesdays to Nov 4, then indoor holiday and winter markets.","zh":"绕着州议会大厦的周六农夫市集（到 11/14）和周三市集（到 11/4），之后转到室内的假日和冬季市集。"},"kw":["Dane County Farmers' Market","DCFM","farmers market","农夫市集","菜市场","Capitol Square","Saturday market","周六市集","Wednesday market","winter market","Garver Feed Mill","Monona Terrace","holiday market","cheese","奶酪","produce","蔬菜"],"sec":{"about":{"en":["The Dane County Farmers' Market is a producer-only market: all items are produced by the members behind the tables, and resale is not allowed. The market says it is reported to be the largest producer-only farmers' market in the country. About 220 vendors sell across the year, and over 130 members attend every Saturday.","The big one is Saturday on the Square, on the sidewalks around the Wisconsin State Capitol. It is really four events at once: the farmers' market, information and political tables inside the Capitol grounds, arts and crafts vendors and food carts across the street, and street musicians.","The market runs all year in four parts: Saturday on the Square (Apr 11–Nov 14, 2026), a smaller Wednesday market in front of the City-County Building (Apr 22–Nov 4), a Holiday Market at Monona Terrace (four Saturdays, Nov 21–Dec 19) and a Winter Market at Garver Feed Mill (Jan 2–Apr 3, 2027)."],"zh":["Dane County Farmers' Market 是“生产者直销”的市集：摊位后面的人就是生产者本人，不许转卖。市集自称据报道是全美最大的生产者直销农夫市集。全年约有 220 家摊贩，每个周六有 130 多家到场。","最大的是 Saturday on the Square，沿着威斯康星州议会大厦 (Wisconsin State Capitol) 四周的人行道摆开。周六其实是四件事同时发生：农夫市集；议会草坪里的公益、政治和信息摊位；街对面的手工艺摊和小吃车；还有街头艺人。","市集全年分四段：周六广场市集（2026 年 4/11–11/14）、City-County Building 门口较小的周三市集（4/22–11/4）、Monona Terrace 的假日市集（11 月 21 日到 12 月 19 日的四个周六）、Garver Feed Mill 的冬季市集（2027 年 1/2–4/3）。"]},"offers":{"en":["Fruit and vegetables, meat, fish, dairy products, cheese, bakery items, pickles, jams, flowers and plants, sold by the producers","Saturday on the Square: Saturdays, Apr 11–Nov 14, 2026, 6:15 a.m.–1:45 p.m., on the Capitol Square","Wednesday Market: Wednesdays, Apr 22–Nov 4, 8:30 a.m.–1:15 p.m., on the 200 block of Martin Luther King Jr. Blvd. in front of the City-County Building","Holiday Market at Monona Terrace (1 John Nolen Dr): Saturdays Nov 21, Dec 5, Dec 12 and Dec 19, 7:30 a.m.–noon (until 1 p.m. on Dec 5)","Winter Market at Garver Feed Mill (3241 Garver Green): Saturdays, Jan 2–Apr 3, 2027, 8 a.m.–noon","On Saturdays, also information tables inside the Capitol grounds, arts and crafts vendors and food carts across the street, and street musicians"],"zh":["水果蔬菜、肉、鱼、奶制品、奶酪、烘焙、腌菜、果酱、鲜花和植物，都由生产者自己卖","Saturday on the Square：2026 年 4/11–11/14 每周六 6:15–13:45，在州议会广场 (Capitol Square)","周三市集 (Wednesday Market)：4/22–11/4 每周三 8:30–13:15，在 Martin Luther King Jr. Blvd. 200 号街区、City-County Building 门口","假日市集 (Holiday Market)：Monona Terrace (1 John Nolen Dr)，11/21、12/5、12/12、12/19 周六 7:30–12:00（12/5 开到 13:00）","冬季市集 (Winter Market)：Garver Feed Mill (3241 Garver Green)，2027 年 1/2–4/3 每周六 8:00–12:00","周六另有议会草坪里的信息摊位、街对面的手工艺摊和小吃车，以及街头艺人"]},"howto":{"en":["Saturdays: walk the sidewalks around the Capitol. The Info Booth (look for the green tent) is at the top of State Street, at W Mifflin St and N Carroll St. On Wednesdays it is across from the bottom of the stairs to the Madison Municipal Building.","FoodShare/SNAP: take your Quest (EBT) card to the Info Booth, choose how much to withdraw and get market dollars to spend with the vendors.","Without a car: Madison Metro serves the Capitol Square, Madison BCycle has stations downtown, and bike parking around the Square is free.","Questions on market day: call Market Management at (608) 455-1999."],"zh":["周六：沿着议会大厦四周的人行道逛。信息亭 (Info Booth，找绿色帐篷) 在 State Street 顶端，W Mifflin St 和 N Carroll St 路口。周三的信息亭在 Madison Municipal Building 台阶下的对面。","FoodShare/SNAP：带着 Quest (EBT) 卡去信息亭，想取多少取多少，换成市集代币 (market dollars)，在摊位上花。","没车也能去：Madison Metro 公交到 Capitol Square，市中心有 BCycle 共享单车站，广场四周的自行车停车位免费。","市集当天有问题，可以打市集管理处电话 (608) 455-1999。"]},"cost":{"en":["Cash works at every vendor; only some take credit cards, PayPal or Venmo.","Free: bike parking around the Square, and 100+ on-site parking spots at Garver Feed Mill (they fill up quickly). Street parking near the Square is mostly metered.","SNAP/FoodShare shoppers get a Double Dollars match: dollar for dollar, up to $20 per market day, on fruits and vegetables only. It began June 1, 2026. The 2025 season ended Oct 31, so ask at the Info Booth whether it is still running."],"zh":["每个摊位都收现金；只有一部分摊位收信用卡、PayPal 或 Venmo。","免费的有：广场四周的自行车停车位，以及 Garver Feed Mill 的 100 多个停车位（很快会满）。广场附近的路边车位大多是收费咪表。","SNAP/FoodShare 用户有 Double Dollars 匹配：一比一，每个市集日最多 $20，只能买水果蔬菜。2026 年 6 月 1 日开始；2025 年的活动 10 月 31 日结束，所以去之前问一下信息亭现在还有没有。"]},"tips":{"en":["Go early. Vendors are producers with limited harvests and can sell out before closing; early arrivals get first choice.","There is no vendor map, and the lineup is only known that morning. Walk the whole Square or call (608) 455-1999.","It runs rain or shine and closes only for severe weather such as thunderstorms or tornadoes; closures are posted on the market's social media.","No pets on the Square at the Saturday Market; service animals are allowed.","Bring a backpack or bag for what you buy."],"zh":["早点去。摊主都是生产者，产量有限，可能没到收摊就卖完；早到的人先挑。","没有摊位地图，当天早上才知道哪些摊来。绕广场走一圈，或者打 (608) 455-1999 问。","刮风下雨照开，只有雷暴、龙卷风这类恶劣天气才会关；是否停办会发在市集的社交媒体上。","周六广场上不让带宠物（服务犬可以）。","带个背包或购物袋装东西。"]},"intl":{"en":["Bring some cash: every vendor takes it, while cards, PayPal and Venmo work only at some stalls."],"zh":["带点现金：每个摊位都收现金，信用卡、PayPal、Venmo 只有部分摊位收。"]}},"src":[["Dane County Farmers' Market - Saturday on the Square","https://dcfm.org/markets/saturday-on-the-square"],["Dane County Farmers' Market - Wednesday Market","https://dcfm.org/markets/wednesday-market"],["Dane County Farmers' Market - Holiday Farmers' Market","https://dcfm.org/markets/holiday-market"],["Dane County Farmers' Market - Winter Farmers' Market","https://dcfm.org/markets/late-winter-market"],["Dane County Farmers' Market - FAQs","https://dcfm.org/faqs"],["Dane County Farmers' Market - About the Farmers' Market","https://dcfm.org/about"],["Dane County Farmers' Market - SNAP / EBT / FoodShare","https://dcfm.org/foodshare-ebt"],["City of Madison - Farmers' Markets","https://www.cityofmadison.com/live-work/neighborhoods/farmers-markets"],["Wisconsin Legislature - Visit the State Capitol","https://legis.wisconsin.gov/about/visit"]],"unv":[],"chk":"2026-10-08","lat":43.074692,"lng":-89.384166,"stops":[["W Main at M L K Junior",135,"E R 75"],["Capitol Square",137,"A B F"],["E Mifflin at N Pinckney",154,"E R 75"]]},{"id":"enson-market","cat":"grocery","n":{"en":"Enson Market","zh":"Enson Market 亚洲超市"},"kind":{"en":"Asian grocery","zh":"亚洲超市"},"addr":"3313 University Ave, Madison, WI 53705","phone":"","web":"","h":null,"ht":{"en":"Store hours not confirmed as of October 2026, so check the store or its map listing before a trip. Brothy Bowl, the soup restaurant inside, is listed as open daily 12:30-9 p.m. in a 2026 Madison Magazine roundup.","zh":"截至 2026 年 10 月没能确认超市本身的营业时间，出门前先看地图上的店面信息。店里的麻辣烫店 Brothy Bowl，Madison Magazine 2026 年的报道写的是每天 12:30-21:00。"},"sum":{"en":"Large Asian grocery in the former Whole Foods building on University Ave: produce, meat, seafood, pantry staples, bakery and hot food.","zh":"University Ave 上的大型亚洲超市，蔬果肉类海鲜、调料干货、面包和热食都有。"},"kw":["Enson Market","Enson","Fresh Mart","亚洲超市","中国超市","日本食品","Asian grocery","international grocery","University Ave","bakery","面包","hot food","热食","Brothy Bowl","malatang","麻辣烫"],"sec":{"about":{"en":["Enson Market is an Asian supermarket at 3313 University Ave, in the building where a Fresh Mart and, before that, a Whole Foods once stood. It opened on March 7, 2026, according to In Business Madison.","It is part of the Fresh International Market chain, which has 25 locations nationally and is known for Asian pantry staples, produce and snacks. A Giftly listing for the Madison store describes a large, organized layout with produce, meat, seafood, frozen foods, a bakery and a hot food area."],"zh":["Enson Market 是 University Ave 3313 号的亚洲超市，这栋楼以前先是 Whole Foods，后来是 Fresh Mart。据 In Business Madison 报道，2026 年 3 月 7 日开业。","它属于 Fresh International Market 连锁，全美有 25 家店，主打亚洲常备食材、蔬果和零食。Giftly 上对这家店的介绍说店面大、分区清楚，有蔬果、肉、海鲜、冷冻食品、面包房和热食区。"]},"offers":{"en":["Fresh produce, meat and seafood","Pantry staples and frozen foods, including Chinese and Japanese items (per the Giftly listing)","Bakery section","Hot food area and deli (per the Giftly listing)","Brothy Bowl inside the store: build-your-own malatang soup bowl","Chain website with weekly ads and an app for shopping"],"zh":["新鲜蔬果、肉类和海鲜","常备干货和冷冻食品，包括中国和日本的商品（Giftly 的介绍）","面包房","热食区和熟食（Giftly 的介绍）","店内的 Brothy Bowl：自选食材的麻辣烫","连锁官网有每周促销，也有购物 App"]},"howto":{"en":["Address: 3313 University Ave. Hours, phone, payment and parking were not confirmed (see unverified list), so check a map listing or call the store before the first trip.","Brothy Bowl: pick meats, vegetables and noodles, choose a spice level, and they cook it in a pork bone broth.","The chain site lists weekly ads, deals and an app. Delivery or pickup for the Madison store is not confirmed."],"zh":["地址：University Ave 3313 号。营业时间、电话、付款方式和停车都没能确认（见 unverified 列表），第一次去之前先看地图上的店面信息，或打电话问。","Brothy Bowl：自己选肉、蔬菜和面条，再选辣度，用猪骨汤煮。","连锁官网有每周促销、优惠和 App。Madison 这家店有没有送货或自取，没能确认。"]},"cost":{"en":["No prices confirmed for this store. The chain site lists weekly ads and special offers by email signup; student discounts were not found."],"zh":["这家店的价格没能确认。连锁官网说订阅邮件可收到每周促销和优惠；没有查到学生折扣。"]},"tips":{"en":["Brothy Bowl is listed as opening at 12:30 p.m., so it is not a morning stop.","Some people still call the place Fresh Mart, the store that was there before. Search both names if a map app is out of date.","Store hours and Brothy Bowl hours can differ. Check the store's hours before an evening trip."],"zh":["Brothy Bowl 12:30 才开门，上午去吃不到。","有人还会用以前的店名 Fresh Mart 称呼这里。地图软件信息旧的话，两个名字都搜一下。","超市和 Brothy Bowl 的营业时间可能不一样，晚上去之前先确认。"]},"intl":{"en":["Brothy Bowl serves malatang, a Sichuan street food, which is a familiar option for Chinese students.","The Giftly listing says the shelves include Chinese and Japanese products. It does not list Korean or Southeast Asian items, so check before relying on them."],"zh":["Brothy Bowl 卖麻辣烫，是四川的街头小吃，中国同学会比较熟悉。","Giftly 的介绍说货架上有中国和日本商品，没提到韩国和东南亚的商品，需要这些的话先确认。"]}},"src":[["In Business Madison (Mar 9, 2026) - Enson Market now open on University","https://www.ibmadison.com/business-report/enson-market-now-open-on-university/article_d5b25219-a05f-497d-a989-90848abac291.html"],["Cap Times - Polish food, a new Asian market and apocalyptic fiction","https://captimes.com/food-drink/polish-food-a-new-asian-market-and-apocalyptic-fiction/article_19a224c4-6c5a-4644-b820-cd256df618a0.html"],["Madison Magazine - Now serving (restaurant openings and closings)","https://www.channel3000.com/madison-magazine/the-latest-restaurant-openings-and-closings-in-madison/article_1e7782d2-7d79-49da-903d-5981c4689a0e.html"],["Enson Market - Giftly listing","https://www.giftly.com/gift-card/enson-market-madison"],["Enson Market store finder (Wayback capture, Sep 23, 2026)","https://web.archive.org/web/2026/https://www.ensonmarket.com/store-finder/"]],"unv":["hours","phone"],"chk":"2026-10-08","lat":43.074965,"lng":-89.444411,"stops":[["Shorewood",83,"A F"],["Shorewood at Locust",138,"63"],["University at Blackhawk",153,"R 28 38"]]},{"id":"festival-foods-madison","cat":"grocery","n":{"en":"Festival Foods (Madison)","zh":"Festival Foods 超市（E Washington Ave 店）"},"kind":{"en":"Supermarket","zh":"超市"},"addr":"810 E Washington Ave, Madison, WI 53703","phone":"(608) 709-1976","web":"https://www.festfoods.com/stores/madison","h":{"Mo":[[360,1320]],"Tu":[[360,1320]],"We":[[360,1320]],"Th":[[360,1320]],"Fr":[[360,1320]],"Sa":[[360,1320]],"Su":[[360,1320]]},"ht":{"en":"Fall 2026: open every day 6 a.m.–10 p.m. Wine & spirits section 8 a.m.–9 p.m. daily.","zh":"2026 年秋季：每天 6:00–22:00；酒类区每天 8:00–21:00。"},"sum":{"en":"Big Wisconsin-owned supermarket on E Washington Ave with hot and salad bars, curbside pickup, and Kwik Trip gas rewards.","zh":"E Washington Ave 上的威州本土大超市，有热菜吧、沙拉吧，可网购自取，购物攒油费折扣。"},"kw":["Festival Foods","grocery","超市","supermarket","hot bar","热菜","salad bar","沙拉","curbside","路边取货","Instacart","DoorDash","East Washington"],"sec":{"about":{"en":["Festival Foods is an employee- and family-owned Wisconsin supermarket chain. The Madison store on East Washington Avenue is a full-size supermarket with a hot bar, a salad bar, a deli dining deck, a wine and spirits section and online ordering for pickup."],"zh":["Festival Foods 是威斯康星本土的连锁超市，由员工和家族共同拥有。麦迪逊这家在 East Washington Avenue，是一家正规大超市，有热菜吧、沙拉吧、熟食区就餐平台、酒类区，还能网上下单自取。"]},"offers":{"en":["Hot bar and salad bar, plus the Deli Dining Deck for eating in","Click N Go online shopping for pickup","Wine and spirits section","Amazon Hub Lockers for package pickup","DMV renewals at the store","Cardboard and plastic bag recycling","Self-checkouts"],"zh":["热菜吧和沙拉吧，还有可以坐下吃的 Deli Dining Deck","Click N Go 网购自取","酒类区","Amazon Hub 自提柜，可以取快递","店内可办 DMV 续期","纸箱和塑料袋回收","自助收银"]},"howto":{"en":["Order online through Click N Go for pickup; questions go to the Click N Go line, (608) 304-6352.","For delivery, Festival's site sends you to Instacart or DoorDash.","Gas Rewards: pick up and activate a card in the store, register it online, then scan it at every checkout."],"zh":["网上用 Click N Go 下单自取，有问题打 Click N Go 专线 (608) 304-6352。","要送货的话，Festival 官网会把你转到 Instacart 或 DoorDash 下单。","Gas Rewards（油费积分）：在店里拿卡激活，上网注册，以后每次结账扫卡。"]},"cost":{"en":["Gas Rewards: 1 point per $1 spent, including beer, wine and spirits; 100 points take 10 cents off each gallon of gas at Kwik Trip.","Weekly ad by email every Wednesday; text FEST to 78402 for the mobile club's deals and free items."],"zh":["油费积分：每花 $1 得 1 分（买酒也算），每 100 分在 Kwik Trip 加油每加仑便宜 10 美分。","每周三邮件发特价广告；发短信 FEST 到 78402 加入短信会员，有专属优惠和免费商品。"]},"tips":{"en":["Festival says a new rewards program is coming in fall 2026, so the Gas Rewards details above may change soon.","Gas Rewards points are redeemed at Kwik Trip gas stations, not at Festival."],"zh":["Festival 说 2026 年秋季要换新的会员积分计划，上面油费积分的规则可能很快会变。","油费积分是在 Kwik Trip 加油站用，不是在 Festival 店里用。"]}},"src":[["Festival Foods - Madison store page","https://www.festfoods.com/stores/madison"],["Festival Foods - Delivery","https://www.festfoods.com/delivery"],["Festival Foods - Gas Rewards","https://www.festfoods.com/gas-rewards"]],"unv":[],"chk":"2026-10-08","lat":43.08148,"lng":-89.375034,"stops":[["Paterson",132,"A B"],["E Johnson at N Livingston",302,"D 28"],["E Johnson at N Paterson",347,"D 28"]]},{"id":"fresh-madison-market","cat":"grocery","n":{"en":"Fresh Madison Market","zh":"Fresh Madison Market 超市"},"kind":{"en":"Supermarket","zh":"超市"},"addr":"703 University Ave, Madison, WI 53715","phone":"(608) 287-0000","web":"https://www.freshmadisonmarket.com/","h":{"Mo":[[420,1320]],"Tu":[[420,1320]],"We":[[420,1320]],"Th":[[420,1320]],"Fr":[[420,1320]],"Sa":[[420,1320]],"Su":[[420,1320]]},"ht":{"en":"Fall 2026: open every day 7 a.m.–10 p.m. Deli counter 8 a.m.–6 p.m. daily. Hot bar Mon–Fri 7 a.m.–6 p.m., closed on weekends.","zh":"2026 年秋季：每天 7:00–22:00。熟食柜台每天 8:00–18:00；热菜吧周一到周五 7:00–18:00，周末不开。"},"sum":{"en":"Full grocery store on University Ave with a deli, sushi and a weekday hot bar; open daily 7 a.m.–10 p.m.","zh":"University Ave 上的正规超市，有熟食、寿司和工作日热菜吧，每天 7:00–22:00。"},"kw":["grocery","supermarket","超市","买菜","deli","熟食","sushi","寿司","hot bar","热菜","delivery","送货","University Ave"],"sec":{"about":{"en":["Fresh Madison Market is a full grocery store on University Avenue. Besides produce, meat, seafood and the usual aisles, it has a deli, hand-rolled sushi, salads, sandwiches and paninis, and a hot bar with breakfast, lunch and dinner on weekdays. It also takes online orders for pickup or delivery."],"zh":["Fresh Madison Market 是 University Avenue 上一家正经的大超市。蔬果、肉、海鲜和普通货架都有，另外有熟食柜台、现做寿司、沙拉、三明治和帕尼尼，工作日还有早中晚的热菜吧。也可以网上下单自取或送货。"]},"offers":{"en":["Fresh produce, meat, seafood and a full range of packaged groceries","Deli counter, open 8 a.m.–6 p.m. every day","Hand-rolled sushi, salads, sandwiches and toasted paninis to go","Hot bar with breakfast, lunch and dinner buffets, Mon–Fri 7 a.m.–6 p.m.","Our Family store-brand products, which the store says are priced for budget-conscious shoppers","Online orders for same-day pickup or delivery anywhere in Dane County"],"zh":["新鲜蔬果、肉类、海鲜和各种包装食品","熟食柜台，每天 8:00–18:00","现做寿司、沙拉、三明治和烤帕尼尼，可以直接带走","热菜吧供应早中晚自助，周一到周五 7:00–18:00","超市自有品牌 Our Family，店家说是给想省钱的人准备的","网上下单，当天自取或送货，整个 Dane County 都送"]},"howto":{"en":["Online orders can be placed up to 7 days ahead or for the same day, at least 2 hours before your pickup or delivery slot. Someone has to be home at the delivery time.","Cards accepted: American Express, Discover, Mastercard and Visa. If you pay an online order in cash, have the exact amount.","Text FMMDEALS to 23065 for deal alerts and a free item of the week with a purchase of $40 or more.","Coming by car? The heated indoor parking is free for 30 minutes with a purchase of $25 or more."],"zh":["网上订单最早可提前 7 天下，也可以下当天的，但要比取货或送货时间早至少 2 小时。送货时家里必须有人。","收 American Express、Discover、Mastercard 和 Visa。网上订单如果付现金，要准备好正好的金额。","发短信 FMMDEALS 到 23065，可以收到优惠通知；单次消费满 $40 还能领每周免费商品。","开车来的话，室内暖气停车场消费满 $25 可免费停 30 分钟。"]},"cost":{"en":["Online shopping has a flat $5.95 fee, no minimum order, and the same prices as in the store. The store page also advertises free delivery on orders of $40 or more, so check the fee at checkout.","Sign up for the weekly email newsletter to get the store's coupons."],"zh":["网购收固定 $5.95 服务费，没有最低消费，价格和店里一样。店铺页面又写着满 $40 免运费，结账时看清实际收多少。","订阅每周邮件可以拿到店里的优惠券。"]},"tips":{"en":["The hot bar menu is limited right now (October 2026). Call (608) 287-0000 before going if you want a particular dish.","On weekends the hot bar is closed, but the deli, sushi and salads are still there.","Student groups can book the store's event room: it seats up to 49 people and has a full kitchen and two video screens."],"zh":["热菜吧目前（2026 年 10 月）菜品有限，想吃某道菜先打 (608) 287-0000 问一下。","周末热菜吧不开，但熟食、寿司和沙拉照常有。","学生社团可以订店里的活动室，最多坐 49 人，带完整厨房和两块显示屏。"]}},"src":[["Fresh Madison Market - home page (location, hours, hot bar, deli)","https://www.freshmadisonmarket.com/"],["Fresh Madison Market - Our Store","https://www.freshmadisonmarket.com/our-store"],["Fresh Madison Market - Online Shopping","https://www.freshmadisonmarket.com/online-shopping"]],"unv":[],"chk":"2026-10-08","lat":43.073308,"lng":-89.397612,"stops":[["N Lake at University",37,"80 82"],["East Campus",100,"B"],["N Lake at W Johnson",126,"81"]]},{"id":"hy-vee-whitney-way","cat":"grocery","n":{"en":"Hy-Vee (Whitney Way)","zh":"Hy-Vee 超市（Whitney Way 店）"},"kind":{"en":"Supermarket with pharmacy","zh":"带药房的大超市"},"addr":"675 S Whitney Way, Madison, WI 53711","phone":"(608) 277-6735","web":"https://www.hy-vee.com/stores/detail.aspx?s=1332","h":{"Mo":[[360,1380]],"Tu":[[360,1380]],"We":[[360,1380]],"Th":[[360,1380]],"Fr":[[360,1380]],"Sa":[[360,1380]],"Su":[[360,1380]]},"ht":{"en":"Fall 2026: store open every day 6 a.m.–11 p.m.; closed on Thanksgiving Day. Pharmacy Mon–Fri 9 a.m.–7 p.m., Sat–Sun 10 a.m.–4 p.m. Chinese and Italian counters 10 a.m.–8 p.m.; Starbucks 6 a.m.–7 p.m.; wine and spirits 8 a.m.–9 p.m.","zh":"2026 年秋季：超市每天 6:00–23:00，感恩节当天不开。药房周一到周五 9:00–19:00，周六周日 10:00–16:00。中餐和意大利餐柜台 10:00–20:00；星巴克 6:00–19:00；酒类 8:00–21:00。"},"sum":{"en":"Large west-side supermarket at Odana Rd and Whitney Way with a pharmacy, Chinese and Italian food counters, a Starbucks and online pickup.","zh":"西边 Odana Rd 和 Whitney Way 路口的大超市，有药房、中餐和意大利餐柜台、星巴克，可网购自取。"},"kw":["Hy-Vee","grocery","超市","pharmacy","药房","prescription","处方药","Chinese food","中餐","Starbucks","星巴克","pickup","自取","Whitney Way"],"sec":{"about":{"en":["Hy-Vee's west-side Madison store sits on the corner of Odana Road and Whitney Way. Besides a full grocery store, it has a pharmacy, a registered dietitian, a meat market and seafood counter, in-store kitchens (Chinese, Italian and a general kitchen), a bakery, a Starbucks and a wine and spirits department."],"zh":["Hy-Vee 在麦迪逊西边的店，在 Odana Road 和 Whitney Way 的路口。除了完整的超市，还有药房、注册营养师、肉类和海鲜柜台、店内厨房（中餐、意大利餐和综合熟食）、面包房、星巴克和酒类区。"]},"offers":{"en":["Pharmacy for prescriptions, phone (608) 277-6731","Chinese food counter and Italian counter, 10 a.m.–8 p.m.","Kitchen with prepared food, 6 a.m.–8 p.m.","Meat market (6 a.m.–9 p.m.) and seafood counter (7 a.m.–9 p.m.) with counter service","Starbucks coffee, 6 a.m.–7 p.m.","Wine and spirits, 8 a.m.–9 p.m.","Registered dietitian, phone (608) 277-6733"],"zh":["药房可以取处方药，电话 (608) 277-6731","中餐柜台和意大利餐柜台，10:00–20:00","综合熟食厨房，6:00–20:00","肉类柜台（6:00–21:00）和海鲜柜台（7:00–21:00），有人现场服务","星巴克，6:00–19:00","酒类区，8:00–21:00","注册营养师，电话 (608) 277-6733"]},"howto":{"en":["Order groceries online for pickup (7 a.m.–10 p.m.) or delivery (8 a.m.–10 p.m.). Questions about online orders: (608) 277-6734.","Hy-Vee has a loyalty program called Hy-Vee PERKS; sign up on hy-vee.com."],"zh":["网上买菜可以自取（7:00–22:00）或送货（8:00–22:00），网购问题打 (608) 277-6734。","Hy-Vee 有会员积分计划 Hy-Vee PERKS，在 hy-vee.com 注册。"]},"cost":{"en":["Hy-Vee says prices and promotions can differ between stores and online, and online prices are set on the day the order is filled."],"zh":["Hy-Vee 说各店之间、店里和网上的价格促销可能不同，网上订单按备货当天的价格算。"]},"tips":{"en":["The pharmacy closes much earlier than the store, and at 4 p.m. on weekends.","The other Madison Hy-Vee is on the east side at 3801 East Washington Avenue."],"zh":["药房比超市关门早很多，周末下午 4 点就关。","麦迪逊另一家 Hy-Vee 在东边，地址 3801 East Washington Avenue。"]}},"src":[["Hy-Vee Madison #2 (Whitney Way) - store page","https://www.hy-vee.com/stores/detail.aspx?s=1332"],["Hy-Vee - store finder results near 53711","https://www.hy-vee.com/stores/store-finder-results.aspx?zip=53711&state=&city=&olfloral=False&olcatering=False&olgrocery=False&olpre=False&olbakery=False&diet=False&chef=False"]],"unv":[],"chk":"2026-10-08","lat":43.050832,"lng":-89.471303,"stops":[["S Whitney at Odana",160,"D E J 63"],["Odana at S Whitney",234,"J"],["Tokay at U W Health",301,"D J 63"]]},{"id":"lees-oriental","cat":"grocery","n":{"en":"Lee's Oriental","zh":"Lee's Oriental 日韩超市"},"kind":{"en":"Japanese and Korean grocery","zh":"日韩超市"},"addr":"3240 University Ave, Madison, WI 53705","phone":"(608) 231-1593","web":"https://madisonleesoriental.com/","h":{"Mo":[[600,1080]],"Tu":[[600,1080]],"We":[[600,1080]],"Th":[[600,1080]],"Fr":[[600,1080]],"Sa":[[600,1020]],"Su":[[660,960]]},"ht":{"en":"Fall 2026: Mon–Fri 10 a.m.–6 p.m., Sat 10 a.m.–5 p.m., Sun 11 a.m.–4 p.m., according to the store's website. One listing shows an 11 a.m. weekday opening, so call if you plan to arrive right at 10.","zh":"2026 年秋季：周一到周五 10:00–18:00，周六 10:00–17:00，周日 11:00–16:00（来自店家官网）。有个网上列表写工作日 11:00 才开门，卡着 10 点到的话先打个电话。"},"sum":{"en":"Japanese and Korean grocery in the Shorewood Shopping Center on University Ave: snacks, drinks, gochujang, Korean side dishes, rice cookers.","zh":"University Ave 上的日韩超市，日本零食饮料、韩国酱料和小菜、电饭煲等小家电都有。"},"kw":["Lee's Oriental","日韩超市","Japanese grocery","Korean grocery","日本零食","韩国食品","gochujang","辣酱","kimchi","泡菜","rice cooker","电饭煲","Daiso","BT21","University Avenue","Shorewood"],"sec":{"about":{"en":["Lee's Oriental is a Japanese and Korean grocery in the Shorewood Shopping Center on University Avenue, on Madison's west side. The store's own site says it brings popular, authentic products from Japan, Korea and other parts of Asia, from Japanese snacks and beverages to Korean spices like gochujang, plus homemade Korean side dishes.","It also sells imported Asian appliances, including Japanese rice cookers, matcha tea sets, Korean BBQ grills and stone bowls and pots, and Japanese anime, BT21 and Daiso merchandise."],"zh":["Lee's Oriental 是 University Ave 上 Shorewood Shopping Center 里的日韩超市，在麦迪逊西边。店家官网说卖日本、韩国和亚洲其他地方的热门正宗商品：从日本零食饮料到韩国辣酱 (gochujang) 这类调味品，还有自制的韩式小菜。","店里还有进口亚洲小家电，比如日本电饭煲、抹茶茶具、韩式烤肉烤盘、石锅石碗，另外有日本动漫、BT21 和 Daiso 的周边。"]},"offers":{"en":["Japanese snacks and beverages","Korean spices and sauces such as gochujang","Homemade Korean side dishes; a neighbor also mentions beef and pork bulgogi and kimchi to take home","Frozen goods from brands like bibigo, and a little produce","Appliances from Japan and Korea: rice cookers, matcha tea sets, Korean BBQ grills, stone bowls and pots","Japanese anime, BT21 and Daiso merchandise"],"zh":["日本零食和饮料","韩国调味品和酱料，比如辣酱 (gochujang)","自制韩式小菜；有邻居提到还有牛肉、猪肉烤肉 (bulgogi) 和泡菜可以带回家","bibigo 等品牌的冷冻食品，也有少量蔬果","日本、韩国的小家电：电饭煲、抹茶茶具、韩式烤肉烤盘、石锅石碗","日本动漫、BT21 和 Daiso 的周边"]},"howto":{"en":["Payment: a listing shows credit cards accepted.","Parking: a private lot at the shopping center.","Product requests: the website has a contact form with a \"Product Suggestions\" category."],"zh":["付款：网上列表写的是收信用卡。","停车：购物中心有私人停车场。","想让店里进某样东西：官网有联系表单，分类里有“产品建议”(Product Suggestions)。"]},"cost":{"en":["A reviewer says it may be a bit pricier than other stores, but it has items that are not readily available in the area."],"zh":["有评价说价格可能比别的店略高，但店里有这一带别处不容易买到的东西。"]},"tips":{"en":["Reviewers describe the owner as friendly and helpful with advice on dishes, so ask if you are not sure what to buy.","It closes at 6 p.m. on weekdays, 5 p.m. on Saturday and 4 p.m. on Sunday, so plan for the afternoon.","Buy fresh produce elsewhere: a December 2025 review says there is some produce, but not much."],"zh":["评价说老板友善，会给做菜建议，不知道买什么可以直接问。","工作日 18:00 关门，周六 17:00，周日 16:00，最好下午去。","新鲜蔬果去别处买：2025 年 12 月的一条评价说有一些蔬果，但不多。"]}},"src":[["Lee's Oriental - official website","https://madisonleesoriental.com/"],["Lee's Oriental LLC - Loc8NearMe listing","https://www.loc8nearme.com/wisconsin/madison/lees-oriental-llc/2413730/"],["Lee's Oriental - Nextdoor","https://nextdoor.com/pages/lees-oriental-madison-wi/"]],"unv":[],"chk":"2026-10-08","lat":43.075722,"lng":-89.443024,"stops":[["Shorewood",58,"A F"],["Shorewood at Locust",86,"63"],["Shorewood at Topping",225,"63"]]},{"id":"metcalfes-hilldale","cat":"grocery","n":{"en":"Metcalfe's Hilldale","zh":"Metcalfe's 超市（Hilldale 店）"},"kind":{"en":"Local supermarket","zh":"本地超市"},"addr":"726 N Midvale Blvd, Madison, WI 53705","phone":"(608) 238-7612","web":"https://www.shopmetcalfes.com/online/metcalfeshilldale/pages/storehoursdirectionsaboutus","h":{"Mo":[[360,1320]],"Tu":[[360,1320]],"We":[[360,1320]],"Th":[[360,1320]],"Fr":[[360,1320]],"Sa":[[360,1320]],"Su":[[360,1320]]},"ht":{"en":"Fall 2026: open every day 6 a.m.–10 p.m.","zh":"2026 年秋季：每天 6:00–22:00。"},"sum":{"en":"Family-owned supermarket at Hilldale with lots of local and organic produce, a meat and seafood counter, deli and specialty cheese.","zh":"Hilldale 的家族超市，本地和有机蔬果多，有肉类海鲜柜台、熟食和特色奶酪。"},"kw":["Metcalfe's","grocery","超市","Hilldale","organic","有机","local","本地","cheese","奶酪","rewards","积分","delivery","送货"],"sec":{"about":{"en":["Metcalfe's Market is a family-owned Wisconsin grocer dating to 1917. Its Hilldale store sells over 500 varieties of local and organic produce and goods from 25 local bakeries, along with a full-service meat counter, a seafood counter, a deli with daily soups, and a large specialty cheese section."],"zh":["Metcalfe's Market 是威斯康星的家族超市，历史可以追溯到 1917 年。Hilldale 店有 500 多种本地和有机蔬果、25 家本地面包房的产品，还有全服务肉类柜台、海鲜柜台、每天换汤的熟食区，以及很大的特色奶酪区。"]},"offers":{"en":["Over 500 varieties of local and organic produce","Breads and baked goods from 25 local bakeries","Full-service meat counter and seafood counter","Deli with prepared entrées and daily soups","Specialty cheese section, including Wisconsin cheeses","Babcock Dairy ice cream and cheese from UW–Madison","Online orders for curbside pickup or delivery"],"zh":["500 多种本地和有机蔬果","25 家本地面包房的面包和点心","全服务肉类柜台和海鲜柜台","熟食区有现成主菜和每日例汤","特色奶酪区，包括威斯康星本地奶酪","UW–Madison 自家 Babcock Dairy 的冰淇淋和奶酪","网上下单，路边取货或送货上门"]},"howto":{"en":["Join Metcalfe's Rewards by typing your phone number into the Rewards terminal at any register or at customer service. No email is needed, and a landline works too.","Order online for curbside pickup at a time slot you choose, or for delivery to your door."],"zh":["加入 Metcalfe's Rewards 积分：在任意收银台或服务台的积分终端输入手机号就行，不需要邮箱，座机号也可以。","网上下单可以选时间段路边取货，也可以送货上门。"]},"cost":{"en":["Rewards: 1 point per $1 spent (not on tobacco, lottery, services or gift cards). At 100 points you can take $1 off; points expire 6 months after you earn them.","Most weekly-ad sale prices are open to everyone, but the best deals are for Rewards members only."],"zh":["积分：每花 $1 得 1 分（烟草、彩票、服务和礼品卡除外），满 100 分可抵 $1，积分 6 个月后过期。","每周广告上的大部分特价所有人都能享受，但最大力度的优惠只给积分会员。"]},"tips":{"en":["Enter your phone number at checkout every time; points cannot be added later from a receipt.","Points can be earned on online orders but cannot be redeemed online."],"zh":["每次结账都要输手机号，事后拿小票补不了积分。","网上订单可以攒积分，但不能在网上用积分抵扣。"]}},"src":[["Metcalfe's - Store Hours, Directions, About Us","https://www.shopmetcalfes.com/online/metcalfeshilldale/pages/storehoursdirectionsaboutus"],["Metcalfe's Hilldale - online store (departments, pickup, delivery)","https://www.shopmetcalfes.com/"],["Metcalfe's Rewards FAQ","https://www.shopmetcalfes.com/online/metcalfeshilldale/pages/newmetcalfesrewards-hilldale"],["UW Babcock Dairy Store - where to buy: Metcalfe's Market Hilldale","https://babcockdairystore.wisc.edu/locations/metcalfes-market-hilldale/"]],"unv":[],"chk":"2026-10-08","lat":43.074452,"lng":-89.451243,"stops":[["N Midvale at University",41,"63"],["Midvale",92,"A F"],["University at N Midvale",95,"63"]]},{"id":"oriental-food-mart","cat":"grocery","n":{"en":"Oriental Food Mart (K-Food Market)","zh":"Oriental Food Mart 韩国超市（K-Food Market）"},"kind":{"en":"Korean grocery","zh":"韩国超市"},"addr":"1206 S Park St, Madison, WI 53715","phone":"(608) 255-0326","web":"","h":{"Mo":[[600,1080]],"Tu":[[600,1080]],"We":[[600,1080]],"Th":[[600,1080]],"Fr":[[600,1080]],"Sa":[[600,1080]],"Su":[[660,1020]]},"ht":{"en":"Fall 2026: Mon–Sat 10 a.m.–6 p.m., Sun 11 a.m.–5 p.m., according to Apple Maps and Yahoo listings (no official site).","zh":"2026 年秋季：周一到周六 10:00–18:00，周日 11:00–17:00（来自 Apple Maps 和 Yahoo 的信息，没有官网）。"},"sum":{"en":"Small Korean grocery on South Park Street: kimchi, noodles, sauces, snacks, and plenty of frozen food and seafood.","zh":"S Park St 上的小型韩国超市，泡菜、面条、酱料、零食和冷冻食品、冷冻海鲜比较全。"},"kw":["Oriental Food Mart","K-Food Market","Korean grocery","韩国超市","韩国食品","kimchi","泡菜","ramen","拉面","frozen seafood","冷冻海鲜","Park Street"],"sec":{"about":{"en":["Oriental Food Mart is a small Korean grocery on South Park Street; some online listings now call it K-Food Market. Brava Magazine names it a local favorite for Korean cuisine, with everything from snacks to packaged pantry goods to frozen foods.","Customers say the range covers non-perishables, frozen items, sauces, condiments, noodles and frozen seafood, with authentic Korean brands. Fresh produce is limited."],"zh":["Oriental Food Mart 是 S Park St 上的一家小型韩国超市，网上有些信息已经叫它 K-Food Market。Brava 杂志称它是本地人爱去的韩餐食材店，从零食、包装食材到冷冻食品都有。","顾客说店里干货、冷冻食品、酱料、调味品、面条和冷冻海鲜都不少，卖的是正宗韩国品牌。新鲜蔬菜比较少。"]},"offers":{"en":["Kimchi, noodles and sauces","Korean snacks and packaged pantry goods","Frozen food, including frozen meals and frozen seafood","Rice, seasonings and handmade noodles from Korean brands","Teas, plus some refrigerated drinks and condiments"],"zh":["泡菜、面条和酱料","韩国零食和包装食材","冷冻食品，包括冷冻成品餐和冷冻海鲜","韩国品牌的大米、调味料和手工面条","茶，以及一些冷藏饮料和调味品"]},"howto":{"en":["Payment: listings show credit and debit cards and Apple Pay or other tap-to-pay. One customer note says cards are accepted for purchases above $10, so bring some cash for small buys.","Parking: Apple Maps lists street parking.","No official website found. Call (608) 255-0326 to check stock."],"zh":["付款：网上信息写的是信用卡、借记卡和 Apple Pay 等感应支付。有顾客留言说刷卡要消费超过 $10，买点小东西时带点现金。","停车：Apple Maps 上写的是路边停车。","没找到官方网站。想确认有没有某样东西，可以打 (608) 255-0326。"]},"cost":{"en":["Customers call prices reasonable, though some say prices run higher than in other markets."],"zh":["顾客普遍觉得价格合理，也有人说比别的市场略贵。"]},"tips":{"en":["Fresh vegetables are limited, so plan to buy produce elsewhere.","Reviewers describe the staff as friendly and helpful with finding ingredients and sharing cooking advice. Ask if you can't find something.","The store closes at 6 p.m. most days and 5 p.m. on Sunday, so go in the afternoon."],"zh":["新鲜蔬菜不多，蔬果要去别处买。","评价说店员友善，会帮忙找食材、教怎么做。找不到就直接问。","多数日子 18:00 关门，周日 17:00 关门，下午去比较稳妥。"]}},"src":[["UW Bridge to the Chemistry Doctorate - Ethnic Grocery Stores in the Madison Area","https://bridge.chem.wisc.edu/local-info-2/ethnic-grocery-stores-in-the-madison-area/"],["Oriental Food Mart - Apple Maps","https://maps.apple.com/place?place-id=I40DF678F52E3CA3A"],["Oriental Food Mart - Yahoo Local","https://local.yahoo.com/info-16783309-oriental-food-mart-madison/"],["Brava Magazine - Madison's International Markets Expand Your Gastronomic Horizons","https://bravamagazine.com/madison-international-markets/"],["K-Food Market - Wheree listing","https://kfood-market.wheree.com/"]],"unv":[],"chk":"2026-10-08","lat":43.053654,"lng":-89.396461,"stops":[["W Olin at S Park",46,"O 63"],["S Park at W Olin",60,"B 64"],["S Park at Cedar",206,"B 63 64"]]},{"id":"pick-n-save-park-street","cat":"grocery","n":{"en":"Pick 'n Save (Park St)","zh":"Pick 'n Save 超市（Park St 店）"},"kind":{"en":"Supermarket","zh":"大型超市"},"addr":"1312 S Park St, Madison, WI 53715","phone":"(608) 257-3748","web":"https://www.picknsave.com/stores/grocery/wi/madison/pns-madison-park/534/00183","h":{"Mo":[[420,1320]],"Tu":[[420,1320]],"We":[[420,1320]],"Th":[[420,1320]],"Fr":[[420,1320]],"Sa":[[420,1320]],"Su":[[420,1320]]},"ht":{"en":"Fall 2026: the store page lists every day 7 a.m.–10 p.m. Holiday hours may differ, so call before a holiday trip.","zh":"2026 年秋季：门店页面写的是每天 7:00–22:00。节假日可能不一样，节日出门前先打个电话。"},"sum":{"en":"Full grocery store on South Park Street with deli, bakery, beer and wine. Takes SNAP/EBT; online Pickup is free on orders of $35 or more.","zh":"S Park St 上的综合超市，有熟食、烘焙、酒类，收 SNAP/EBT，网上下单取货满 $35 免费。"},"kw":["Pick 'n Save","Pick n Save","PNS","supermarket","超市","grocery","买菜","Park Street","SNAP","EBT","pickup","到店取货","deli","bakery","Kroger"],"sec":{"about":{"en":["A full grocery store on South Park Street, one of three Pick 'n Save stores in Madison. Its store page lists a deli, bakery, rotisserie chicken, beer, wine and liquor, books and magazines, lottery tickets and a drug and general merchandise section. The chain says its Madison stores carry fresh produce, meats, seafood, dry goods, home supplies and health products."],"zh":["S Park St 上的一家综合超市，是 Pick 'n Save 在麦迪逊的三家店之一。门店页面列出的部门有熟食、烘焙、烤鸡、啤酒/葡萄酒/烈酒、书报杂志、彩票，以及药品和日用杂货区。官网说麦迪逊的店有新鲜蔬果、肉、海鲜、干货、家居用品和保健品。"]},"offers":{"en":["Fresh produce, meat, seafood, dry goods, home supplies and health products","Deli, bakery and rotisserie chicken; deli and bakery items can be ordered ahead online","Beer, wine and liquor","Drug and general merchandise section","Online Pickup orders; the store page also lists a locker collection point","Lottery tickets, books and magazines"],"zh":["新鲜蔬果、肉、海鲜、干货、家居用品、保健品","熟食、烘焙和烤鸡；熟食和烘焙可以网上提前下单","啤酒、葡萄酒和烈酒","药品和日用杂货区","网上下单到店取货 (Pickup)；门店页面还列了取货储物柜","彩票、书报杂志"]},"howto":{"en":["Make a digital account on picknsave.com or in the app (an email address is needed), then load digital coupons to your Shopper's Card or Alt ID. At the register, scan the card or type in the Alt ID.","Pickup: order online and bring the payment card you used online plus a backup credit or debit card. Online orders take credit, debit, gift cards, FSA/HSA and SNAP EBT, but no cash or checks. Alcohol orders need a government-issued ID.","In the store, SNAP/EBT is accepted."],"zh":["在 picknsave.com 或 App 上注册账号（要用邮箱），然后把电子优惠券 (digital coupons) 加到你的会员卡 (Shopper's Card) 或 Alt ID 上。结账时扫卡或输入 Alt ID。","取货 (Pickup)：网上下单，取货时带上网上付款用的那张卡，再带一张备用信用卡或借记卡。网上订单收信用卡、借记卡、礼品卡、FSA/HSA 和 SNAP EBT，不收现金和支票。订单里有酒的话要带政府签发的证件。","到店购物可以用 SNAP/EBT。"]},"cost":{"en":["Pickup is free on orders of $35 or more; under $35 there is a $4.95 service fee.","Digital coupons load straight to your Shopper's Card and come off automatically when you buy the qualifying item."],"zh":["取货 (Pickup) 满 $35 免费，不满 $35 收 $4.95 服务费。","电子优惠券直接加到会员卡上，买到对应商品时自动抵扣。"]},"tips":{"en":["The map box on the store page says hours are unavailable, but its hours section shows 7 a.m.–10 p.m. every day. Call (608) 257-3748 if you plan a trip on a holiday.","Check your receipt: digital coupon savings show under the item and are labeled \"ecpn\".","To avoid the $4.95 Pickup fee, bring the cart up to $35."],"zh":["门店页面的地图框写着“暂无营业时间”，但下面的营业时间栏是每天 7:00–22:00。节假日出门前打 (608) 257-3748 问一下。","看一下小票：电子优惠券的折扣会显示在对应商品下面，标注为 \"ecpn\"。","想省掉 $4.95 的取货费，把购物车凑到 $35。"]},"intl":{"en":["No US phone number needed to join: the Alt ID can be any unused 10-digit number that does not start with 0, and you only need an email address to make the account."],"zh":["入会不用美国手机号：Alt ID 可以是任意没被占用、且不以 0 开头的 10 位数字，注册账号只需要一个邮箱。"]}},"src":[["Pick 'n Save - PNS Madison - Park store page","https://www.picknsave.com/stores/grocery/wi/madison/pns-madison-park/534/00183"],["Pick 'n Save - Grocery stores in Madison, WI","https://www.picknsave.com/stores/grocery/wi/madison"],["Pick 'n Save - Pickup FAQs","https://www.picknsave.com/hc/help/faqs/ways-to-shop/pickup"],["Pick 'n Save - Digital Coupon FAQs","https://www.picknsave.com/hc/help/faqs/ways-to-save/coupons"],["Pick 'n Save - Digital Account FAQs","https://www.picknsave.com/hc/help/faqs/account/general"],["Greater Madison Chamber - Pick 'n Save Madison (Park St.)","https://member.greatermadisonchamber.com/list/member/pick-n-save-madison-park-st-6238"]],"unv":[],"chk":"2026-10-08","lat":43.052256,"lng":-89.396011,"stops":[["S Park at Cedar",98,"B 63 64"],["W Olin at S Park",187,"O 63"],["S Park at W Olin",217,"B 64"]]},{"id":"regent-market-coop","cat":"grocery","n":{"en":"Regent Market Co-op","zh":"Regent Market 合作社超市"},"kind":{"en":"Neighborhood co-op grocery","zh":"社区合作社超市"},"addr":"2136 Regent St, Madison, WI 53726","phone":"(608) 233-4329","web":"https://regentmarketcoop.com/","h":{"Mo":[[480,1260]],"Tu":[[480,1260]],"We":[[480,1260]],"Th":[[480,1260]],"Fr":[[480,1260]],"Sa":[[480,1260]],"Su":[[480,1260]]},"ht":{"en":"Fall 2026: open every day 8 a.m.–9 p.m. Phone-order home delivery Mon–Thu only.","zh":"2026 年秋季：每天 8:00–21:00。电话订货送上门只在周一到周四。"},"sum":{"en":"Small member-owned grocery on Regent St with local produce, Wisconsin cheese and beer, and house-made brats; anyone can shop.","zh":"Regent St 上的小型会员制合作社超市，本地蔬菜、威州奶酪啤酒和自制香肠，谁都能买。"},"kw":["Regent Market","co-op","合作社","grocery","超市","local","本地","brats","香肠","cheese","奶酪","delivery","送货","Regent Street"],"sec":{"about":{"en":["Regent Market Co-op, nicknamed \"The Little Store\", is a member-owned neighborhood grocery serving the Regent, Monroe and Vilas neighborhoods. It is small, with wooden floors and small carts, but stocks most everyday groceries along with many products from local farms and Wisconsin producers. Members get a discount, but anyone can shop."],"zh":["Regent Market Co-op 外号「The Little Store」（小店），是会员共同拥有的社区超市，服务 Regent、Monroe、Vilas 这几个街区。店不大，木地板、小推车，但日常食品基本都有，还有很多本地农场和威斯康星本地厂家的产品。会员有折扣，非会员也能买。"]},"offers":{"en":["Local and organic vegetables from nearby farms","Wisconsin dairy and a case of local cheeses","Meat counter with house-made Regent Market bratwursts and whole chickens rotisserie-roasted daily","Mostly Wisconsin beers, plus wine and liquor","Madison Sourdough bread delivered daily"],"zh":["附近农场的本地有机蔬菜","威斯康星乳制品和一整柜本地奶酪","肉类柜台：店里自制的 Regent Market 香肠（bratwurst），每天现烤整鸡","啤酒大多是威斯康星本地酒厂的，也有葡萄酒和烈酒","Madison Sourdough 面包每天送货"]},"howto":{"en":["Home delivery: order by phone at (608) 233-4329 or by email, Monday to Thursday only. Call before 2 p.m. for same-day delivery. They deliver within a 2–3 mile radius of the store.","Pay delivery orders over the phone by credit or debit card, or from a prepaid account with the store.","Join at the store; membership is payable by cash or card."],"zh":["送货上门：打 (608) 233-4329 或发邮件订货，只限周一到周四；下午 2 点前打电话当天送。送货范围是店周围 2–3 英里。","送货订单可以电话里刷信用卡/借记卡付，或者从店里的预付账户扣。","在店里就能入会，现金或刷卡都行。"]},"cost":{"en":["Membership: $25 per household per year, or $125 one time for life. Members pay 10% less than non-members at checkout.","Home delivery costs $5 per order."],"zh":["会员：每户每年 $25，或一次性 $125 终身。会员结账比非会员便宜 10%。","送货每单收 $5。"]},"tips":{"en":["Already a member of another co-op, such as Willy Street Co-op? Tell the cashier: membership is reciprocal here.","There is no parking lot, but free 2-hour street parking is available nearby."],"zh":["已经是别的合作社（比如 Willy Street Co-op）的会员？结账时告诉收银员，这里会员互认。","店里没有停车场，但附近有不少免费的 2 小时路边停车位。"]}},"src":[["Regent Market Co-op - home page (hours, address, phone)","https://regentmarketcoop.com/"],["Regent Market Co-op - What We Carry","https://regentmarketcoop.com/regent-market-coop/"],["Regent Market Co-op - Shopping at RMC (delivery, parking)","https://regentmarketcoop.com/orders/"],["Regent Market Co-op - Membership","https://regentmarketcoop.com/membership/"]],"unv":[],"chk":"2026-10-08","lat":43.068078,"lng":-89.423453,"stops":[["Regent at S Allen",31,"E"],["Regent at N Allen",56,"E"],["Regent at N Prospect",197,"E"]]},{"id":"target-madison-state-street","cat":"grocery","n":{"en":"Target Madison State Street","zh":"Target 超市（State Street 店）"},"kind":{"en":"Small-format Target","zh":"小型 Target"},"addr":"610 State St, Madison, WI 53703","phone":"(608) 722-4849","web":"https://www.target.com/sl/madison-state-street/3405","h":{"Mo":[[420,1320]],"Tu":[[420,1320]],"We":[[420,1320]],"Th":[[420,1320]],"Fr":[[420,1320]],"Sa":[[480,1320]],"Su":[[480,1320]]},"ht":{"en":"Fall 2026: Mon–Fri 7 a.m.–10 p.m., Sat–Sun 8 a.m.–10 p.m.","zh":"2026 年秋季：周一到周五 7:00–22:00，周六周日 8:00–22:00。"},"sum":{"en":"Two-floor small Target on State Street: groceries and dorm basics downstairs, toiletries upstairs; Order Pickup available.","zh":"State Street 上的两层小型 Target，楼下是食品和宿舍日用品，楼上是洗护用品，可网上下单店内取。"},"kw":["Target","塔吉特","grocery","超市","dorm","宿舍用品","toiletries","日用品","State Street","order pickup","自取"],"sec":{"about":{"en":["Wisconsin's first small-format Target opened at 610 State Street in 2021. The 15,000-square-foot store has two levels: health and beauty products on the street level, and a large grocery section plus household goods aimed at college students on the lower level. It also carries clothing and home decor."],"zh":["这是威斯康星州第一家小型 Target，2021 年在 State Street 610 号开业。店面 15,000 平方英尺，分两层：一楼是洗护和美妆，地下一层是大片食品区和面向大学生的家居日用品。也卖衣服和家居装饰。"]},"offers":{"en":["Groceries on the lower level: fresh produce, packaged meat, frozen food, milk, cheese, yogurt, cereal, rice and pasta","Health, beauty and personal care products on the first floor","Household goods for student rooms on the lower level","Clothing and home decor","Order Pickup: buy on the Target app or website and collect in the store"],"zh":["地下一层的食品：新鲜蔬果、包装肉、冷冻食品、牛奶、奶酪、酸奶、麦片、大米和意面","一楼是洗护、美妆和个人护理用品","地下一层有给学生宿舍用的家居日用品","衣服和家居装饰","Order Pickup：在 Target app 或官网下单，到店自取"]},"howto":{"en":["Order Pickup works at this store. Drive Up and Same Day Delivery are not available here (as of October 2026).","The lower level is reached by a central staircase or an elevator."],"zh":["这家店可以用 Order Pickup。Drive Up（停车场取货）和 Same Day Delivery（当天送货）这家店不提供（2026 年 10 月）。","去地下一层走中间的楼梯，或者坐电梯。"]},"cost":{"en":["Target Circle, Target's loyalty program, is free to join.","Prices and promotions can differ between this store and Target.com."],"zh":["Target 的会员计划 Target Circle 免费加入。","这家店和 Target 官网的价格、促销可能不一样。"]},"tips":{"en":["This is a small store with a limited range. For more choice, other Madison Targets are Madison Hilldale (750 Hilldale Way), Madison East (4301 Lien Rd) and Madison West (201 Junction Rd).","Weekend hours start an hour later, at 8 a.m."],"zh":["这家店面积小，东西不全。想买得更全，可以去麦迪逊其他几家 Target：Hilldale 店（750 Hilldale Way）、East 店（4301 Lien Rd）和 West 店（201 Junction Rd）。","周末晚一小时开门，早上 8 点才开。"]}},"src":[["Target Madison State Street - store page","https://www.target.com/sl/madison-state-street/3405"],["Target - Find a store near 53703","https://www.target.com/store-locator/find-stores/53703"],["Target Circle","https://www.target.com/circle"],["Wisconsin State Journal - A Target store with 2 levels opens on State Street (2021)","https://madison.com/business/article_1afa187e-72c1-5819-83e5-37339908008e.html"],["Madison Magazine - A look inside the new Target on State Street","https://www.channel3000.com/madison-magazine/city-life/a-look-inside-the-new-target-on-state-street/article_c11889cc-8cd0-547e-8d9d-441c13316f9e.html"],["WMTV - State St. welcomes Target's first small-format store in Madison (2021)","https://www.wmtv15news.com/2021/10/20/target-opens-first-small-format-version-store-madison"]],"unv":[],"chk":"2026-10-08","lat":43.075176,"lng":-89.396044,"stops":[["Langdon at N Lake",93,"81"],["N Lake at Langdon",101,"80 82"],["University at N Bassett",239,"C D R 28 38 65 81"]]},{"id":"trader-joes-madison","cat":"grocery","n":{"en":"Trader Joe's (Madison)","zh":"Trader Joe's 超市（Monroe St 店）"},"kind":{"en":"Specialty grocery chain","zh":"特色连锁超市"},"addr":"1810 Monroe St, Madison, WI 53711","phone":"(608) 257-1916","web":"https://locations.traderjoes.com/wi/madison/712/","h":{"Mo":[[540,1260]],"Tu":[[540,1260]],"We":[[540,1260]],"Th":[[540,1260]],"Fr":[[540,1260]],"Sa":[[540,1260]],"Su":[[540,1260]]},"ht":{"en":"Fall 2026: open every day 9 a.m.–9 p.m.","zh":"2026 年秋季：每天 9:00–21:00。"},"sum":{"en":"Trader Joe's on Monroe Street: own-label frozen meals, snacks, cheese and flowers plus everyday basics. In-store shopping only.","zh":"Monroe St 上的 Trader Joe's，自有品牌冷冻餐和零食出名，日常食材也有；只能到店买。"},"kw":["Trader Joe's","TJ","缺德舅","grocery","超市","frozen food","冷冻食品","snacks","零食","cheese","奶酪","Monroe Street"],"sec":{"about":{"en":["Madison's only Trader Joe's sits on Monroe Street. Most products carry the Trader Joe's label, such as its Mandarin Orange Chicken and Cold Brew Coffee Concentrate, alongside everyday basics: milk, eggs, meat, bakery items and fresh produce. The store also sells cheese and fresh flowers."],"zh":["麦迪逊唯一的 Trader Joe's 在 Monroe Street。店里大部分是 Trader Joe's 自有品牌，比如有名的陈皮鸡（Mandarin Orange Chicken）和冷萃咖啡浓缩液，也有牛奶、鸡蛋、肉、面包和新鲜蔬果这些日常食材，另外卖奶酪和鲜花。"]},"offers":{"en":["Trader Joe's own-label frozen meals, snacks and sauces","Everyday basics: milk, eggs, meat, bread and fresh produce","Cheese section","Fresh flowers"],"zh":["Trader Joe's 自有品牌的冷冻餐、零食和酱料","日常食材：牛奶、鸡蛋、肉、面包和新鲜蔬果","奶酪区","鲜花"]},"howto":{"en":["Shop in person only: no online orders, no curbside pickup, no delivery.","Payment: credit and debit cards, Apple Pay, Google Pay, Samsung Pay, cash, EBT, personal checks up to $150, and physical Trader Joe's gift cards."],"zh":["只能到店买：没有网购、没有路边取货、没有送货。","付款方式：信用卡、借记卡、Apple Pay、Google Pay、Samsung Pay、现金、EBT、$150 以内的个人支票，以及实体 Trader Joe's 礼品卡。"]},"cost":{"en":["No coupons, no membership card and no sales: the shelf price is the price everyone pays.","Gift cards are sold and accepted only as physical cards in the store."],"zh":["没有优惠券、没有会员卡、也不搞促销，货架上的价格就是所有人付的价格。","礼品卡只有实体卡，只能在店里买和用。"]},"tips":{"en":["Trader Joe's says it does not work with Instacart or other delivery apps, so any app offering Trader Joe's delivery is not from the store.","Trader Joe's regularly discontinues products, so stock up on a favorite while it is on the shelf."],"zh":["Trader Joe's 明确说不和 Instacart 等外卖平台合作，App 上号称能送 Trader Joe's 的都不是官方的。","Trader Joe's 经常下架商品，喜欢的东西看到了就多囤一点。"]},"intl":{"en":["Phone wallets (Apple Pay, Google Pay, Samsung Pay) are accepted, which helps if your foreign card has trouble at the terminal."],"zh":["收 Apple Pay、Google Pay、Samsung Pay，国外的卡刷不了时可以用手机支付试试。"]}},"src":[["Trader Joe's Madison (712) - store page","https://locations.traderjoes.com/wi/madison/712"],["Trader Joe's locations in Madison, WI","https://locations.traderjoes.com/wi/madison/"],["Trader Joe's - General FAQs","https://www.traderjoes.com/home/FAQ/general-faqs"]],"unv":[],"chk":"2026-10-08","lat":43.064948,"lng":-89.417502,"stops":[["Monroe at Spooner",72,"D"],["Monroe at Van Buren",127,"D"],["Monroe at S Prospect",207,"D"]]},{"id":"viet-hoa-market","cat":"grocery","n":{"en":"Viet Hoa Market","zh":"Viet Hoa Market 亚洲超市"},"kind":{"en":"Asian grocery","zh":"亚洲超市"},"addr":"4602 Monona Dr, Madison, WI 53716","phone":"(608) 661-1300","web":"","h":{"Mo":[[540,1140]],"Tu":[[540,1140]],"We":[[540,1140]],"Th":[[540,1140]],"Fr":[[540,1140]],"Sa":[[540,1140]],"Su":[[540,1140]]},"ht":{"en":"Fall 2026: two recent listings show every day 9 a.m.–7 p.m. Older listings show an 8 p.m. or 9 p.m. close, so call before an evening trip.","zh":"2026 年秋季：两个较新的网上信息写的是每天 9:00–19:00。较旧的信息写 20:00 或 21:00 关门，晚上去之前最好打电话确认。"},"sum":{"en":"Pan-Asian grocery on Monona Drive with Vietnamese, Chinese, Japanese and Korean goods, plus a Laotian restaurant inside.","zh":"Monona Dr 上的泛亚超市，有越南、中国、日本、韩国食品，店里还有老挝餐馆。"},"kw":["Viet Hoa","Viet Hoa Market","越南超市","亚洲超市","Asian grocery","Vietnamese","banh mi","越南三明治","Hot N Spicy","Laotian","老挝菜","Monona Drive","noodles","sauces"],"sec":{"about":{"en":["Viet Hoa Market is a pan-Asian grocery on Monona Drive. City Cast Madison says it has items from Vietnam, Japan, China, Korea and beyond, and Brava Magazine describes aisles of sauces, dry goods, meats, drinks and candies.","A Laotian restaurant, Hot N Spicy, runs inside the store. Reviews also mention banh mi, fresh produce, frozen goods and snacks."],"zh":["Viet Hoa Market 是 Monona Dr 上的泛亚超市。City Cast Madison 说店里有越南、日本、中国、韩国等地的货，Brava 杂志写到货架上有酱料、干货、肉类、饮料和糖果。","店里有一家老挝餐馆 Hot N Spicy。评价里还提到越南三明治 (banh mi)、新鲜蔬果、冷冻食品和零食。"]},"offers":{"en":["Imported goods from Vietnam, China, Japan, Korea, Thailand and more","Sauces, spices, noodles, rice and other pantry staples; specialty items such as miso paste, fish sauce, kimchi, sushi rice and curry pastes","Meats, drinks and candies","Fresh produce, frozen goods and snacks","Banh mi sandwiches","Hot N Spicy, a Laotian restaurant at the back of the store"],"zh":["越南、中国、日本、韩国、泰国等地的进口食品","酱料、香料、面条、大米等常备食材；还有味噌、鱼露、泡菜、寿司米和咖喱酱这类特色货","肉类、饮料和糖果","新鲜蔬果、冷冻食品和零食","越南三明治 (banh mi)","店里靠后的老挝餐馆 Hot N Spicy"]},"howto":{"en":["Payment: listings show credit and debit cards, tap-to-pay and SNAP/EBT.","No official website found. Call (608) 661-1300 to check hours or ask whether an item is in stock.","The restaurant counter is at the back of the store."],"zh":["付款：网上信息写的是信用卡、借记卡、感应支付和 SNAP/EBT。","没找到官方网站。想确认营业时间或问有没有某样东西，可以打 (608) 661-1300。","餐馆柜台在店的最里面。"]},"cost":{"en":["Reviewers generally call prices reasonable for the range of products on the shelves."],"zh":["评价普遍觉得价格合理，货也很全。"]},"tips":{"en":["Stock varies: some reviewers needed more than one visit to find specialty sauces or candies.","Reviewers praise the fried rice and pad Thai from the in-store restaurant.","For an Asian grocery closer to campus, Asian Midway Foods and Oriental Food Mart are both on South Park Street."],"zh":["货会有变化：有顾客为了找某种特色酱料或糖果跑了不止一趟。","评价夸店里餐馆的炒饭和泰式炒河粉 (pad Thai)。","想找离校园更近的亚洲超市，Asian Midway Foods 和 Oriental Food Mart 都在 S Park St。"]},"intl":{"en":["Local listings say it covers Vietnam, Thailand, Japan and Korea as well as China, so one trip can cover cooking from several home countries."],"zh":["本地介绍说除了中国，越南、泰国、日本、韩国的东西也有，一趟能买到好几个国家的食材。"]}},"src":[["UW Bridge to the Chemistry Doctorate - Ethnic Grocery Stores in the Madison Area","https://bridge.chem.wisc.edu/local-info-2/ethnic-grocery-stores-in-the-madison-area/"],["City Cast Madison - How to Spice Up Your Grocery Trips While Shopping Locally","https://madison.citycast.fm/neighborhood-guides/how-to-spice-up-your-grocery-trips-while-shopping-locally"],["Brava Magazine - Madison's International Markets Expand Your Gastronomic Horizons","https://bravamagazine.com/madison-international-markets/"],["Viet Hoa Market - Yellow Pages","https://www.yellowpages.com/madison-wi/mip/viet-hoa-market-2484374"],["Viet Hoa Market - Yahoo Local","https://local.yahoo.com/info-52625562-viet-hoa-market-madison"],["Viet Hoa Market - Wheree listing","https://viet-hoa-market.wheree.com/"],["The Madison Guide - Viet Hoa Market","https://www.themadisonguide.com/listings/viet-hoa-market/"]],"unv":["hours"],"chk":"2026-10-08","lat":43.070074,"lng":-89.325413,"stops":[["Monona at Dean",76,"L 38"],["Monona at Coldspring",329,"L 38"],["Dean at Shore Acres",511,"38"]]},{"id":"whole-foods-madison-yards","cat":"grocery","n":{"en":"Whole Foods Market (Madison Yards)","zh":"Whole Foods 全食超市（Madison Yards 店）"},"kind":{"en":"Natural and organic supermarket","zh":"天然有机超市"},"addr":"4710 Madison Yards Way, Madison, WI 53705","phone":"(608) 233-9566","web":"https://www.wholefoodsmarket.com/stores/madisonsegoe","h":{"Mo":[[480,1260]],"Tu":[[480,1260]],"We":[[480,1260]],"Th":[[480,1260]],"Fr":[[480,1260]],"Sa":[[480,1260]],"Su":[[480,1260]]},"ht":{"en":"Fall 2026: open every day 8 a.m.–9 p.m.","zh":"2026 年秋季：每天 8:00–21:00。"},"sum":{"en":"Madison's Whole Foods, moved in 2023 from University Ave to Madison Yards: organic groceries, hot bar, sushi and Amazon returns.","zh":"2023 年搬到 Madison Yards 的 Whole Foods：有机食品、热菜吧，能退 Amazon 包裹。"},"kw":["Whole Foods","全食","organic","有机","grocery","超市","hot bar","热菜","Amazon returns","亚马逊退货","Prime","Madison Yards","Hilldale"],"sec":{"about":{"en":["Whole Foods Market's Madison store moved in December 2023 from University Avenue, where it had been since 1996, to a 50,000-square-foot store at 4710 Madison Yards Way, near Hilldale. The store website lists it as \"Madison Segoe\". It sells natural and organic groceries, more than 700 local items from the Midwest, and has several food counters inside."],"zh":["Whole Foods 在麦迪逊的门店 2023 年 12 月从 University Avenue（1996 年起在那里）搬到了 Hilldale 附近 Madison Yards Way 4710 号，新店 50,000 平方英尺，官网上叫 \"Madison Segoe\"。主打天然和有机食品，有 700 多种中西部本地商品，店里还有好几个餐食柜台。"]},"offers":{"en":["Hot bar and salad bar","Kikka Sushi, Madison Pizza, Market Sandwich and a coffee bar inside the store","Grind-your-own nut butters","Certified cheese professional at the cheese counter (ask the store for hours)","Beer, wine and spirits","Amazon returns: counter and self-service kiosk, no box or label needed"],"zh":["热菜吧和沙拉吧","店内有 Kikka Sushi 寿司、Madison Pizza 披萨、Market Sandwich 三明治和咖啡吧","可以自己现磨坚果酱","奶酪柜台有认证奶酪专家（具体时间问店员）","啤酒、葡萄酒和烈酒","Amazon 退货：有人工柜台和自助机，不用箱子也不用打印标签"]},"howto":{"en":["Online grocery delivery and pickup are ordered on Amazon.com and are for Prime members only.","You can pay with the In-Store Code in the Whole Foods Market or Amazon app.","Self-checkout is available; pre-weigh produce and bulk items to speed it up."],"zh":["网上买菜送货或自取要在 Amazon.com 下单，只限 Prime 会员。","可以用 Whole Foods 或 Amazon app 里的 In-Store Code 付款。","有自助收银，蔬果和散装食品可以先自己称好，结账更快。"]},"cost":{"en":["Delivery and pickup orders require an Amazon Prime membership.","Returning eligible Amazon orders here is free."],"zh":["送货和自取需要 Amazon Prime 会员。","符合条件的 Amazon 订单在这里退货免费。"]},"tips":{"en":["Old maps and some listings still show Whole Foods at 3313 University Ave. That building is now Enson Market, an Asian grocery that opened in March 2026.","The Amazon returns kiosk is open during store hours, so it doubles as a late drop-off point for returns."],"zh":["有些老地图和网站还把 Whole Foods 标在 3313 University Ave，那栋楼现在是 2026 年 3 月开业的亚洲超市 Enson Market。","Amazon 自助退货机在营业时间都能用，晚上退包裹也方便。"]}},"src":[["Whole Foods Market - Madison Segoe store page","https://www.wholefoodsmarket.com/stores/madisonsegoe"],["WMTV - New Madison Whole Foods Market location opens (Dec 2023)","https://www.wmtv15news.com/2023/12/14/new-madison-whole-foods-market-location-opens/"],["In Business Madison - Enson Market now open on University (March 2026)","https://www.ibmadison.com/business-report/enson-market-now-open-on-university/article_d5b25219-a05f-497d-a989-90848abac291.html"]],"unv":[],"chk":"2026-10-08","lat":43.074423,"lng":-89.45849,"stops":[["N Segoe at University",124,"R 28 38"],["Sheboygan at N Segoe",182,"F R 28 38"],["Segoe",191,"A F"]]},{"id":"willy-street-coop-east","cat":"grocery","n":{"en":"Willy Street Co-op East","zh":"Willy Street 合作社超市（东店）"},"kind":{"en":"Grocery co-op","zh":"合作社超市"},"addr":"1221 Williamson St, Madison, WI 53703","phone":"(608) 251-6776","web":"https://www.willystreet.coop/store-locations-and-hours/","h":{"Mo":[[450,1260]],"Tu":[[450,1260]],"We":[[450,1260]],"Th":[[450,1260]],"Fr":[[450,1260]],"Sa":[[450,1260]],"Su":[[450,1260]]},"ht":{"en":"Fall 2026: open every day 7:30 a.m.–9 p.m. Hot bar: breakfast 7:30 to about 10 a.m., lunch and dinner from about 11 a.m. to 8 p.m. Thanksgiving: closes at 2 p.m.; closed on Christmas Day and New Year's Day.","zh":"2026 年秋季：每天 7:30–21:00。热菜吧早餐 7:30 到 10 点左右，午餐晚餐大约 11:00–20:00。感恩节 14:00 关门，圣诞节和元旦不营业。"},"sum":{"en":"Customer-owned grocery co-op on Williamson St: local and organic food, a big bulk section and a hot bar. Anyone can shop.","zh":"Williamson St 上的顾客合作社超市：本地有机食品、大散装区和热菜吧，谁都能来买。"},"kw":["Willy Street Co-op","co-op","合作社","organic","有机","bulk","散装","hot bar","热菜","local food","本地食品","grocery","超市"],"sec":{"about":{"en":["Willy Street Co-op is a grocery cooperative owned by its customers. Its stores focus on food that is locally grown or made, organic and sustainable. Everyone can shop there; people who buy an ownership share (Owners) get extra discounts. Willy East is on Williamson Street; the co-op also runs Willy West in Middleton and Willy North on Sherman Avenue."],"zh":["Willy Street Co-op 是一家由顾客共同拥有的合作社超市，主打本地种植或本地制造、有机、可持续的食品。谁都可以来买东西，买了股份的会员（Owner）另有折扣。东店在 Williamson Street，另外还有 Middleton 的西店和 Sherman Avenue 的北店。"]},"offers":{"en":["Large bulk department: rice, beans, pasta, flour, herbs, spices, olive oil and honey, sold by weight so you can buy just what you need","Hot bar with breakfast and with lunch and dinner every day","Deli and bakery, meat, seafood, cheese and produce departments","Wellness and body care products","Beer, wine and spirits","Online store with delivery or pickup at Willy North"],"zh":["大散装区：大米、豆子、意面、面粉、香草香料、橄榄油、蜂蜜，按重量卖，要多少买多少","热菜吧每天供应早餐和午晚餐","熟食烘焙、肉类、海鲜、奶酪和蔬果","保健品和身体护理用品","啤酒、葡萄酒和烈酒","网上商店可送货，也可到北店（Willy North）自取"]},"howto":{"en":["To become an Owner, fill in the Fair Share Contract and pay at the Customer Service desk or online. You can shop as an Owner right after the first payment; pick up your Owner card at Customer Service.","Show your Owner card or tell the cashier your Owner number every time you shop.","Online orders: delivery, or pickup at Willy North (2817 N Sherman Ave). Hot bar food cannot be ordered online."],"zh":["想当会员：填 Fair Share Contract（入股协议），在服务台或网上付款。第一次付款后马上就能按会员身份购物，会员卡去服务台领。","每次结账出示会员卡，或者报会员号。","网上订单可以送货，或去北店（2817 N Sherman Ave）自取。热菜吧的菜不能网上买。"]},"cost":{"en":["Ownership is an equity share, not a yearly fee: $56 for an individual (all at once or $8 a year) or $91 for a household (all at once or $13 a year). Each payment has a $2 non-refundable fee, and the equity is refundable if you leave.","The co-op says Owners who spend $40 a week save about $102 a year on Owner-only sales.","Access Program: Owners with financial need (for example FoodShare/SNAP, WIC or SSI, or income at or below 150% of the federal poverty guideline) get 10% off and can pay their share in smaller amounts."],"zh":["会员是入股，不是年费：个人 $56（可一次付清，或每年付 $8），家庭 $91（或每年付 $13）。每次付款另收 $2 不退的手续费；退出时股金可以退。","合作社说，每周花 $40 的会员，一年靠会员专享特价大约能省 $102。","Access Program：有经济困难的会员（比如领 FoodShare/SNAP、WIC、SSI，或收入在联邦贫困线 150% 以下）买东西打九折，股金也可以分小额付。"]},"tips":{"en":["All three stores keep the same hours: Willy West is at 6825 University Ave in Middleton and Willy North at 2817 N Sherman Ave.","Buying a small amount of a spice or grain from bulk is often cheaper than a full package, which helps when you are cooking for one.","Regent Market Co-op says membership is reciprocal there, so mention your Willy Street ownership at its checkout."],"zh":["三家店营业时间一样：西店在 Middleton 的 6825 University Ave，北店在 2817 N Sherman Ave。","香料、杂粮从散装区少量买，往往比买整包便宜，一个人做饭很合适。","Regent Market Co-op 说会员资格互认，在那边结账时报一下你是 Willy Street 会员。"]}},"src":[["Willy Street Co-op - Store Locations and Hours","https://www.willystreet.coop/store-locations-and-hours/"],["Willy Street Co-op - Hot Bar Menus","https://www.willystreet.coop/hot-bar-menus/"],["Willy Street Co-op - Co-op Ownership","https://www.willystreet.coop/ownership/"],["Willy Street Co-op - Benefits of Becoming an Owner","https://www.willystreet.coop/ownership/benefits-of-becoming-an-owner/"],["Willy Street Co-op - Access Program","https://www.willystreet.coop/ownership/access-program/"],["Willy Street Co-op - Bulk department","https://www.willystreet.coop/about/departments/bulk"],["Willy Street Co-op - online store","https://shop.willystreet.coop/online/north/home"],["Regent Market Co-op - Membership","https://regentmarketcoop.com/membership/"]],"unv":[],"chk":"2026-10-08","lat":43.083536,"lng":-89.362753,"stops":[["S Baldwin at Williamson",83,"C 38"],["Jenifer at S Few",104,"C 38"],["Williamson at S Baldwin",128,"C 38"]]},{"id":"woodmans-madison-east","cat":"grocery","n":{"en":"Woodman's Market (Madison East)","zh":"Woodman's 超市（东店）"},"kind":{"en":"24-hour supermarket","zh":"24 小时大超市"},"addr":"3817 Milwaukee St, Madison, WI 53714","phone":"(608) 244-6630","web":"https://www.woodmans-food.com/store-locations/madison-east/","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1440]],"Sa":[[0,1440]],"Su":[[0,1440]]},"ht":{"en":"Grocery store open 24 hours (fall 2026). Liquor store 8 a.m.–8:45 p.m. daily. Closed Thanksgiving from 2 p.m. to 6 a.m. the next day, from 6 p.m. Dec 24 to 6 a.m. Dec 26, and from 8 p.m. Dec 31 to 9 a.m. Jan 1.","zh":"超市 24 小时营业（2026 年秋季）；酒类店每天 8:00–20:45。感恩节 14:00 关门到次日 6:00，12 月 24 日 18:00 到 26 日 6:00 关门，12 月 31 日 20:00 到 1 月 1 日 9:00 关门。"},"sum":{"en":"Huge employee-owned grocery on the east side, open 24 hours. In-store, the only credit card accepted is Discover.","zh":"东边的员工持股超大超市，24 小时营业。店内信用卡只收 Discover。"},"kw":["Woodman's","grocery","超市","24 hours","24小时","cheap","便宜","bulk","大包装","Milwaukee Street","east side","东边","Discover"],"sec":{"about":{"en":["Woodman's is an employee-owned Wisconsin grocery chain founded in 1919. Its stores sell only groceries, not clothing or housewares, and the company says it aims for the widest variety of grocery items at the best prices. The Madison East store is open 24 hours and also has a liquor store, a gas and lube station and a car wash."],"zh":["Woodman's 是 1919 年创立的威斯康星连锁超市，由员工持股。它只卖食品杂货，不卖衣服家居，公司自己的说法是要做到品种最多、价格最好。东店 24 小时营业，旁边还有酒类店、加油换机油站和洗车。"]},"offers":{"en":["Groceries around the clock, 24 hours a day","Sushi counter","Liquor store, 8 a.m.–8:45 p.m.","License plate renewal kiosk","Free Wi-Fi and self-checkouts","Gas and lube station and a 24-hour car wash","ShopWoodmans.com online orders for pickup or delivery"],"zh":["24 小时随时能买菜","寿司柜台","酒类店 8:00–20:45","车牌续期自助机","免费 Wi-Fi 和自助收银","加油换机油站和 24 小时洗车","ShopWoodmans.com 网上下单，自取或送货"]},"howto":{"en":["In the store you can pay with cash, checks, PIN debit cards, Discover credit cards, WIC and EBT. Visa, Mastercard and American Express credit cards are not accepted at the register.","Online orders at ShopWoodmans.com or in the ShopWoodman's app accept all major credit cards, debit cards and EBT.","Bring reusable bags if you like; they can be used at any register.","No smartphone for digital coupons? Make a free ShopWoodmans.com account, clip coupons there and give the cashier your Shopper ID."],"zh":["店里付款可以用现金、支票、要输 PIN 的借记卡、Discover 信用卡、WIC 和 EBT。Visa、Mastercard、American Express 信用卡在收银台刷不了。","在 ShopWoodmans.com 或 ShopWoodman's app 网上下单，可以用各大信用卡、借记卡和 EBT。","可以自带环保袋，所有收银台都能用。","没有智能手机领电子优惠券？免费注册 ShopWoodmans.com 账户，在上面领券，结账时报 Shopper ID 就行。"]},"cost":{"en":["ShopWoodmans.com prices often differ from shelf prices in the store, so the same item can cost a different amount online.","Woodman's is partnered with Ibotta and other cash-back apps."],"zh":["ShopWoodmans.com 的价格经常和店里不一样，同一件东西网上可能更贵或更便宜。","Woodman's 和 Ibotta 等返现 app 有合作。"]},"tips":{"en":["There is no pharmacy at Woodman's.","Online shopping (pickup and delivery) runs 8 a.m.–10 p.m. daily, but you can place the order any time."],"zh":["Woodman's 没有药房。","网购取货和送货时间是每天 8:00–22:00，下单任何时间都可以。"]},"intl":{"en":["A Visa or Mastercard credit card from home will not work at the register. Bring cash or a debit card you can use with a PIN, or order online with your credit card."],"zh":["国内带来的 Visa 或 Mastercard 信用卡在收银台刷不了。带现金或能输 PIN 的借记卡，或者用信用卡在网上下单。"]}},"src":[["Woodman's Madison (East) - store page","https://www.woodmans-food.com/store-locations/madison-east/"],["Woodman's - Frequently Asked Questions","https://www.woodmans-food.com/frequently-asked-questions/"],["Woodman's - Store Locations","https://www.woodmans-food.com/store-locations/"]],"unv":[],"chk":"2026-10-08","lat":43.096993,"lng":-89.318812,"stops":[["Milwaukee at Dempsey",139,"D G L 61"],["Dempsey at Milwaukee",152,"G"],["Milwaukee at W Corporate",230,"D G L 61"]]},{"id":"woodmans-madison-west","cat":"grocery","n":{"en":"Woodman's Market (Madison West)","zh":"Woodman's 超市（西店）"},"kind":{"en":"24-hour supermarket","zh":"24 小时大超市"},"addr":"725 S Gammon Rd, Madison, WI 53719","phone":"(608) 274-8944","web":"https://www.woodmans-food.com/store-locations/madison-west/","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1440]],"Sa":[[0,1440]],"Su":[[0,1440]]},"ht":{"en":"Grocery store open 24 hours (fall 2026). Liquor store 8 a.m.–8:45 p.m. daily; gas station staffed 8:15 a.m.–6:45 p.m. Closed Thanksgiving from 2 p.m. to 6 a.m. the next day, from 6 p.m. Dec 24 to 6 a.m. Dec 26, and from 8 p.m. Dec 31 to 9 a.m. Jan 1.","zh":"超市 24 小时营业（2026 年秋季）；酒类店每天 8:00–20:45，加油站有人值守 8:15–18:45。感恩节 14:00 关门到次日 6:00，12 月 24 日 18:00 到 26 日 6:00 关门，12 月 31 日 20:00 到 1 月 1 日 9:00 关门。"},"sum":{"en":"West-side Woodman's: huge employee-owned grocery, open 24 hours. In-store, the only credit card accepted is Discover.","zh":"西边的 Woodman's 员工持股超大超市，24 小时营业。店内信用卡只收 Discover。"},"kw":["Woodman's","grocery","超市","24 hours","24小时","cheap","便宜","bulk","大包装","Gammon Road","west side","西边","Discover"],"sec":{"about":{"en":["The west-side store of Woodman's, an employee-owned Wisconsin grocery chain founded in 1919. Woodman's sells only groceries, not clothing or housewares, and says it aims for the widest variety of grocery items at the best prices. This store is open 24 hours and has a liquor store, a sushi counter, a gas station and EV charging."],"zh":["这是 Woodman's 的西店。Woodman's 是 1919 年创立、员工持股的威斯康星连锁超市，只卖食品杂货，不卖衣服家居，公司说要做到品种最多、价格最好。这家店 24 小时营业，有酒类店、寿司柜台、加油站和电动车充电桩。"]},"offers":{"en":["Groceries around the clock, 24 hours a day","Sushi counter","Liquor store, 8 a.m.–8:45 p.m.","License plate renewal kiosk","Free Wi-Fi, self-checkouts and electric vehicle charging","ShopWoodmans.com online orders for pickup or delivery"],"zh":["24 小时随时能买菜","寿司柜台","酒类店 8:00–20:45","车牌续期自助机","免费 Wi-Fi、自助收银和电动车充电","ShopWoodmans.com 网上下单，自取或送货"]},"howto":{"en":["In the store you can pay with cash, checks, PIN debit cards, Discover credit cards, WIC and EBT. Visa, Mastercard and American Express credit cards are not accepted at the register.","Online orders at ShopWoodmans.com accept all major credit cards, debit cards and EBT.","Bring reusable bags if you like; they can be used at any register."],"zh":["店里付款可以用现金、支票、要输 PIN 的借记卡、Discover 信用卡、WIC 和 EBT。Visa、Mastercard、American Express 信用卡在收银台刷不了。","在 ShopWoodmans.com 网上下单可以用各大信用卡、借记卡和 EBT。","可以自带环保袋，所有收银台都能用。"]},"cost":{"en":["ShopWoodmans.com prices often differ from shelf prices in the store.","Gas pumps work 24 hours, but only with PIN debit cards or Discover credit cards."],"zh":["ShopWoodmans.com 的价格经常和店里货架价格不一样。","加油机 24 小时可用，但只认要输 PIN 的借记卡或 Discover 信用卡。"]},"tips":{"en":["There is no pharmacy at Woodman's.","Local guides list more international groceries on the same road: India House at 709 S Gammon Rd (Indian) and Istanbul Supermarket at 745 S Gammon Rd (Turkish and halal). Check they are open before you go."],"zh":["Woodman's 没有药房。","同一条路上还有别的国际超市，本地指南里列了 709 S Gammon Rd 的 India House（印度货）和 745 S Gammon Rd 的 Istanbul Supermarket（土耳其和清真食品），去之前先确认还开着。"]},"intl":{"en":["A Visa or Mastercard credit card from home will not work at the register. Bring cash or a debit card you can use with a PIN, or order online with your credit card."],"zh":["国内带来的 Visa 或 Mastercard 信用卡在收银台刷不了。带现金或能输 PIN 的借记卡，或者用信用卡在网上下单。"]}},"src":[["Woodman's Madison (West) - store page","https://www.woodmans-food.com/store-locations/madison-west/"],["Woodman's - Frequently Asked Questions","https://www.woodmans-food.com/frequently-asked-questions/"],["Woodman's - Store Locations","https://www.woodmans-food.com/store-locations/"],["UW Bridge to the Chemistry Doctorate - Ethnic Grocery Stores in the Madison Area","https://bridge.chem.wisc.edu/local-info-2/ethnic-grocery-stores-in-the-madison-area/"],["BRAVA Magazine - Madison's International Markets (Dec 2023)","https://bravamagazine.com/?p=30472"]],"unv":[],"chk":"2026-10-08","lat":43.048952,"lng":-89.503049,"stops":[["S Gammon at Watts",111,"D H 64"],["Watts at S Gammon",159,"D"],["S Gammon at Schroeder",273,"D H 62 64"]]},{"id":"bursars-office","cat":"campus","n":{"en":"Bursar's Office","zh":"学费账单办公室 (Bursar's Office)"},"kind":{"en":"Tuition billing office","zh":"学费缴费办公室"},"addr":"333 East Campus Mall, Madison, WI 53715","phone":"(608) 262-3611","web":"https://bursar.wisc.edu/","h":{"Mo":[[480,960]],"Tu":[[480,960]],"We":[[480,960]],"Th":[[480,960]],"Fr":[[480,960]],"Sa":[],"Su":[]},"ht":{"en":"Virtual service (phone and email) Mon–Fri 8 a.m.–4 p.m. The website lists no walk-in counter hours; pay online or use the drop box in the first-floor lobby.","zh":"线上服务（电话、邮件）周一到周五 8:00–16:00。官网没有列出现场柜台时间；交费走网上，或者投一楼大厅的投递箱。"},"sum":{"en":"Sends your tuition bill (eBill) and handles payments, refunds and payment plans. Pay by eCheck: no fee, while cards cost 2.95–4.25%.","zh":"发学费账单，管缴费、退款和分期。用 eCheck 付没有手续费，刷卡要 2.95%–4.25%。"},"kw":["bursar","tuition","学费","eBill","payment","交学费","eCheck","Flywire","Convera","refund","退款","BadgerPay","分期","hold"],"sec":{"about":{"en":["The Bursar's Office bills and collects tuition, fees and housing charges, posts financial aid and scholarships to your student account, and issues refunds. Its office is Suite 10501 at 333 East Campus Mall, but service is virtual, and email is the fastest way to reach staff.","You view and pay your bill in MyUW Student Center (Financial Account > Manage My Payment), which opens the eBill/ePayment site. For most students, fall and spring payments are due on the second Friday of the semester; for fall 2026 the due date was September 11."],"zh":["Bursar's Office 负责学费、杂费和宿舍费的账单和收款，把助学金、奖学金记到你的学生账户，也负责退款。办公室在 333 East Campus Mall 的 Suite 10501，但服务都在线上，发邮件最快。","账单在 MyUW 的 Student Center 里看和付（Financial Account → Manage My Payment，会打开 eBill/ePayment 网站）。大多数学生秋季、春季的缴费截止日是开学第二个周五；2026 秋季是 9 月 11 日。"]},"offers":{"en":["eBill for tuition, fees and housing charges, published in Student Center before each term.","Online payment by eCheck, 529 plan, U.S. or international card, or foreign currency through Convera or Flywire.","BadgerPay plan: pay the term in three installments (fall 2026: Sept 11, Oct 9 and Nov 6).","Authorized payer logins so parents can view your bills and pay online.","eRefund (direct deposit) of extra financial aid or tuition credits to a U.S. bank account.","Help with Bursar holds and late payment fee appeals."],"zh":["每学期开学前在 Student Center 发 eBill，含学费、杂费和宿舍费。","网上缴费：eCheck、529 计划、美国或国际银行卡，或者通过 Convera / Flywire 用外币付。","BadgerPay 分期：一学期分 3 期付（2026 秋季：9/11、10/9、11/6）。","给爸妈开授权付款人 (authorized payer) 账号，他们能自己看账单、网上付款。","eRefund 直存：多出来的助学金或学费退款打进美国银行账户。","处理 Bursar 的 hold 和滞纳金申诉。"]},"howto":{"en":["Pay in MyUW Student Center: Financial Account > Manage My Payment. Turn off your pop-up blocker; Safari is not supported.","To pay with no fee, save a U.S. checking or savings account as an eCheck method a few days before the due date, and double-check the routing and account numbers.","Paying from abroad: choose Foreign Currency, then Convera or Flywire, and send the bank transfer early; the payment posts once UW receives the funds, typically in 2–5 business days.","Paper checks: write your full name and 10-digit Campus ID on the check and put it in the drop box in the first-floor lobby near the elevators, or mail it to Suite 10501. No cash.","Questions: email tuition@bussvc.wisc.edu (fastest) or call (608) 262-3611."],"zh":["在 MyUW 的 Student Center 付：Financial Account → Manage My Payment。要关掉弹窗拦截，不支持 Safari 浏览器。","想零手续费就用 eCheck：提前几天把美国的支票或储蓄账户存成付款方式，核对好 routing number 和账号。","从国外付款：付款方式选 Foreign Currency，再选 Convera 或 Flywire，早点汇款；学校收到钱才入账，一般要 2–5 个工作日。","纸质支票：写上全名和 10 位 Campus ID，投到一楼大厅电梯旁的投递箱，或寄到 Suite 10501。不收现金。","有问题发邮件 tuition@bussvc.wisc.edu（最快），或打 (608) 262-3611。"]},"cost":{"en":["eCheck: no fee. A returned eCheck costs a $20 nonrefundable fee.","Cards: 2.95% on U.S. cards and 4.25% on international cards, both nonrefundable; card payments between $20 and $106 have a $3 minimum fee.","Late payment: $100 if the eBill is not paid in full by the due date. You can appeal, but only after the balance is paid.","Unpaid balances can bring holds that block enrollment, and some also block transcripts and diplomas."],"zh":["eCheck 免手续费；被银行退回的 eCheck 罚 20 美元，不退。","刷卡：美国卡 2.95%，国际卡（国内办的卡也算）4.25%，都不退；20 到 106 美元之间的刷卡最低收 3 美元。","逾期：到期没付清罚 100 美元滞纳金。可以申诉，但要先把欠款付清。","欠款会带来 hold，卡住选课，有的还会卡成绩单和毕业证。"]},"tips":{"en":["On a $20,000 bill, the 4.25% international card fee would be $850; an eCheck from a U.S. bank account costs nothing.","Financial aid and scholarships are applied to your account first; only the amount above your balance is refunded.","The Bursar does not take Wiscard deposits; add Wiscard money online or at the Wiscard Office.","Sign up for eRefund before you need it: refunds post to your bank within 1–3 business days of processing."],"zh":["账单 2 万美元的话，4.25% 的国际卡手续费就是 850 美元；用美国银行账户走 eCheck 一分不花。","助学金和奖学金先抵账单，超出余额的部分才退给你。","Bursar 不收 Wiscard 充值；Wiscard 去网上或 Wiscard Office 充。","提前开通 eRefund：退款处理后 1–3 个工作日到账。"]},"intl":{"en":["eRefunds go only to checking or savings accounts at U.S. banks; UW cannot send money to foreign bank accounts.","No U.S. bank account yet? Open one near campus: it lets you pay by eCheck and receive eRefunds.","Embassies and sponsors that pay your tuition are third-party payers and cannot be set up as authorized payers."],"zh":["eRefund 只能打进美国银行的支票或储蓄账户，学校没法把钱汇到国外账户。","还没有美国银行账户的话，在学校附近开一个：有了才能用 eCheck 付款、收 eRefund。","使馆或资助机构替你交学费属于第三方付款 (third party)，不能设成 authorized payer。"]}},"src":[["Bursar's Office - home","https://bursar.wisc.edu/"],["Bursar's Office - About","https://bursar.wisc.edu/about/"],["Bursar's Office - Student Account","https://bursar.wisc.edu/student-tuition-account"],["Bursar's Office - Payment Methods","https://bursar.wisc.edu/student-tuition-account/payment-methods/"],["Bursar's Office - ePayments (online payment)","https://bursar.wisc.edu/student-tuition-account/payment-methods/epayments-online-payment/"],["Bursar's Office - Holds","https://bursar.wisc.edu/holds/"],["Bursar's Office - eRefund (Direct Deposit)","https://bursar.wisc.edu/refunds/erefund-direct-deposit/"]],"unv":[],"chk":"2026-10-08","lat":43.072489,"lng":-89.398931,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"cross-college-advising-service","cat":"campus","n":{"en":"Cross-College Advising Service (CCAS)","zh":"跨学院学业咨询中心 (CCAS)"},"kind":{"en":"Academic advising office","zh":"学业咨询办公室"},"addr":"1155 Observatory Dr, Madison, WI 53706","phone":"(608) 265-5460","web":"https://ccas.wisc.edu/","h":{"Mo":[[510,990]],"Tu":[[510,990]],"We":[[660,990]],"Th":[[510,990]],"Fr":[[510,990]],"Sa":[],"Su":[]},"ht":{"en":"Main office, 10 Ingraham Hall: Mon, Tue, Thu, Fri 8:30 a.m.–4:30 p.m.; Wed 11 a.m.–4:30 p.m. Residence hall offices: drop-ins and appointments Mon–Thu 12:30–4:30 p.m. while fall and spring classes are in session. Evening drop-ins at College Library in November and April.","zh":"主办公室（Ingraham Hall 10 室）：周一、二、四、五 8:30–16:30；周三 11:00–16:30。宿舍楼办公室：秋季、春季上课期间周一到周四 12:30–16:30 有 drop-in 和预约。11 月和 4 月晚上在 College Library 也有 drop-in。"},"sum":{"en":"Academic advising for undergraduates exploring majors, and a first stop for any undergrad with questions about classes, majors or where to go.","zh":"给还在选专业的本科生做学业咨询；任何本科生对选课、专业或该找谁有疑问，都可以先来这里。"},"kw":["CCAS","advising","学业咨询","advisor","导师","major","专业","declare","选专业","undecided","choosing classes","选课","Starfish","Ingraham Hall"],"sec":{"about":{"en":["The Cross-College Advising Service advises undergraduates who are exploring majors and is the hub for information about degree programs in every undergraduate school and college. Incoming students are assigned an advisor at SOAR; you can see your assigned advisor in Student Center.","The main office is Room 10 on the ground level of Ingraham Hall, behind Bascom Hall. Five more offices are in residence halls (Chadbourne, Dejope, Ogg, Sellery and Witte) for drop-ins and appointments."],"zh":["跨学院学业咨询中心 (CCAS) 给还在探索专业的本科生做学业咨询，也是全校各本科学院专业信息的汇总点。新生在 SOAR 入学指导时就会分到 advisor；你的 advisor 是谁可以在 Student Center 查到。","主办公室在 Bascom Hall 后面 Ingraham Hall 地面层的 10 室。另外 5 栋宿舍楼（Chadbourne、Dejope、Ogg、Sellery、Witte）里也有办公室，可以 drop-in 或预约。"]},"offers":{"en":["Advising on choosing, adding and dropping classes, exploring majors, applying to limited-enrollment majors and declaring a major.","Help with academic probation, summer classes and readmission.","Drop-in conversations of about 10 minutes with no appointment, open to all undergraduates.","In-person or Zoom appointments with a CCAS advisor.","INTER-LS 139, a 1-credit course for undecided and exploring students in their first year.","Career advising through the Career Exploration Center, and referrals to other campus resources."],"zh":["选课、加退课、探索专业、申请限额专业 (limited-enrollment)、申报 (declare) 专业。","学业警告 (academic probation)、暑期课程、重新入学方面的帮助。","约 10 分钟的 drop-in 聊天，不用预约，所有本科生都能来。","和 CCAS advisor 当面或 Zoom 预约面谈。","INTER-LS 139：给大一还没定专业的学生开的 1 学分课。","通过 Career Exploration Center 做职业咨询，也帮你转介其他校园资源。"]},"howto":{"en":["Assigned to CCAS: open the Starfish tile in MyUW, click your advisor under Your Connections, and book.","Not assigned to CCAS: book any CCAS advisor through the CCAS Starfish calendar, or submit the appointment request form and staff will schedule you.","Drop-in rooms, Mon–Thu 12:30–4:30 p.m.: Chadbourne 101B (Wed and Thu only), Dejope 1130, Ogg 1116 (Mon and Tue only), Sellery 145, Witte 124.","For an in-person appointment at Ingraham Hall, check in at the front desk."],"zh":["分到 CCAS 的同学：在 MyUW 打开 Starfish，在 Your Connections 里点你的 advisor 预约。","没分到 CCAS 的同学：用 CCAS 的 Starfish 日历约任意 advisor，或者提交预约申请表，由前台帮你排。","Drop-in 地点，周一到周四 12:30–16:30：Chadbourne 101B（仅周三、四）、Dejope 1130、Ogg 1116（仅周一、二）、Sellery 145、Witte 124。","到 Ingraham Hall 当面预约，先去前台签到。"]},"cost":{"en":["Drop-in advising is open to all undergraduates, whatever school or college they are in.","INTER-LS 139 carries 1 credit."],"zh":["Drop-in 对所有本科生开放，不管你在哪个学院。","INTER-LS 139 是 1 学分的课。"]},"tips":{"en":["Drop-ins are about 10 minutes; book an appointment for longer planning.","In November and April, evening drop-ins run Mon–Thu 5–7 p.m. at College Library, first floor behind the information desk.","Not sure where to go? Start with CCAS: advisors can answer questions from students of any major."],"zh":["Drop-in 大约 10 分钟；要做长一点的规划就预约。","11 月和 4 月周一到周四 17:00–19:00，College Library 一楼问讯台后面有晚间 drop-in。","不知道去哪问，就先找 CCAS：任何专业的学生都可以来问。"]}},"src":[["CCAS - Hours & Locations","https://ccas.wisc.edu/hours/"],["CCAS - Start Exploring","https://ccas.wisc.edu/start/"],["CCAS - Advising with CCAS","https://ccas.wisc.edu/ccas-advising/"],["CCAS - Get Advising","https://ccas.wisc.edu/get-advising/"]],"unv":[],"chk":"2026-10-08","lat":43.075553,"lng":-89.405212,"stops":[["Observatory at N Charter",74,"80 82"],["Linden at N Charter",115,"28 38 65 80"],["Observatory at Bascom",135,"80 82"]]},{"id":"gender-and-sexuality-campus-center","cat":"campus","n":{"en":"Gender and Sexuality Campus Center (GSCC)","zh":"性别与性取向校园中心 (GSCC)"},"kind":{"en":"LGBTQ+ student center","zh":"LGBTQ+ 学生中心"},"addr":"716 Langdon St, Madison, WI 53706","phone":"(608) 265-3344","web":"https://lgbt.wisc.edu/","h":{"Mo":[[540,1020]],"Tu":[[540,1140]],"We":[[540,1140]],"Th":[[540,1140]],"Fr":[[540,1020]],"Sa":[],"Su":[]},"ht":{"en":"Drop-in Mon and Fri 9 a.m.–5 p.m., Tue–Thu 9 a.m.–7 p.m., or by appointment. Another section of the GSCC site gives a 10 a.m. start on Tue–Thu, so call ahead before an early visit.","zh":"Drop-in：周一、周五 9:00–17:00，周二到周四 9:00–19:00，也可以预约。官网另一处写周二到周四 10:00 开门，早上去之前先打电话确认。"},"sum":{"en":"LGBTQ+ student center in the Red Gym: a lounge to study or relax, confidential conversations with staff, a lending library and community events.","zh":"Red Gym 里的 LGBTQ+ 学生中心：可以自习放松，和工作人员保密聊天，有借书库和社区活动。"},"kw":["GSCC","LGBTQ","LGBT","queer","酷儿","gender","性别","sexuality","coming out","出柜","pronouns","代词","Red Gym"],"sec":{"about":{"en":["The Gender and Sexuality Campus Center supports LGBTQ+ students and their communities through education, outreach, advocacy and resources, and welcomes allies too. Its space is Room 137 in the Red Gym, with couches, two big TVs, a quiet room, a conference room and a library.","Students come to study, eat lunch, do crafts, play games or talk with student staff in the open space; professional staff offer confidential conversations and advising."],"zh":["性别与性取向校园中心 (GSCC) 通过教育、宣传、维权和资源支持 LGBTQ+ 学生和他们的社群，也欢迎支持者 (allies)。地点在 Red Gym 137 室，有沙发、两台大电视、安静小间、会议室和图书角。","学生来这里自习、吃午饭、做手工、玩游戏，或者在开放区跟学生员工聊天；专职工作人员提供保密的谈话和咨询。"]},"offers":{"en":["A drop-in lounge to relax, study, nap, print documents or play board games.","Confidential conversations about identity, coming out, finding resources or hard situations, drop-in or by appointment (by phone, in the office or elsewhere on campus).","A small quiet room and a conference room for studying, practicing presentations or meetings.","A lending library of books and materials.","Let's Talk with a UHS counselor in the GSCC Quiet Room, Wednesdays 2:30–4:30 p.m. (fall 2026).","Events such as National Coming Out Day (Oct 9, 2026, on Library Mall), plus a Discord server and a newsletter.","Guides on pronouns, an all-gender restroom map, and name and gender change materials."],"zh":["Drop-in 休息区：放松、自习、打个盹、打印文件、玩桌游都行。","保密谈话：身份认同、出柜、找资源或遇到难处，都可以 drop-in 或预约（电话、办公室或校园任何地方）。","安静小间和会议室，可以自习、练习演讲或开会。","图书角可以借书和资料。","Let's Talk：UHS 心理咨询师在 GSCC Quiet Room，2026 秋季每周三 14:30–16:30。","活动：比如 2026 年 10 月 9 日在 Library Mall 的 National Coming Out Day；还有 Discord 群和周报。","资源指南：代词、全性别厕所地图、改名和性别标记的材料。"]},"howto":{"en":["Walk in to Red Gym Room 137 (716 Langdon St) during drop-in hours.","For an appointment, call (608) 265-3344 or email lgbtq@studentaffairs.wisc.edu.","To use a different first name on campus, set a name in use in MyUW; it replaces your legal name in many campus systems. Legal name changes go through the Registrar."],"zh":["drop-in 时间直接去 Red Gym 137 室（716 Langdon St）。","预约打 (608) 265-3344，或发邮件 lgbtq@studentaffairs.wisc.edu。","想在学校用别的名字，就在 MyUW 设置常用名 (name in use)，很多校内系统会用它代替法定姓名。改法定姓名走教务处 (Registrar)。"]},"cost":{"en":["Let's Talk sessions are free for UW–Madison students.","The center serves UW–Madison student communities and their allies."],"zh":["Let's Talk 对 UW–Madison 学生免费。","服务对象是 UW–Madison 的学生社群和他们的支持者 (allies)。"]},"tips":{"en":["Crisis support any time: UHS 24-hour line (608) 265-5600, option 9.","The Red Gym is under exterior restoration (October 2026); enter through the front doors beneath the scaffolding.","The GSCC KnowledgeBase and Discord server are linked from the GSCC home page if you want to look around before visiting."],"zh":["任何时候需要危机帮助：UHS 24 小时热线 (608) 265-5600 选 9。","Red Gym 外墙在翻修（2026 年 10 月），从脚手架下面的正门进。","想先了解再过去，GSCC 首页有 KnowledgeBase 和 Discord 群的链接。"]},"intl":{"en":["A name in use does not change your legal name (the name on your passport), which still appears on transcripts, payroll and federal immigration documents; ask your ISS advisor about names on immigration papers."],"zh":["常用名不会改变法定姓名（护照上的名字）；成绩单、工资单和联邦移民文件上还是法定姓名。移民文件上的姓名问题问你的 ISS advisor。"]}},"src":[["Gender and Sexuality Campus Center - home","https://lgbt.wisc.edu/"],["GSCC - About the GSCC","https://lgbt.wisc.edu/about-the-cc/"],["Multicultural Student Center - Support for students (Let's Talk schedule)","https://msc.wisc.edu/student_resources/"],["Office of the Registrar - Personal Information in UW Records","https://registrar.wisc.edu/personal-info/"],["International Academic Programs - home (Red Gym restoration notice)","https://studyabroad.wisc.edu/"]],"unv":["hours"],"chk":"2026-10-08","lat":43.07632,"lng":-89.398488,"stops":[["N Lake at Langdon",137,"80 82"],["Langdon at N Park",142,"80 82"],["Langdon at N Lake",144,"81"]]},{"id":"international-academic-programs","cat":"campus","n":{"en":"International Academic Programs (Study Abroad)","zh":"海外学习项目办公室 (International Academic Programs)"},"kind":{"en":"Study abroad office","zh":"出国交换办公室"},"addr":"716 Langdon St, Madison, WI 53706","phone":"(608) 265-6329","web":"https://studyabroad.wisc.edu/","h":{"Mo":[[480,990]],"Tu":[[480,990]],"We":[[480,990]],"Th":[[480,990]],"Fr":[[480,990]],"Sa":[],"Su":[]},"ht":{"en":"Mon–Fri 8 a.m.–4:30 p.m., 301 Red Gym. Advising is by appointment through Starfish (in person, Zoom or phone).","zh":"周一到周五 8:00–16:30，Red Gym 301 室。咨询要在 Starfish 预约（到场、Zoom 或电话都行）。"},"sum":{"en":"UW's study abroad office: helps students of any major choose a program, apply, transfer credits and fund a semester, summer or internship abroad.","zh":"学校的出国交换办公室：帮任何专业的学生挑项目、申请、转学分、找经费，学期、暑期、海外实习都有。"},"kw":["study abroad","出国交换","exchange","交换","IAP","international internship","海外实习","Red Gym","scholarship","奖学金","Global Gateway","Starfish"],"sec":{"about":{"en":["International Academic Programs (IAP) runs UW–Madison's study abroad and international internship advising for students of all majors. The office is Room 301 in the Red Gym; drop-in sessions take place in the Study Abroad Resource Center on the third floor.","Students in the College of Agricultural and Life Sciences and the Wisconsin School of Business start with their own college's study abroad office; engineering programs are run in partnership with IAP."],"zh":["海外学习项目办公室 (International Academic Programs, IAP) 负责 UW–Madison 所有专业学生的出国交换和海外实习咨询。办公室在 Red Gym 301 室；drop-in 在三楼的 Study Abroad Resource Center。","农学院 (CALS) 和商学院 (Wisconsin School of Business) 的学生先找本学院的出国办公室；工学院的项目和 IAP 合办。"]},"offers":{"en":["Exploration advising to learn about program options, narrow them down and understand the process.","Program advising on academics, housing, visas, health and safety abroad, and funding and scholarships.","Application and Course Equivalency Request (CER) appointments for program eligibility and credit transfer.","International internship advising, including UW Signature Internships.","Drop-ins with an Office of Student Financial Aid advisor on using aid for study abroad.","Funding info sessions and an online Introduction to Study Abroad course in Canvas."],"zh":["Exploration advising：了解有哪些项目、缩小选择、搞懂整个流程。","项目咨询：学业、住宿、签证、海外健康安全，还有经费和奖学金。","申请和学分转换 (Course Equivalency Request, CER) 面谈：项目资格和转学分。","海外实习咨询，包括 UW Signature Internships。","财务援助办公室的顾问在这里开 drop-in，讲怎么用助学金出国。","经费讲座，以及 Canvas 上的 Introduction to Study Abroad 网课。"]},"howto":{"en":["Start with an Exploration Advising session. It is appointment only; check Starfish for open slots each day.","Quick questions: email peeradvisor@studyabroad.wisc.edu or call (608) 265-6329, Mon–Fri 8 a.m.–4:30 p.m.","Once you have chosen programs, book Program Advising, or an application/CER appointment with your Enrollment Manager.","Office: 301 Red Gym, 716 Langdon St. During the exterior restoration, use the front doors beneath the scaffolding."],"zh":["先约一次 Exploration Advising，只接预约；每天在 Starfish 上查空档。","小问题发邮件 peeradvisor@studyabroad.wisc.edu，或打 (608) 265-6329，周一到周五 8:00–16:30。","选好项目后约 Program Advising，或者找你的 Enrollment Manager 约申请/CER 面谈。","办公室：716 Langdon St 的 Red Gym 301 室。外墙翻修期间从脚手架下面的正门进。"]},"cost":{"en":["Program costs vary widely; some cost no more than a semester on campus.","You may be able to apply your financial aid to a study abroad program.","UW Global Gateway offers fellowships and fully funded summer programs."],"zh":["项目费用差别很大，有的并不比在校一学期贵。","有可能用助学金支付出国项目。","UW Global Gateway 提供奖学金 (fellowship) 和全额资助的暑期项目。"]},"tips":{"en":["Not ready for an appointment? The Introduction to Study Abroad Canvas course answers common questions.","Feeling unwell? Switch your appointment to virtual, even on short notice.","Incoming first-years can study abroad for their whole first year, or the summer before starting, through UW Global & Summer Launch."],"zh":["还没准备好预约，可以先上 Canvas 的 Introduction to Study Abroad 课程看常见问题。","身体不舒服就把预约改成线上，临时改也可以。","新生可以通过 UW Global & Summer Launch 把大一整年或入学前的暑假放在海外。"]},"intl":{"en":["F-1/J-1 students need a valid ISS travel signature on the I-20/DS-2019 to re-enter the U.S., and an F-1 or J-1 visa cannot be renewed inside the U.S.; plan visa timing with ISS before you commit to a program.","Keep your passport valid at least six months into the future; ISS recommends renewing early."],"zh":["F-1/J-1 学生回美国入境要有 ISS 在 I-20/DS-2019 上签的有效旅行签字，而且 F-1、J-1 签证不能在美国境内续签；报名项目前先和 ISS 规划好签证时间。","护照要一直保持 6 个月以上有效期；ISS 建议提前续。"]}},"src":[["International Academic Programs - home","https://studyabroad.wisc.edu/"],["International Academic Programs - Contact Us (hours and location)","https://studyabroad.wisc.edu/hours-location/"],["International Academic Programs - Advising","https://studyabroad.wisc.edu/advising/"],["International Academic Programs - Get Started","https://studyabroad.wisc.edu/get-started/"],["ISS - Travel","https://iss.wisc.edu/students/current-students/travel/"]],"unv":[],"chk":"2026-10-08","lat":43.07632,"lng":-89.398488,"stops":[["N Lake at Langdon",137,"80 82"],["Langdon at N Park",142,"80 82"],["Langdon at N Lake",144,"81"]]},{"id":"international-student-services","cat":"campus","n":{"en":"International Student Services (ISS)","zh":"国际学生服务处 (ISS)"},"kind":{"en":"Immigration advising office","zh":"国际学生签证办公室"},"addr":"702 Langdon St, Madison, WI 53706","phone":"(608) 262-2044","web":"https://iss.wisc.edu/","h":{"Mo":[[510,960]],"Tu":[[510,960]],"We":[[510,960]],"Th":[[510,960]],"Fr":[[510,960]],"Sa":[],"Su":[]},"ht":{"en":"Office open Mon–Fri 8:30 a.m.–4 p.m. Hybrid drop-in advising (Zoom or in person): Mon and Tue 2–4 p.m., Fri 9–11 a.m. (fall 2026). Other advising is by appointment, almost all virtual.","zh":"办公室周一到周五 8:30–16:00。混合 drop-in 咨询（Zoom 或到场）：周一、周二 14:00–16:00，周五 9:00–11:00（2026 秋季）。其他咨询要预约，基本都在线上。"},"sum":{"en":"UW's office for F-1/J-1 students: I-20 travel signatures, SSN letters, CPT/OPT and immigration advising, mostly requested in Terra Dotta.","zh":"F-1/J-1 学生的身份事务找这里：旅行签字、SSN 信、CPT/OPT，大多在 Terra Dotta 线上办。"},"kw":["ISS","international student","国际学生","I-20","travel signature","旅行签字","CPT","OPT","SSN","社安号","Terra Dotta","visa","签证","Pyle Center"],"sec":{"about":{"en":["International Student Services advises UW–Madison's F-1 and J-1 students on keeping their immigration status: I-20/DS-2019 documents, travel signatures, permission to work (on-campus jobs, CPT, OPT, J-1 Academic Training) and letters such as the SSN letter. Since August 2023 the office has been in the International Services suite in the Pyle Center (702 Langdon St, Suite 130), not in the Red Gym.","Almost every request is submitted online in Terra Dotta, where each student has an assigned ISS advisor. Document requests can take up to 15 business days, so apply early."],"zh":["国际学生服务处 (ISS) 负责 F-1 和 J-1 学生的身份事务：I-20/DS-2019、旅行签字、打工许可（校内工作、CPT、OPT、J-1 Academic Training），还有 SSN 信这类证明。2023 年 8 月起办公室在 Pyle Center 的 International Services 套间（702 Langdon St, Suite 130），已经不在 Red Gym 了。","几乎所有申请都在 Terra Dotta 网上提交，每个学生都有指定的 ISS advisor。文件类申请最长要 15 个工作日，早点办。"]},"offers":{"en":["Travel signature on your I-20/DS-2019 so you can re-enter the U.S.; for current students it is valid for 1 year.","UW–Madison SSN letter for students with an on-campus job, requested in Terra Dotta, for your Social Security appointment.","CPT and OPT applications: ISS reviews them in Terra Dotta; OPT then needs your own Form I-765 filing with USCIS.","Program extensions, approved reduced course loads, change of education level and other I-20 updates.","Hybrid drop-in advising for quick questions (about 5–10 minutes each) and longer appointments with your assigned advisor.","Emergency funding for F-1 students in a financial crisis, as a scholarship or loan, applied for through the Wisconsin Scholarship Hub (WiSH).","Student peer advisors on the phone line for help with Terra Dotta and campus resources (no immigration advice by phone)."],"zh":["在 I-20/DS-2019 上签旅行签字 (travel signature)，出境后才能顺利回美国；在读学生的签字有效期 1 年。","有校内工作的学生在 Terra Dotta 申请 UW–Madison SSN 信，去社安局 (SSA) 面谈时要用。","CPT、OPT 申请：ISS 在 Terra Dotta 里审核；OPT 之后还要自己向 USCIS 递 I-765 表。","延长学业期限 (program extension)、批准减课 (reduced course load)、换学位层级等 I-20 更新。","混合 drop-in 咨询解决小问题（每人约 5–10 分钟）；复杂问题约指定 advisor 面谈。","陷入经济困难的 F-1 学生可申请应急资助（奖学金或贷款），通过 Wisconsin Scholarship Hub (WiSH) 申请。","电话由学生 peer advisor 接听，帮你用 Terra Dotta、找校园资源，但电话里不做移民咨询。"]},"howto":{"en":["Submit requests and contact your advisor through Terra Dotta information requests instead of email; replies usually take 3–5 business days.","Drop-in advising runs on the QLess queue: join from the ISS Hours & Services page with a phone that can receive texts. Coming in person does not get you seen sooner.","Book longer appointments with your assigned advisor through QLess; all appointments are virtual except change of status to F or J.","Need a travel signature fast? Drop off your most recent I-20/DS-2019 at the office and it is processed within 1 business day. A reprint request in Terra Dotta takes up to 15 business days.","Office: Pyle Center, 702 Langdon St, Suite 130. For an in-person appointment, check in at the front desk."],"zh":["申请和联系 advisor 都走 Terra Dotta 的 information request，别发邮件；一般 3–5 个工作日回复。","Drop-in 用 QLess 排队：在 ISS 官网 Hours & Services 页面加入，手机要能收短信。人到现场并不会更快轮到你。","复杂问题用 QLess 约你的 advisor；除了转成 F/J 身份 (change of status)，其他预约全在线上。","急着要旅行签字就把最新的 I-20/DS-2019 送到办公室，1 个工作日内处理好；在 Terra Dotta 申请重印最长要 15 个工作日。","办公室在 Pyle Center，702 Langdon St, Suite 130；线下预约到了先去前台签到。"]},"cost":{"en":["OPT: besides the ISS step, you pay the USCIS filing fee for Form I-765.","ISS emergency funding for F-1 students is a scholarship or a loan; international students cannot use the Office of Student Financial Aid emergency form."],"zh":["OPT：除了 ISS 这一步，还要自己交 USCIS 的 I-765 申请费。","ISS 给 F-1 学生的应急资助是奖学金或贷款；国际学生不能用财务援助办公室 (OSFA) 的应急申请表。"]},"tips":{"en":["The first hour of drop-in advising is usually the busiest.","Use one channel per question. Duplicate Terra Dotta requests or calls to several staff members slow down everyone's answers.","First-semester F-1 students cannot apply for an SSN until UW registers their SEVIS record (within 30 days of the first day of the semester) and issues a new I-20 marked Continued Attendance.","CPT tightened in August 2026: ISS can only authorize CPT if the internship or practicum is required of every student in your degree program. Pre-completion OPT is the alternative. Ask ISS before accepting an internship offer.","As of October 2026, a federal judge has paused the Duration of Status rule change, and a lawsuit over the CPT guidance was filed on October 5, 2026. ISS posts updates on its home page."],"zh":["Drop-in 第一个小时通常人最多。","一个问题只走一个渠道。重复提交 Terra Dotta 或给好几位老师打电话，大家的回复都会变慢。","第一学期的 F-1 学生要等学校在 SEVIS 里完成注册（开学后 30 天内），拿到 Form Issue Reason 写着 Continued Attendance 的新 I-20，才能申请 SSN。","2026 年 8 月起 CPT 收紧：只有你的学位要求所有学生都必须实习/实践时，ISS 才能批 CPT。替代方案是 pre-completion OPT。接实习 offer 前先问 ISS。","截至 2026 年 10 月，Duration of Status 新规被联邦法官暂停；10 月 5 日还有高校组织就 CPT 新指引起诉政府。ISS 首页会持续更新。"]},"intl":{"en":["F-1 on-campus jobs are limited to 20 hours per week during fall and spring, all positions combined.","After you receive your SSN, show the card and a photo ID such as your passport at the Registrar's Office, 333 E Campus Mall, so UW can update your record.","Keep photos or paper copies of your passport, visa, latest I-20 and I-94 on your phone or in your wallet, as ISS recommends."],"zh":["F-1 学生秋季、春季学期校内打工每周最多 20 小时（所有工作加起来）。","拿到 SSN 后，带卡和护照等带照片的证件去教务处 (Registrar, 333 E Campus Mall)，让学校更新你的档案。","按 ISS 的建议，把护照、签证、最新 I-20 和 I-94 拍照存手机或复印放钱包。"]}},"src":[["International Student Services - home","https://iss.wisc.edu/"],["ISS - Hours & Services","https://iss.wisc.edu/about/hours/"],["International Division - International Services Suite Now Open (Pyle Center)","https://international.wisc.edu/international-services-suite/"],["ISS - Travel","https://iss.wisc.edu/students/current-students/travel/"],["ISS - Social Security Number (SSN)","https://iss.wisc.edu/employment/social-security/"],["ISS - F-1 Curricular Practical Training (CPT)","https://iss.wisc.edu/employment/cpt/"],["ISS - Federal Immigration Update: CPT 8/25/26","https://iss.wisc.edu/federal-immigration-curricular-practical-training-cpt-update-8-25-26/"],["ISS - CPT Lawsuit (Oct 7, 2026)","https://iss.wisc.edu/curricular-practical-training-cpt-lawsuit/"],["ISS - F-1 Employment Overview","https://iss.wisc.edu/employment/f1-employment/"],["Office of Student Financial Aid - Emergency Support","https://financialaid.wisc.edu/emergencysupport/"]],"unv":[],"chk":"2026-10-08","lat":43.076236,"lng":-89.397761,"stops":[["Langdon at N Lake",90,"81"],["N Lake at Langdon",91,"80 82"],["Langdon at N Park",197,"80 82"]]},{"id":"mcburney-disability-resource-center","cat":"campus","n":{"en":"McBurney Disability Resource Center","zh":"McBurney 残障资源中心"},"kind":{"en":"Disability accommodations office","zh":"残障支持办公室"},"addr":"702 W Johnson St, Madison, WI 53715","phone":"(608) 263-2741","web":"https://mcburney.wisc.edu/","h":{"Mo":[[480,990]],"Tu":[[480,990]],"We":[[480,990]],"Th":[[480,990]],"Fr":[[480,990]],"Sa":[],"Su":[]},"ht":{"en":"Mon–Fri 8 a.m.–4:30 p.m. Closed on university holidays, e.g. Thanksgiving, Nov 26, 2026; Nov 27 is tentatively online-only. Appointments in person, by video or by phone.","zh":"周一到周五 8:00–16:30。学校假日关门，比如 2026 年 11 月 26 日感恩节；11 月 27 日暂定只有线上服务。面谈可以到场、视频或电话。"},"sum":{"en":"Approves and arranges disability accommodations, such as extra exam time, a quieter testing room, notetaking help and accessible course materials.","zh":"认定并安排残障相关的学业便利：考试延时、安静考场、笔记辅助、无障碍教材等。"},"kw":["McBurney","disability","残障","accommodation","学业便利","extra time","考试延时","ADHD","learning disability","notetaking","笔记","McBurney Connect"],"sec":{"about":{"en":["The McBurney Center decides whether students qualify for disability-related accommodations and helps arrange them with instructors. Approval is individual: you talk with an Access Consultant and provide documentation of your disability. The center is on the second floor of 702 W Johnson St, Suite 2104, reachable by elevator.","Everything runs through McBurney Connect, the online portal where you apply, see your approved accommodations and send letters to instructors."],"zh":["McBurney Center 负责认定学生能不能获得残障相关的学业便利 (accommodations)，并和老师一起落实。审核是个案进行的：要和 Access Consultant 面谈，并提供残障证明。中心在 702 W Johnson St 二楼 Suite 2104，有电梯。","所有流程都在网上的 McBurney Connect 里完成：申请、查看已批准的便利、给老师发通知信。"]},"offers":{"en":["Alternative testing, for example extended time and a reduced-distraction room.","Notetaking accommodations: smart pens, notetaking apps or a peer notetaker.","Course materials in accessible formats, such as audio, enlarged text or braille.","Support for temporary conditions such as a broken bone or recovery from surgery, when they substantially limit major life activities.","Sign language interpreting and live captioning (CART) on campus.","An Access Consultant who verifies documentation, talks with instructors if needed and advocates for you."],"zh":["考试便利 (alternative testing)：比如延长考试时间、减少干扰的考场。","笔记便利：智能笔、笔记软件或同学帮忙记笔记 (peer notetaker)。","无障碍格式的教材：音频、大字版或盲文。","暂时性情况也能申请，比如骨折、手术后恢复，前提是严重影响日常活动。","校内的手语翻译和实时字幕 (CART)。","专属 Access Consultant：审核材料、必要时跟老师沟通、替你争取权益。"]},"howto":{"en":["Apply as early as possible with the McBurney Connect Online Student Application; you don't need documentation to start.","Your Access Consultant emails you to set up a first meeting (in person, phone or video). No email within 5 business days? Check junk mail, then contact the front desk.","Upload documentation in McBurney Connect or fax it to (608) 265-2998; documents from the last 3–5 years are preferred.","Each semester, send a Student Accommodation Letter through McBurney Connect for every course where you use accommodations, and talk with each instructor, ideally by the third week of class.","Front desk: call (608) 263-2741, text (608) 225-7956, or email; give the days and times you are free when scheduling."],"zh":["尽早在 McBurney Connect 提交网上申请 (Online Student Application)；开始申请不需要证明材料。","Access Consultant 会发邮件约第一次面谈（到场、电话或视频）。5 个工作日没收到邮件就查垃圾箱，再联系前台。","证明材料传到 McBurney Connect，或传真到 (608) 265-2998；最好是近 3–5 年的。","每学期都要在 McBurney Connect 给每门要用便利的课发 Student Accommodation Letter，并和每位老师沟通，最好在开学第三周前。","前台：电话 (608) 263-2741，短信 (608) 225-7956，或发邮件；约时间时说清楚你哪些时段有空。"]},"cost":{"en":["Eligibility: students facing a substantial barrier to their education who can document a disability. A diagnosis alone does not guarantee approval.","If you need new documentation, the outside clinic or provider may charge; ask them about fees and insurance coverage.","Driving there: you pay for parking in nearby ramps or meters."],"zh":["资格：学习受到实质障碍、并能提供残障证明的学生。光有诊断不保证批准。","需要新开证明的话，校外诊所或医生可能收费，先问清费用和保险能不能报。","开车去要自己付停车费（附近停车楼或路边咪表）。"]},"tips":{"en":["Apply before you need it: eligibility takes time, and testing or notetaking accommodations typically take a few weeks to set up with instructors.","Eligibility lasts your whole time at UW–Madison, but the letters must be sent again every semester.","Instructors do not see your diagnosis or documentation, and they are not told when you start an application.","The office is near the northwest corner of W Johnson and Lake streets, across from Gordon Commons, on the same block as Walgreens."],"zh":["别等到要用才申请：资格审核要时间，考试和笔记便利跟老师协调一般还要几周。","资格在 UW–Madison 期间一直有效，但通知信每学期都要重新发。","老师看不到你的诊断和材料，你开始申请时也不会通知老师。","中心在 W Johnson St 和 Lake St 路口西北角，对面是 Gordon Commons，和 Walgreens 在同一个街区。"]}},"src":[["McBurney Disability Resource Center - home","https://mcburney.wisc.edu/"],["McBurney Center - Contact Us, hours and location","https://mcburney.wisc.edu/contact-us/"],["McBurney Center - Applying for Accommodations","https://mcburney.wisc.edu/apply-for-accommodations/"],["McBurney Center - Using Accommodations","https://mcburney.wisc.edu/using-accommodations/"]],"unv":[],"chk":"2026-10-08","lat":43.072281,"lng":-89.397766,"stops":[["N Lake at W Johnson",17,"81"],["W Johnson at East Campus",44,"C D R 28 38 65"],["East Campus",83,"A B F"]]},{"id":"memorial-union","cat":"campus","n":{"en":"Memorial Union","zh":"Memorial Union 学生活动中心"},"kind":{"en":"Student union","zh":"学生活动中心"},"addr":"800 Langdon St, Madison, WI 53706","phone":"(608) 265-3000","web":"https://union.wisc.edu/visit/memorial-union/","h":{"Mo":[[420,1380]],"Tu":[[420,1380]],"We":[[420,1380]],"Th":[[420,1380]],"Fr":[[420,1440]],"Sa":[[480,1440]],"Su":[[480,1320]]},"ht":{"en":"Building hours 2026: Mon–Thu 7 a.m.–11 p.m., Fri 7 a.m.–midnight, Sat 8 a.m.–midnight. The Union's page lists Sunday as 8 a.m.–11 a.m., which looks like a typo; Der Rathskeller inside is open Sundays 11 a.m.–10 p.m. this fall. The Terrace season ends Oct 27, 2026.","zh":"2026 年大楼时间：周一到周四 7:00–23:00，周五 7:00–24:00，周六 8:00–24:00。官网把周日写成 8:00–11:00，看着像笔误；楼里的 Der Rathskeller 今年秋季周日开到 22:00。Terrace 露台季 2026 年 10 月 27 日结束。"},"sum":{"en":"UW's lakeside student union: the Terrace, Der Rathskeller, lounges to study in, Outdoor UW gear rentals, a campus info desk and events.","zh":"湖边的学生活动中心：Terrace 露台、Der Rathskeller、自习、租户外装备、问讯台。"},"kw":["Memorial Union","union","学生活动中心","Terrace","露台","Rathskeller","study","自习","Outdoor UW","租装备","camping","露营","Hoofers","Lake Mendota"],"sec":{"about":{"en":["Memorial Union opened in 1928 on the shore of Lake Mendota, between Helen C. White Library and the Red Gym. Students come here to eat, study, see shows and sit on the Terrace with its green, orange and yellow sunburst chairs. The Wisconsin Union runs it for students, staff, Union members and the Madison community.","Floor 1 has Der Rathskeller and the other food counters plus a campus welcome desk; the lower level has Outdoor UW, Wisconsin Hoofers and Wheelhouse Studios; floor 2 has galleries and the Main Lounge; floor 4 has the Great Hall."],"zh":["Memorial Union 1928 年开放，在 Lake Mendota 湖边，夹在 Helen C. White 图书馆和 Red Gym 之间。学生来这里吃饭、自习、看演出，坐在 Terrace 露台那种绿、橙、黄三色的太阳花椅子上。由 Wisconsin Union 运营，学生、教职工、Union 会员和 Madison 市民都能来。","一楼是 Der Rathskeller 等餐饮和校园问讯台；地下层是 Outdoor UW、Wisconsin Hoofers 和 Wheelhouse Studios 艺术工作室；二楼是画廊和 Main Lounge；四楼是 Great Hall。"]},"offers":{"en":["Food: Der Rathskeller (burgers, wraps, fries, cheese curds; weekly live music), Strada (wood-fired pizza and pasta), Peet's Coffee, Daily Scoop ice cream.","Places to sit and study: the Great Hall with its grand piano, the Lakeview Lounge, and the Shannon Sunset Lounge with a fireplace.","Outdoor UW gear rentals: tents, backpacks, sleeping bags and other camping gear year-round, winter gear such as snowshoes and ice skates, and paddle craft in summer.","Campus and Visitor Relations welcome desk for any campus question.","Wisconsin Hoofers outdoor clubs (6 clubs), Wheelhouse Studios art classes, and Badger game broadcasts in Der Rath.","Campus Arts Ticketing box office for Wisconsin Union Theater and other campus performances.","UW Credit Union ATMs in the west wing."],"zh":["吃的：Der Rathskeller（汉堡、卷饼、薯条、奶酪豆 cheese curds，每周有现场音乐）、Strada（柴火披萨和意面）、Peet's Coffee、Daily Scoop 冰淇淋。","坐下来自习的地方：有三角钢琴的 Great Hall、看湖的 Lakeview Lounge、有壁炉的 Shannon Sunset Lounge。","Outdoor UW 租装备：帐篷、背包、睡袋等露营装备全年可租，冬天有雪鞋、冰鞋等，夏天能租皮划艇和桨板。","Campus and Visitor Relations 问讯台，校园里的事都能问。","Wisconsin Hoofers 户外社团（共 6 个）、Wheelhouse Studios 艺术课，在 Der Rath 看 Badger 比赛直播。","Campus Arts Ticketing 售票处：Wisconsin Union Theater 和校内其他演出的票。","西翼有 UW Credit Union 的 ATM。"]},"howto":{"en":["Pay with your Wiscard at Wisconsin Union restaurants: students save 10% on most food and drinks.","Outdoor UW rentals: submit a rental request online, pay the emailed invoice, then pick up the gear and sign a liability waiver. Renters must be 18 or older; bring payment and ID.","Outdoor UW is on the lower level, on the lake side; call (608) 262-1630 or email outdooruw@union.wisc.edu.","Box office: Mon–Fri 2–6 p.m., (608) 265-2787; also open one hour before ticketed shows outside those hours."],"zh":["在 Wisconsin Union 的餐厅用 Wiscard 付款：学生大部分餐饮打 9 折。","Outdoor UW 租装备：网上提交租借申请，付邮件发来的账单，取装备时签免责书。租借人须满 18 岁，带上钱和证件。","Outdoor UW 在地下层靠湖一侧；电话 (608) 262-1630，邮箱 outdooruw@union.wisc.edu。","售票处：周一到周五 14:00–18:00，电话 (608) 265-2787；营业时间以外有售票演出时，开演前 1 小时也开门。"]},"cost":{"en":["Outdoor UW weekend rental (Friday to Tuesday): tent $20, backpack $15, sleeping bag $15, sleeping pad $8.","Summer paddling for UW students: $15 per hour for a one-person kayak, canoe or SUP, $20 for a two-person craft.","Paying with your student Wiscard: 10% off most food and drinks; at Der Rathskeller also 5% off activities."],"zh":["Outdoor UW 周末租（周五到周二）：帐篷 20 美元，背包 15 美元，睡袋 15 美元，防潮垫 8 美元。","夏季划船（UW 学生）：单人皮划艇、独木舟或桨板每小时 15 美元，双人 20 美元。","用学生 Wiscard 付款：大部分餐饮 9 折；Der Rathskeller 的活动另有 95 折。"]},"tips":{"en":["The 2026 Terrace season runs until Oct 27 (Mon–Fri 7 a.m.–11 p.m., Sat–Sun 8 a.m.–11 p.m.).","Der Rath shows every televised Badger game unless another event is already booked.","Never camped before? Outdoor UW staff will demonstrate any gear you rent.","Paddle craft go out only on green-flag days when UW Lifesaving is open; check Lake Mendota conditions before you walk over."],"zh":["2026 年 Terrace 露台季到 10 月 27 日（周一到周五 7:00–23:00，周末 8:00–23:00）。","只要没有别的活动，Der Rath 会直播所有 Badger 比赛。","没露营过？租的装备可以让 Outdoor UW 工作人员现场演示怎么用。","皮划艇只在 UW Lifesaving 挂绿旗、开放的日子出租；出门前先看 Lake Mendota 湖况。"]}},"src":[["Wisconsin Union - Memorial Union","https://union.wisc.edu/visit/memorial-union/"],["Wisconsin Union - Hours & Services","https://union.wisc.edu/visit/hours/"],["Wisconsin Union - Find Food & Drink","https://union.wisc.edu/dine/find-food-and-drink/"],["Wisconsin Union - Der Rathskeller dining and hours","https://union.wisc.edu/dine/find-food-and-drink/der-rathskeller/"],["Wisconsin Union - Der Rathskeller","https://union.wisc.edu/visit/memorial-union/der-rathskeller/"],["Wisconsin Union - Outdoor UW","https://union.wisc.edu/events-and-activities/outdoor-uw/"],["Outdoor UW - Equipment Rentals","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoor-rentals/"],["Outdoor UW - Camping, Hiking and Climbing Rentals","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoor-rentals/camping-and-hiking-rentals/"],["Outdoor UW - Paddling Rentals","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoor-rentals/paddling-rentals/"]],"unv":["hours"],"chk":"2026-10-08","lat":43.07652,"lng":-89.4003,"stops":[["Langdon at N Park",66,"80 82"],["N Park at State",214,"81"],["N Lake at Langdon",276,"80 82"]]},{"id":"multicultural-student-center","cat":"campus","n":{"en":"Multicultural Student Center (MSC)","zh":"多元文化学生中心 (MSC)"},"kind":{"en":"Multicultural student center","zh":"多元文化学生中心"},"addr":"716 Langdon St, Madison, WI 53706","phone":"(608) 262-4503","web":"https://msc.wisc.edu/","h":{"Mo":[[540,1320]],"Tu":[[540,1320]],"We":[[540,1320]],"Th":[[540,1320]],"Fr":[[540,1020]],"Sa":[],"Su":[]},"ht":{"en":"Fall and spring semesters: Mon–Thu 9 a.m.–10 p.m., Fri 9 a.m.–5 p.m.; after 5 p.m. you need your Wiscard to enter the Red Gym. Summer: Mon–Fri 9 a.m.–5 p.m.","zh":"秋季、春季学期：周一到周四 9:00–22:00，周五 9:00–17:00；17:00 以后进 Red Gym 要刷 Wiscard。暑假：周一到周五 9:00–17:00。"},"sum":{"en":"A Red Gym lounge for studying, free snacks, drop-in tutoring and counseling, and community events; open to all students, with four cultural centers.","zh":"在 Red Gym 里：休息自习、免费零食、drop-in 辅导和心理咨询；对所有学生开放，下设四个文化中心。"},"kw":["MSC","Multicultural Student Center","多元文化","Red Gym","cultural center","文化中心","study space","自习","prayer room","祈祷室","free snacks","免费零食","APIDA","Let's Talk"],"sec":{"about":{"en":["The Multicultural Student Center offers support, advocacy and programs that center and celebrate the varied identities and experiences of UW students, and all of its spaces are open to all students. The front desk is Suite 250 on the second floor of the Red Gym. The MSC includes four cultural centers: the Black Cultural Center, APIDA Student Center, Latine Cultural Center and Indigenous Student Center.","Students come here to study, heat up lunch, meet friends and find events. More than 100 student organizations are affiliated with the MSC, and it organizes campus heritage months such as Latine Heritage Month (Sept 15–Oct 15)."],"zh":["多元文化学生中心 (MSC) 为学生提供支持、维权和课外活动，重视并庆祝每个人不同的身份和经历；所有空间对所有学生开放。前台在 Red Gym 二楼 Suite 250。MSC 下设四个文化中心：Black Cultural Center、APIDA Student Center、Latine Cultural Center 和 Indigenous Student Center。","学生在这里自习、热午饭、交朋友、找活动。有 100 多个学生社团挂靠在 MSC，它还牵头办全校的传统月活动，比如 Latine Heritage Month（9/15–10/15）。"]},"offers":{"en":["Lounge and study space, and a place to heat up your lunch.","Free drop-in help in Red Gym 206, bringing services from across campus: Writing Center tutoring Tuesdays 12:15–3:15 p.m. and advising drop-ins from several offices (fall 2026).","Let's Talk: a free, informal and confidential chat with a UHS counselor, Wednesdays 1–3 p.m. in Red Gym 129.","An embedded UHS therapist on Wednesdays, in Red Gym 129 or on Zoom (fall 2026).","Snack n Go station in Red Gym 206 with fruit, granola bars, cereal and oatmeal.","Prayer and Meditation Room (Red Gym 206A) with prayer rugs, head coverings, thobes, yoga mats and religious texts.","Events, heritage months, and support for affiliated student organizations, including room reservations."],"zh":["休息和自习空间，还能热午饭。","Red Gym 206 的免费 drop-in，把校内各部门的服务集中到一处：写作中心辅导每周二 12:15–15:15，另有多个部门的咨询 drop-in（2026 秋季）。","Let's Talk：和 UHS 心理咨询师免费、非正式、保密地聊聊，每周三 13:00–15:00，Red Gym 129。","UHS 驻点心理治疗师，每周三在 Red Gym 129 或 Zoom（2026 秋季）。","Red Gym 206 的 Snack n Go：水果、燕麦棒、麦片和燕麦片。","祈祷冥想室（Red Gym 206A），备有礼拜毯、头巾、长袍 (thobe)、瑜伽垫和宗教经典。","各种活动、传统月，以及给挂靠社团的支持，包括预订房间。"]},"howto":{"en":["Front desk: Red Gym, 716 Langdon St, second floor, Suite 250; (608) 262-4503.","After 5 p.m., use your Wiscard to get into the Red Gym.","For one-on-one writing help at the MSC, book a Writing Center appointment; same-day slots are available, and drop-ins when there is room.","Leftover food from events is announced on the campus app Free Food Alert."],"zh":["前台：Red Gym（716 Langdon St）二楼 Suite 250，电话 (608) 262-4503。","17:00 以后要刷 Wiscard 才能进 Red Gym。","想在 MSC 一对一改论文，就预约写作中心 (Writing Center)；可以约当天的号，有空位也接 drop-in。","活动剩下的食物会通过校园 App Free Food Alert 通知附近的同学。"]},"cost":{"en":["Drop-in tutoring and advising resources here are free of charge.","Let's Talk is free for UW–Madison students, and Snack n Go items are free to take.","All MSC spaces, including the cultural centers, are open to all students."],"zh":["这里的 drop-in 辅导和咨询都免费。","Let's Talk 对 UW–Madison 学生免费，Snack n Go 的零食随便拿。","MSC 所有空间（包括各文化中心）对所有学生开放。"]},"tips":{"en":["The Red Gym is under exterior restoration (October 2026); enter through the front doors beneath the scaffolding.","You can drop by for a tour any time during open hours; groups must request a tour at least 3 weeks ahead.","OSAS staff hold drop-in hours in Red Gym 206 on the first and third Monday of each month, 3–5 p.m. (fall 2026)."],"zh":["Red Gym 外墙在翻修（2026 年 10 月），从脚手架下面的正门进。","开放时间随时可以来参观；团体参观要至少提前 3 周申请。","2026 秋季每月第一、第三个周一 15:00–17:00，OSAS 在 Red Gym 206 驻点。"]},"intl":{"en":["International students are welcome at every MSC space and event; programs cover many identities, for example a VisibiliTea session on third culture kids on Oct 13, 2026."],"zh":["MSC 的空间和活动国际学生都能参加；话题很多元，比如 2026 年 10 月 13 日关于第三文化孩子 (third culture kids) 的 VisibiliTea。"]}},"src":[["Multicultural Student Center - home","https://msc.wisc.edu/"],["Multicultural Student Center - About","https://msc.wisc.edu/about/"],["Multicultural Student Center - Support for students","https://msc.wisc.edu/student_resources/"],["International Academic Programs - home (Red Gym restoration notice)","https://studyabroad.wisc.edu/"]],"unv":[],"chk":"2026-10-08","lat":43.07632,"lng":-89.398488,"stops":[["N Lake at Langdon",137,"80 82"],["Langdon at N Park",142,"80 82"],["Langdon at N Lake",144,"81"]]},{"id":"office-of-student-assistance-and-support","cat":"campus","n":{"en":"Office of Student Assistance and Support (OSAS)","zh":"学生援助与支持办公室 (OSAS)"},"kind":{"en":"Student support office","zh":"学生支持办公室"},"addr":"500 Lincoln Dr, Madison, WI 53706","phone":"(608) 263-5700","web":"https://osas.wisc.edu/","h":{"Mo":[[510,960]],"Tu":[[510,960]],"We":[[510,960]],"Th":[[510,960]],"Fr":[[510,960]],"Sa":[],"Su":[]},"ht":{"en":"Drop-in staff Mon–Fri 8:30 a.m.–4 p.m. in 70 Bascom Hall, or by phone and email. After hours: UHS crisis line (608) 265-5600, option 9; 911 for emergencies.","zh":"周一到周五 8:30–16:00 有 drop-in 值班，地点 70 Bascom Hall，也可以打电话、发邮件。下班后：心理危机打 UHS (608) 265-5600 选 9，紧急情况打 911。"},"sum":{"en":"The former Dean of Students Office: where to start when a personal, health, family or money crisis is getting in the way of your studies.","zh":"原 Dean of Students Office。个人、健康、家庭或经济出了状况影响学业，先找这里。"},"kw":["OSAS","Dean of Students","DoSO","学生支持","crisis","危机","emergency fund","应急资助","absence","缺课","basic needs","food pantry","Bascom Hall"],"sec":{"about":{"en":["The Office of Student Assistance and Support (OSAS) is the office UW–Madison called the Dean of Students Office (DoSO) until August 2024; the services and staff stayed the same. It helps students work through personal, academic or health problems, explains university policies, and connects them with the right office. It is in Room 70 of Bascom Hall.","If you don't know where to start, fill out the online student assistance form; staff usually get back to you the same day."],"zh":["学生援助与支持办公室 (OSAS) 就是 2024 年 8 月之前叫 Dean of Students Office (DoSO) 的那个办公室，改名后服务和人员都没变。它帮学生处理个人、学业或健康方面的难题，解释学校政策，再把你转给对口的部门。办公室在 Bascom Hall 70 室。","不知道从哪下手，就填网上的 student assistance form，一般当天就有人联系你。"]},"offers":{"en":["Drop-in conversations about any problem, with referrals to the right campus or community resource.","Help notifying your instructors if you are in the hospital or otherwise unable to contact them yourself, with your permission.","Short-term money and food help: emergency support requests, BadgerFARE funds for food on campus, and the Open Seat food pantry.","Ways to report a concern: a student you are worried about, harassment, discrimination or bias, or sexual misconduct.","Guidance on academic complaints, such as course drops, withdrawals and grade disputes.","Referrals to free, confidential student legal services, including off-campus housing problems."],"zh":["任何问题都可以来 drop-in 聊，工作人员帮你找到对口的校内外资源。","你住院或者实在没法自己联系老师时，经你同意帮忙通知任课老师。","短期的钱和吃饭问题：应急资助申请、BadgerFARE 校内餐费补助、Open Seat 食物银行。","反映和举报：担心某位同学、骚扰、歧视或偏见事件、性骚扰/性侵。","学业投诉指导，比如退课、休学和成绩争议。","转介免费、保密的学生法律服务，包括校外租房纠纷。"]},"howto":{"en":["Walk in to Bascom Hall Room 70 on weekdays 8:30 a.m.–4 p.m., call (608) 263-5700, or email osas@studentaffairs.wisc.edu.","Or submit the student assistance form on osas.wisc.edu; staff typically follow up within the same business day.","Missing class because you are sick or have a family emergency? Email your instructors yourself as soon as possible; OSAS steps in only when you can't.","In fall 2026, OSAS staff also hold drop-in hours in Red Gym Room 206 (Multicultural Student Center) on the first and third Monday of each month, 3–5 p.m."],"zh":["工作日 8:30–16:00 直接去 Bascom Hall 70 室，或打 (608) 263-5700，或发邮件 osas@studentaffairs.wisc.edu。","也可以在 osas.wisc.edu 填 student assistance form，一般当个工作日就有回复。","因病或家里急事要缺课？自己尽快给老师发邮件；只有你实在没法联系时 OSAS 才出面。","2026 秋季每月第一、第三个周一 15:00–17:00，OSAS 还在 Red Gym 206 室（多元文化学生中心）设 drop-in。"]},"cost":{"en":["Emergency financial support is limited grant funding and loans. Any actively enrolled student may submit a request, but not every request can be funded.","Campus food programs offer free groceries and prepared meals.","Student legal services are free and confidential."],"zh":["应急资助是有限的补助和贷款。在读学生都能申请，但不保证每个都能批。","校内食物项目提供免费食品杂货和现成的饭。","学生法律服务免费、保密。"]},"tips":{"en":["Mental health crisis at any hour: call (608) 265-5600 and choose option 9. UW Police non-emergency line: (608) 264-2677.","Extensions and makeup work are usually your instructor's decision, not OSAS's; instructors may ask for documentation of an illness or hospitalization.","Not sure which office handles your problem? Asking OSAS is a good first step."],"zh":["任何时间遇到心理危机，打 (608) 265-5600 选 9。UW 警察非紧急电话 (608) 264-2677。","能不能延期、补交作业通常由任课老师决定，不是 OSAS；老师可能会要生病或住院的证明。","不知道问题归哪个部门管，先问 OSAS。"]},"intl":{"en":["International students can't use the financial aid emergency form; F-1 students can apply for ISS emergency funding, and OSAS can help you look for other support."],"zh":["国际学生不能用财务援助办公室的应急表；F-1 学生可以申请 ISS 的应急资助，OSAS 也能帮你找其他支持。"]}},"src":[["Office of Student Assistance and Support - home","https://osas.wisc.edu/"],["OSAS - Contact Us","https://osas.wisc.edu/contact-us/"],["OSAS - Who We Are","https://osas.wisc.edu/who-we-are/"],["OSAS - For Students","https://osas.wisc.edu/for-students/"],["OSAS - Academic Flexibility and Attendance Guidance","https://osas.wisc.edu/for-faculty-and-staff/academic-flexibility-and-attendance-guidance/"],["Student Affairs - Dean of Students Office changes name to OSAS","https://students.wisc.edu/news/dean-of-students-office-changes-name-to-office-of-student-assistance-and-support/"],["Office of Student Financial Aid - Emergency Support","https://financialaid.wisc.edu/emergencysupport/"],["Office of Student Financial Aid - Contact (campus resources list)","https://financialaid.wisc.edu/contact/"],["Multicultural Student Center - Support for students","https://msc.wisc.edu/student_resources/"]],"unv":[],"chk":"2026-10-08","lat":43.075371,"lng":-89.404361,"stops":[["Observatory at Bascom",90,"80 82"],["Observatory at N Charter",135,"80 82"],["Linden at N Charter",171,"28 38 65 80"]]},{"id":"office-of-student-financial-aid","cat":"campus","n":{"en":"Office of Student Financial Aid (OSFA)","zh":"学生财务援助办公室 (OSFA)"},"kind":{"en":"Financial aid office","zh":"助学金办公室"},"addr":"333 East Campus Mall, Madison, WI 53715","phone":"(608) 262-3060","web":"https://financialaid.wisc.edu/","h":{"Mo":[[540,960]],"Tu":[[540,960]],"We":[[540,960]],"Th":[[540,960]],"Fr":[[540,960]],"Sa":[],"Su":[]},"ht":{"en":"Mon–Fri 9 a.m.–4 p.m. Current students book advising appointments in Starfish; everyone else calls to schedule.","zh":"周一到周五 9:00–16:00。在校生在 Starfish 预约顾问，其他人打电话预约。"},"sum":{"en":"Handles FAFSA aid, scholarships, money coaching and emergency support, and runs the Student Jobs board for part-time work.","zh":"管 FAFSA 助学金、奖学金、理财咨询和应急资助，还运营兼职网站 Student Jobs。"},"kw":["financial aid","助学金","FAFSA","scholarship","奖学金","WiSH","student jobs","校内兼职","part-time job","emergency","应急资助","Starfish"],"sec":{"about":{"en":["The Office of Student Financial Aid (OSFA) advises students on grants, loans, scholarships and paying for college, and also runs Student Employment, which manages the Student Jobs site for part-time work on and near campus. OSFA is Suite 9701 at 333 East Campus Mall; Student Employment is on the 9th floor of the same building.","Advisors help with the FAFSA, your aid offer, budgeting, money management and debt. Your own aid information is in MyUW Student Center."],"zh":["学生财务援助办公室 (OSFA) 负责助学金、贷款、奖学金和学费筹措方面的咨询，还管 Student Employment，也就是校内外兼职网站 Student Jobs。OSFA 在 333 East Campus Mall 的 Suite 9701，Student Employment 在同一栋楼 9 楼。","顾问可以帮你填 FAFSA、看懂资助方案、做预算、理财和处理债务。你自己的资助信息在 MyUW 的 Student Center 里。"]},"offers":{"en":["One-on-one advising on the FAFSA, your aid offer, budgeting, money management and debt.","FAFSA help: the 2027–28 FAFSA is open now, and UW–Madison's school code is 003895.","Scholarship applications through the Wisconsin Scholarship Hub (WiSH).","Emergency support requests (limited grants and loans) for enrolled students in a financial crisis.","The Student Jobs site, with thousands of part-time jobs at UW and in Madison, plus one-on-one Student Employment peer advising.","Basic Needs Assistants who connect students with food, housing and insurance resources."],"zh":["一对一咨询：FAFSA、资助方案、预算、理财和债务。","FAFSA 帮忙：2027–28 学年 FAFSA 已经开放，UW–Madison 学校代码 003895。","通过 Wisconsin Scholarship Hub (WiSH) 申请奖学金。","应急资助申请（名额有限的补助和贷款），给遇到经济危机的在校生。","Student Jobs 网站：校内和 Madison 本地几千个兼职；还有 Student Employment 的 peer advisor 一对一帮你找工作。","Basic Needs Assistants 帮你对接食物、住房和保险方面的资源。"]},"howto":{"en":["Current students book advising in Starfish (in MyUW); prospective students and others call (608) 262-3060.","Have your 10-digit Campus ID ready when you call or email finaid@finaid.wisc.edu.","Emergency support form: MyUW Student Center > Student eForms > Financial Aid folder > Emergency Support.","Student job questions: student.employment@finaid.wisc.edu or (608) 262-3060, option 3. Use Handshake, not Student Jobs, for internships and full-time jobs."],"zh":["在校生在 MyUW 的 Starfish 预约顾问；新生和其他人打 (608) 262-3060。","打电话或发邮件 (finaid@finaid.wisc.edu) 前准备好 10 位 Campus ID。","应急资助表：MyUW Student Center → Student eForms → Financial Aid 文件夹 → Emergency Support。","兼职问题：发邮件 student.employment@finaid.wisc.edu 或打 (608) 262-3060 转 3。实习和全职工作用 Handshake，不在 Student Jobs 上。"]},"cost":{"en":["The FAFSA (Free Application for Federal Student Aid) costs nothing to file.","Emergency funding is limited and may not cover every request.","The No Fees Project removes campus Cost of Experience fees for Pell Grant-eligible and UW Promise Program students."],"zh":["FAFSA（Free Application for Federal Student Aid）申请本身免费。","应急资助经费有限，不保证每个申请都能拿到。","No Fees Project：符合 Pell Grant 资格的学生和 UW Promise 项目学生免交校园 Cost of Experience 杂费。"]},"tips":{"en":["Aid starts disbursing 10 days before fall and spring classes begin; anything above your bill comes back to you as a refund.","OSFA runs workshops during the semester, for example Money Hour in the STARR Lab (9th floor, 333 East Campus Mall) on October 13, 2026.","Advisors also hold office hours around campus, such as drop-ins on using aid for study abroad at the Study Abroad Resource Center in the Red Gym.","Moving off campus? Ask OSFA how your aid package applies to off-campus housing costs."],"zh":["助学金在秋季、春季开学前 10 天开始发放；超出账单的部分会退给你。","学期中有讲座，比如 2026 年 10 月 13 日在 STARR Lab（333 East Campus Mall 9 楼）的 Money Hour。","顾问也在校园各处开 office hours，比如在 Red Gym 的 Study Abroad Resource Center 讲怎么用助学金出国交换。","要搬去校外住？问 OSFA 助学金怎么用在校外房租上。"]},"intl":{"en":["International students cannot apply for emergency support through OSFA; F-1 students can apply for ISS emergency funding (scholarship or loan) through WiSH.","F-1 students can take on-campus jobs from Student Jobs, up to 20 hours a week in fall and spring, all jobs combined; check the ISS rules first."],"zh":["国际学生不能在 OSFA 申请应急资助；F-1 学生可以通过 WiSH 申请 ISS 的应急资助（奖学金或贷款）。","F-1 学生可以做 Student Jobs 上的校内工作，秋季、春季所有工作加起来每周最多 20 小时；先看 ISS 的规定。"]}},"src":[["Office of Student Financial Aid - home","https://financialaid.wisc.edu/"],["Office of Student Financial Aid - Contact","https://financialaid.wisc.edu/contact/"],["Office of Student Financial Aid - Services","https://financialaid.wisc.edu/services/"],["Office of Student Financial Aid - Emergency Support","https://financialaid.wisc.edu/emergencysupport/"],["Student Jobs (Student Employment, OSFA)","https://studentjobs.wisc.edu/"],["Student Jobs - Student Employment Peer Advising","https://studentjobs.wisc.edu/student-employment-peer-advising/"],["Bursar's Office - home (aid disbursement FAQ)","https://bursar.wisc.edu/"],["University Housing - Off-Campus Housing","https://www.housing.wisc.edu/undergraduate/off-campus/"],["ISS - F-1 Employment Overview","https://iss.wisc.edu/employment/f1-employment/"]],"unv":[],"chk":"2026-10-08","lat":43.072489,"lng":-89.398931,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"office-of-the-registrar","cat":"campus","n":{"en":"Office of the Registrar","zh":"教务处 (Office of the Registrar)"},"kind":{"en":"Student records office","zh":"学籍档案办公室"},"addr":"333 East Campus Mall, Madison, WI 53715","phone":"(608) 262-3811","web":"https://registrar.wisc.edu/","h":{"Mo":[[540,720],[780,960]],"Tu":[[540,720],[780,960]],"We":[[540,720],[780,960]],"Th":[[540,720],[780,960]],"Fr":[],"Sa":[],"Su":[]},"ht":{"en":"Walk-in counter Mon–Thu 9 a.m.–noon and 1–4 p.m. Fridays in person by appointment only: call at least 24 hours ahead. Phone and email help Mon–Fri 9 a.m.–4 p.m. (fall 2026).","zh":"现场柜台周一到周四 9:00–12:00、13:00–16:00。周五现场只接预约，至少提前 24 小时打电话。电话和邮件周一到周五 9:00–16:00（2026 秋季）。"},"sum":{"en":"Keeps your student record: official transcripts, enrollment verification letters, name and personal data updates, and adding your SSN.","zh":"管学籍档案：成绩单、在读证明、改名和个人信息、登记 SSN 都找这里。"},"kw":["registrar","教务处","transcript","成绩单","enrollment verification","在读证明","name change","改名","preferred name","SSN","Student Center","Parchment"],"sec":{"about":{"en":["The Office of the Registrar keeps UW–Madison student records: enrollment, grades, transcripts, enrollment and degree verification, and personal data such as your legal name, name in use and SSN. Its counter is Suite 11101 at 333 East Campus Mall, the same building as the Bursar's Office and the Office of Student Financial Aid.","Most tasks are self-service in MyUW Student Center under Academic Records. Go to the counter when you need something printed, a form handed in, or a records problem sorted out."],"zh":["教务处 (Office of the Registrar) 管 UW–Madison 的学籍档案：选课注册、成绩、成绩单、在读和学位证明，以及法定姓名、常用名、SSN 等个人信息。柜台在 333 East Campus Mall 的 Suite 11101，和 Bursar's Office、财务援助办公室在同一栋楼。","大部分事情在 MyUW 的 Student Center → Academic Records 里自己就能办。要打印东西、交表或者档案出了问题，再去柜台。"]},"offers":{"en":["Official transcripts ordered through Parchment in Student Center, as a PDF or on paper.","Enrollment verification letter (full-time, half-time and so on) as an official PDF from Academic Records; a separate voter version works as proof of residence for voting in Wisconsin.","Unofficial transcript PDF from Student Center for advisors or your own checks.","Setting a name in use (preferred name), or updating your legal name, birthdate or legal sex.","Adding your SSN or ITIN to your record by uploading a photo of the card to the Registrar's Secure Box, or showing it at the counter.","Paper official transcripts printed at the counter when you need one right away.","Degree verification letters once your degree is posted."],"zh":["正式成绩单：在 Student Center 里通过 Parchment 下单，PDF 或纸质都行。","在读证明 (enrollment verification)：在 Academic Records 生成官方 PDF，写明全职、半职等状态；另有投票专用版本，可在威州当居住证明。","非正式成绩单 (unofficial transcript)：Student Center 里直接下载 PDF，给 advisor 看或自己查。","设置常用名 (name in use)，或更改法定姓名、生日、法定性别。","登记 SSN 或 ITIN：把卡的照片传到教务处的 Secure Box，或到柜台出示。","急需纸质正式成绩单，可以到柜台当场打印。","学位记入档案后可开学位证明 (degree verification)。"]},"howto":{"en":["Order official transcripts: MyUW > Student Center > Academic Records > Request My Official Transcript (you need a Parchment account).","Counter: 333 East Campus Mall, Suite 11101. Fridays are by appointment; call (608) 262-3811 at least 24 hours ahead.","To hand in forms without waiting, use the Registrar drop box in the first-floor elevator lobby of 333 East Campus Mall.","On the phone menu, students press 2 and then 6 for enrollment, records, transcripts and certifications.","SSN: upload a scan or photo of your card to the Registrar's Secure Box folder. Never send SSN or ITIN information by email."],"zh":["订正式成绩单：MyUW → Student Center → Academic Records → Request My Official Transcript（要有 Parchment 账号）。","柜台在 333 East Campus Mall 的 Suite 11101。周五只接预约，至少提前 24 小时打 (608) 262-3811。","只交表不想排队，就投进 333 East Campus Mall 一楼电梯厅的教务处投递箱。","打电话时学生先按 2 再按 6，转选课、学籍、成绩单和各类证明。","SSN：把卡的扫描件或照片传到教务处的 Secure Box 文件夹。千万别用邮件发 SSN 或 ITIN。"]},"cost":{"en":["Transcripts are free, including first-class mail and PDF delivery; FedEx with tracking costs extra.","Official documents are covered by a one-time fee charged with your first term's tuition."],"zh":["成绩单免费，平信和 PDF 寄送也免费；要带单号的 FedEx 快递得另付钱。","各类官方文件的费用已经包含在第一学期学费里收的一次性费用中。"]},"tips":{"en":["For voting, choose the voter enrollment verification letter; the regular letter is not valid for voting purposes.","Printing an official PDF transcript yourself makes it unofficial (it shows watermarks); order a paper copy instead.","Your legal name still appears on transcripts, financial aid, payroll and federal immigration documents even if you set a name in use.","After setting a name in use you can get a new Wiscard with that name for free if you hand in the old card.","Problems with Course Search & Enroll go to the DoIT Help Desk, (608) 264-4357, not the Registrar."],"zh":["投票用的在读证明要选 voter enrollment verification；普通版本不能用于投票。","官方 PDF 成绩单自己打印出来会带水印、变成非正式的；要纸质版就直接订纸质。","就算设置了常用名，成绩单、助学金、工资单和联邦移民文件上还是法定姓名。","设置常用名后，交回旧卡就能免费换一张印着常用名的新学生证 (Wiscard)。","选课系统 Course Search & Enroll 出问题，打 DoIT Help Desk (608) 264-4357，别找教务处。"]},"intl":{"en":["International students may not need, or be eligible for, an SSN; ask ISS about SSN or ITIN questions.","Many university forms use your legal name, which for international students is the name on your passport.","International students who go by a different name in the U.S. can set it as their name in use."],"zh":["国际学生不一定需要、也不一定有资格申请 SSN；SSN 和 ITIN 的问题去问 ISS。","学校很多表格用法定姓名，对国际学生来说就是护照上的名字。","在美国想用英文名，可以把它设为常用名 (name in use)。"]}},"src":[["Office of the Registrar - Contact Us","https://registrar.wisc.edu/contact/"],["Office of the Registrar - Transcripts","https://registrar.wisc.edu/transcript/"],["Office of the Registrar - Verifications","https://registrar.wisc.edu/verification/"],["Office of the Registrar - Personal Information in UW Records","https://registrar.wisc.edu/personal-info/"],["Registrar KB - Secure Box: Uploading SSN Card","https://kb.wisc.edu/registrar/123347"],["ISS - Social Security Number (SSN)","https://iss.wisc.edu/employment/social-security/"],["Bursar's Office - home","https://bursar.wisc.edu/"],["Office of Student Financial Aid - home","https://financialaid.wisc.edu/"]],"unv":[],"chk":"2026-10-08","lat":43.072489,"lng":-89.398931,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"successworks","cat":"campus","n":{"en":"SuccessWorks at the College of Letters & Science","zh":"SuccessWorks 文理学院职业中心"},"kind":{"en":"Career center","zh":"职业发展中心"},"addr":"711 State St, Madison, WI 53703","phone":"(608) 262-3921","web":"https://successworks.wisc.edu/","h":{"Mo":[[600,960]],"Tu":[[600,960]],"We":[[600,960]],"Th":[[600,960]],"Fr":[[600,960]],"Sa":[],"Su":[]},"ht":{"en":"Book Store office (3rd floor, 711 State St): Mon–Fri 10 a.m.–4 p.m.; Career Closet Mon–Thu 10 a.m.–4 p.m. (fall 2026). Drop-in advising at Levy Hall, 232 N Park St: Mon–Fri 10 a.m.–3 p.m. during fall and spring terms.","zh":"Book Store 办公室（711 State St 三楼）：周一到周五 10:00–16:00；Career Closet 周一到周四 10:00–16:00（2026 秋季）。Levy Hall（232 N Park St）drop-in：秋季、春季学期周一到周五 10:00–15:00。"},"sum":{"en":"Career advising, resume reviews and free interview clothes for College of Letters & Science students; other colleges have their own career offices.","zh":"文理学院 (L&S) 的职业中心：职业咨询、改简历、免费面试服装；其他学院有自己的职业办公室。"},"kw":["SuccessWorks","career","职业","resume","简历","internship","实习","job","找工作","Handshake","career fair","招聘会","Career Closet","L&S"],"sec":{"about":{"en":["SuccessWorks is the career center of the College of Letters & Science (L&S). It helps L&S students explore careers, find internships and jobs, and prepare resumes, applications and interviews. The main office is on the third floor of the University Book Store building (711 State St, Suite 300); quick drop-in help is at the entrance of Levy Hall.","Each UW school or college has its own career office. Engineering students use Engineering Career Services (1147 Engineering Hall), business students the Wisconsin School of Business career team, and undergraduates still exploring majors can use the Career Exploration Center (114 Ingraham Hall)."],"zh":["SuccessWorks 是文理学院 (College of Letters & Science, L&S) 的职业中心，帮 L&S 学生探索职业方向、找实习和工作、准备简历、申请和面试。主办公室在 University Book Store 大楼三楼（711 State St, Suite 300）；Levy Hall 入口处有快速 drop-in。","UW 每个学院都有自己的职业办公室。工学院学生找 Engineering Career Services（1147 Engineering Hall），商学院学生找 Wisconsin School of Business 的职业团队，还在选专业的本科生可以去 Career Exploration Center（114 Ingraham Hall）。"]},"offers":{"en":["30-minute career advising appointments, in person or virtual, including specialist advisors by field: tech and data, consulting and finance, public service, science and health, media and the arts.","Drop-in help at Levy Hall with resumes, cover letters, career fairs and Handshake, no appointment needed.","Career Closet: up to four free pieces of professional clothing per semester, yours to keep.","Career fairs, events and the SuccessWorks Internship Fund.","Career courses for credit: Inter-LS 210 and 215, and the internship course Inter-LS 260.","Advising for L&S graduates within six months of graduation."],"zh":["30 分钟一对一职业咨询，可到场或线上；还有按领域分的专门顾问：科技与数据、咨询与金融、公共服务、科学与健康、传媒与艺术。","Levy Hall 的 drop-in：改简历、求职信，问招聘会和 Handshake，不用预约。","Career Closet：每学期最多免费拿 4 件正装，拿了就归你。","招聘会、各类活动，还有 SuccessWorks 实习资助 (Internship Fund)。","有学分的职业课程：Inter-LS 210、215，以及实习课 Inter-LS 260。","毕业 6 个月内的 L&S 校友也能预约咨询。"]},"howto":{"en":["Book through the Make an Appointment page on the SuccessWorks site; front desk staff greet you on the third floor of the Book Store building.","Can't make it? Cancel before 8 a.m. on the day of the appointment; SuccessWorks has a no-show policy.","For a quick resume check, walk in at Levy Hall, 232 N Park St, Mon–Fri 10 a.m.–3 p.m. during fall and spring terms.","Set up your Handshake profile: campus job postings, interviews and career events are all there."],"zh":["在 SuccessWorks 官网的 Make an Appointment 页面预约；到 Book Store 大楼三楼会有前台接待。","来不了要在预约当天早上 8 点前取消；SuccessWorks 有爽约规定 (no-show policy)。","只想快速看简历，就去 Levy Hall（232 N Park St）drop-in，秋季、春季学期周一到周五 10:00–15:00。","把 Handshake 主页填好：校园招聘、面试和职业活动都在上面。"]},"cost":{"en":["Advising and drop-ins are for L&S students; students in other colleges should use their own college's career office.","Career Closet clothing is free for L&S students, up to four items per semester (no shoes or socks)."],"zh":["咨询和 drop-in 面向 L&S 学生；其他学院的学生去自己学院的职业办公室。","Career Closet 对 L&S 学生免费，每学期最多 4 件（不提供鞋袜）。"]},"tips":{"en":["The Career Closet keeps shorter hours than advising: Mon–Thu 10 a.m.–4 p.m. in fall 2026.","Drop-ins are for quick questions; book a 30-minute appointment for anything longer.","Engineering Career Services is in 1147 Engineering Hall, (608) 262-3471."],"zh":["Career Closet 开放时间比咨询短：2026 秋季周一到周四 10:00–16:00。","Drop-in 适合小问题，复杂的事约 30 分钟的正式咨询。","工学院的 Engineering Career Services 在 1147 Engineering Hall，电话 (608) 262-3471。"]},"intl":{"en":["SuccessWorks advisors help international students with job-search strategy and how to talk to employers; immigration questions go to ISS.","CPT guidance changed in August 2026. If you are an F-1 student considering an internship, consult ISS early about whether CPT is possible for your program.","GoinGlobal, linked from ISS career resources, lists job opportunities in more than 121 locations worldwide."],"zh":["SuccessWorks 顾问帮国际学生制定求职策略、教你怎么跟雇主沟通；移民身份问题找 ISS。","2026 年 8 月 CPT 指引变了。F-1 学生打算实习的话，尽早问 ISS 你的专业能不能办 CPT。","ISS 职业资源里链接的 GoinGlobal，收录了全球 121 个以上地区的工作机会。"]}},"src":[["SuccessWorks - home (locations and hours)","https://successworks.wisc.edu/"],["SuccessWorks - Career & Internship Advising","https://successworks.wisc.edu/make-an-appointment/"],["SuccessWorks - Career Closet","https://successworks.wisc.edu/career-closet/"],["SuccessWorks - International Students","https://successworks.wisc.edu/international-students/"],["Career Services at UW-Madison - Find a Career Services Office","https://careers.wisc.edu/find-an-office/"],["Engineering Career Services","https://ecs.wisc.edu/"],["Career Exploration Center","https://cec.wisc.edu/"],["Student Jobs - International Student Support","https://studentjobs.wisc.edu/international-student-support/"]],"unv":[],"chk":"2026-10-08","lat":43.074668,"lng":-89.397843,"stops":[["N Lake at Langdon",109,"80 82"],["Langdon at N Lake",135,"81"],["East Campus",167,"B"]]},{"id":"union-south","cat":"campus","n":{"en":"Union South","zh":"Union South 学生活动中心"},"kind":{"en":"Student union","zh":"学生活动中心"},"addr":"1308 W Dayton St, Madison, WI 53715","phone":"(608) 890-3000","web":"https://union.wisc.edu/visit/union-south/","h":{"Mo":[[420,1380]],"Tu":[[420,1380]],"We":[[420,1380]],"Th":[[420,1380]],"Fr":[[420,1440]],"Sa":[[420,1440]],"Su":[[420,1380]]},"ht":{"en":"Fall 2026 building hours (Sept 1–Dec 17): Mon–Thu 7 a.m.–11 p.m., Fri–Sat 7 a.m.–midnight, Sun 7 a.m.–11 p.m. Offices inside, such as the Wiscard Office and UW Credit Union, keep their own shorter hours.","zh":"2026 秋季（9/1–12/17）大楼时间：周一到周四 7:00–23:00，周五、周六 7:00–24:00，周日 7:00–23:00。里面的 Wiscard Office、UW Credit Union 等有各自更短的营业时间。"},"sum":{"en":"South-campus student union with free WUD films at the Marquee, bowling and billiards at The Sett, food, study spaces and the Wiscard Office.","zh":"南校区学生活动中心：Marquee 免费电影、The Sett 保龄球和台球、吃饭自习，Wiscard 办公室也在这。"},"kw":["Union South","学生活动中心","Marquee","电影","free movies","The Sett","bowling","保龄球","billiards","台球","study","自习","Badger Bash"],"sec":{"about":{"en":["Union South, a 2011 building near Camp Randall, is the Wisconsin Union's south-campus union: a movie theater, a recreation center with bowling, billiards, a two-story climbing wall and video games, eight dining options, a hotel and meeting rooms.","Several everyday services are on floor 1: the Wiscard Office (student IDs), a UW Credit Union branch and a Campus and Visitor Relations welcome desk. Floor 2 has an InfoLab computer lab and the Marquee cinema."],"zh":["Union South 是 2011 年建成的楼，在 Camp Randall 球场附近，是 Wisconsin Union 在南校区的学生活动中心：有电影院、带保龄球、台球、两层高攀岩墙和电子游戏的娱乐中心、8 个餐饮点、酒店和会议室。","一楼有几个常用的服务点：Wiscard Office（办学生证）、UW Credit Union 网点和 Campus and Visitor Relations 问讯台。二楼有 InfoLab 机房和 Marquee 电影院。"]},"offers":{"en":["Free WUD Film screenings at the Marquee (floor 2), usually Thursday to Saturday during the academic year, from new releases to classics; some showings are open-captioned.","Sett Recreation (lower level): eight bowling lanes, pool tables, free board and video games, and VR.","Food: Ginger Root (pan-Asian bento bowls), Harvest Grains (pasta bowls and salads), Prairie Fire (coffee and sandwiches), the Sett Pub, and Badger Market for snacks and school supplies.","Study spots: the Sun Garden by the fire, and The Well (Room 233), an alcohol-free space for enrolled students to study and relax.","Reflection Room (floor 3) for prayer or meditation.","Wiscard Office, UW Credit Union branch and an InfoLab with Mac and Windows computers.","Badger Bash before every home football game, with the UW Marching Band and Spirit Squad."],"zh":["Marquee（二楼）免费 WUD Film 电影：学期中一般周四到周六放映，新片老片都有，部分场次带字幕 (open caption)。","Sett Recreation（地下层）：8 条保龄球道、台球、免费桌游和电子游戏，还有 VR。","吃的：Ginger Root（泛亚洲便当碗）、Harvest Grains（意面碗和沙拉）、Prairie Fire（咖啡三明治）、Sett Pub，Badger Market 卖零食和文具。","自习：有壁炉的 Sun Garden，以及 233 室的 The Well：禁酒的自习放松空间，在读学生都能用。","三楼 Reflection Room，可以祈祷或冥想。","Wiscard Office、UW Credit Union 网点，还有装着 Mac 和 Windows 电脑的 InfoLab 机房。","每场主场橄榄球赛前的 Badger Bash，有 UW 军乐队和啦啦队表演。"]},"howto":{"en":["WUD films are free; check the Marquee page on union.wisc.edu for this week's titles and times.","Sett Recreation is on the lower level and the Sett Pub on floor 1; call Sett Rec at (608) 263-2514.","Pay with your Wiscard: students save 10% on most food and drinks, and students and Union members get 10% off recreation prices.","The Reflection Room is open to UW–Madison students, faculty and staff for personal reflection or meditation."],"zh":["WUD 电影免费；本周片单和时间看 union.wisc.edu 上的 Marquee 页面。","Sett Recreation 在地下层，Sett Pub 在一楼；Sett Rec 电话 (608) 263-2514。","用 Wiscard 付款：学生大部分餐饮 9 折；学生和 Union 会员娱乐项目也打 9 折。","Reflection Room 对 UW–Madison 学生和教职工开放，可以静思或冥想。"]},"cost":{"en":["Bowling: $26.80 per lane per hour (up to six people), shoes $2.94. Sunday Budget Bowl: $20.50 per lane-hour, shoes included (September–May).","Matinee deal: 50% off bowling, pool and shoe rental Mon–Fri before 5 p.m.","Billiards: $10.45 per table per hour; $5.25 all day on Tuesdays. VR: $10 per hour.","WUD Film screenings are free."],"zh":["保龄球：每道每小时 26.80 美元（最多 6 人），租鞋 2.94 美元。周日 Budget Bowl：每道每小时 20.50 美元含鞋（9 月到次年 5 月）。","白天优惠：周一到周五 17:00 前保龄球、台球和租鞋半价。","台球：每桌每小时 10.45 美元；周二全天 5.25 美元。VR 每小时 10 美元。","WUD 电影免费。"]},"tips":{"en":["Cheapest bowling is a weekday before 5 p.m. (half price) or any time on Sunday.","Glow Bowl runs Friday and Saturday from 10 p.m. to close, September to May.","Home football Saturdays are busy: Badger Bash starts 2½ hours before kickoff.","The Well is open for study whenever no event is scheduled there."],"zh":["保龄球最便宜的时段：工作日 17:00 前（半价），或者周日全天。","Glow Bowl 荧光保龄球：9 月到次年 5 月的周五、周六 22:00 到关门。","主场橄榄球比赛日人很多：开球前 2.5 小时就开始 Badger Bash。","The Well 只要没排活动就能去自习。"]}},"src":[["Wisconsin Union - Union South","https://union.wisc.edu/visit/union-south/"],["Wisconsin Union - Hours & Services","https://union.wisc.edu/visit/hours/"],["Wisconsin Union - The Marquee Cinema","https://union.wisc.edu/visit/union-south/the-marquee/"],["Wisconsin Union - The Sett","https://union.wisc.edu/visit/union-south/the-sett-at-union-south/"],["Wisconsin Union - Sett Recreation: Bowling + Games","https://union.wisc.edu/events-and-activities/games-and-bowling/"],["Wisconsin Union - The Well","https://union.wisc.edu/visit/union-south/the-well/"],["Wisconsin Union - Find Food & Drink","https://union.wisc.edu/dine/find-food-and-drink/"]],"unv":[],"chk":"2026-10-08","lat":43.072211,"lng":-89.408637,"stops":[["N Randall at Engineering",45,"D O 80"],["W Johnson at N Orchard",70,"C D J O R"],["N Randall at W Dayton",97,"D O"]]},{"id":"university-housing","cat":"campus","n":{"en":"University Housing (residence hall desks)","zh":"学校宿舍服务 (University Housing)"},"kind":{"en":"Dorm service desks","zh":"宿舍前台"},"addr":"625 Babcock Dr, Madison, WI 53706","phone":"(608) 262-2522","web":"https://www.housing.wisc.edu/undergraduate/services/desks","h":null,"ht":{"en":"Hall desks (academic year): Mon–Fri 9 a.m.–9 p.m., Sat–Sun 10 a.m.–8 p.m. Lakeshore Package Center: Mon–Fri 10 a.m.–7 p.m., Sat–Sun noon–5 p.m. Desks keep very limited hours during breaks. The Housing main office (625 Babcock Dr) answers by phone and web form.","zh":"各宿舍前台（学期中）：周一到周五 9:00–21:00，周末 10:00–20:00。Lakeshore 包裹中心：周一到周五 10:00–19:00，周末 12:00–17:00。假期前台开放时间很少。宿舍总办公室（625 Babcock Dr）通过电话和网上表格答疑。"},"sum":{"en":"For dorm residents: your hall desk handles mail, packages, lockouts and loaner keys; Housing's main office answers contract questions.","zh":"住校生日常找宿舍前台：取信取包裹、锁在门外借钥匙；合同问题找宿舍总办公室。"},"kw":["University Housing","宿舍","dorm","residence hall","hall desk","前台","package","包裹","lockout","钥匙","maintenance","维修","My UW Housing"],"sec":{"about":{"en":["UW's Division of University Housing runs the residence halls. For everyday needs, each hall or group of halls has a hall desk that receives mail and packages, lends keys when you are locked out, checks out equipment and answers questions. Lakeshore residents (except Waters Hall) pick up packages at the Lakeshore Package Center, 1650 Kronshage Dr.","Room assignments and contract details are in the My UW Housing portal. The Housing main office is at 625 Babcock Dr (Slichter Hall); its web contact form usually gets a reply within three business days."],"zh":["宿舍由学校的 Division of University Housing 管理。日常的事找自己楼（或几栋楼共用）的前台 (hall desk)：收信收包裹、锁在门外时借钥匙、借用物品、答疑。Lakeshore 片区的同学（Waters Hall 除外）在 Lakeshore Package Center 领包裹，地址 1650 Kronshage Dr。","分房和合同信息在 My UW Housing 门户里。宿舍总办公室在 625 Babcock Dr（Slichter Hall）；网上联系表一般 3 个工作日内回复。"]},"offers":{"en":["Mail and package pickup; you get an email at your wisc.edu address when a package is ready.","Loaner keys when you are locked out, and help with room key or Wiscard door problems.","Free equipment checkout with your Wiscard, such as vacuums, cookware and ping pong paddles.","Online maintenance requests for non-emergency repairs; facilities staff work 24 hours a day, 7 days a week.","Refrigerated medication deliveries held at the Waters Hall desk for all residence hall students.","An Amazon pickup site connected to Sellery Hall."],"zh":["取信件和包裹；包裹到了会发邮件到你的 wisc.edu 邮箱。","锁在门外借备用钥匙，房间钥匙或 Wiscard 门禁出问题也找前台。","凭 Wiscard 免费借吸尘器、锅具、乒乓球拍等物品。","非紧急维修在网上报修；宿舍维修人员 24 小时、7 天都有人。","需要冷藏的药物统一寄到 Waters Hall 前台保管，所有宿舍学生都适用。","Sellery Hall 旁边有 Amazon 取件点。"]},"howto":{"en":["Address packages with your full preferred name, hall name, house and room number, and the hall's street address. Lakeshore residents use 1650 Kronshage Dr and put hall, house and room in the Address 2 line.","Bring your Wiscard or another ID to pick up a package; you don't need to print the email.","Locked out after the desk closes? Call the House Fellow duty phone posted in your building.","Emergency repairs: contact a House Fellow or your hall desk. Everything else: submit the online maintenance request.","Main office: (608) 262-2522, or the contact form on housing.wisc.edu."],"zh":["包裹地址写：常用名全名、宿舍楼名、house 和房间号、楼的街道地址。Lakeshore 的同学统一写 1650 Kronshage Dr，把楼名、house、房间号写在地址第二行 (Address 2)。","取包裹带 Wiscard 或其他证件，不用打印邮件。","前台下班后被锁在外面，打楼里贴着的 House Fellow 值班电话。","紧急维修找 House Fellow 或前台，其他的在网上报修。","总办公室电话 (608) 262-2522，或用 housing.wisc.edu 上的联系表。"]},"cost":{"en":["Two free loaner keys or House Fellow lockout calls per semester, then $15 each.","A loaner key not returned within 72 hours triggers a lock change ($75). A replacement for a lost room key is also $75.","Equipment checkout is free; lost or damaged items cost the replacement price plus a $10 restocking fee.","Contract releases are granted only in limited cases (such as leaving UW or studying abroad); otherwise you can buy out the contract at 85% of the remaining amount."],"zh":["每学期前 2 次借钥匙或找 House Fellow 开门免费，之后每次 15 美元。","借的钥匙 72 小时内没还就换锁，收 75 美元；房间钥匙丢了补一把也是 75 美元。","借物品免费；丢了或弄坏按原价赔，另收 10 美元手续费。","解约只在少数情况下批准（比如离开 UW 或出国交换）；否则可以按剩余金额的 85% 买断合同。"]},"tips":{"en":["Don't ship packages to campus during breaks; desks keep very limited hours then.","Desks can't send packages out. Use FedEx at 311 E Campus Mall (inside Walgreens), UPS at 1360 Regent St or the post office at 441 N Lake St.","After you move out, packages not picked up within 2 weeks go back to the sender.","Wi-Fi and Media Center problems go to the DoIT Help Desk, not the hall desk."],"zh":["假期别往学校寄包裹，那时前台开放时间很少。","前台不能帮你寄件。寄东西去 311 E Campus Mall 的 FedEx（在 Walgreens 里）、1360 Regent St 的 UPS，或 441 N Lake St 的邮局。","搬走以后，包裹 2 周内没领就退回寄件人。","Wi-Fi 和 Media Center 的问题找 DoIT Help Desk，不归前台管。"]},"intl":{"en":["If you go by an English name, put that preferred first name plus your last name on packages; missing details delay delivery."],"zh":["用英文名的话，包裹上写常用名加姓；信息不全会耽误取件。"]}},"src":[["University Housing - Hall Desks (locations, hours, packages)","https://www.housing.wisc.edu/undergraduate/services/desks"],["University Housing - Contact Us","https://www.housing.wisc.edu/about/contact/"],["University Housing - Slichter Residence Hall","https://www.housing.wisc.edu/residence-halls/slichter/"],["University Housing - Resident expectations (keys and lockouts)","https://www.housing.wisc.edu/undergraduate/experience/expectations/"],["University Housing - Maintenance","https://www.housing.wisc.edu/undergraduate/services/maintenance"],["University Housing - Resident Guide","https://residents.housing.wisc.edu/"]],"unv":[],"chk":"2026-10-08","lat":43.07713,"lng":-89.412242,"stops":[["Observatory at Babcock",94,"28 38 65 80 82"],["Linden at Babcock",210,"28 38 65 80 84"],["Babcock at Linden",211,"28 38 65 80"]]},{"id":"uw-transportation-services","cat":"campus","n":{"en":"UW Transportation Services","zh":"UW 交通服务处 (Transportation Services)"},"kind":{"en":"Parking and bus pass office","zh":"停车和公交卡办公室"},"addr":"21 N Park St, Madison, WI 53715","phone":"(608) 263-6666","web":"https://transportation.wisc.edu/","h":{"Mo":[[480,960]],"Tu":[[480,960]],"We":[[480,960]],"Th":[[480,960]],"Fr":[[480,960]],"Sa":[],"Su":[]},"ht":{"en":"21 N Park St, Suite 1200: lobby Mon–Fri 8 a.m.–4 p.m. Main office, WARF Building (610 Walnut St, Room 124): Mon, Tue, Thu, Fri 7:15 a.m.–4:30 p.m., Wed 8 a.m.–4 p.m. Closed on legal holidays, e.g. Nov 26 and Dec 24–25, 2026.","zh":"21 N Park St, Suite 1200：大厅周一到周五 8:00–16:00。主办公室在 WARF Building（610 Walnut St, 124 室）：周一、二、四、五 7:15–16:30，周三 8:00–16:00。法定假日关门，比如 2026 年 11 月 26 日、12 月 24–25 日。"},"sum":{"en":"Pick up your free ASM student bus pass here, buy moped or parking permits, and pay or appeal campus parking tickets.","zh":"领免费的 ASM 学生公交卡、买 moped 或汽车停车证、交或申诉校园停车罚单都在这里。"},"kw":["bus pass","公交卡","Transportation Services","parking","停车","permit","停车证","moped","电动车","SAFEwalk","Metro","citation","罚单"],"sec":{"about":{"en":["UW Transportation Services runs campus parking, permits and citations, and the student bus pass program. Most students come here once, to pick up the ASM student bus pass: unlimited rides on Madison Metro buses, BRT routes and paratransit. The office nearest central campus is at 21 N Park St, Suite 1200, to the left of the parking garage entrance and bike racks.","Campus bus routes are fare-free for everyone, so the pass is for city routes."],"zh":["UW 交通服务处管校园停车、停车证、罚单和学生公交卡项目。大多数学生只来一次：领 ASM 学生公交卡，坐 Madison Metro 公交、BRT 快线和 paratransit 都不限次数。离校园中心最近的办公点在 21 N Park St, Suite 1200，停车楼入口和自行车架的左边。","校园线公交对所有人免费，公交卡是坐市区线路用的。"]},"offers":{"en":["ASM student bus pass, free, usable for as long as you are an eligible student.","Replacement for a lost bus pass.","Buy-it-now permits with no pre-approval: moped, motorcycle, afternoon and night parking.","Student Parking Program permits for commuters from outside Madison or students who drive to an off-campus job at least three times a week (pre-approval required).","UW accessible parking permits for students with a state DOT disabled parking permit.","Paying or appealing parking citations.","SAFEwalk, a free walking companion service around campus at night."],"zh":["ASM 学生公交卡：免费，只要你还是符合条件的学生就一直能用。","公交卡丢了可以补办。","不用预先审批、直接买的停车证：moped、摩托车、下午证和夜间证。","学生停车项目 (Student Parking Program)：给住在 Madison 以外的通勤生，或每周至少开车 3 次去校外打工的学生（需预先审批）。","持有州交通部 (DOT) 残障停车证的学生可以买 UW 无障碍停车证。","缴纳或申诉停车罚单。","SAFEwalk：晚上在校园里免费陪你走一段。"]},"howto":{"en":["Bus pass: bring your Wiscard or another photo ID to 21 N Park St, Suite 1200, or 610 Walnut St, Room 124. A new Wiscard can be used for this 15 minutes after it is printed.","The pass works right away: tap it on the fare reader when you board.","Permits are bought online through the Permit Application System or the eBusiness Portal; questions go to customerservice@fpm.wisc.edu or (608) 263-6666.","Clear old tickets first: unpaid citations or fees owed to Transportation Services block new parking permits."],"zh":["领公交卡：带 Wiscard 或其他带照片的证件，去 21 N Park St, Suite 1200 或 610 Walnut St 124 室。新办的 Wiscard 出卡 15 分钟后就能用来领。","公交卡当场生效：上车在读卡器上刷一下就行。","停车证在网上的 Permit Application System 或 eBusiness Portal 买；有问题发邮件 customerservice@fpm.wisc.edu 或打 (608) 263-6666。","先把旧罚单交清：欠交通服务处的罚款或费用没还，买不了新停车证。"]},"cost":{"en":["Student bus pass: no charge; it is funded through the segregated fee in your tuition. Replacement pass: $25.","Moped or motorcycle parking permit: $146 a year.","Night parking permit (surface lots): $136 a year; afternoon permit: $289 a year.","SAFEwalk is free for students, faculty, staff and visitors."],"zh":["学生公交卡免费，费用含在学费里的 segregated fee 中。补卡 25 美元。","Moped 或摩托车停车证一年 146 美元。","夜间停车证（露天停车场）一年 136 美元；下午证一年 289 美元。","SAFEwalk 对学生、教职工和访客免费。"]},"tips":{"en":["The Student Parking Program is not for parking near where you live or for driving between buildings for class; that is what the bus pass and campus buses are for.","SAFEwalk: call or text (608) 262-5000 for a free walk across campus, 7 p.m.–1 a.m. from Oct 1 to Mar 31. No service Dec 18, 2026–Jan 10, 2027.","Moped permits are tied to a specific moped lot, so pick the lot near where you park most.","Graduating or withdrawing? The pass keeps working until the first day of classes of the next semester; return it afterward."],"zh":["学生停车项目不批给想在住处附近停车、或开车在教学楼之间赶课的人；这些情况请用公交卡和校园巴士。","SAFEwalk：打电话或发短信 (608) 262-5000，有人免费陪你穿过校园；10 月 1 日到 3 月 31 日每天 19:00 到次日 1:00。2026 年 12 月 18 日到 2027 年 1 月 10 日暂停。","Moped 停车证只对应一个指定停车区，选你最常停的那一个。","毕业或休学后，公交卡能用到下学期开课第一天，之后要交还。"]},"intl":{"en":["All you need for the bus pass is your Wiscard or another photo ID, such as your passport."],"zh":["领公交卡只要 Wiscard 或其他带照片的证件，比如护照。"]}},"src":[["UW Transportation Services - home","https://transportation.wisc.edu/"],["Transportation Services - Contact Us, office locations and hours","https://transportation.wisc.edu/contact-us/"],["Transportation Services - UW Student Bus Pass Program","https://transportation.wisc.edu/bus/student-bus-pass-program/"],["Transportation Services - Bus","https://transportation.wisc.edu/commuter-solutions/bus/"],["Transportation Services - Rates","https://transportation.wisc.edu/rates-and-policies/rates/"],["Transportation Services - Student Parking","https://transportation.wisc.edu/permits/student-parking/"],["Transportation Services - SAFEwalk","https://transportation.wisc.edu/commuter-solutions/safewalk/"],["Wiscard - How to Use Your Wiscard","https://wiscard.wisc.edu/id-card/how-to-use-your-wiscard/"]],"unv":[],"chk":"2026-10-08","lat":43.068627,"lng":-89.400833,"stops":[["N Park at Regent",72,"B 82"],["Regent at N Park",109,"E 64"],["Regent at S Park",124,"E"]]},{"id":"wiscard-office","cat":"campus","n":{"en":"Wiscard Office","zh":"学生证办公室 (Wiscard Office)"},"kind":{"en":"Student ID card office","zh":"学生证办理处"},"addr":"1308 W Dayton St, Madison, WI 53715","phone":"(608) 262-3258","web":"https://wiscard.wisc.edu/","h":{"Mo":[[510,1020]],"Tu":[[510,1020]],"We":[[510,1020]],"Th":[[510,1020]],"Fr":[[510,1020]],"Sa":[],"Su":[]},"ht":{"en":"Mon–Fri 8:30 a.m.–5 p.m.; closed weekends and on Labor Day. Inside Union South, Room 149.","zh":"周一到周五 8:30–17:00；周末和 Labor Day 不开。在 Union South 149 室。"},"sum":{"en":"Makes your Wiscard, UW's official photo ID, while you wait; also replaces lost cards, takes account deposits and prints passport photos.","zh":"当场办学生证 (Wiscard)；补卡、充值、拍证件照也在这里。"},"kw":["Wiscard","student ID","学生证","ID card","补卡","lost card","passport photo","证件照","visa photo","deposit","充值","Union South"],"sec":{"about":{"en":["The Wiscard is UW–Madison's official photo ID. You need it to borrow library books, enter Rec Well facilities, get into your residence hall, and pick up the free student bus pass. The Wiscard Office in Union South, Room 149, checks your ID, takes your photo and prints the card during your visit.","The card also works as a Wiscard Account, a prepaid balance accepted at more than 60 campus locations, with discounts at campus restaurants, convenience stores and the University Book Store."],"zh":["Wiscard 是 UW–Madison 的官方带照片证件：借书、进 Rec Well 健身房、刷宿舍门禁、领免费学生公交卡都要用。Union South 149 室的 Wiscard Office 核对证件、拍照，当场把卡打出来。","卡里还带 Wiscard Account：预存的钱能在校内 60 多个地方用，学校餐厅、便利店和 University Book Store 还有折扣。"]},"offers":{"en":["Your first Wiscard, free and valid for 5 years.","Replacement cards for lost, stolen or damaged cards.","Free replacement for a name change, a status change, normal wear and tear, or a card more than 5 years old (hand in the old card).","Wiscard Account deposits in person by cash, check or credit card.","Passport, visa, immigration and OPT photos: a set of two 2x2-inch prints, made on the spot.","Free voter-compliant ID for eligible U.S. citizen students who vote in Wisconsin."],"zh":["第一张 Wiscard 免费，有效期 5 年。","丢失、被偷或损坏后补办新卡。","改名、身份变化、正常磨损或卡用满 5 年，换新卡免费（要交回旧卡）。","现场给 Wiscard Account 充值：现金、支票、信用卡都行。","护照、签证、移民文件和 OPT 用的证件照：一组两张 2x2 英寸照片，当场拍当场取。","给符合条件的美国公民学生免费办可在威州投票用的 voter ID。"]},"howto":{"en":["Bring one original government ID; a foreign passport is accepted. Copies are not.","Staff check that you are enrolled, take your photo and hand you the card before you leave; a confirmation email follows.","Lost card: mark it Lost/Stolen on the Wiscard account website right away so nobody can use your balance; door access is switched off too. Then come in for a replacement.","A new card can take a few days to work everywhere. Libraries update at mid-morning each business day; tell Rec Well staff if you visit before their nightly update.","You can pick up your student bus pass at Transportation Services 15 minutes after your card is made."],"zh":["带一份政府证件原件，外国护照就可以；复印件不收。","工作人员确认你在读后拍照，当场把卡给你；之后会收到确认邮件。","卡丢了马上在 Wiscard 账户网站点 Lost/Stolen 冻结，别人就用不了里面的钱，门禁也会一起停用。然后再来补卡。","新卡要几天才能在各处生效。图书馆每个工作日上午更新；Rec Well 每晚更新，之前去的话跟工作人员说一声。","出卡 15 分钟后就能去 Transportation Services 领学生公交卡。"]},"cost":{"en":["First card: free. Replacement for a lost, stolen or abused card: $25 (cash, check or credit card).","Passport photos: $10 for a set of two for students and Union members, $13 for others; prints only, no digital file.","In-person Wiscard deposits paid by credit card carry a 2% service fee ($0.50 minimum).","Paying with your Wiscard Account: 5% off and no sales tax at campus restaurants and convenience stores, 5% off textbooks and supplies at the University Book Store."],"zh":["第一张免费；丢失、被偷或人为损坏补卡 25 美元（现金、支票、信用卡都收）。","证件照：学生和 Union 会员一组两张 10 美元，其他人 13 美元；只有纸质照片，没有电子版。","在柜台用信用卡给 Wiscard 充值收 2% 手续费（最低 0.50 美元）。","用 Wiscard Account 付款：学校餐厅和便利店 95 折且免销售税，University Book Store 的课本文具 95 折。"]},"tips":{"en":["Found your lost card after reporting it? Reactivate it on the same Lost/Stolen page instead of paying for a new one.","Cards found on campus are returned to the Wiscard Office; call (608) 262-3258 to check.","Some systems ask for an 11-digit number: your ID number plus the issue code printed in the lower right corner of the card.","The Wiscard is not accepted as voter ID in Wisconsin; eligible U.S. citizens can get the separate free voter ID here."],"zh":["挂失后卡又找到了？在同一个 Lost/Stolen 页面重新激活就行，不用花钱补卡。","校内捡到的卡会送回 Wiscard Office，打 (608) 262-3258 问问。","有些系统要 11 位号码：就是卡号加上卡片右下角的 issue code。","Wiscard 在威州不能当投票证件；符合条件的美国公民可以在这里另办免费的 voter ID。"]},"intl":{"en":["Your foreign passport alone is enough ID to get a Wiscard.","Need photos for a visa renewal or an OPT application? The office makes them while you wait.","Around Madison, ISS advises carrying your Wiscard plus copies of your immigration documents."],"zh":["只带外国护照就能办 Wiscard。","续签证或申请 OPT 要证件照，这里可以当场拍、当场拿。","ISS 建议在 Madison 市内随身带 Wiscard 和移民文件复印件。"]}},"src":[["Wiscard - Contact, hours and location","https://wiscard.wisc.edu/contact-wiscard/"],["Wiscard - How to Get Your Wiscard","https://wiscard.wisc.edu/id-card/how-to-get-your-wiscard/"],["Wiscard - Replacement Fees","https://wiscard.wisc.edu/id-card/wiscard-replacement-fees/"],["Wiscard - How to Use Your Wiscard","https://wiscard.wisc.edu/id-card/how-to-use-your-wiscard/"],["Wiscard - Suspend a Lost Wiscard","https://wiscard.wisc.edu/id-card/suspend-a-lost-wiscard/"],["Wiscard - Passport Photos","https://wiscard.wisc.edu/passport-photos/"],["Wiscard - Voter ID","https://wiscard.wisc.edu/voter-id/"],["Wiscard - Make a Deposit","https://wiscard.wisc.edu/wiscard-account/make-a-deposit/"],["Wiscard - Wiscard Account","https://wiscard.wisc.edu/wiscard-account/accounts/"],["University Housing - Hall Desks","https://www.housing.wisc.edu/undergraduate/services/desks"],["ISS - Travel","https://iss.wisc.edu/students/current-students/travel/"]],"unv":[],"chk":"2026-10-08","lat":43.072211,"lng":-89.408637,"stops":[["N Randall at Engineering",45,"D O 80"],["W Johnson at N Orchard",70,"C D J O R"],["N Randall at W Dayton",97,"D O"]]},{"id":"cvs-pharmacy-south-bedford","cat":"health","n":{"en":"CVS Pharmacy – 2 S Bedford St","zh":"CVS 药店（S Bedford St 店）"},"kind":{"en":"Pharmacy & drugstore","zh":"药店"},"addr":"2 S Bedford St, Madison, WI 53703","phone":"(608) 251-6047","web":"https://www.cvs.com/store-locator/madison-wi-pharmacies/2-south-bedford-st-madison-wi-53703/storeid=4930","h":{"Mo":[[480,1320]],"Tu":[[480,1320]],"We":[[480,1320]],"Th":[[480,1320]],"Fr":[[480,1380]],"Sa":[[480,1380]],"Su":[[480,1320]]},"ht":{"en":"Store, as listed for October 2026: Mon–Thu and Sun 8 a.m.–10 p.m., Fri–Sat 8 a.m.–11 p.m. Pharmacy: Mon–Fri 9 a.m.–7 p.m., Sat 10 a.m.–6 p.m., Sun 11 a.m.–5 p.m.; closed 1:30–2 p.m. for lunch.","zh":"店面（2026 年 10 月）：周一到周四、周日 8:00–22:00，周五周六 8:00–23:00。药房：周一到周五 9:00–19:00，周六 10:00–18:00，周日 11:00–17:00；13:30–14:00 午休。"},"sum":{"en":"The CVS closest to campus, near S Bedford St and W Washington Ave: pharmacy with a drive-thru, vaccines, groceries and a UPS Access Point.","zh":"离校园最近的 CVS：药房带免下车窗口，能打疫苗，也卖食品，还是 UPS 取寄件点。"},"kw":["pharmacy","drugstore","CVS","prescription","vaccine","flu shot","UPS","passport photo","药店","药房","处方药","流感疫苗","寄快递"],"sec":{"about":{"en":["The CVS closest to campus, on South Bedford St. near West Washington Ave. It's a full drugstore with a pharmacy (including a drive-thru window), first aid supplies, vitamins, cosmetics and some groceries.","It is also a UPS Access Point, so you can drop off and pick up packages here."],"zh":["离校园最近的 CVS，在 South Bedford St，靠近 West Washington Ave。药房（带免下车取药窗口）、急救用品、维生素、化妆品和一些食品都有。","这里也是 UPS 取寄件点 (UPS Access Point)，可以寄包裹、取包裹。"]},"offers":{"en":["Pharmacy with drive-thru, prescription refills, transfers and Rx delivery","15+ vaccines including flu, COVID-19, RSV and shingles: schedule online or walk in","First aid, vitamins, cosmetics and groceries; SNAP and WIC accepted","UPS Access Point: drop off prepaid packages; packages sent here are held up to 7 days","Passport photos and photo printing","Drug disposal and an ATM inside"],"zh":["药房：免下车窗口、续药、转处方、送药上门","15 种以上疫苗（流感、新冠、RSV、带状疱疹等），可以网上预约，也可以直接去","急救用品、维生素、化妆品和食品；收 SNAP 和 WIC","UPS 取寄件点：能寄已付邮费的包裹；寄到这里的包裹保留 7 天","证件照（护照照片）和冲印照片","过期药回收，店内有 ATM"]},"howto":{"en":["Show your insurance card at the pharmacy. CVS says it takes most plans, but check that yours is accepted.","SHIP members: show the SHIP ID card. A new SHIP enrollment can take up to 3 business days to reach pharmacy systems.","The pharmacy closes 1:30–2 p.m. for lunch and keeps shorter hours on weekends.","An ExtraCare membership earns rewards and personalized coupons."],"zh":["在药房出示保险卡。CVS 说大部分保险都收，但最好先确认你的保险能用。","SHIP 学生出示 SHIP 卡；刚买的 SHIP 最多要 3 个工作日药房才查得到。","药房 13:30–14:00 午休，周末营业时间更短。","办 ExtraCare 会员可以攒积分、收到个性化优惠券。"]},"cost":{"en":["SHIP international plan 2026–27 prescription copays: $15 generic, $30 brand, $50 non-formulary.","Flu shots here are free with most insurance. UHS's fall campus flu clinics are free for students even without insurance."],"zh":["SHIP 国际生计划 2026–27 药费自付：仿制药 $15、品牌药 $30、非目录药 $50。","这里打流感疫苗，大部分保险免费；UHS 秋季校园流感疫苗点对学生免费，没保险也行。"]},"tips":{"en":["SHIP's prescription benefit is managed by CVS Caremark; reimbursement requests go through your caremark.com account.","Need medicine in the middle of the night? Walgreens' only 24-hour pharmacy in Madison is at 7810 Mineral Point Rd.","The next-closest CVS is at Hilldale (750 Hilldale Way)."],"zh":["SHIP 的药品福利由 CVS Caremark 管理，报销申请在 caremark.com 账户里提交。","半夜要买药：Madison 唯一 24 小时的 Walgreens 药房在 7810 Mineral Point Rd。","下一家最近的 CVS 在 Hilldale（750 Hilldale Way）。"]}},"src":[["CVS Pharmacy – 2 South Bedford St., Madison (store #4930)","https://www.cvs.com/store-locator/madison-wi-pharmacies/2-south-bedford-st-madison-wi-53703/storeid=4930"],["CVS – Stores in Madison, WI","https://www.cvs.com/store-locator/cvs-pharmacy-locations/Wisconsin/Madison"],["SHIP – FAQ about Member Cost Sharing & Claims","https://www.uhs.wisc.edu/ship/member-cost-sharing-claims-faq/"],["UHS – Student Health Insurance Plan (SHIP)","https://www.uhs.wisc.edu/ship/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["UHS – Flu & COVID-19 Vaccines for Students & Employees","https://www.uhs.wisc.edu/medical/flu-vaccines-for-students-employees/"],["Walgreens – 24-hour pharmacies, Madison WI","https://www.walgreens.com/storelocator/24-hour-pharmacy/madison-wi"]],"unv":[],"chk":"2026-10-08","lat":43.068604,"lng":-89.392385,"stops":[["W Washington at N Bedford",44,"E 75"],["W Washington at S Bedford",46,"E 75 81"],["N Bedford at W Mifflin",167,"81"]]},{"id":"madison-college-dental-hygiene-clinic","cat":"health","n":{"en":"Madison College Dental Hygiene Clinic","zh":"Madison College 洗牙诊所 (Dental Hygiene Clinic)"},"kind":{"en":"Low-cost dental cleanings","zh":"平价洗牙"},"addr":"1705 Hoffman St, Madison, WI 53704","phone":"(608) 258-2400","web":"https://madisoncollege.edu/dental-hygiene-clinic","h":null,"ht":{"en":"By appointment only. A 2024 news report says appointments are generally not available in summer, when classes aren't in session.","zh":"只接受预约。2024 年的报道说，夏天不上课时一般约不到。"},"sum":{"en":"Cheap teeth cleanings, X-rays and fluoride from supervised dental hygiene students at Madison College's Truax Campus; open to the public.","zh":"Madison College 牙科卫生专业学生在老师指导下洗牙、拍牙片，便宜，对外开放。"},"kw":["dental","dentist","teeth cleaning","low cost","Madison College","dental hygiene","牙医","洗牙","看牙","便宜","牙科"],"sec":{"about":{"en":["UHS does not do dental care, and SHIP's international plan doesn't cover adult dental care. For a routine cleaning, Madison College's Dental Hygiene Clinic is a cheap option: dental hygiene students do the work under instructor supervision, and the clinic is open to the public.","It is in Room 151 of the Health Education Building on Madison College's Truax Campus, on the east side. Its service list covers cleanings and preventive care; fillings and other dentist work are not on it."],"zh":["UHS 不看牙，SHIP 国际生计划也不保成人牙科。想洗个牙，Madison College 的洗牙诊所很便宜：牙科卫生专业的学生在老师指导下操作，对外开放。","诊所在 Madison College 东边 Truax 校区 Health Education Building 151 室。服务单上是洗牙和预防性护理，补牙等牙医的活不在上面。"]},"offers":{"en":["Cleanings (oral prophylaxis) and deep cleanings (periodontal therapy)","Dental X-rays","Fluoride treatments and sealants","Oral cancer exams, blood pressure checks and oral hygiene instruction"],"zh":["洗牙（洁治）和深层洗牙（牙周治疗）","拍牙片 (X 光)","涂氟、窝沟封闭","口腔癌筛查、量血压、口腔卫生指导"]},"howto":{"en":["Book by calling 608-258-2400 or emailing dentalclinic@madisoncollege.edu; the clinic works by appointment only.","Don't put your birth date or medical details in the email; the clinic warns that email isn't secure.","Go to the Health Education Building, 1705 Hoffman St., Room 151, on the Truax Campus."],"zh":["打 608-258-2400 或发邮件到 dentalclinic@madisoncollege.edu 预约，只接受预约。","邮件里别写生日和病情，诊所提醒邮件不安全。","地点：Truax 校区 Health Education Building，1705 Hoffman St.，151 室。"]},"cost":{"en":["Madison College calls the fee nominal and gives Madison College students and military veterans a discount. A local paper reported $40 per visit, or $30 for veterans and college students, in April 2024; confirm the current price when you book.","Not covered by UHS, and SHIP's international plan lists adult dental care as not covered."],"zh":["Madison College 说收费很低，Madison College 学生和退伍军人有折扣。2024 年 4 月当地报纸报道每次 $40，退伍军人和大学生 $30；预约时再确认现在的价格。","UHS 不管，SHIP 国际生计划也写明不保成人牙科。"]},"tips":{"en":["Book during the fall or spring semester; the clinic generally has no appointments in summer (2024 report).","Patients can often get in sooner than at a regular dental office, a faculty member said in 2024.","Need fillings or a toothache treated? UHS's medical page lists dentists near campus, including First Choice Dental Group (1050 Regent St., 608-256-0671), noted as having a low-cost dental plan for students."],"zh":["秋季或春季学期去约；2024 年的报道说夏天一般没号。","2024 年一位老师说，这里往往比普通牙医诊所约得快。","要补牙或牙疼？UHS 门诊页面列了校园附近的牙医，其中 First Choice Dental Group（1050 Regent St.，608-256-0671）标注有面向学生的低价牙科计划。"]},"intl":{"en":["SHIP doesn't pay for routine adult dental care, so cleanings here are out of pocket."],"zh":["SHIP 不管成人常规牙科，在这里洗牙要自己付钱。"]}},"src":[["Madison College – Dental Hygiene Clinic","https://madisoncollege.edu/dental-hygiene-clinic"],["HNG News (Apr 10, 2024) – At Madison College, dental hygiene students learn on patients","https://www.hngnews.com/lake_mills_leader/news/regional/at-madison-college-dental-hygiene-students-learn-on-patients/article_f96fb142-f50d-11ee-8faf-8fcf0aab2e93.html"],["About University Health Services","https://www.uhs.wisc.edu/about/"],["UHS – Medical Care (dentist list)","https://www.uhs.wisc.edu/medical/"],["SHIP 2026–27 International Summary of Benefits & Coverage (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SHIP-Intl-SBC-6-2-26.pdf"]],"unv":[],"chk":"2026-10-08","lat":43.123059,"lng":-89.333471,"stops":[["Wright at Madison College",312,"L"],["Wright at Kinsman",366,"L"],["Kinsman at Wright",410,"L"]]},{"id":"madison-optical-center","cat":"health","n":{"en":"Madison Optical Center","zh":"Madison Optical Center 验光配镜"},"kind":{"en":"Optometrist & eyewear","zh":"验光配镜"},"addr":"658 W Washington Ave, Madison, WI 53703","phone":"(608) 251-2020","web":"https://www.madisonopticalcenter.com/","h":{"Mo":[[600,960]],"Tu":[[600,1050]],"We":[[600,960]],"Th":[[600,1050]],"Fr":[[600,960]],"Sa":[[600,840]],"Su":[]},"ht":{"en":"Mon, Wed, Fri 10 a.m.–4 p.m.; Tue, Thu 10 a.m.–5:30 p.m.; Sat 10 a.m.–2 p.m.; Sun closed. Closed during all Badger home football games.","zh":"周一、三、五 10:00–16:00；周二、四 10:00–17:30；周六 10:00–14:00；周日休息。Badger 橄榄球主场比赛时关门。"},"sum":{"en":"Eye exams, glasses and contacts on W Washington Ave; it's SHIP's vision plan provider, so SHIP members get a $0 yearly eye exam.","zh":"W Washington Ave 上的验光配镜店，SHIP 指定视力服务点：SHIP 学生每年一次眼科检查免费。"},"kw":["eye exam","optometrist","glasses","contact lenses","vision","SHIP vision plan","验光","配眼镜","眼镜店","隐形眼镜","眼科检查"],"sec":{"about":{"en":["A locally owned optometry and eyewear shop, in business since 1983, in the City Station building on West Washington Ave. It is the provider named in SHIP's vision plan, so SHIP members get one comprehensive eye exam a year here at no charge, plus discounts on eyewear.","UHS has no eye care. Its medical page lists this shop among nearby optometrists, together with Isthmus Eye Care, Eye Contact and UW Health Eye Care Services."],"zh":["本地人开的验光配镜店，1983 年开到现在，在 West Washington Ave 的 City Station 楼里。它是 SHIP 视力福利 (vision plan) 指定的店：SHIP 学生每年一次全面眼科检查免费，配眼镜还有折扣。","UHS 不看眼睛。UHS 门诊页面列的附近验光店里就有这家，另外还有 Isthmus Eye Care、Eye Contact 和 UW Health Eye Care Services。"]},"offers":{"en":["Comprehensive eye exams (30 minutes to an hour)","Contact lens fittings, with instructions for putting lenses in and taking them out","Glasses: help choosing frames and lenses; sunglasses","Consultations about laser eye correction","Frame adjustments and simple repairs: free for frames bought there, $5–10 otherwise"],"zh":["全面眼科检查（30 分钟到 1 小时）","配隐形眼镜，教你怎么戴、怎么摘","配眼镜：帮你挑镜框和镜片；也有墨镜","近视激光手术咨询","调镜架、简单维修：在这买的镜框免费，别处买的收 $5–10"]},"howto":{"en":["Call 608-251-2020 to book; SHIP vision appointments must be scheduled in advance.","SHIP members: show your SHIP card at the visit so the vision plan pricing applies.","Running late or need to cancel? Call ahead. Under the SHIP plan a broken appointment costs $25.","Payment: cash, checks and major credit cards."],"zh":["打 608-251-2020 预约；SHIP 规定视力服务必须提前约。","SHIP 学生看诊时出示 SHIP 卡，才能按视力福利算价。","要迟到或取消，提前打电话。按 SHIP 规定，爽约一次收 $25。","付款：现金、支票和主要信用卡。"]},"cost":{"en":["SHIP members: annual comprehensive eye exam $0; contact lens fitting $60 (standard) or $70 (specialty).","SHIP discounts: 20–25% off frames, lenses and lens add-ons, 25% off sunglasses, 20% off conventional and 10% off disposable contacts. Discounts come off regular prices, and a lower sale price wins."],"zh":["SHIP 学生：每年一次全面眼科检查 $0；隐形眼镜验配 $60（普通）或 $70（特殊）。","SHIP 折扣：镜框、镜片和镜片加项 20–25%，墨镜 25%，普通隐形眼镜 20%，抛弃型 10%。折扣按原价算，店里促销价更低时按促销价。"]},"tips":{"en":["Closed during Badger home football games; check the schedule before booking a fall Saturday.","Not on SHIP? Compare with the other optometrists on UHS's list, such as Isthmus Eye Care (425 W. Washington Ave., 608-255-3854)."],"zh":["Badger 橄榄球主场比赛时关门，秋季周六预约前先看赛程。","没买 SHIP 的话，可以对比 UHS 名单上的其他验光店，比如 Isthmus Eye Care（425 W. Washington Ave.，608-255-3854）。"]},"intl":{"en":["SHIP's international plan includes an annual eye exam; bring your SHIP card or use the electronic ID card from the SHIP website."],"zh":["SHIP 国际生计划包含每年一次眼科检查；带 SHIP 卡，或者用 SHIP 网站上的电子卡。"]}},"src":[["Madison Optical Center – home","https://www.madisonopticalcenter.com/"],["Madison Optical Center – FAQs","https://www.madisonopticalcenter.com/faqs/"],["SHIP – Description of Vision Plan (PDF linked from the 2026–27 SHIP page)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/05/Vision-Benefit-Page-Only-from-Plan-Doc-23-24-with-Reference-to-Pediatric-Vision-Benefit-added-RS-9-29-23.pdf"],["SHIP – Health Insurance for International Students","https://www.uhs.wisc.edu/ship/international/"],["UHS – Medical Care (optometrist list)","https://www.uhs.wisc.edu/medical/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["SHIP – FAQ about Member Cost Sharing & Claims","https://www.uhs.wisc.edu/ship/member-cost-sharing-claims-faq/"]],"unv":[],"chk":"2026-10-08","lat":43.067658,"lng":-89.394289,"stops":[["W Washington at Regent",49,"E 75"],["Regent at W Washington",107,"E"],["W Washington at N Bedford",213,"E 75"]]},{"id":"medic-southside-free-clinic","cat":"health","n":{"en":"MEDiC Southside Clinic (UW student-run free clinic)","zh":"MEDiC Southside 免费诊所（UW 医学院学生义诊）"},"kind":{"en":"Free clinic","zh":"免费诊所"},"addr":"1102 S Park St, Madison, WI 53715","phone":"(608) 265-4972","web":"https://www.med.wisc.edu/education/medic/clinics/","h":null,"ht":{"en":"Saturdays; MEDiC does not post clinic times online. Call 608-265-4972 (option 2) for an appointment; some walk-ins are accepted.","zh":"周六开诊，具体时间网上没写。打 608-265-4972 按 2 预约；也接受少量直接上门的病人。"},"sum":{"en":"Free Saturday urgent care run by UW health-professions students for adults who are uninsured or underinsured, regardless of status or language.","zh":"UW 医学相关专业学生办的周六免费急症门诊，面向没保险或保险不够的成年人。"},"kw":["free clinic","MEDiC","uninsured","underinsured","student-run clinic","urgent care","UW School of Medicine","免费诊所","义诊","没保险","看病"],"sec":{"about":{"en":["MEDiC is a student-run program of the UW School of Medicine and Public Health. Medical, physician assistant, nursing, pharmacy and physical therapy students, supervised by volunteer clinicians, run four free clinics in Madison and partner with three more.","Its Saturday Southside Clinic, on the 2nd floor of 1102 S. Park St., gives free urgent care to adults who are uninsured or underinsured, regardless of documentation status or language spoken. MEDiC's other clinics grew out of shelters and day centers for people experiencing homelessness."],"zh":["MEDiC 是 UW 医学与公共卫生学院 (SMPH) 学生自己运营的项目：医学、医师助理、护理、药学、物理治疗专业的学生在志愿医生指导下，在 Madison 开了 4 家免费诊所，还和另外 3 家合作。","周六开的 Southside Clinic 在 1102 S. Park St. 二楼，给没保险或保险不够的成年人免费看急症，不问身份、不限语言。MEDiC 其他几家诊所主要设在收容所和流浪者日间中心。"]},"offers":{"en":["Free urgent care for adults without insurance or with too little coverage","Help getting connected to a regular primary care provider in the community","Care regardless of documentation status or language spoken"],"zh":["给没保险或保险不够的成年人免费看急症","帮你在社区里找到固定的家庭医生 (primary care provider)","不问身份证件，不限语言"]},"howto":{"en":["Call 608-265-4972, option 2, to make an appointment; MEDiC prefers that you call ahead. Option 1 is for general questions.","Some walk-in patients are accepted.","Medical emergency: call 911 instead."],"zh":["打 608-265-4972 按 2 预约，MEDiC 希望你提前打电话；一般问题按 1。","也接受少量直接上门的病人。","急症（危及生命）：打 911。"]},"cost":{"en":["Free.","Services MEDiC refers you to may charge different amounts based on your income."],"zh":["免费。","MEDiC 转介你去的社区服务，可能按收入收不同的费用。"]},"tips":{"en":["Have SHIP or other insurance? Use UHS on weekdays or an urgent care instead; MEDiC is meant for adults without enough coverage.","Already have a primary care provider? MEDiC says it's best to see that provider.","UW health-professions students can volunteer in MEDiC clinics."],"zh":["买了 SHIP 或有其他保险的话，工作日去 UHS 或者去 urgent care；MEDiC 是给保险不够的成年人准备的。","已经有固定家庭医生的，MEDiC 建议还是找自己的医生。","UW 医学相关专业的学生可以去 MEDiC 诊所做志愿者。"]}},"src":[["UW SMPH – MEDiC Clinics","https://www.med.wisc.edu/education/medic/clinics/"],["UW SMPH – MEDiC","https://www.med.wisc.edu/education/medic"],["UW SMPH – About MEDiC","https://www.med.wisc.edu/education/medic/about/"],["UW Health – 1102 S Park St Clinic (building address, ZIP)","https://www.uwhealth.org/locations/1102-s-park-st-clinic-258"],["SHIP – Find Health Care Providers","https://www.uhs.wisc.edu/ship/providers/"]],"unv":["hours"],"chk":"2026-10-08","lat":43.055134,"lng":-89.397954,"stops":[["Fish Hatchery at Midland",101,"O 63 75"],["S Park at W Olin",142,"B 63 64"],["S Park at Fish Hatchery",159,"B O 63 64"]]},{"id":"ssm-health-st-marys-hospital-emergency","cat":"health","n":{"en":"SSM Health St. Mary's Hospital – Madison, Emergency Room","zh":"SSM Health St. Mary's 医院急诊（Madison）"},"kind":{"en":"Hospital emergency room","zh":"医院急诊"},"addr":"700 S Brooks St, Madison, WI 53715","phone":"(608) 251-6100","web":"https://www.ssmhealth.com/locations/location-details/emergency-room-st-marys-hospital-madison","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1440]],"Sa":[[0,1440]],"Su":[[0,1440]]},"ht":{"en":"Emergency room open 24 hours, every day.","zh":"急诊 24 小时全年开。"},"sum":{"en":"24/7 emergency room and Level II trauma center at SSM Health St. Mary's Hospital in Madison. In a life-threatening emergency, call 911.","zh":"SSM Health St. Mary's 医院的 24 小时急诊，二级创伤中心。危及生命先打 911。"},"kw":["emergency room","ER","St. Mary's","SSM Health","hospital","trauma","stroke","911","急诊","医院","急救"],"sec":{"about":{"en":["St. Mary's is SSM Health's hospital in Madison, serving the area since 1912. Its emergency room is open 24/7 and is an American College of Surgeons-verified Level II Trauma Center; the hospital is also a certified thrombectomy-capable stroke center.","SSM's own location pages give the address as 700 S. Brooks St., where the main entrance is, across from the SSM Health Outpatient Center. Older listings, including UHS's ER page, still say 700 S. Park St."],"zh":["St. Mary's 是 SSM Health 在 Madison 的医院，1912 年起就在这里。急诊 24 小时开，是美国外科医师学会认证的二级创伤中心 (Level II Trauma Center)；医院还是认证的取栓卒中中心。","SSM 官网现在写的地址是 700 S. Brooks St.，正门就在这条街上，对面是 SSM Health Outpatient Center。一些旧资料（包括 UHS 的急诊页面）还写 700 S. Park St.。"]},"offers":{"en":["24/7 emergency and critical care for serious injuries, including falls and bicycle, motorcycle and car crashes","Level II trauma team with a trauma surgeon, plus on-call neurosurgeons, orthopedic and other specialist surgeons","Stroke care as a certified thrombectomy-capable stroke center","Free interpreters and written information in other languages"],"zh":["24 小时急诊和重症救治：摔伤、自行车、摩托车、车祸等严重外伤","二级创伤团队：有创伤外科医生，神经外科、骨科等专科医生随叫随到","卒中（中风）救治：认证的取栓卒中中心","免费翻译，也有其他语言的书面资料"]},"howto":{"en":["Life-threatening emergency: call 911.","Going in yourself: the hospital's main entrance is at 700 S. Brooks St., across from the main entrance of the SSM Health Outpatient Center.","Hospital main line: 608-251-6100.","Need an interpreter? Tell your care team; SSM says to ask your health care professional."],"zh":["危及生命：打 911。","自己去：医院正门在 700 S. Brooks St.，对面是 SSM Health Outpatient Center 的正门。","医院总机：608-251-6100。","要翻译就直接跟医护人员说（SSM 官网就是这么建议的）。"]},"cost":{"en":["ER and hospital charges are not covered by segregated fees or UHS.","SHIP's Premier Ruby (lower-cost) list for Madison names UW Health and Meriter, not St. Mary's. For a medical emergency, though, SHIP's ER cost is the same in every tier: $100 copay plus the deductible, 0% coinsurance."],"zh":["急诊和住院费用不在隔离费里，UHS 也不付。","SHIP 在 Madison 的 Premier Ruby（便宜档）名单只写了 UW Health 和 Meriter，没有 St. Mary's；不过真急症在每一档的急诊费用都一样：$100 自付加免赔额，0% 共付。"]},"tips":{"en":["Not an emergency? UHS lists SSM Health urgent care at 1821 S. Stoughton Rd. (608-260-6000) and 752 N. High Point Rd. (608-824-4000).","For map apps, use 700 S. Brooks St., the main entrance address SSM gives."],"zh":["不算急诊的话：UHS 列了 SSM Health 的 urgent care，在 1821 S. Stoughton Rd.（608-260-6000）和 752 N. High Point Rd.（608-824-4000）。","用地图导航时输 700 S. Brooks St.，这是 SSM 给的正门地址。"]},"intl":{"en":["SSM lists language help in many languages, including Simplified Chinese, and interpreters are free."],"zh":["SSM 有多种语言协助，包括简体中文，翻译免费。"]}},"src":[["SSM Health – Emergency Room at St. Mary's Hospital – Madison","https://www.ssmhealth.com/locations/location-details/emergency-room-st-marys-hospital-madison"],["SSM Health St. Mary's Hospital – Madison","https://www.ssmhealth.com/locations/wisconsin/st-marys-hospital-madison"],["SSM Health – Notice of Non-Discrimination","https://www.ssmhealth.com/non-discrimination"],["UHS – Emergency Rooms & Urgent Care","https://www.uhs.wisc.edu/emergency-rooms-urgent-care/"],["SHIP – Find Health Care Providers","https://www.uhs.wisc.edu/ship/providers/"],["SHIP 2026–27 International Summary of Benefits & Coverage (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SHIP-Intl-SBC-6-2-26.pdf"]],"unv":[],"chk":"2026-10-08","lat":43.059758,"lng":-89.402541,"stops":[["Erin at S Mills",91,"O"],["Erin at S Park",110,"O"],["S Park at Erin",126,"B O 63 64 75"]]},{"id":"uhs-student-health-insurance-plan-office","cat":"health","n":{"en":"Student Health Insurance Plan (SHIP) Office","zh":"学生医保 (SHIP) 办公室"},"kind":{"en":"Student insurance office","zh":"学生医保办公室"},"addr":"333 East Campus Mall, Madison, WI 53715","phone":"(608) 265-5232","web":"https://www.uhs.wisc.edu/ship/","h":{"Mo":[[480,960]],"Tu":[],"We":[[480,960]],"Th":[],"Fr":[[480,960]],"Sa":[],"Su":[]},"ht":{"en":"New schedule, as of October 2026: in person Mon, Wed, Fri 8 a.m.–4 p.m.; phone and email Mon–Fri 8 a.m.–4 p.m. 8th floor of 333 East Campus Mall.","zh":"新时间表（2026 年 10 月）：现场办理周一、三、五 8:00–16:00；电话和邮件周一到周五 8:00–16:00。地点在 333 East Campus Mall 8 楼。"},"sum":{"en":"UW–Madison's own student health insurance, run by UHS. International students must have SHIP or an approved waiver; this office handles both.","zh":"UW 自己的学生医保，由 UHS 管理。国际生必须买 SHIP 或获批豁免，都在这里办。"},"kw":["SHIP","Student Health Insurance Plan","health insurance","international students","waiver","insurance card","学生医保","医疗保险","保险","国际生","豁免","保险卡"],"sec":{"about":{"en":["SHIP is UW–Madison's student health insurance plan, run locally by UHS and not for profit. International students and their visa dependents must enroll in SHIP or have an approved waiver; U.S. students can buy it if they carry at least 6 credits (undergrad) or 3 credits (grad).","SHIP pays for what UHS doesn't do: after-hours and urgent care, the ER, hospital stays, specialists and prescriptions. Care is tiered: UHS first (no cost), then the Premier Ruby network (UW Health, UnityPoint–Meriter), then other network and out-of-network providers. The office on the 8th floor of 333 East Campus Mall handles enrollment, waivers, ID cards and coverage questions."],"zh":["SHIP 是 UW–Madison 自己的学生医疗保险，由 UHS 在本地管理，不以盈利为目的。国际生和签证家属必须买 SHIP 或申请到豁免 (waiver)；美国学生本科修满 6 学分、研究生 3 学分也可以买。","UHS 管不了的，SHIP 来付：下班后和急症门诊、急诊、住院、专科、处方药。看病分档：先找 UHS（免费），其次 Premier Ruby 网络（UW Health、UnityPoint–Meriter），再往后是其他网络和网络外医生。333 East Campus Mall 8 楼的办公室负责投保、豁免、保险卡和各种保障问题。"]},"offers":{"en":["Enrollment, premium payment and your member ID card online at ship.uhs.wisc.edu","Waivers, automatic waivers for UW–Madison employees with UW health insurance, and compliance holds","Help with claims, Explanation of Benefits statements and finding in-network providers","International plan extras: annual eye exam and worldwide assistance, including medical evacuation and repatriation","Coverage for non-emergency care when traveling outside the U.S."],"zh":["在 ship.uhs.wisc.edu 上投保、交保费、下载保险卡","办理豁免（在 UW 工作并有 UW 医保的自动豁免）、处理不合规 hold","理赔问题、看懂 Explanation of Benefits 说明、找网络内医生","国际生计划附加：每年一次眼科检查，全球紧急援助（包括医疗转运和遗体运返）","在美国境外的非急诊看病也在保障范围内"]},"howto":{"en":["International students, 2026–27: Annual/Fall enrollment closed Sept 14 (Annual coverage runs Aug 15, 2026–Aug 14, 2027). Spring/Summer enrollment opens Dec 15, 2026 and is due Feb 14.","Waivers are approved only for the criteria on the waiver form; individual, travel and Marketplace plans don't qualify. Read the form before buying other insurance.","Visit in person Mon, Wed or Fri, or call 608-265-5232 / email shipmail@uhs.wisc.edu Mon–Fri, 8 a.m.–4 p.m.","Right after enrolling, pharmacies may not see your coverage for up to 3 business days; use the electronic ID card from the SHIP site meanwhile.","Use UHS for primary care whenever possible; SHIP requires UHS for any preventive care UHS offers."],"zh":["国际生 2026–27：全年/秋季 9 月 14 日已截止（全年保障期 2026/8/15–2027/8/14）。春夏季 2026 年 12 月 15 日开放，2 月 14 日截止。","豁免只按申请表上列的条件批；个人保险、旅行险、Marketplace 保险都不算。买别的保险之前先看清申请表。","周一、三、五可以去现场；周一到周五 8:00–16:00 可以打 608-265-5232 或发邮件到 shipmail@uhs.wisc.edu。","刚投保时药房最多要 3 个工作日才查得到，这期间用 SHIP 网站上的电子保险卡。","能在 UHS 看的先在 UHS 看；SHIP 规定 UHS 能做的预防性医疗必须在 UHS 做。"]},"cost":{"en":["International student premiums 2026–27 (student only): $1,572 annual, $655 fall, $917 spring/summer. Student + spouse/partner: $4,728 a year.","International plan cost sharing: UHS $0; Premier Ruby deductible $125, then 5% coinsurance, out-of-pocket maximum $1,500 a year.","ER: $100 copay plus the $250 deductible for medical emergencies. Prescriptions: $15 generic, $30 brand, $50 non-formulary.","Late: a $100 fee plus premiums back to the start of the compliance period, and an academic hold until you comply."],"zh":["国际生 2026–27 保费（仅本人）：全年 $1,572，秋季 $655，春夏 $917。本人 + 配偶/伴侣全年 $4,728。","国际生计划自付：UHS $0；Premier Ruby 网络免赔额 $125，之后自付 5%，每年自付封顶 $1,500。","急诊：真急症 $100 自付加 $250 免赔额。处方药：仿制药 $15、品牌药 $30、非目录药 $50。","逾期：罚 $100，保费从保障期开头补交，并被加学业 hold，直到合规为止。"]},"tips":{"en":["Annual coverage ends Aug 14 each year; buy the next plan year by the Sept 14 deadline.","Buying Fall and Spring/Summer separately ($655 + $917) costs the same as Annual ($1,572).","Undergrads can ask Student Financial Services to include the SHIP cost in their financial aid package.","In The Alliance provider search, Tier 2 (Premier Ruby) providers are listed first. Benefit questions can also go to the claims administrator, Wellfleet, at 1-877-657-5031.","SHIP has no continuation option once you're no longer eligible; UHS points to coveringwi.org for other options."],"zh":["全年保障每年 8 月 14 日到期；下一年度要在 9 月 14 日前买。","秋季和春夏季分开买（$655 + $917）和买全年（$1,572）一样贵。","本科生可以请学生资助办公室 (Student Financial Services) 把 SHIP 费用算进助学金预算。","在 The Alliance 搜医生，Tier 2（Premier Ruby）排在最前面。保障问题也可以打理赔管理方 Wellfleet：1-877-657-5031。","不再符合资格后 SHIP 没有续保选项，UHS 建议去 coveringwi.org 找别的保险。"]},"intl":{"en":["Required: all international students and visa dependents need SHIP or an approved waiver. UW–Madison employees whose UW health insurance starts by Sept 1, 2026 (fall) get an automatic waiver filed for them.","Miss the deadline and you're enrolled automatically, charged a $100 late fee, and get an academic hold that blocks adding or dropping classes and getting transcripts.","UHS is the cheapest place to use SHIP: most UHS care is fully covered with no out-of-pocket cost."],"zh":["强制要求：国际生和签证家属都必须有 SHIP 或获批的豁免。在 UW 工作、UW 医保 2026 年 9 月 1 日前生效的，SHIP 办公室会自动替你办豁免。","错过截止日会被自动投保，罚 $100，还会被加学业 hold，不能加课退课、不能开成绩单。","用 SHIP 最省钱的地方是 UHS：大部分 UHS 看诊全额覆盖，自己不用掏钱。"]}},"src":[["UHS – Student Health Insurance Plan (SHIP)","https://www.uhs.wisc.edu/ship/"],["SHIP – Health Insurance for International Students","https://www.uhs.wisc.edu/ship/international/"],["SHIP – Frequently Asked Questions about Health Insurance","https://www.uhs.wisc.edu/ship/faq-ship/"],["SHIP – FAQ about Member Cost Sharing & Claims","https://www.uhs.wisc.edu/ship/member-cost-sharing-claims-faq/"],["SHIP – Find Health Care Providers","https://www.uhs.wisc.edu/ship/providers/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["SHIP 2026–27 International Summary of Benefits & Coverage (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SHIP-Intl-SBC-6-2-26.pdf"],["SHIP – International Student Waiver Application 2026–27 Fall (PDF, 7/15/26)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/07/INTL-STUDENT-WAIVER-APP-2026-27-FALL-7-15-26.pdf"]],"unv":[],"chk":"2026-10-08","lat":43.072489,"lng":-89.398931,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"uhs-health-vending-machine","cat":"health","n":{"en":"UHS Health Vending Machine (Student Activity Center)","zh":"UHS 健康用品售货机（学生活动中心 SAC）"},"kind":{"en":"Health supplies vending machine","zh":"健康用品售货机"},"addr":"333 East Campus Mall, Madison, WI 53715","phone":"","web":"https://www.uhs.wisc.edu/health-vending-machine/","h":{"Mo":[[600,1320]],"Tu":[[600,1320]],"We":[[600,1320]],"Th":[[600,1320]],"Fr":[[600,1200]],"Sa":[[600,1200]],"Su":[[600,1320]]},"ht":{"en":"Usable whenever the Student Activity Center is open. SAC fall 2026 hours: Sun–Thu 10 a.m.–10 p.m., Fri–Sat 10 a.m.–8 p.m.; closed Labor Day and over Thanksgiving (closes 5 p.m. Nov 25, reopens 10 a.m. Nov 30).","zh":"学生活动中心 (SAC) 开门时都能用。SAC 2026 秋季：周日到周四 10:00–22:00，周五周六 10:00–20:00；劳动节和感恩节期间关门（11/25 下午 5 点关，11/30 上午 10 点开）。"},"sum":{"en":"Vending machine in the Student Activity Center selling cheap health basics: $6 emergency contraception, pain relievers, tests; free Narcan.","zh":"学生活动中心 (SAC) 里的健康用品售货机：$6 紧急避孕药、止痛药、验孕棒，Narcan 免费。"},"kw":["vending machine","emergency contraception","Plan B","condoms","pregnancy test","Narcan","naloxone","ibuprofen","售货机","紧急避孕药","避孕套","验孕棒","止痛药"],"sec":{"about":{"en":["A vending machine on the 3rd floor of the Student Activity Center (SAC) at 333 East Campus Mall, the same building as UHS. UHS runs it with Associated Students of Madison (ASM), who pushed for cheaper health products for students.","It covers small needs without a pharmacy trip: pain relievers, cold and allergy medicine, first aid, sexual health products and emergency contraception."],"zh":["放在 333 East Campus Mall 学生活动中心 (SAC) 3 楼的自动售货机，和 UHS 同一栋楼。UHS 和学生组织 ASM (Associated Students of Madison) 合办，是 ASM 为了让学生买到更便宜的健康用品争取来的。","小毛病不想跑药店时很方便：止痛药、感冒过敏药、创可贴、性健康用品和紧急避孕药都有。"]},"offers":{"en":["Emergency contraception (levonorgestrel pill) for $6","Pain and fever: ibuprofen $3, Tylenol $3.50, thermometer $7.50","Cold and allergy: loratadine $0.50, allergy relief $3.50, cough drops $5, Robitussin $8, decongestant nasal spray $3","Stomach: Tums $3, Pepto Bismol $3.50, anti-diarrheal $2.50","Sexual and menstrual health: condoms $4, lubricant $6.50, pregnancy test $15, Monistat $15, menstrual cup $15","Band-Aids $4; toothbrush and toothpaste $4","Free naloxone (Narcan) nasal spray and fentanyl test strips"],"zh":["紧急避孕药（左炔诺孕酮片）$6","止痛退烧：布洛芬 $3、泰诺 $3.50、体温计 $7.50","感冒过敏：氯雷他定 $0.50、抗过敏药 $3.50、润喉糖 $5、Robitussin 止咳糖浆 $8、鼻塞喷雾 $3","肠胃：Tums $3、Pepto Bismol $3.50、止泻药 $2.50","性健康和经期：安全套 $4、润滑剂 $6.50、验孕棒 $15、Monistat $15、月经杯 $15","创可贴 $4；牙刷牙膏 $4","免费的纳洛酮 (Narcan) 鼻喷剂和芬太尼试纸"]},"howto":{"en":["Go to the 3rd floor of the Student Activity Center, 333 East Campus Mall.","For free fentanyl test strips, enter the item code for test strips.","UHS says emergency contraception should be taken as soon as possible within 72 hours of unprotected sex."],"zh":["去 333 East Campus Mall 学生活动中心 (SAC) 3 楼。","要免费芬太尼试纸，输入试纸对应的商品编号。","UHS 提醒：紧急避孕药要在无保护性行为后 72 小时内尽快吃。"]},"cost":{"en":["Prices run from $0.50 to $15 (UHS list, October 2026); naloxone and fentanyl test strips are free."],"zh":["价格 $0.50 到 $15（UHS 2026 年 10 月价目）；纳洛酮和芬太尼试纸免费。"]},"tips":{"en":["Emergency contraception here costs $6; the Walgreens in the same building listed Plan B One-Step at $49.99 in October 2026.","Naloxone boxes are also in residence halls (keycard access) and in other campus buildings during open hours.","For anything beyond self-care, book a visit at UHS in the same building."],"zh":["这里的紧急避孕药 $6；同一栋楼的 Walgreens 2026 年 10 月网页上 Plan B One-Step 标价 $49.99。","宿舍楼（刷卡进入）和其他校园建筑（开放时间内）也有纳洛酮急救箱。","自己处理不了的，去同一栋楼的 UHS 约医生。"]}},"src":[["UHS – Health Vending Machine","https://www.uhs.wisc.edu/health-vending-machine/"],["Student Organization Leadership & Involvement – Student Activity Center (SAC) hours","https://soli.wisc.edu/student-activity-center-sac/"],["UHS – Harm Reduction Resources on Campus","https://www.uhs.wisc.edu/prevention/substance-misuse-prevention/harm-reduction/"],["Walgreens – Store #11858, 311 E Campus Mall","https://www.walgreens.com/locator/walgreens-311+e+campus+mall-madison-wi-53715/id=11858"],["UHS – Information for Incoming Students","https://www.uhs.wisc.edu/soar/"]],"unv":["hours"],"chk":"2026-10-08","lat":43.072489,"lng":-89.398931,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"uhs-lakeshore-clinic","cat":"health","n":{"en":"UHS Lakeshore Clinic (Dejope Hall)","zh":"UHS Lakeshore 分诊所（Dejope 宿舍楼）"},"kind":{"en":"Campus clinic","zh":"校内小诊所"},"addr":"640 Elm Dr, Madison, WI 53706","phone":"(608) 265-5600","web":"https://www.uhs.wisc.edu/about/hours-locations/","h":{"Mo":[[540,720],[780,990]],"Tu":[[540,720],[780,990]],"We":[[580,720],[780,990]],"Th":[[540,720],[780,990]],"Fr":[[540,720],[780,990]],"Sa":[],"Su":[]},"ht":{"en":"As posted in October 2026: Mon, Tue, Thu, Fri 9 a.m.–4:30 p.m.; Wed 9:40 a.m.–4:30 p.m.; closed for lunch 12–1 p.m. every day. Closed on legal holidays, during winter and spring break, and all summer.","zh":"2026 年 10 月官网：周一、二、四、五 9:00–16:30，周三 9:40–16:30；每天 12:00–13:00 午休。法定假日、寒假、春假和整个夏天关门。"},"sum":{"en":"Small UHS clinic in Dejope Hall on the lakeshore for basic problems like colds, allergies, pink eye and ear pain; free, by appointment.","zh":"Dejope 宿舍楼里的 UHS 小诊所，看感冒、过敏、红眼病、耳朵疼这类小毛病；免费，要预约。"},"kw":["UHS","Lakeshore Clinic","Dejope","clinic","doctor","cold","allergies","校医院","分诊所","看病","湖边宿舍","感冒"],"sec":{"about":{"en":["UHS's satellite clinic in Room 1104 of Dejope Residence Hall, on the shore of Lake Mendota. It offers basic medical care for certain problems: allergies, neck and back pain, bug bites and stings, colds and flu, pink eye and ear pain. It's open to all students, not only Dejope residents.","Everything else, including mental health, survivor services and the full range of medical care, is at the main UHS clinic at 333 East Campus Mall."],"zh":["UHS 在 Dejope 宿舍楼 1104 室开的分诊所，就在 Lake Mendota 湖边。只看一部分常见小毛病：过敏、脖子和腰背痛、虫咬蜂蜇、感冒流感、红眼病、耳朵疼。所有学生都能用，不限 Dejope 住户。","其他的，比如心理咨询、性侵后援助和完整的门诊服务，都在 333 East Campus Mall 的 UHS 主诊所。"]},"offers":{"en":["Colds, flu and allergies","Pink eye and ear pain","Neck and back pain","Bug bites and stings"],"zh":["感冒、流感、过敏","红眼病、耳朵疼","脖子痛、腰背痛","虫咬、蜂蜇"]},"howto":{"en":["Appointments are required: book in MyUHS or call 608-265-5600 (option 1).","The clinic is in Room 1104 of Dejope Hall, 640 Elm Dr.","Complete the required MyUHS health forms first; the same rules apply as at the main clinic."],"zh":["需要预约：在 MyUHS 上约，或打 608-265-5600 按 1。","诊所在 Dejope Hall（640 Elm Dr.）1104 室。","先在 MyUHS 里填好必填的健康表格，规矩和主诊所一样。"]},"cost":{"en":["No cost for students enrolled for credit who pay segregated fees, same as the main UHS clinic."],"zh":["和 UHS 主诊所一样，修学分并交了隔离费的学生免费。"]},"tips":{"en":["Closed 12–1 p.m. for lunch every day, and closed all summer and over winter and spring break.","After hours, call UHS's 24/7 nurse line: 608-265-5600 (option 1)."],"zh":["每天 12:00–13:00 午休；夏天、寒假、春假都关门。","下班后打 UHS 24 小时护士电话：608-265-5600 按 1。"]}},"src":[["UHS – Hours & Locations","https://www.uhs.wisc.edu/about/hours-locations/"],["University Housing – Dejope Residence Hall","https://www.housing.wisc.edu/undergraduate/residence-halls/dejope/"],["UHS – Information for Incoming Students","https://www.uhs.wisc.edu/soar/"],["UHS – Make an Appointment","https://www.uhs.wisc.edu/make-an-appointment/"],["About University Health Services","https://www.uhs.wisc.edu/about/"],["UHS – Eligibility for UHS Services","https://www.uhs.wisc.edu/about/eligibility/"],["UHS – Call for Help","https://www.uhs.wisc.edu/call-for-help/"]],"unv":[],"chk":"2026-10-08","lat":43.07784,"lng":-89.417757,"stops":[["Observatory at Elm",186,"28 38 65 80 82"],["Observatory at Colwood",271,"28 38 65 80 84"],["Observatory at Babcock",408,"28 38 65 80 82"]]},{"id":"uhs-mental-health-services","cat":"health","n":{"en":"UHS Mental Health Services","zh":"UHS 心理健康服务 (Mental Health Services)"},"kind":{"en":"Student counseling center","zh":"学生心理咨询中心"},"addr":"333 East Campus Mall, Madison, WI 53715","phone":"(608) 265-5600","web":"https://www.uhs.wisc.edu/mental-health/","h":{"Mo":[[480,960]],"Tu":[[480,960]],"We":[[480,960]],"Th":[[570,960]],"Fr":[[480,960]],"Sa":[],"Su":[]},"ht":{"en":"Office hours as posted in October 2026: Mon, Tue, Wed, Fri 8 a.m.–4 p.m.; Thu 9:30 a.m.–4 p.m. Crisis line 24/7 at 608-265-5600 (option 9). Uwill online counseling also has night and weekend times.","zh":"办公时间（2026 年 10 月官网）：周一、二、三、五 8:00–16:00，周四 9:30–16:00。危机热线 24 小时：608-265-5600 按 9。Uwill 线上咨询晚上和周末也能约。"},"sum":{"en":"Free, confidential counseling for UW students: short-term therapy, groups, drop-in chats, online sessions and a 24/7 crisis line.","zh":"UW 学生免费、保密的心理咨询：短期咨询、小组、随到随谈、线上咨询，还有 24 小时危机热线。"},"kw":["counseling","mental health","therapy","crisis line","psychiatry","Uwill","Let's Talk","Access Appointment","心理咨询","心理健康","抑郁","焦虑","危机热线","精神科"],"sec":{"about":{"en":["Mental Health Services is the UHS counseling center on the 7th floor of 333 East Campus Mall. It offers short-term individual counseling, group counseling, couple/partner counseling, psychiatry for evaluation and medication, and assessment and treatment for eating and substance-use concerns. Care is confidential and free for students.","Most clinical care starts with an Access Appointment: a 20–25 minute phone call with a mental health provider who connects you to the right service. For quicker, lighter support there are Let's Talk drop-ins and Uwill online counseling."],"zh":["UHS 的心理咨询中心在 333 East Campus Mall 7 楼。有短期一对一咨询、小组咨询、情侣/伴侣咨询、精神科（评估和开药），以及进食问题、物质使用问题的评估和治疗。全部保密，对学生免费。","大部分正式咨询要先约一个 Access Appointment：20–25 分钟的电话，咨询师了解情况后帮你对接合适的服务。想快一点、轻一点，可以去 Let's Talk 随到随谈，或者用 Uwill 线上咨询。"]},"offers":{"en":["24/7 crisis line staffed by licensed professionals: 608-265-5600, option 9. Friends, roommates, family and staff worried about a student can call too.","Individual counseling: 50-minute sessions in a brief-care model that aims to wrap up in less than a semester","Let's Talk: free 20–25 minute drop-in chats at spots around campus, first come, first served","Uwill: free online counseling by video, phone or chat, including nights and weekends; 3 sessions to start, usually bookable within 24 hours","Group counseling: 6–8 students for 8 weeks; fall 2026 groups include ACT for social anxiety, grief support, a graduate student group and DBT skills","Psychiatry: evaluation and medication management","Thrive Online self-help resources and free wellness workshops"],"zh":["24 小时危机热线，持证专业人员接听：608-265-5600 按 9。担心某个同学的朋友、室友、家人、老师也可以打。","一对一咨询：每次 50 分钟，短期模式，目标一般是一个学期内结束","Let's Talk：校园各处免费的 20–25 分钟随到随谈，先到先得","Uwill：免费线上咨询，视频、电话、文字都行，晚上周末也有；先给 3 次，通常 24 小时内能约上","小组咨询：6–8 人一组，连续 8 周；2026 秋季有社交焦虑 (ACT)、哀伤支持、研究生小组、DBT 技能等","精神科：评估和药物管理","Thrive Online 自助资源，以及免费的身心健康工作坊"]},"howto":{"en":["Book an Access Appointment in MyUHS or by calling 608-265-5600, option 2. They are usually available within 5 days and happen by phone.","Fill in the questionnaire in MyUHS before the call, and take the call somewhere private.","Groups: book the required pre-group orientation the same way (option 2 or MyUHS).","Uwill: create an account with your UW–Madison email, then pick a counselor and a time.","Let's Talk needs no appointment. The fall 2026 schedule (Aug 31–Dec 18) with times and rooms is on the UHS Let's Talk page."],"zh":["在 MyUHS 上或打 608-265-5600 按 2 约 Access Appointment，一般 5 天内能约上，电话进行。","通话前先在 MyUHS 里填好问卷，接电话时找个没人打扰的地方。","想参加小组：用同样方式（按 2 或 MyUHS）先约一次组前说明会 (pre-group orientation)。","Uwill：用学校邮箱注册账号，然后自己选咨询师和时间。","Let's Talk 不用预约；2026 秋季（8/31–12/18）的时间和地点在 UHS 的 Let's Talk 页面上。"]},"cost":{"en":["Counseling, groups, Let's Talk, Uwill and psychiatry appointments cost nothing for enrolled students; UHS does not bill insurance.","Medication prescribed through UHS psychiatry is paid at the pharmacy, where your insurance or SHIP copay applies."],"zh":["在读学生的咨询、小组、Let's Talk、Uwill 和精神科门诊全部免费；UHS 不走保险。","精神科开的药要在药房自己付，可以用保险或 SHIP 付自付额。"]},"tips":{"en":["In immediate danger, call 911. Other lines: call or text 988; text HOME to 741-741 (Crisis Text Line).","UHS counselors can't treat you while you are physically outside Wisconsin, for example over break. Uwill works from anywhere.","Wait times change with the time of year. Uwill and Let's Talk are the quickest ways to talk to someone.","Counselor not a good fit? Tell them, or call UHS to talk it over.","UHS also helps students find off-campus mental health care."],"zh":["有生命危险先打 911。其他热线：打电话或发短信到 988；发短信 HOME 到 741-741（Crisis Text Line）。","人在威斯康星州外（比如放假回国）时，UHS 的咨询师不能给你做咨询；Uwill 在哪都能用。","排队时间看学期忙不忙。想最快找人聊，用 Uwill 或 Let's Talk。","觉得咨询师不合适，可以直接跟他说，或者打电话给 UHS 商量。","UHS 也能帮你找校外的心理咨询。"]},"intl":{"en":["At the Access Appointment you can ask for a provider with a specific language or identity. UHS's staff list includes a Mandarin–English bilingual counselor.","Let's Talk runs a session with International Student Services: fall 2026, Tuesdays 10:30 a.m.–noon, Pyle Center Suite 130.","It's free with or without SHIP; any enrolled student can use it."],"zh":["约 Access Appointment 时可以要求特定语言或身份背景的咨询师。UHS 有一位中英双语（普通话）的咨询师。","Let's Talk 有一场是和国际学生办公室 (ISS) 合办的：2026 秋季每周二 10:30–12:00，Pyle Center 130 室。","有没有买 SHIP 都免费，在读学生都能用。"]}},"src":[["UHS – Mental Health Services","https://www.uhs.wisc.edu/mental-health/"],["SHIP – Find Health Care Providers (UHS floors)","https://www.uhs.wisc.edu/ship/providers/"],["UHS – Make an Appointment","https://www.uhs.wisc.edu/make-an-appointment/"],["UHS – Hours & Locations","https://www.uhs.wisc.edu/about/hours-locations/"],["UHS – Call for Help","https://www.uhs.wisc.edu/call-for-help/"],["UHS – Access Appointments","https://www.uhs.wisc.edu/mental-health/appointment/"],["UHS – Individual Counseling","https://www.uhs.wisc.edu/mental-health/individual/"],["UHS – Drop-in Support at Let's Talk","https://www.uhs.wisc.edu/mental-health/drop-in-support-at-lets-talk/"],["UHS – Uwill virtual counseling","https://www.uhs.wisc.edu/mental-health/uwill/"],["UHS – Group Counseling","https://www.uhs.wisc.edu/mental-health/group-counseling/"],["UHS – Psychiatric Services","https://www.uhs.wisc.edu/mental-health/psychiatric-services/"],["UHS – Connecting Badgers: Introduction to Mental Health Services (transcript, Sept 2026)","https://www.uhs.wisc.edu/2026/09/11/connecting-badgers-introduction-to-mental-health-services-transcript/"],["UHS staff profile – bilingual Mandarin/English mental health provider","https://www.uhs.wisc.edu/staff/hsu-%e5%be%90%e8%96%87%e5%96%ac-chiao/"],["UHS – Eligibility for UHS Services","https://www.uhs.wisc.edu/about/eligibility/"]],"unv":[],"chk":"2026-10-08","lat":43.072489,"lng":-89.398931,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"unitypoint-meriter-hospital-emergency","cat":"health","n":{"en":"UnityPoint Health – Meriter Hospital Emergency Department","zh":"UnityPoint Health – Meriter 医院急诊"},"kind":{"en":"Hospital emergency room","zh":"医院急诊"},"addr":"202 S Park St, Madison, WI 53715","phone":"(608) 417-6000","web":"https://www.unitypoint.org/locations/unitypoint-health---meriter---emergency-services","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1440]],"Sa":[[0,1440]],"Su":[[0,1440]]},"ht":{"en":"Emergency Department open 24 hours a day, 365 days a year. The hospital's Weekend After-Hours Clinic for non-emergencies is open Sat–Sun 8 a.m.–4 p.m.","zh":"急诊全年 24 小时开。医院里看非急症的周末门诊 (Weekend After-Hours Clinic) 周六、周日 8:00–16:00。"},"sum":{"en":"24/7 emergency room at Meriter Hospital on South Park Street, for all ages; part of SHIP's lower-cost Premier Ruby network.","zh":"S Park St 上 Meriter 医院的 24 小时急诊，所有年龄都看，在 SHIP 较便宜的网络里。"},"kw":["emergency room","ER","Meriter","UnityPoint","hospital","911","sexual assault care","急诊","医院","急救","性侵就医"],"sec":{"about":{"en":["Meriter is a full hospital on South Park Street, south of campus, run by UnityPoint Health as a partner of UW Health. Its Emergency Department is open 24 hours a day, 365 days a year, for patients of all ages, and is staffed by board-certified emergency physicians.","There are two marked entrances, one for people arriving on their own and one for ambulances. UnityPoint's driving directions send ED patients to the Emergency Services entrance off South Brooks Street, with parking right next to the main ED entrance."],"zh":["Meriter 是校园南边 S Park St 上的综合医院，由 UnityPoint Health 经营，和 UW Health 是合作关系。急诊全年 24 小时开，所有年龄都看，医生都有急诊专科认证。","急诊有两个入口：自己来的走一个，救护车走另一个。UnityPoint 的路线说明让急诊病人从 South Brooks Street 进急诊入口 (Emergency Services entrance)，旁边就有停车位。"]},"offers":{"en":["24/7 emergency care for all ages","Off-campus option for medical care after a sexual assault: UHS points students to Meriter Hospital or the RCC 24-hour line (608-251-7273)","Free language and accessibility services, including interpreters","A walk-in Weekend After-Hours Clinic inside the same hospital for non-emergencies (Sat–Sun 8 a.m.–4 p.m.)"],"zh":["24 小时急诊，所有年龄","性侵后想去校外就医：UHS 推荐 Meriter 医院，或打 RCC 24 小时热线 608-251-7273","免费语言服务（包括翻译）和无障碍服务","同一栋医院里有免预约的周末门诊，看非急症（周六、周日 8:00–16:00）"]},"howto":{"en":["Call 911 for loss of consciousness, chest pain, trouble breathing, extensive burns, weakness on one side or trouble speaking, poisoning or a severe allergic reaction (Meriter's list).","Arriving by car or drop-off: use the Emergency Services entrance from South Brooks Street; parking is next to the main ED entrance.","Masks are required in the Meriter Emergency Department; check the hospital's visitor page for current rules.","Patients and immediate family park free in the ramp: validate the ticket at Guest Services or the Main Lobby information desk."],"zh":["昏迷、胸痛、呼吸困难、大面积烧伤、一侧身体无力或说话困难、中毒、严重过敏：打 911（Meriter 列的情况）。","开车或被人送来：从 South Brooks Street 进急诊入口，停车位就在急诊主入口旁边。","Meriter 急诊要求戴口罩，最新规定看医院的访客页面。","病人和直系家属停车楼免费：停车票到 Guest Services 或大堂 Information Desk 盖章。"]},"cost":{"en":["Not covered by segregated fees or UHS; billed to you and your insurance.","SHIP: Meriter is in the lower-cost Premier Ruby network. A medical emergency costs a $100 copay plus the $250 deductible, then nothing more for covered care; the copay is waived if you're admitted."],"zh":["隔离费和 UHS 都不管急诊费用，账单寄给你和你的保险。","SHIP：Meriter 属于较便宜的 Premier Ruby 网络。真急症交 $100 自付加 $250 免赔额，之后承保部分不再收钱；住院的话 $100 免掉。"]},"tips":{"en":["Minor problem on a weekend? Use the Weekend After-Hours Clinic in the same hospital instead of the ED.","Parking-ramp construction is under way. UnityPoint suggests allowing extra time or using the free valet (weekdays 6 a.m.–4:30 p.m. at the front entrance).","The main hospital entrance is also on South Brooks Street, not Park Street."],"zh":["周末小毛病，去同一栋楼里的周末门诊，不用挂急诊。","停车楼在施工，UnityPoint 建议多留时间，或者用免费代客泊车（工作日 6:00–16:30，在正门）。","医院正门也在 South Brooks Street 上，不在 Park Street。"]},"intl":{"en":["Language services are free for patients and caregivers; ask at the desk.","In a real medical emergency, SHIP's cost is the same at every ER ($100 copay, 0% coinsurance), so go to the closest one."],"zh":["语言服务对病人和陪同家属免费，在前台提出来。","真正急症在 SHIP 下去哪家急诊费用都一样（$100 自付、0% 共付），去最近的就行。"]}},"src":[["UnityPoint Health – Meriter – Emergency Services","https://www.unitypoint.org/madison/emergency-services.aspx"],["UnityPoint Health – Meriter Hospital","https://www.unitypoint.org/locations/unitypoint-health---meriter-hospital"],["Meriter Hospital – Directions, Parking and Maps","https://www.unitypoint.org/locations/unitypoint-health---meriter-hospital/patients-and-visitors/directions-and-maps"],["UnityPoint Health – Meriter – Weekend After-Hours Clinic","https://www.unitypoint.org/locations/unitypoint-health---meriter---weekend-after-hours-clinic"],["UnityPoint Health – Non-Discrimination Accessibility Notice","https://www.unitypoint.org/about-unitypoint-health/compliance/non-discrimination-accessibility-notice"],["SHIP – Find Health Care Providers","https://www.uhs.wisc.edu/ship/providers/"],["UHS – Medical Care After an Unwanted Sexual Encounter","https://www.uhs.wisc.edu/survivor-services/survivor-services-medical/"],["UHS – Emergency Rooms & Urgent Care","https://www.uhs.wisc.edu/emergency-rooms-urgent-care/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["SHIP 2026–27 International Summary of Benefits & Coverage (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SHIP-Intl-SBC-6-2-26.pdf"]],"unv":[],"chk":"2026-10-08","lat":43.06605,"lng":-89.401712,"stops":[["S Park at Meriter",121,"B 63 64"],["S Park at Regent",155,"B 64"],["Regent at N Park",192,"E 64"]]},{"id":"unitypoint-meriter-weekend-after-hours-clinic","cat":"health","n":{"en":"UnityPoint Health – Meriter Weekend After-Hours Clinic","zh":"Meriter 医院周末门诊 (Weekend After-Hours Clinic)"},"kind":{"en":"Weekend walk-in clinic","zh":"周末免预约门诊"},"addr":"202 S Park St, Madison, WI 53715","phone":"(608) 417-6868","web":"https://www.unitypoint.org/locations/unitypoint-health---meriter---weekend-after-hours-clinic","h":{"Mo":[],"Tu":[],"We":[],"Th":[],"Fr":[],"Sa":[[480,960]],"Su":[[480,960]]},"ht":{"en":"Saturdays and Sundays 8 a.m.–4 p.m. (as of October 2026); closed Monday to Friday.","zh":"周六、周日 8:00–16:00（2026 年 10 月）；周一到周五不开。"},"sum":{"en":"Weekend walk-in clinic inside Meriter Hospital for minor illness and injury, with X-ray on site; no appointment needed.","zh":"Meriter 医院里的周末免预约门诊，看小病小伤，现场能拍 X 光。"},"kw":["urgent care","walk-in clinic","weekend","Meriter","UnityPoint","after hours","IUD","急症","周末看病","免预约","小病"],"sec":{"about":{"en":["A walk-in clinic inside Meriter Hospital on South Park Street that treats minor illness and injury on Saturdays and Sundays, for patients of all ages, when most clinics (including UHS) are closed. UnityPoint lists it as the urgent care option at Meriter.","It is not an emergency room. With chest pain or shortness of breath, go to the Emergency Department in the same hospital or call 911."],"zh":["开在 S Park St 上 Meriter 医院里的免预约门诊，周六周日看小病小伤，所有年龄都看；这时候大部分诊所（包括 UHS）都关门。UnityPoint 写明 Meriter 的 urgent care 就在这里。","这里不是急诊。胸痛或喘不上气，去同一家医院的急诊或打 911。"]},"offers":{"en":["Colds, coughs, flu, fevers, sore throats, earaches and allergies","Cuts that need stitches, burns, sprains and fractures, with X-ray on site","UTIs, yeast infections, other infections, minor eye problems and certain rapid tests","LARC clinic (IUDs and Nexplanon) on the second Saturday of each month, 9 a.m.–2 p.m., by appointment; you don't need to be a Meriter patient"],"zh":["感冒、咳嗽、流感、发烧、嗓子疼、耳朵疼、过敏","需要缝针的伤口、烫伤、扭伤、骨折，现场能拍 X 光","尿路感染、阴道念珠菌感染、其他感染、轻微眼部问题，部分快速检测","每月第二个周六 9:00–14:00 有长效避孕门诊（IUD 和 Nexplanon），要预约，不是 Meriter 病人也能约"]},"howto":{"en":["No appointment: walk in on Saturday or Sunday between 8 a.m. and 4 p.m. The clinic is inside Meriter Hospital (address line '202 South Park Street, 2 Atrium').","The clinic's web page shows how many patients are waiting right now.","UnityPoint suggests first checking for a same-day appointment with your own provider or a Care Anywhere video visit.","LARC clinic appointments: call 608-417-6868."],"zh":["不用预约：周六或周日 8:00–16:00 直接去。门诊在 Meriter 医院里面（地址写的是「202 South Park Street, 2 Atrium」）。","门诊网页上能看到现在有多少人在排队。","UnityPoint 建议先看看自己的医生当天有没有号，或者用 Care Anywhere 视频看病。","约长效避孕门诊：打 608-417-6868。"]},"cost":{"en":["UHS and segregated fees don't cover care here; use your insurance.","SHIP international plan 2026–27: Meriter is Premier Ruby, so urgent care costs 5% coinsurance after the $125 deductible."],"zh":["UHS 和隔离费不管这里的费用，要用你自己的保险。","SHIP 国际生计划 2026–27：Meriter 属于 Premier Ruby，urgent care 在 $125 免赔额之后自付 5%。"]},"tips":{"en":["Closed Monday to Friday. On weekday evenings use UW Health urgent care or a Care Anywhere video visit.","Meriter patients can use UW Health Care Anywhere for virtual urgent care; you must be in Wisconsin during the visit.","Flu shots and physicals are not offered at every urgent care location; call first if that's what you need.","Mental health crisis: UnityPoint says to call 988. UW students can also call the UHS crisis line, 608-265-5600 (option 9)."],"zh":["周一到周五不开。工作日晚上去 UW Health 的 urgent care，或者用 Care Anywhere 视频看病。","Meriter 的病人也能用 UW Health Care Anywhere 视频看急症，看的时候人必须在威州。","不是每个 urgent care 都打流感疫苗或做体检，要办这些先打电话问。","心理危机：UnityPoint 让打 988；UW 学生也可以打 UHS 危机热线 608-265-5600 按 9。"]},"intl":{"en":["UnityPoint provides language and accessibility services at no cost to patients and caregivers."],"zh":["UnityPoint 对病人和陪同家属免费提供语言服务和无障碍服务。"]}},"src":[["UnityPoint Health – Meriter – Weekend After-Hours Clinic","https://www.unitypoint.org/locations/unitypoint-health---meriter---weekend-after-hours-clinic"],["SHIP – Find Health Care Providers","https://www.uhs.wisc.edu/ship/providers/"],["UHS – Emergency Rooms & Urgent Care","https://www.uhs.wisc.edu/emergency-rooms-urgent-care/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["UHS – Call for Help","https://www.uhs.wisc.edu/call-for-help/"],["UnityPoint Health – Non-Discrimination Accessibility Notice","https://www.unitypoint.org/about-unitypoint-health/compliance/non-discrimination-accessibility-notice"]],"unv":[],"chk":"2026-10-08","lat":43.06605,"lng":-89.401712,"stops":[["S Park at Meriter",121,"B 63 64"],["S Park at Regent",155,"B 64"],["Regent at N Park",192,"E 64"]]},{"id":"uhs-medical-services","cat":"health","n":{"en":"University Health Services (UHS) – Medical Services","zh":"大学健康服务中心 (UHS) 门诊"},"kind":{"en":"Student health clinic","zh":"校医院门诊"},"addr":"333 East Campus Mall, Madison, WI 53715","phone":"(608) 265-5600","web":"https://www.uhs.wisc.edu/medical/","h":{"Mo":[[510,1020]],"Tu":[[510,1020]],"We":[[540,1020]],"Th":[[510,1020]],"Fr":[[510,1020]],"Sa":[],"Su":[]},"ht":{"en":"Medical Services, as posted in October 2026: Mon, Tue, Thu, Fri 8:30 a.m.–5 p.m.; Wed 9 a.m.–5 p.m. Closed weekends and listed holidays. Phone nurse advice 24/7 at 608-265-5600 (option 1).","zh":"门诊时间（2026 年 10 月官网）：周一、二、四、五 8:30–17:00，周三 9:00–17:00；周末和官网列出的节假日不开。护士电话咨询 24 小时：608-265-5600 按 1。"},"sum":{"en":"UW–Madison's student health center: most visits, lab tests and STI testing are free for enrolled students. Book in MyUHS or by phone.","zh":"UW 学生自己的校医院：大部分看诊、化验和性病检测对在读学生免费，用 MyUHS 或电话预约。"},"kw":["UHS","University Health Services","student health","clinic","doctor","STI testing","vaccines","MyUHS","校医院","看病","诊所","医生","性病检测","打疫苗"],"sec":{"about":{"en":["University Health Services (UHS) is the student health center for UW–Madison. Medical Services fill the 5th and 6th floors of 333 East Campus Mall and cover everyday illness and injury, primary care, gynecology and birth control, sexual health and STI testing, lab work, vaccines, travel health, nutrition, athletic training and physical therapy.","UHS is not part of UW Health or UW Hospital. It does not take walk-ins, is closed evenings and weekends, and has no pharmacy, emergency room, dental or vision care. For those you need outside providers, so UHS encourages students to keep their own health insurance."],"zh":["UHS（University Health Services）就是 UW–Madison 的校医院。门诊 (Medical Services) 在 333 East Campus Mall 的 5、6 楼：感冒发烧、小伤、慢性病、妇科和避孕、性健康和性病检测、化验、打疫苗、出国旅行健康咨询、营养、运动损伤和物理治疗都能看。","UHS 不属于 UW Health，也不是 UW Hospital。这里不接受直接走进来看病 (walk-in)，晚上和周末不开门，没有药房、急诊，也不看牙和眼睛。这些得去校外，所以 UHS 建议学生自己要有医疗保险。"]},"offers":{"en":["Visits for colds, sore throats, upset stomachs, pink eye, sprains and chronic conditions such as asthma; many same-day appointments","Sexual health: STI testing at no charge, a chlamydia self-test option booked in MyUHS, and HIV prevention (PrEP and PEP)","Gynecology: contraception, plus pregnancy options counseling and referrals","Lab tests and X-rays; X-rays ordered from your UHS visit are free","Vaccines, TB testing and pre-travel consultations (most vaccines cost extra)","Physical therapy, athletic training for sports injuries, and nutrition counseling","24/7 nurse advice at 608-265-5600 (option 1) and an online Symptom Checker","Care after an unwanted sexual encounter without an appointment: 7th-floor Survivor Services Suite, Mon–Fri 9 a.m.–5 p.m. (nurse line 608-852-9533)"],"zh":["感冒、嗓子疼、肠胃不舒服、红眼病、扭伤，以及哮喘这类慢性病都能看；很多当天就能约上","性健康：性病检测不收费；MyUHS 里能约衣原体自检；也提供 HIV 预防药 PrEP 和 PEP","妇科：避孕，以及怀孕后的选择咨询和转诊","化验和 X 光；看诊时 UHS 开的 X 光不收钱","打疫苗、结核 (TB) 检测、出国前健康咨询（大部分疫苗另外收费）","物理治疗、运动损伤处理 (athletic training)、营养咨询","24 小时护士电话咨询：608-265-5600 按 1；官网还有在线症状自查 (Symptom Checker)","遭遇性侵后的医疗不用预约：7 楼 Survivor Services，周一到周五 9:00–17:00，护士专线 608-852-9533"]},"howto":{"en":["Book in MyUHS (myuhs.uhs.wisc.edu) or call 608-265-5600, option 1. No slots online? Call anyway: UHS holds some appointments back for people who need care sooner.","Before your first visit, complete the required health forms (health history, information and consent) under Medical Clearances in MyUHS. UHS cannot see you without them.","When you call, have your name, student ID number and date of birth ready. A nurse may call you back to judge how urgent it is.","An hour before the visit, MyUHS prompts you to start check-in. Arrive 15 minutes early and check in with the barcode in the MyUHS app.","Prescriptions go to a pharmacy you choose. UHS has no pharmacy of its own; the closest is the Walgreens in the same building."],"zh":["在 MyUHS（myuhs.uhs.wisc.edu）上约，或打 608-265-5600 按 1。网上没号也要打电话：UHS 会留一些号给急着看的人。","第一次看病前，先在 MyUHS 的 Medical Clearances 里填完健康史和知情同意表，不填 UHS 不给看。","打电话时准备好姓名、学号 (student ID) 和生日；护士可能会回电话判断急不急。","看诊前 1 小时 MyUHS 会提醒你开始签到；提前 15 分钟到，用 MyUHS app 里的条形码签到。","处方会发到你指定的药房。UHS 自己没有药房，最近的是同一栋楼里的 Walgreens。"]},"cost":{"en":["Most care is free for enrolled students because segregated fees pay for it: appointments, lab tests, X-rays ordered at UHS and STI testing.","You pay for most vaccines, physical therapy ($75 first visit, $50 return visit), splints, braces and crutches, and third-party forms and physicals ($25–$150).","Charges show up as a Statement of Service in MyUHS. Pay within 30 days; after 60 days unpaid, a hold blocks registration and transcripts.","UHS bills no insurance except SHIP. With other insurance, pay UHS and send the statement to your insurer for possible reimbursement.","Eligible: students enrolled for credit who pay segregated fees. Fall 2026 eligibility runs Aug 15–Dec 23."],"zh":["在读学生交了隔离费 (segregated fees)，大部分看病不用再花钱：门诊、化验、UHS 开的 X 光、性病检测都免费。","要收钱的：大部分疫苗、物理治疗（首次 $75，复诊 $50）、护具和拐杖、第三方表格和体检（$25–$150）。","费用会以 Statement of Service 出现在 MyUHS 里，30 天内付清；超过 60 天不付会被加 hold，不能选课、不能开成绩单。","UHS 除了 SHIP 不跟任何保险结算。用别的保险的话，先自己付，再拿账单找保险公司报销。","谁能用：修学分并交隔离费的学生。2026 秋季的有效期是 8/15–12/23。"]},"tips":{"en":["UHS is not UW Health. If UHS sends you to any hospital, including UW Hospital, the ER or hospital bill is yours.","Evenings and weekends, call the 24/7 nurse line first if you can't tell whether you need urgent care or the ER.","Free flu shots at UHS pop-up clinics around campus through Dec 1, 2026; bring your Wiscard and insurance card.","No dental or eye care here; UHS's medical page lists nearby dentists and optometrists.","Living in the Lakeshore dorms? The UHS Lakeshore Clinic in Dejope Hall handles basic problems."],"zh":["UHS 不是 UW Health。就算是 UHS 把你送去医院（包括 UW Hospital），急诊和住院的账单也得你自己付。","晚上和周末拿不准该去 urgent care 还是急诊，先打 24 小时护士电话问。","秋季 UHS 在校园各处办免费流感疫苗点，一直到 2026 年 12 月 1 日；带学生证 (Wiscard) 和保险卡。","这里不看牙、不看眼睛；UHS 门诊页面列了校园附近的牙医和验光店。","住 Lakeshore 宿舍区的话，Dejope 楼里的 UHS Lakeshore Clinic 能看简单的小毛病。"],"exp":[null,null,"2026-12-01",null,null]},"intl":{"en":["SHIP members: most UHS care, including primary, urgent and preventive care, is fully covered with no out-of-pocket cost. SHIP expects you to use UHS first.","You have the right to an interpreter; ask for one when you book.","UHS can't see records from other health systems. Upload vaccine records, prescriptions and test results from home to MyUHS.","Bring enough of your regular medicine to last until you can see a UHS provider."],"zh":["买了学生医保 (SHIP) 的话，UHS 的大部分看诊（初级、急症、预防）全额覆盖，自己不用掏钱；SHIP 要求能在 UHS 看的先在 UHS 看。","看病可以要求翻译 (interpreter)，预约时就说。","UHS 看不到你在别的医疗系统的病历。把国内的疫苗记录、处方、检查结果上传到 MyUHS。","常吃的药带够，撑到你在 UHS 约上医生为止。"]}},"src":[["University Health Services – home","https://www.uhs.wisc.edu/"],["UHS – Make an Appointment","https://www.uhs.wisc.edu/make-an-appointment/"],["UHS – Hours & Locations","https://www.uhs.wisc.edu/about/hours-locations/"],["SHIP – Find Health Care Providers","https://www.uhs.wisc.edu/ship/providers/"],["UHS – Medical Care","https://www.uhs.wisc.edu/medical/"],["About University Health Services","https://www.uhs.wisc.edu/about/"],["UHS – Information for Incoming Students","https://www.uhs.wisc.edu/soar/"],["UHS – Primary Care","https://www.uhs.wisc.edu/medical/primary-care-clinic/"],["UHS – Costs and Billing","https://www.uhs.wisc.edu/about/costs/"],["UHS – Sexual Health","https://www.uhs.wisc.edu/medical/sexual-health-clinic/"],["UHS – Travel Health","https://www.uhs.wisc.edu/medical/travel-clinic/"],["UHS – Call for Help","https://www.uhs.wisc.edu/call-for-help/"],["UHS – Medical Care After an Unwanted Sexual Encounter","https://www.uhs.wisc.edu/survivor-services/survivor-services-medical/"],["UHS – Eligibility for UHS Services","https://www.uhs.wisc.edu/about/eligibility/"],["UHS – Emergency Rooms & Urgent Care","https://www.uhs.wisc.edu/emergency-rooms-urgent-care/"],["UHS – Flu & COVID-19 Vaccines for Students & Employees","https://www.uhs.wisc.edu/medical/flu-vaccines-for-students-employees/"],["SHIP – Health Insurance for International Students","https://www.uhs.wisc.edu/ship/international/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["UHS – Privacy & Patient Rights","https://www.uhs.wisc.edu/about/privacy/"]],"unv":[],"chk":"2026-10-08","lat":43.072489,"lng":-89.398931,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"uw-health-union-corners-urgent-care","cat":"health","n":{"en":"UW Health Union Corners Clinic – Urgent Care","zh":"UW Health Union Corners 急症门诊 (Urgent Care)"},"kind":{"en":"Urgent care clinic","zh":"急症门诊"},"addr":"2402 Winnebago St, Madison, WI 53704","phone":"(608) 828-7603","web":"https://www.uwhealth.org/locations/union-corners-clinic-299/urgent-care-clinic-1191","h":{"Mo":[[480,1200]],"Tu":[[480,1200]],"We":[[480,1200]],"Th":[[480,1200]],"Fr":[[480,1200]],"Sa":[[480,1020]],"Su":[[480,1020]]},"ht":{"en":"Urgent care, as of October 2026: Mon–Fri 8 a.m.–8 p.m., Sat–Sun 8 a.m.–5 p.m. Walk-ins welcome; you can also reserve a spot in line in MyChart.","zh":"急症门诊（2026 年 10 月）：周一到周五 8:00–20:00，周末 8:00–17:00。可以直接去，也可以先在 MyChart 上排号。"},"sum":{"en":"The closer of UW Health's two walk-in urgent cares to campus; open evenings and weekends, with X-ray, lab and a pharmacy on site.","zh":"离校园较近的 UW Health 急症门诊，晚上和周末都开，现场有 X 光、化验和药房。"},"kw":["urgent care","walk-in clinic","UW Health","Union Corners","evening","weekend","x-ray","急症","急诊门诊","周末看病","晚上看病","免预约"],"sec":{"about":{"en":["UW Health runs two urgent care clinics in Madison: this one at Union Corners on the east side, and West Towne Clinic (7102 Mineral Point Rd) on the far west side. Union Corners is the closer one to campus.","Urgent care is for problems that need care today but aren't life-threatening. Patients of all ages are seen without an appointment, and the clinic has X-ray, lab services and a pharmacy on site."],"zh":["UW Health 在 Madison 有两家急症门诊 (urgent care)：东边 Union Corners 这家，和远在西边的 West Towne Clinic（7102 Mineral Point Rd）。离校园近的是 Union Corners。","Urgent care 看当天就要处理、但不危及生命的问题。所有年龄都看，不用预约，现场有 X 光、化验和药房。"]},"offers":{"en":["Walk-in care for sprains, cuts, bruises and minor fractures","Colds, flu, sore throats, earaches, headaches, rashes and back pain (UHS's urgent care examples)","X-ray and lab tests on site","On-site pharmacy","Reserve your spot in line through UW Health MyChart"],"zh":["免预约处理扭伤、割伤、淤青、轻微骨折","感冒、流感、嗓子疼、耳朵疼、头疼、皮疹、腰背痛（UHS 列的 urgent care 情况）","现场能拍 X 光、做化验","门诊里有药房","可以先在 UW Health MyChart 上排号"]},"howto":{"en":["Walk in during open hours, or reserve a spot in line through MyChart.","Use it when UHS is closed (evenings, weekends) or can't see you in time. Unsure where to go? Call UHS at 608-265-5600 (option 1), 24/7.","Chest pain, trouble breathing or another emergency: call 911. Urgent care is not for emergencies.","Have your insurance card with you; SHIP members can use the electronic ID card from the SHIP website."],"zh":["开门时间直接去，或者先在 MyChart 上排号。","UHS 关门（晚上、周末）或约不上时用。拿不准去哪：打 UHS 608-265-5600 按 1，24 小时有人接。","胸痛、呼吸困难这类急症打 911，urgent care 不看急诊。","带上保险卡；SHIP 学生可以用 SHIP 网站上的电子保险卡。"]},"cost":{"en":["Not covered by segregated fees or UHS; the visit is billed to your insurance.","SHIP international plan 2026–27: UW Health is Premier Ruby, so urgent care costs 5% coinsurance after the $125 deductible."],"zh":["隔离费和 UHS 不管，看诊费用走你的保险。","SHIP 国际生计划 2026–27：UW Health 属于 Premier Ruby，urgent care 在 $125 免赔额之后自付 5%。"]},"tips":{"en":["UW Health Care Anywhere offers urgent care video visits 24/7 with no appointment; you must be physically in Wisconsin. Get the 'Video Visit - UW Health Care Anywhere' app.","On weekends, Meriter's walk-in Weekend After-Hours Clinic on S. Park St. is another option.","SHIP's provider page marks both UW Health urgent cares as Premier Ruby; the SSM Health urgent care it lists (1821 S. Stoughton Rd., 608-260-6000) carries no such label."],"zh":["UW Health Care Anywhere 可以 24 小时视频看急症，不用预约，但人必须在威斯康星州内。下载 app「Video Visit - UW Health Care Anywhere」。","周末也可以去 S. Park St. 上 Meriter 医院里的周末门诊，同样免预约。","SHIP 的医生名单把两家 UW Health urgent care 都标成 Premier Ruby；名单上 SSM Health 的 urgent care（1821 S. Stoughton Rd.，608-260-6000）没有这个标注。"]},"intl":{"en":["Interpreters are free for all UW Health patients and families, in person, by phone or by video."],"zh":["UW Health 对所有病人和家属提供免费翻译，现场、电话、视频都可以。"]}},"src":[["UW Health – Union Corners Clinic Urgent Care","https://www.uwhealth.org/locations/union-corners-clinic-299/urgent-care-clinic-1191"],["UW Health – Emergency and urgent care locations","https://www.uwhealth.org/search/locations?refinementList%5Buwh_location_category%5D%5B0%5D=Emergency%20and%20urgent%20care"],["SHIP – Find Health Care Providers","https://www.uhs.wisc.edu/ship/providers/"],["UHS – Emergency Rooms & Urgent Care","https://www.uhs.wisc.edu/emergency-rooms-urgent-care/"],["SHIP – FAQ about Member Cost Sharing & Claims","https://www.uhs.wisc.edu/ship/member-cost-sharing-claims-faq/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["UW Health – Care Anywhere video visits","https://www.uwhealth.org/services/uw-health-care-anywhere"],["UnityPoint Health – Meriter – Weekend After-Hours Clinic","https://www.unitypoint.org/locations/unitypoint-health---meriter---weekend-after-hours-clinic"],["UW Health – Language Access and Interpreter Services","https://www.uwhealth.org/social-impact-and-belonging/language-interpreter-services"]],"unv":[],"chk":"2026-10-08","lat":43.097827,"lng":-89.349642,"stops":[["Milwaukee-North",264,"A B"],["Milwaukee at E Washington",274,"D"],["North at E Washington",342,"B D"]]},{"id":"uw-health-university-hospital-emergency","cat":"health","n":{"en":"UW Health University Hospital – BerbeeWalsh Emergency Department","zh":"UW Health 大学医院急诊 (BerbeeWalsh Emergency Department)"},"kind":{"en":"Hospital emergency room","zh":"医院急诊"},"addr":"1565 Highland Ave, Madison, WI 53792","phone":"(608) 262-2398","web":"https://www.uwhealth.org/locations/university-hospital-170/berbeewalsh-emergency-department-81","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1440]],"Sa":[[0,1440]],"Su":[[0,1440]]},"ht":{"en":"Emergency Department open 24 hours, every day. Hospital pharmacy: Mon–Fri 8 a.m.–8 p.m., Sat–Sun 8 a.m.–6 p.m. Inpatient visiting hours 8 a.m.–9 p.m.","zh":"急诊 24 小时全年开。医院药房：周一到周五 8:00–20:00，周末 8:00–18:00。住院探视时间 8:00–21:00。"},"sum":{"en":"24/7 emergency room at UW Hospital on the west edge of campus, with Level I trauma care. In a life-threatening emergency, call 911.","zh":"校园西边 UW Hospital 的 24 小时急诊，一级创伤中心。危及生命先打 911。"},"kw":["emergency room","ER","emergency department","UW Hospital","University Hospital","trauma","911","急诊","医院","急救","大学医院"],"sec":{"about":{"en":["University Hospital is UW Health's main hospital, on the western edge of the UW–Madison campus. Its BerbeeWalsh Emergency Department is open 24/7 for serious and life-threatening illness and injury. UW Health is the only health system in Wisconsin with Level I Trauma and Burn Centers for adults and children.","The emergency department's address is 1565 Highland Ave; the hospital's main address and public parking ramp are at 600 Highland Ave. The children's emergency department in American Family Children's Hospital shares the 1565 Highland Ave address."],"zh":["University Hospital 是 UW Health 的主院区，就在 UW–Madison 校园西边。院内的 BerbeeWalsh 急诊 (Emergency Department) 24 小时开，看严重和危及生命的急病和外伤。UW Health 是威州唯一有成人和儿童一级创伤 (Level I Trauma) 及烧伤中心的医疗系统。","急诊的地址是 1565 Highland Ave；医院主地址和公共停车楼在 600 Highland Ave。American Family 儿童医院的儿童急诊也用 1565 Highland Ave 这个地址。"]},"offers":{"en":["Emergency care 24/7 for problems such as chest pain, shortness of breath, loss of consciousness, drug overdose, seizures, fractures, eye injuries and severe cuts (examples from UHS's ER list)","Level I trauma and burn care for adults and children","Free medical interpreters in person, by phone or by video","Hospital pharmacy (Mon–Fri 8 a.m.–8 p.m., Sat–Sun 8 a.m.–6 p.m.) and a pharmacy kiosk with 24-hour prescription pickup"],"zh":["24 小时急诊：胸痛、喘不上气、昏迷、药物过量、抽搐、骨折、眼外伤、严重割伤等（UHS 列的急诊情况）","成人和儿童一级创伤及烧伤救治","免费医疗翻译：现场、电话或视频","医院药房（周一到周五 8:00–20:00，周末 8:00–18:00），还有 24 小时自助取药机 (pharmacy kiosk)"]},"howto":{"en":["Life-threatening emergency: call 911.","Going in yourself: use the Emergency Department at 1565 Highland Ave.","Not sure it's an emergency? Call UHS at 608-265-5600 (option 1) for 24/7 nurse advice.","Have your insurance card with you; SHIP members can pull up an electronic ID card on the SHIP website.","Visitors and non-emergency patients: park in the ramp at 600 Highland Ave and have the ticket validated at the Information Desk for free parking."],"zh":["危及生命：打 911。","自己去的话：到 1565 Highland Ave 的急诊。","拿不准算不算急诊：打 UHS 608-265-5600 按 1，24 小时有护士接。","随身带保险卡；SHIP 学生可以在 SHIP 网站上调出电子保险卡。","探病或非急诊就诊：车停 600 Highland Ave 的停车楼，停车票拿到 Information Desk 盖章就能免费停。"]},"cost":{"en":["ER and hospital care are not covered by segregated fees, and UHS doesn't pay for them; you or your insurance do.","SHIP international plan 2026–27: a medical emergency costs a $100 copay plus the $250 deductible, then nothing more for covered care. The copay is waived if you're admitted.","Using the ER for something that isn't a medical emergency still costs the $100 copay, plus 5% coinsurance at UW Health under SHIP.","UW Health bills professional and hospital charges separately, so expect more than one bill.","SHIP's benefits summary lists emergency ambulance transport at 10% coinsurance, with the Tier 3 deductible."],"zh":["急诊和住院不在隔离费里，UHS 也不付，由你自己或保险付。","SHIP 国际生计划 2026–27：真正的急症，交 $100 急诊自付额加 $250 免赔额，之后承保部分不再收钱；住院的话 $100 免掉。","不是真急症却去急诊，SHIP 在 UW Health 照样收 $100，还要加 5% 共付 (coinsurance)。","UW Health 会把医生费和医院费分开出账单，可能收到不止一张。","SHIP 福利摘要里急救车 (ambulance) 是 10% 共付，适用第三档 (Tier 3) 的免赔额。"]},"tips":{"en":["Oct 9–13, 2026: Highland Ave is closed between Campus Drive and the main Veterans Hospital intersection for railroad crossing work. Detour via Walnut St or University Bay Dr.","For minor problems at night or on weekends, UW Health urgent care or UHS's nurse line costs SHIP members far less than the ER (urgent care is 5% after the deductible).","If a friend is admitted, visiting hours are 8 a.m.–9 p.m.","When you follow up at UHS after an ER visit, bring or share the ER records: UHS can't see UW Health's MyChart."],"zh":["2026 年 10 月 9–13 日：Highland Ave 在 Campus Drive 到退伍军人医院 (Veterans Hospital) 路口之间因修铁路道口封路，绕 Walnut St 或 University Bay Dr。","晚上或周末的小毛病，用 UW Health urgent care 或 UHS 护士电话，对 SHIP 学生比急诊便宜得多（urgent care 是免赔额后 5%）。","朋友住院的话，探视时间 8:00–21:00。","急诊后回 UHS 复诊，记得带上或转给 UHS 急诊记录：UHS 看不到 UW Health 的 MyChart。"],"exp":["2026-10-13",null,null,null]},"intl":{"en":["Interpreters are free for all UW Health patients and families; ask at registration.","In a real medical emergency, SHIP's cost is the same at any ER ($100 copay, 0% coinsurance), so go to the nearest one."],"zh":["UW Health 对所有病人和家属提供免费翻译，挂号时就提出来。","真正的急症，SHIP 在哪家急诊的费用都一样（$100 自付、0% 共付），去最近的就行。"]}},"src":[["UW Health – BerbeeWalsh Emergency Department","https://www.uwhealth.org/locations/university-hospital-170/berbeewalsh-emergency-department-81"],["UW Health – University Hospital","https://www.uwhealth.org/locations/university-hospital-170"],["UW Health – Emergency and urgent care locations","https://www.uwhealth.org/search/locations?refinementList%5Buwh_location_category%5D%5B0%5D=Emergency%20and%20urgent%20care"],["UW Health – Language Access and Interpreter Services","https://www.uwhealth.org/social-impact-and-belonging/language-interpreter-services"],["UHS – Emergency Rooms & Urgent Care","https://www.uhs.wisc.edu/emergency-rooms-urgent-care/"],["SHIP – FAQ about Member Cost Sharing & Claims","https://www.uhs.wisc.edu/ship/member-cost-sharing-claims-faq/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["SHIP 2026–27 International Summary of Benefits & Coverage (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SHIP-Intl-SBC-6-2-26.pdf"],["UW Transportation – Highland Avenue closed Oct. 9–13, 2026","https://transportation.wisc.edu/2026/09/18/highland-avenue-closed-for-railroad-crossing-replacement-october-2026/"],["UHS – Primary Care","https://www.uhs.wisc.edu/medical/primary-care-clinic/"]],"unv":[],"chk":"2026-10-08","lat":43.078908,"lng":-89.431813,"stops":[["Highland at Marsh",84,"C J 28 38"],["Highland at Waisman",140,"C J 28 38"],["Marsh at Highland",164,"80"]]},{"id":"walgreens-east-campus-mall","cat":"health","n":{"en":"Walgreens – 311 E Campus Mall","zh":"Walgreens 药店（East Campus Mall 店）"},"kind":{"en":"Pharmacy & drugstore","zh":"药店"},"addr":"311 E Campus Mall, Madison, WI 53715","phone":"(608) 251-0042","web":"https://www.walgreens.com/locator/walgreens-311+e+campus+mall-madison-wi-53715/id=11858","h":{"Mo":[[420,1380]],"Tu":[[420,1380]],"We":[[420,1380]],"Th":[[420,1380]],"Fr":[[420,1380]],"Sa":[[480,1380]],"Su":[[480,1380]]},"ht":{"en":"Store: Mon–Fri 7 a.m.–11 p.m., Sat–Sun 8 a.m.–11 p.m. Pharmacy: Mon–Fri 9 a.m.–9 p.m., Sat–Sun 9 a.m.–5 p.m., closed 1:30–2 p.m. every day for a meal break (as of October 2026).","zh":"店面：周一到周五 7:00–23:00，周末 8:00–23:00。药房：周一到周五 9:00–21:00，周末 9:00–17:00，每天 13:30–14:00 午休（2026 年 10 月）。"},"sum":{"en":"Drugstore with a pharmacy counter in the same building as UHS, at East Campus Mall and Johnson St. UHS has no pharmacy of its own.","zh":"和 UHS 同一栋楼的 Walgreens，有药房柜台；UHS 自己没药房，开了药多半来这儿拿。"},"kw":["pharmacy","drugstore","prescription","Walgreens","vaccine","passport photo","Plan B","药店","药房","处方药","拿药","打疫苗","证件照"],"sec":{"about":{"en":["UHS has no pharmacy, so prescriptions from UHS go to a pharmacy you pick. UHS notes three pharmacies within walking distance of campus, including this Walgreens in the same building as UHS, at the northeast corner of East Campus Mall and West Johnson St.","Besides the pharmacy counter it is a regular drugstore with over-the-counter medicine, toiletries and snacks, plus photo printing and package services."],"zh":["UHS 没有药房，UHS 开的处方会发到你选的药房。UHS 说校园步行范围内有三家药房，其中一家就是这家 Walgreens，和 UHS 在同一栋楼，位置在 East Campus Mall 和 West Johnson St 的东北角。","除了药房柜台，就是一家普通的美国药妆店：非处方药、日用品、零食都有，还能冲印照片、寄快递。"]},"offers":{"en":["Pharmacy counter for prescriptions and refills","Vaccines, subject to availability: flu, COVID-19, Tdap, meningitis, hepatitis A and B, MMR, and travel vaccines such as typhoid, yellow fever and Japanese encephalitis","Travel health consultations","Passport photos and photo printing","FedEx pickup and drop-off, and Western Union","Over-the-counter medicine, toiletries and snacks"],"zh":["药房柜台：取处方药、续药","打疫苗（看库存）：流感、新冠、百白破 (Tdap)、脑膜炎、甲肝乙肝、麻腮风，以及伤寒、黄热病、乙脑等出国疫苗","出国旅行健康咨询","证件照（护照照片）和冲印照片","FedEx 寄取件、Western Union 汇款","非处方药、日用品、零食"]},"howto":{"en":["At your UHS visit, say this Walgreens is your pharmacy; UHS sends prescriptions to the pharmacy you choose.","Show your insurance card; SHIP members show the SHIP ID card. Billing insurance may lower the price.","Just enrolled in SHIP? Pharmacies may not see it for up to 3 business days. If you pay full price meanwhile, come back after 3 business days and ask Walgreens to reprocess the claim through SHIP for a refund (minus your copay).","Schedule vaccines from the store page or at the pharmacy.","Plan around the pharmacy's 1:30–2 p.m. meal break."],"zh":["在 UHS 看病时说你用这家 Walgreens，UHS 会把处方发到你选的药房。","出示保险卡，SHIP 学生出示 SHIP 卡；走保险通常能便宜些。","刚买 SHIP？药房系统最多要 3 个工作日才查得到。这期间先付了全价的话，3 个工作日后回店里请 Walgreens 用 SHIP 重新结算，退回差价（扣掉自付额）。","疫苗可以在门店网页上预约，也可以到药房问。","药房每天 13:30–14:00 午休，避开这半小时。"]},"cost":{"en":["SHIP international plan 2026–27 prescription copays: $15 generic, $30 brand, $50 non-formulary; specialty drugs 30% coinsurance.","Emergency contraception: the store page listed Plan B One-Step at $49.99 in October 2026. The UHS Health Vending Machine (Student Activity Center, 3rd floor of 333 East Campus Mall) sells a levonorgestrel pill for $6."],"zh":["SHIP 国际生计划 2026–27 的药费自付：仿制药 $15、品牌药 $30、非目录药 $50；特殊药 30%。","紧急避孕药：2026 年 10 月门店网页上 Plan B One-Step 标价 $49.99；333 East Campus Mall 学生活动中心 (SAC) 3 楼的 UHS 健康售货机卖同成分的药，只要 $6。"]},"tips":{"en":["The Walgreens at 676 State St. is store and photo only, with no pharmacy.","Pharmacy closed (after 9 p.m., or 5 p.m. on weekends)? The only 24-hour Walgreens pharmacy in Madison is at 7810 Mineral Point Rd.","SHIP's drug benefit runs through CVS Caremark, and Walgreens takes it too: the SHIP FAQ names Walgreens as able to reprocess SHIP claims."],"zh":["State St 676 号那家 Walgreens 只有店面和冲印，没有药房。","药房关了（工作日 21:00 后，周末 17:00 后）？Madison 唯一 24 小时的 Walgreens 药房在 7810 Mineral Point Rd。","SHIP 的药品福利由 CVS Caremark 管理，但 Walgreens 也能用：SHIP 的 FAQ 里专门写了 Walgreens 可以用 SHIP 重新结算。"]},"intl":{"en":["SHIP covers travel vaccines given at UHS, so SHIP members should check with UHS before paying for them here."],"zh":["SHIP 覆盖在 UHS 打的出国疫苗，SHIP 学生在这儿自费打之前先问问 UHS。"]}},"src":[["Walgreens – Store #11858, 311 E Campus Mall","https://www.walgreens.com/locator/walgreens-311+e+campus+mall-madison-wi-53715/id=11858"],["Walgreens – pharmacies near 53715","https://www.walgreens.com/storelocator/pharmacy/madison-wi"],["Walgreens – 24-hour pharmacies, Madison WI","https://www.walgreens.com/storelocator/24-hour-pharmacy/madison-wi"],["UHS – Information for Incoming Students","https://www.uhs.wisc.edu/soar/"],["UHS – Primary Care","https://www.uhs.wisc.edu/medical/primary-care-clinic/"],["SHIP – FAQ about Member Cost Sharing & Claims","https://www.uhs.wisc.edu/ship/member-cost-sharing-claims-faq/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["UHS – Health Vending Machine","https://www.uhs.wisc.edu/health-vending-machine/"],["UHS – Student Health Insurance Plan (SHIP)","https://www.uhs.wisc.edu/ship/"],["SHIP – Frequently Asked Questions about Health Insurance","https://www.uhs.wisc.edu/ship/faq-ship/"]],"unv":[],"chk":"2026-10-08","lat":43.072282,"lng":-89.398951,"stops":[["East Campus",43,"A B F"],["W Johnson at East Campus",84,"C D R 28 38 65"],["N Lake at W Johnson",108,"81"]]},{"id":"walgreens-mineral-point-24-hour","cat":"health","n":{"en":"Walgreens – 7810 Mineral Point Rd (24-hour pharmacy)","zh":"Walgreens 24 小时药店（Mineral Point Rd 店）"},"kind":{"en":"24-hour pharmacy","zh":"24 小时药店"},"addr":"7810 Mineral Point Rd, Madison, WI 53717","phone":"(608) 833-1222","web":"https://www.walgreens.com/locator/walgreens-7810+mineral+point+rd-madison-wi-53717/id=3343","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1440]],"Sa":[[0,1440]],"Su":[[0,1440]]},"ht":{"en":"Store and pharmacy open 24 hours, every day; the pharmacy closes 1:30–2 a.m. for a meal break (as of October 2026).","zh":"店面和药房都 24 小时营业，天天开；药房凌晨 1:30–2:00 休息半小时（2026 年 10 月）。"},"sum":{"en":"No 24-hour pharmacy is near campus. This far-west-side Walgreens is the only Madison store on Walgreens' 24-hour pharmacy list.","zh":"校园附近没有通宵药房；Walgreens 在 Madison 唯一的 24 小时药房在西边远郊。"},"kw":["24-hour pharmacy","late night pharmacy","open 24 hours","Walgreens","prescription","24 小时药店","通宵药店","半夜买药","处方药"],"sec":{"about":{"en":["No pharmacy near campus is open all night. Walgreens' 24-hour pharmacy search returns three stores in the area: this one at Mineral Point Rd. and High Point Rd. on Madison's far west side, plus stores in Sun Prairie and Oconomowoc.","The store side is open 24 hours too, so you can buy over-the-counter medicine and supplies at any hour."],"zh":["校园附近没有通宵营业的药房。Walgreens 官网搜 24 小时药房，这一带只有三家：Madison 西边远郊 Mineral Point Rd 和 High Point Rd 路口的这家，另外两家在 Sun Prairie 和 Oconomowoc。","店面也是 24 小时，半夜也能买非处方药和日用品。"]},"offers":{"en":["Prescriptions filled around the clock, except a 1:30–2 a.m. meal break","Over-the-counter medicine and supplies at any hour"],"zh":["全天候配处方药，只有凌晨 1:30–2:00 休息","任何时间都能买非处方药和日用品"]},"howto":{"en":["Call 608-833-1222 before going at night to check that your medicine is ready or in stock.","If a doctor or urgent care gives you a prescription late in the day, ask them to send it to this store.","Not sure you need medicine tonight? Call UHS's 24/7 nurse line first: 608-265-5600 (option 1)."],"zh":["晚上去之前先打 608-833-1222，确认药配好了或者有货。","傍晚或晚上看了医生、urgent care 拿到处方，请他们直接发到这家。","拿不准今晚是不是一定要买药，先打 UHS 24 小时护士电话：608-265-5600 按 1。"]},"cost":{"en":["Your insurance applies here. SHIP international plan 2026–27 copays: $15 generic, $30 brand."],"zh":["可以走保险。SHIP 国际生计划 2026–27：仿制药自付 $15，品牌药 $30。"]},"tips":{"en":["Before 9 p.m. on weekdays (5 p.m. on weekends), the Walgreens pharmacy at 311 E Campus Mall is much closer to campus.","UW Health pharmacy kiosks, including one at University Hospital, offer 24-hour prescription pickup."],"zh":["工作日 21:00 前（周末 17:00 前），311 E Campus Mall 那家 Walgreens 药房离校园近得多。","UW Health 的自助取药机（University Hospital 就有）24 小时都能取处方药。"]}},"src":[["Walgreens – Store #3343, 7810 Mineral Point Rd","https://www.walgreens.com/locator/walgreens-7810+mineral+point+rd-madison-wi-53717/id=3343"],["Walgreens – 24-hour pharmacies, Madison WI","https://www.walgreens.com/storelocator/24-hour-pharmacy/madison-wi"],["Walgreens – Store #11858, 311 E Campus Mall","https://www.walgreens.com/locator/walgreens-311+e+campus+mall-madison-wi-53715/id=11858"],["UHS – Call for Help","https://www.uhs.wisc.edu/call-for-help/"],["SHIP 2026–27 International Student Plan – Snapshot of Benefits and Premiums (PDF)","https://www.uhs.wisc.edu/wp-content/uploads/sites/40/2026/06/SM26_SHIPSnapshotBenefits_International_Final.pdf"],["UW Health – University Hospital","https://www.uwhealth.org/locations/university-hospital-170"]],"unv":[],"chk":"2026-10-08","lat":43.06046,"lng":-89.518078,"stops":[["S High Point at Mineral Point",44,"R"],["High Point",62,"A"],["S High Point at D'Onofrio",367,"R"]]},{"id":"bakke-recreation-wellbeing-center","cat":"fitness","n":{"en":"Bakke Recreation & Wellbeing Center (the Bakke)","zh":"Bakke 健身与身心健康中心 (the Bakke)"},"kind":{"en":"Campus gym, pool, ice rink","zh":"校园健身房、泳池、冰场"},"addr":"1976 Observatory Dr, Madison, WI 53706","phone":"(608) 262-8244","web":"https://recwell.wisc.edu/locations/bakke/","h":{"Mo":[[360,1440]],"Tu":[[360,1440]],"We":[[360,1440]],"Th":[[360,1440]],"Fr":[[360,1320]],"Sa":[[480,1320]],"Su":[[480,1440]]},"ht":{"en":"Fall 2026 (Aug 24–Dec 18): Mon–Thu 6 a.m.–midnight, Fri 6 a.m.–10 p.m., Sat 8 a.m.–10 p.m., Sun 8 a.m.–midnight. Thanksgiving: Nov 25 until 6:30 p.m., closed Nov 26–27. Closed Dec 19–25. The climbing wall, pool and ice rink keep their own hours.","zh":"2026 秋季（8/24–12/18）：周一到周四 6:00–24:00，周五 6:00–22:00，周六 8:00–22:00，周日 8:00–24:00。感恩节：11/25 开到 18:30，11/26–27 关闭。12/19–25 闭馆。攀岩墙、泳池、冰场另有各自时间。"},"sum":{"en":"Rec Well's newest gym on Observatory Drive: pool, climbing wall, ice rink, sports simulators and nap pods. Free for enrolled students with a Wiscard.","zh":"Rec Well 最新的健身中心：泳池、攀岩墙、冰场、模拟器、午睡舱。在读学生刷 Wiscard 免费进。"},"kw":["Bakke","Bakke Recreation & Wellbeing Center","gym","fitness","climbing wall","bouldering","ice rink","Sub-Zero","pool","nap pods","esports","Rec Well","Wiscard","健身房","攀岩","冰场","游泳","午睡舱","电竞"],"sec":{"about":{"en":["The Bakke Recreation & Wellbeing Center, called the Bakke, is Rec Well's newest gym. It opened April 24, 2023 and replaced the old Natatorium, built in 1963. It has over 29,000 square feet of fitness space, an 8-lane 25-yard pool, eight courts, an indoor jogging track, a rooftop fitness area, the Sub-Zero Ice Center and the Mt. Mendota climbing and bouldering wall.","Part of the building is for wellbeing: a teaching kitchen, restorative studios, and rooms for massage therapy, peer wellness coaching and meditation. There are also sports simulators and an esports lounge."],"zh":["Bakke Recreation & Wellbeing Center（读作 bah-kee）是 Rec Well 最新的健身中心，2023 年 4 月 24 日开放，取代了 1963 年建的旧 Natatorium。健身区 2.9 万平方英尺以上，有 8 道 25 码泳池、8 个球场、室内慢跑道、屋顶健身区、Sub-Zero 冰场和 Mt. Mendota 攀岩抱石墙。","楼里有专门的身心健康空间：教学厨房、修复式教室，以及按摩、同伴心理辅导和冥想的房间；另有运动模拟器和电竞室。"]},"offers":{"en":["Cardio, strength and free-weight areas on over 29,000 sq ft, plus a rooftop fitness area and an indoor jogging track","Cove Pool: 8 lanes, 25 yards, for open lap swim (hours below)","Mt. Mendota climbing and bouldering wall on level 3, plus a Kilter Board; shoes and harnesses are free to borrow","Eight multipurpose courts for drop-in basketball, volleyball and badminton","Sub-Zero Ice Center: public skate, figure skating, stick and puck, and open hockey sessions","Sports simulators in the Skybox Suites (golf, cricket, soccer, baseball and more): three screens, 1-hour reservations","Esports Lounge with 12 gaming computers, open to all UW–Madison students","Three nap pods for a 20-minute nap, massage and meditation rooms, and the Wolf Teaching Kitchen","Group fitness studios, plus a Member Services desk for equipment checkout, towels and day-use lockers"],"zh":["有氧、力量和自由重量区共 2.9 万平方英尺以上，另有屋顶健身区和室内慢跑道","Cove 泳池：8 条泳道，25 码，可以游泳（时间见下）","3 楼的 Mt. Mendota 攀岩抱石墙，还有一块 Kilter Board；攀岩鞋和安全带免费借","8 个多功能球场，可随到随打篮球、排球、羽毛球","Sub-Zero 冰场：公共滑冰、花样滑冰、stick and puck 和冰球对抗场次","Skybox Suites 运动模拟器（高尔夫、板球、足球、棒球等）：3 块屏，按 1 小时预约","电竞室 (Esports Lounge) 有 12 台游戏电脑，所有 UW–Madison 学生可用","3 个午睡舱 (nap pods) 睡 20 分钟，另有按摩、冥想房间和 Wolf Teaching Kitchen","团体操教室；Member Services 柜台可借器材、租毛巾，另有当日储物柜"]},"howto":{"en":["Show your Wiscard at the front desk. Enrolled students need no sign-up and no payment.","Wear closed-toe, non-marking athletic shoes. Climbing needs climbing shoes, which are free to borrow at the wall.","Climbing: check in at the wall desk and sign the waiver. Belaying needs a Rec Well belay certification; take the Top Rope Belay Clinic (10:30 a.m.–noon) on Oct 16, Nov 9 or Dec 4.","Sports simulators: reserve on the Rec Well website or at the Bakke Member Services desk, up to a week ahead, two 1-hour slots a day at most. Drop-in works during Open Rec.","Esports Lounge: log in with your own NetID account; account sharing is not allowed.","Courts and pool are drop-in. The Daily Schedules page shows what each court is set up for.","Ice rink: skate passes are sold in person at the rink services desk; the rink's phone is (608) 263-6566."],"zh":["前台刷学生证 (Wiscard) 进门。在读学生不用报名、不用付钱。","必须穿包脚趾、不留鞋印的运动鞋。攀岩要穿攀岩鞋，在墙边免费借。","攀岩：先在攀岩墙柜台登记并签免责声明。要保护别人（belay）得有 Rec Well 的 belay 认证，可报名 Top Rope Belay Clinic（10:30–12:00），10/16、11/9、12/4 开班。","运动模拟器：在 Rec Well 官网或 Bakke 的 Member Services 预约，最多提前一周，每天最多 2 个小时段；Open Rec 时也可直接去。","电竞室：用自己的 NetID 账号登录，不许共用账号。","球场和泳池随到随用，不用预约；Daily Schedules 页面写着各球场当时的安排。","冰场：滑冰通票在冰场服务台现场买；冰场电话 (608) 263-6566。"]},"cost":{"en":["Free with student fees: gym floors, pool, courts, climbing wall (shoes and harness included), sports simulators, nap pods and esports equipment.","The ice rink costs extra: a $4 rink fee for UW students plus $3 for skates, or a $40 semester skate pass ($60 with rentals).","Other fall 2026 extras: Group Fitness pass $40; towel service $10 (or $1 a day); half-size rental locker $40; Top Rope Belay Clinic $5 for students.","A visitor with no UW link buys a Community day pass for $20 and shows a government-issued photo ID."],"zh":["学费 (segregated fees) 已包含：器械区、泳池、球场、攀岩墙（鞋和安全带也免费）、运动模拟器、午睡舱、电竞设备。","冰场要另付：UW 学生场地费 $4 加租冰鞋 $3，或买学期通票 $40（含租鞋 $60）。","2026 秋季其他收费：Group Fitness 通票 $40；毛巾服务 $10（单次租 $1）；半柜租用 $40；学生报 Top Rope Belay Clinic $5。","校外朋友要买 Community 日票 $20，并出示政府签发的带照片证件。"]},"tips":{"en":["Cove Pool open swim this fall: Mon & Wed 6:30 a.m.–1:30 p.m. and 4:30–8:30 p.m.; Tue & Thu 11:30 a.m.–8:30 p.m.; Fri 6:30 a.m.–1:30 p.m. and 4:30–7:30 p.m.; Sat–Sun 9 a.m.–4:30 p.m. Oct 10: noon–4:30 p.m.","Mt. Mendota fall hours: Mon & Wed noon–10 p.m., Tue & Thu 2–10 p.m., Fri–Sun noon–8 p.m. Closed Oct 10 and Nov 26–29.","The nap pods are on the second floor in the Wellbeing area. Do not use them right after a workout. They close 15 minutes before the building does.","The Rec Well Esports page had no fall 2026 lounge hours posted yet; check Daily Schedules before you go.","The old Natatorium is gone: the Bakke replaced it in 2023, so older guides that list it are out of date.","Bikes, scooters and skateboards stay outside: park bikes at the stalls in front and leave boards in the outdoor board storage."],"zh":["Cove 泳池今秋开放：周一、三 6:30–13:30 和 16:30–20:30；周二、四 11:30–20:30；周五 6:30–13:30 和 16:30–19:30；周末 9:00–16:30。10/10 为 12:00–16:30。","Mt. Mendota 秋季开放：周一、三 12:00–22:00，周二、四 14:00–22:00，周五到周日 12:00–20:00。10/10 和 11/26–29 关闭。","午睡舱在 2 楼 Wellbeing 区。运动完别马上用。比整栋楼早 15 分钟关。","Rec Well 电竞页面还没贴出 2026 秋季开放时间，去之前看 Daily Schedules。","旧的 Natatorium 已经没了：2023 年被 Bakke 取代，老攻略里写的 Natatorium 已过时。","自行车、滑板、滑板车不能进楼：自行车停门前车架，滑板放室外存放处。"]}},"src":[["Rec Well – Bakke Recreation & Wellbeing Center","https://recwell.wisc.edu/locations/bakke/"],["Rec Well – Bakke Recreation & Wellbeing Center to Open April 24 (2023)","https://recwell.wisc.edu/2023/04/13/bakke-recreation-wellbeing-center-to-open-april-24/"],["Rec Well – Cove Pool","https://recwell.wisc.edu/pools/pool-cove/"],["Rec Well – Climbing & Bouldering Wall","https://recwell.wisc.edu/locations/climbing/"],["Rec Well – Policies","https://recwell.wisc.edu/policies/"],["Rec Well – Open Rec","https://recwell.wisc.edu/play/"],["Rec Well – Sports Simulators","https://recwell.wisc.edu/sports-simulators/"],["Rec Well – Esports Lounge","https://recwell.wisc.edu/intramuralsports/esports-lounge/"],["Rec Well – Nap Pods","https://recwell.wisc.edu/nap-pods/"],["Rec Well – Ice Rink (Sub-Zero Ice Center)","https://recwell.wisc.edu/locations/icerink/"],["Rec Well – Student Memberships","https://recwell.wisc.edu/students/"],["Rec Well – Group Fitness","https://recwell.wisc.edu/groupfitness/"],["Rec Well – Member Services (lockers, towels, equipment checkout)","https://recwell.wisc.edu/memberservices/"],["Rec Well – Memberships","https://recwell.wisc.edu/memberships/"]],"unv":[],"chk":"2026-10-08","lat":43.076851,"lng":-89.419769,"stops":[["Observatory at Colwood",75,"28 38 65 80 84"],["Observatory at Elm",284,"28 38 65 80 82"],["Observatory at Walnut",378,"28 38 65 80"]]},{"id":"camp-randall-fitness-center","cat":"fitness","n":{"en":"Camp Randall Fitness Center (CRFC)","zh":"Camp Randall 健身房 (CRFC)"},"kind":{"en":"Campus gym","zh":"校园健身房"},"addr":"1436 Monroe St, Madison, WI 53711","phone":"(608) 262-8244","web":"https://recwell.wisc.edu/locations/crfc/","h":{"Mo":[[360,1320]],"Tu":[[360,1320]],"We":[[360,1320]],"Th":[[360,1320]],"Fr":[[360,1320]],"Sa":[[480,1320]],"Su":[[480,1320]]},"ht":{"en":"Fall 2026 (Sept 22–Dec 17): Mon–Fri 6 a.m.–10 p.m., Sat–Sun 8 a.m.–10 p.m. Closed on Badger home football game days (Oct 24 and Nov 7 are still ahead) and Nov 26–29; Nov 25 closes at 6:30 p.m. Closed Dec 19–25.","zh":"2026 秋季（9/22–12/17）：周一到周五 6:00–22:00，周六、周日 8:00–22:00。Badger 橄榄球主场比赛日闭馆（之后是 10/24、11/7）；感恩节 11/25 18:30 关门，11/26–29 关闭；12/19–25 闭馆。"},"sum":{"en":"Rec Well weight room by Camp Randall Stadium with cardio, machines and free weights. Free for enrolled students. The old Shell is gone.","zh":"Camp Randall 球场旁的 Rec Well 器械房，学生免费。旧的 Shell 已不在。"},"kw":["Camp Randall","CRFC","Camp Randall Fitness Center","the Shell","Camp Randall Sports Center","gym","weight room","Kellner Family Athletic Center","Rec Well","Wiscard","健身房","器械","力量训练","Shell"],"sec":{"about":{"en":["The Camp Randall Fitness Center (CRFC) is a Rec Well gym on the southwest side of campus, inside the Kellner Family Athletic Center. It is an 11,000-square-foot room with cardio equipment, strength equipment and free weights.","It takes the place of the Camp Randall Sports Center, the old Shell. The Shell closed on April 19, 2023 and its ownership passed to UW Athletics, which later tore it down for a new indoor practice facility next to the football stadium. Older guides that still list the Shell are out of date."],"zh":["Camp Randall Fitness Center (CRFC) 是校园西南片的 Rec Well 健身房，在 Kellner Family Athletic Center 里面。面积 11,000 平方英尺，有有氧器械、力量器械和自由重量。","它顶替的是旧的 Camp Randall Sports Center（大家叫 the Shell）。Shell 2023 年 4 月 19 日关闭，产权转给 UW Athletics，后来被拆掉，给球场旁边的新室内训练馆让路。老攻略里写的 Shell 已经过时。"]},"offers":{"en":["Cardio machines, strength machines and free weights in an 11,000 sq ft room","A limited number of day-use lockers","Restrooms in the Kellner Family Athletic Center for Rec Well members","A Live Building Usage link on the CRFC page to check the crowd"],"zh":["11,000 平方英尺的房间里有有氧器械、力量器械和自由重量","数量有限的当日储物柜 (day-use locker)","Kellner Family Athletic Center 里有供 Rec Well 会员用的卫生间","CRFC 页面有 Live Building Usage 链接，可以看现在人多不多"]},"howto":{"en":["Enter through the Schaefer Family Entrance at the south end of the Kellner Family Athletic Center, 1436 Monroe St. Show your Wiscard.","Memberships and passes are not sold here. If you ever need one, buy it at the Nick, the Bakke or Nielsen Tennis Stadium, or online.","There is no towel service, equipment checkout or merchandise here, so bring your own towel."],"zh":["从 Kellner Family Athletic Center 南端的 Schaefer Family Entrance 进门（1436 Monroe St），刷学生证 (Wiscard)。","这里不卖会员和日票；需要的话去 Nick、Bakke 或 Nielsen Tennis Stadium，或在网上买。","这里没有毛巾服务、器材借用和商品销售，毛巾自己带。"]},"cost":{"en":["Free for enrolled students: entry is in your segregated fees. Show a valid Wiscard.","A visitor with no UW link buys a Community day pass for $20 at the Nick or the Bakke (or online) and shows a government-issued photo ID."],"zh":["在读学生免费：进门费用已含在学费 (segregated fees) 里，刷有效的 Wiscard。","校外朋友要在 Nick、Bakke 或网上买 Community 日票 $20，并出示政府签发的带照片证件。"]},"tips":{"en":["There are no showers here. Change at home, or use the Nick or the Bakke instead.","The gym is closed on Badger home football game days. The CRFC page lists Oct 24 and Nov 7 as the remaining fall dates.","Want a pool, courts or classes? Go to the Nick or the Bakke. This room has cardio, strength and free-weight equipment only.","There are no rental lockers, so use a day-use locker or leave valuables at home."],"zh":["这里没有淋浴，在家换好再来，或者去 Nick、Bakke。","Badger 橄榄球主场比赛日整天闭馆；CRFC 页面列出的秋季剩余日期是 10/24 和 11/7。","想游泳、打球、上团体课就去 Nick 或 Bakke；这里只有有氧、力量和自由重量器械。","没有可租用的储物柜，用当日储物柜，或者贵重物品别带。"]}},"src":[["Rec Well – Camp Randall Fitness Center","https://recwell.wisc.edu/locations/crfc/"],["Rec Well – Student Memberships","https://recwell.wisc.edu/students/"],["Rec Well – Memberships","https://recwell.wisc.edu/memberships/"],["UW–Madison News – Last day at the Shell (April 19, 2023)","https://news.wisc.edu/last-day-at-the-shell"],["Cap Times – Track alums urge UW-Madison athletics to reconsider Shell replacement","https://captimes.com/news/education/track-alums-urge-uw-madison-athletics-to-reconsider-shell-replacement/article_eb5680f8-9185-11ef-ada0-c3c7332eb9a8.html"]],"unv":[],"chk":"2026-10-08","lat":43.068091,"lng":-89.412511,"stops":[["Regent at S Breese",87,"E 64 82"],["Monroe at S Breese",134,"D"],["Regent at N Breese",145,"E 64"]]},{"id":"lakeshore-path-picnic-point","cat":"fitness","n":{"en":"Lakeshore Path and Picnic Point (Lakeshore Nature Preserve)","zh":"湖滨步道与 Picnic Point (Lakeshore Nature Preserve)"},"kind":{"en":"Running path, nature preserve","zh":"跑步道、自然保护区"},"addr":"2003 University Bay Dr, Madison, WI 53705","phone":"(608) 265-9275","web":"https://lakeshorepreserve.wisc.edu/","h":{"Mo":[[240,1320]],"Tu":[[240,1320]],"We":[[240,1320]],"Th":[[240,1320]],"Fr":[[240,1320]],"Sa":[[240,1320]],"Su":[[240,1320]]},"ht":{"en":"The Preserve is open daily 4 a.m.–10 p.m. The Picnic Point lot (UW Lot 130) is closed 10 p.m.–4 a.m. In winter the trails are not groomed.","zh":"保护区每天 4:00–22:00 开放。Picnic Point 入口的停车场 (UW Lot 130) 22:00–4:00 关闭。冬天步道不除雪压实。"},"sum":{"en":"Lakefront preserve with 12 miles of trails and the Lakeshore Path out to Picnic Point, the classic campus run or walk. Open daily 4 a.m.–10 p.m.","zh":"沿湖自然保护区，12 英里步道，湖滨步道通到 Picnic Point，校园经典跑步线。每天 4:00–22:00。"},"kw":["Lakeshore Path","Picnic Point","Lakeshore Nature Preserve","running","jogging","trail","walk","Lake Mendota","fire circle","bike path","湖滨步道","跑步","散步","Picnic Point","篝火","自然保护区"],"sec":{"about":{"en":["The Lakeshore Nature Preserve is a 300-acre natural area that stretches 4.3 miles along the south shore of Lake Mendota, from the Hasler Limnology Laboratory in the east to Shorewood Hills in the west. Its trails run about 12 miles between the Union Terrace and Eagle Heights Woods.","The Lakeshore Path is the main route. The Howard Temin Path runs from North Park Street in the east to Oxford Road in the west; the Lake Mendota Path branches off at the Picnic Point entrance and runs out to the tip of the Point. Picnic Point is a nearly mile-long peninsula and the most popular spot in the Preserve."],"zh":["Lakeshore Nature Preserve 是 300 英亩的自然区，沿 Lake Mendota 南岸伸展 4.3 英里，东起 Hasler Limnology Laboratory，西到 Shorewood Hills。Union Terrace 到 Eagle Heights Woods 之间的步道一共约 12 英里。","主线是湖滨步道 (Lakeshore Path)：Howard Temin Path 东起 North Park Street、西到 Oxford Road；Lake Mendota Path 在 Picnic Point 入口分出，通到半岛尖端。Picnic Point 是近一英里长的半岛，也是保护区里最热门的地方。"]},"offers":{"en":["Running and walking on the Howard Temin Path and the trails of the Preserve","Picnic Point: a nearly mile-long peninsula with lawns along the main path where you can lay out a blanket","Six reservable fire circles on Picnic Point for campfires and s'mores; firewood at the racks is free","Bird watching: University Bay is a popular place to see migrating waterfowl in spring and fall","Free guided nature walks every spring and fall, led by Friends of the Preserve volunteers","Snowshoeing and skiing on ungroomed trails in winter; Outdoor UW rents snowshoes"],"zh":["在 Howard Temin Path 和保护区步道上跑步、散步","Picnic Point：近一英里长的半岛，主路边有草坪可以铺野餐垫","Picnic Point 上有 6 个可预约的篝火圈，烤火、烤棉花糖；木柴架上的柴免费","观鸟：University Bay 是春秋看迁徙水鸟的热门地点","春秋两季有免费导览自然步行，由 Friends of the Preserve 志愿者带队","冬天可在未压雪的步道上穿雪鞋或滑雪；Outdoor UW 出租雪鞋"]},"howto":{"en":["Classic route: walk or bike to the Picnic Point entrance (UW Lot 130, 2003 University Bay Dr), follow the Lakeshore Path to the tip, and come back. The path is paved or packed limestone.","Longer route: from Memorial Union, follow the Lakeshore Path west along the water to the tip of Picnic Point and back.","Stay on marked trails, and do not block the trail when you walk or run in a group. Bike racks are at all the parking lots and at the Lakeshore Residence Halls.","Fire circle: ask Campus Event Services (Wisconsin Union), which answers within 3 business days. Reservations are not required, so a circle may be in use when you arrive.","A free campus bus runs out to Picnic Point and Eagle Heights; the Preserve's Plan a Visit page describes it."],"zh":["经典路线：走路或骑车到 Picnic Point 入口（UW Lot 130，2003 University Bay Dr），沿湖滨步道到半岛尖端再回来。路面是柏油或压实石灰石。","更长的路线：从 Memorial Union 沿湖边的湖滨步道往西走到 Picnic Point 尖端再折返。","只走标出的步道；几个人一起跑步时不要堵住路。所有停车场和 Lakeshore 宿舍区都有自行车架。","篝火圈：向 Campus Event Services（Wisconsin Union）申请，3 个工作日内回复。预约不是强制的，到了可能已有人在用。","有免费的校园巴士开到 Picnic Point 和 Eagle Heights，Preserve 官网 Plan a Visit 页有介绍。"]},"cost":{"en":["The visitor pages post no fee for walking or running here. Firewood at the racks along the main Picnic Point path is free.","Parking at Lot 130 is $1 per 30 minutes for the first 3 hours (daily maximum $13) on weekdays 7 a.m.–4:30 p.m., and free evenings and weekends. The Frautschi Point and Raymer's Cove lots are free for Preserve visitors."],"zh":["官网访客页没有标注步行、跑步的费用。Picnic Point 主路边木柴架上的柴免费。","Lot 130 工作日 7:00–16:30 前 3 小时每 30 分钟 $1（日封顶 $13），晚上和周末免费。Frautschi Point 和 Raymer's Cove 的停车场对访客免费。"]},"tips":{"en":["Since Oct 5, 2026 UW Lot 130 has only 10–15 stalls because of Frautschi Center construction. Walk or bike, or use UW Lot 60 or Lot 76.","Bikes are allowed on the Howard Temin Path and the paved path through the woods to Eagle Heights Drive only. The Lake Mendota Path and the main Picnic Point path are for walkers and runners.","At the Narrows, halfway out, the Point is so thin you can see University Bay and Lake Mendota at the same time.","The toilets out on the Point are rustic pit toilets.","Dogs must be on a leash. No camping, drones, hammocks or slacklines, and no amplified sound.","Winter: trails are not groomed, and off-trail snowshoeing, hiking and skiing is not permitted."],"zh":["2026 年 10 月 5 日起，因 Frautschi Center 施工，UW Lot 130 只剩 10–15 个车位。建议走路、骑车，或停 UW Lot 60、Lot 76。","自行车只能走 Howard Temin Path 和通往 Eagle Heights Drive 的柏油林间路；Lake Mendota Path 和 Picnic Point 主路只给步行和跑步。","半路的 Narrows 窄得能同时看到 University Bay 和 Lake Mendota。","半岛上的厕所是简易旱厕。","狗必须拴绳。不许露营、放无人机、挂吊床或拉 slackline，也不许放大音量的音乐。","冬天步道不压雪，不许离开步道穿雪鞋、徒步或滑雪。"]},"intl":{"en":["Swimming in Lake Mendota is only allowed at the Memorial Union swim pier, not along the Preserve.","Fires are only allowed in the six fire circles. Charcoal grills, gas grills and lighter fluid are not allowed, and alcohol is banned except at permitted university events."],"zh":["在 Lake Mendota 游泳只能去 Memorial Union 的游泳码头，保护区沿岸不行。","只能在 6 个篝火圈里生火；不许用炭烤架、燃气烤架和打火液。除非是批准的校方活动，也不许喝酒。"]}},"src":[["Lakeshore Nature Preserve – Getting Here and Parking","https://lakeshorepreserve.wisc.edu/visit/getting-here-and-parking/"],["Lakeshore Nature Preserve – Visitor Etiquette","https://lakeshorepreserve.wisc.edu/visitor-etiquette/"],["Lakeshore Nature Preserve – Recreational Opportunities","https://lakeshorepreserve.wisc.edu/recreational-opportunities/"],["Lakeshore Nature Preserve – The Lakeshore Path","https://lakeshorepreserve.wisc.edu/visit/places/the-lakeshore-path/"],["Lakeshore Nature Preserve – Picnic Point","https://lakeshorepreserve.wisc.edu/visit/places/picnic-point/"],["Lakeshore Nature Preserve – Plan a Visit","https://lakeshorepreserve.wisc.edu/visit/plan-a-visit/"],["Lakeshore Nature Preserve – Reserve a Fire Circle","https://lakeshorepreserve.wisc.edu/reserve-a-fire-circle/"],["Lakeshore Nature Preserve – Picnic Point UW Lot 130 Parking Update (Oct 5, 2026)","https://lakeshorepreserve.wisc.edu/2026/10/05/picnic-point-parking-update/"]],"unv":[],"chk":"2026-10-08","lat":43.084342,"lng":-89.429155,"stops":[["University Bay at Picnic Point",14,"80 84"],["Lake Mendota at University Bay",352,"63 80 84"],["University Bay at Lot 76",390,"80"]]},{"id":"nicholas-recreation-center","cat":"fitness","n":{"en":"Nicholas Recreation Center (the Nick)","zh":"Nicholas 健身中心 (the Nick)"},"kind":{"en":"Campus gym and pool","zh":"校园健身房和游泳馆"},"addr":"797 W Dayton St, Madison, WI 53715","phone":"(608) 262-8244","web":"https://recwell.wisc.edu/locations/nick/","h":{"Mo":[[360,1440]],"Tu":[[360,1440]],"We":[[360,1440]],"Th":[[360,1440]],"Fr":[[360,1320]],"Sa":[[480,1320]],"Su":[[480,1440]]},"ht":{"en":"Fall 2026 (Aug 24–Dec 17): Mon–Thu 6 a.m.–midnight, Fri 6 a.m.–10 p.m., Sat 8 a.m.–10 p.m., Sun 8 a.m.–midnight. Thanksgiving: closes 6:30 p.m. on Nov 25, closed Nov 26–28. Closed Dec 18–Jan 6.","zh":"2026 秋季（8/24–12/17）：周一到周四 6:00–24:00，周五 6:00–22:00，周六 8:00–22:00，周日 8:00–24:00。感恩节：11/25 18:30 关门，11/26–28 全天关闭。12/18–1/6 闭馆。"},"sum":{"en":"UW–Madison's big campus gym: 50-meter pool, 8 courts, 5 studios and 30,000 sq ft of weights and cardio. Free for enrolled students with a Wiscard.","zh":"校园大型健身房：50 米泳池、8 个球场、大片器械区。在读学生刷 Wiscard 免费进。"},"kw":["Nick","Nicholas Recreation Center","gym","fitness","recreation center","pool","swimming","basketball","Rec Well","Wiscard","健身房","健身中心","游泳","篮球","体育馆"],"sec":{"about":{"en":["The Nicholas Recreation Center, or the Nick, is a University Recreation & Wellbeing (Rec Well) gym in the southeast campus neighborhood. It has 30,000 square feet of cardio and strength space across five levels, 8 courts, 5 studios, 2 racquetball courts, an indoor track and a 50-meter pool with a diving well.","Rec Well's other big gym is the Bakke on Observatory Drive. Your Wiscard works at both, so use whichever is closer."],"zh":["Nicholas Recreation Center，大家叫 the Nick，是校园 Rec Well (University Recreation & Wellbeing) 的大型健身中心，在校园东南片。五层楼，健身器械区 3 万平方英尺，另有 8 个球场、5 间教室、2 个 racquetball 场地、室内跑道和带跳水池的 50 米泳池。","Rec Well 另一个大馆是 Observatory Drive 上的 Bakke。学生证 (Wiscard) 两边都能刷，哪个近去哪个。"]},"offers":{"en":["Cardio and strength floors, free weights, and a sprint ramp that leads up to a suspended indoor track (one-sixth of a mile)","8 full-size courts for basketball, volleyball, badminton and futsal, plus 2 racquetball courts","50-meter pool and a 25-yard diving well for lap swim and open swim","5 studios for group fitness, indoor cycling and small-group training; over 100 classes a week across the Nick and the Bakke","A personal training suite, and a 30-minute one-on-one Fitness Equipment Orientation to learn the machines","Member Services desk: equipment checkout (basketballs, volleyballs, jump ropes, racquetball rackets), daily towels, goggles and caps","More than 300 day-use lockers with built-in locks"],"zh":["有氧和力量器械区、自由重量区，还有通往悬空室内跑道（1/6 英里）的冲刺坡道","8 个标准球场：篮球、排球、羽毛球、五人制足球；另有 2 个 racquetball 场地","50 米泳池加 25 码跳水池，可以游泳、练长距离","5 间教室上团体操、动感单车、小班训练；Nick 和 Bakke 合计每周 100 多节课","有私教室；Fitness Equipment Orientation 是 30 分钟一对一教你用器械","Member Services 柜台可借篮球、排球、跳绳、racquetball 球拍，租毛巾，买泳镜泳帽","300 多个自带锁的当日储物柜"]},"howto":{"en":["Show your Wiscard at the front desk. Enrolled students need no sign-up and no payment; entry is already in your fees.","Forgot the card? Members get six courtesy passes a semester (fall, spring, summer), shared across all Rec Well buildings.","Wear closed-toe, non-marking athletic shoes. Street shoes, backless shoes, clogs and boots are not allowed.","Courts are drop-in, no booking. The Daily Schedules page shows which sport has priority on each court.","Group classes are first come, first served with a Group Fitness pass. Arrive 10 minutes early; late entry is not allowed.","Day-use lockers have built-in locks, so no padlock is needed, and they are emptied every night.","Logging in to Rec Well's online member portal (Sign Up on recwell.wisc.edu) first requires an Assumption of Risk waiver."],"zh":["前台刷学生证 (Wiscard) 进门。在读学生不用报名、不用付钱，费用已含在学费里。","忘带卡：每学期有 6 次临时通行 (courtesy pass)，所有 Rec Well 场馆合用。","必须穿包脚趾、不留鞋印的运动鞋；街鞋、拖鞋、木屐和靴子不行。","球场随到随打，不用预约；Daily Schedules 页面写着各场地当时优先打什么球。","团体课先到先得，需要买 Group Fitness 通票；提前 10 分钟到，迟到不让进。","当日储物柜自带锁，不用带锁头；每晚清空。","第一次登录 Rec Well 在线会员系统（官网 Sign Up）要先签 Assumption of Risk 免责声明。"]},"cost":{"en":["Free with your student fees: gym floors, pool, diving well and courts. Show a valid Wiscard.","Paid extras, fall 2026: Group Fitness pass $40; towel service $10 (or $1 a day); rental locker $25 (one-third size) or $40 (half size). Goggles $12, swim cap $5.","Massage, personal training and lessons also cost extra.","A visitor with no UW link buys a Community day pass for $20 and shows a government-issued photo ID. Lending your Wiscard to a friend is banned."],"zh":["学费 (segregated fees) 已包含：器械区、泳池、跳水池和球场。刷有效的 Wiscard 就行。","2026 秋季另付：Group Fitness 通票 $40；毛巾服务 $10（单次租 $1）；租储物柜 $25（1/3 柜）或 $40（半柜）。泳镜 $12，泳帽 $5。","按摩、私教和课程也要另付。","校外朋友要买 Community 日票 $20，并出示政府签发的带照片证件。不能把 Wiscard 借给朋友进门。"]},"tips":{"en":["Pool open swim this fall: Mon–Fri 11 a.m.–2 p.m. and 5–8:30 p.m.; Sat–Sun 11:30 a.m.–7:30 p.m. The pool is closed Oct 17, Oct 31, Nov 6, Nov 21 and Dec 5.","Open Live Building Usage from the Nick page to see how crowded it is before you walk over.","Winter break: the Nick is closed Dec 18–Jan 6, but the Bakke is open Dec 26–30 and Jan 2–3.","Bikes are not allowed inside. Lock up at the stalls in front of the building.","Never used weights? Take the 30-minute equipment orientation with a trainer, then use the same machines any time.","The locker rooms have private shower stalls, and there are all-gender single-use bathrooms and showers."],"zh":["今秋泳池开放时间：周一到周五 11:00–14:00、17:00–20:30；周末 11:30–19:30。10/17、10/31、11/6、11/21、12/5 泳池关闭。","去之前在 Nick 页面点 Live Building Usage，看现在人多不多。","寒假：Nick 12/18–1/6 闭馆，但 Bakke 在 12/26–30 和 1/2–3 开门。","室内不许放自行车，停在楼前的车架上。","没练过器械？约一次 30 分钟的器械指导 (orientation)，教练带你认一遍机器。","更衣室有独立淋浴间，另有不分性别的单人卫生间和淋浴间。"]},"intl":{"en":["The Wiscard is your gym pass. If you have not picked it up yet, the Wiscard office is in Union South. There is nothing to buy or register at the gym.","Pool etiquette: shower before you get in, and again after the sauna, steam room or toilet."],"zh":["Wiscard 就是进馆的卡。还没领的话，Wiscard 办公室在 Union South；在馆里不用另外买或登记。","泳池规矩：下水前先冲澡；用过桑拿、蒸汽房或厕所后要再冲一次。"]}},"src":[["Rec Well – Nicholas Recreation Center","https://recwell.wisc.edu/locations/nick/"],["Rec Well – Locations & Hours","https://recwell.wisc.edu/locations/"],["Rec Well – Student Memberships","https://recwell.wisc.edu/students/"],["Rec Well – Policies","https://recwell.wisc.edu/policies/"],["Rec Well – Open Rec","https://recwell.wisc.edu/play/"],["Rec Well – Memberships","https://recwell.wisc.edu/memberships/"],["Rec Well – Group Fitness","https://recwell.wisc.edu/groupfitness/"],["Rec Well – Fitness Equipment Orientation","https://recwell.wisc.edu/equipmentorientation/"],["Rec Well – Member Services (lockers, towels, equipment checkout)","https://recwell.wisc.edu/memberservices/"],["Rec Well – Soderholm Family Aquatic Center","https://recwell.wisc.edu/pools/pool-sfac/"],["Rec Well – Bakke Recreation & Wellbeing Center","https://recwell.wisc.edu/locations/bakke/"],["Wisconsin Union – Hours & Services","https://union.wisc.edu/visit/hours"]],"unv":[],"chk":"2026-10-08","lat":43.070437,"lng":-89.398265,"stops":[["W Dayton at N Park",149,"80 82"],["W Johnson at East Campus",168,"C D R 28 38 65"],["East Campus",172,"A B F"]]},{"id":"nielsen-tennis-stadium","cat":"fitness","n":{"en":"Nielsen Tennis Stadium","zh":"Nielsen 网球馆 (Nielsen Tennis Stadium)"},"kind":{"en":"Indoor tennis and squash","zh":"室内网球和壁球馆"},"addr":"1000 Highland Ave, Madison, WI 53705","phone":"(608) 262-8244","web":"https://recwell.wisc.edu/locations/nielsen/","h":{"Mo":[[405,1350]],"Tu":[[405,1350]],"We":[[405,1350]],"Th":[[405,1350]],"Fr":[[405,1350]],"Sa":[[465,1350]],"Su":[[465,1350]]},"ht":{"en":"Fall 2026 (Sept 2–Dec 20): Mon–Fri 6:45 a.m.–10:30 p.m., Sat–Sun 7:45 a.m.–10:30 p.m. Badger home football days (Oct 24, Nov 7) and Nov 27: 7:45 a.m.–noon. Thanksgiving: Nov 25 until 6:30 p.m., closed Nov 26. It can close early or for tournaments, so call to confirm.","zh":"2026 秋季（9/2–12/20）：周一到周五 6:45–22:30，周六、周日 7:45–22:30。Badger 橄榄球主场日（10/24、11/7）和 11/27 只开 7:45–12:00。感恩节：11/25 开到 18:30，11/26 关闭。可能提前关门或因比赛关闭，去前打电话确认。"},"sum":{"en":"Rec Well's 12 indoor tennis courts and 2 squash courts. Reserve ahead; UW students pay $8 per person for singles, $4 for doubles.","zh":"Rec Well 的 12 片室内网球场和 2 片壁球场，需预约；UW 学生单打每人 $8，双打 $4。"},"kw":["Nielsen Tennis Stadium","tennis","squash","indoor tennis","court reservation","racquet","Rec Well","网球","壁球","球拍","订场"],"sec":{"about":{"en":["Nielsen Tennis Stadium is Rec Well's indoor racquet building at 1000 Highland Avenue, with 12 indoor tennis courts and 2 squash courts. It is a separate building from the Nick and the Bakke.","Anyone can play. Student status or a Rec Well membership gives reduced court fees. Unlike the Nick and the Bakke, you do not just swipe in: reservations are required."],"zh":["Nielsen Tennis Stadium 是 Rec Well 的室内球拍运动馆，地址 1000 Highland Avenue，有 12 片室内网球场和 2 片壁球场，和 Nick、Bakke 不在同一栋楼。","谁都能打。有学生身份或 Rec Well 会员，场地费更低。不像 Nick 和 Bakke 刷卡就进，这里必须预约。"]},"offers":{"en":["12 indoor tennis courts and 2 squash courts, open year-round","Racquet rental: demo tennis and squash racquets $2 each; tennis ball machine $12 plus court fees","Racquet repair and stringing, prepaid and guaranteed within three business days","Tennis lessons from certified instructors, and a system to help you find a tennis partner","Student Nights: unlimited open rec tennis 6–9 p.m. for $5 a player (fall 2026 dates were not posted yet)"],"zh":["12 片室内网球场、2 片壁球场，全年开放","租球拍：网球拍、壁球拍各 $2；发球机 $12 外加场地费","球拍维修和穿线，需预付，三个工作日内保证完成","有认证教练的网球课，也有帮你找球友的系统","Student Night：晚 6–9 点不限次数打 open rec 网球，每人 $5（2026 秋季日期还没公布）"]},"howto":{"en":["Reserve a tennis court online with CourtReserve, by phone at (608) 262-8244 (option 2), or at the Member Services desk. Squash courts: online, or by phone or the front desk.","Slots are 1 hour 15 minutes. Booking opens at 7:45 a.m. each day. Students can book three days ahead; non-members one day ahead.","Online booking closes 2 hours before the slot; after that, call or go to the desk. One reservation per person per day, and each person books their own.","Pay the court fee at the stadium before you play. Cancel at least 2 hours ahead to avoid a $12 late-cancel or no-show fee."],"zh":["网球场：在 CourtReserve 上预约，或打 (608) 262-8244 按 2，或到 Member Services 柜台。壁球场：网上、电话或前台。","每场 1 小时 15 分。每天 7:45 开始放号。学生可提前 3 天订，非会员提前 1 天。","网上订场截止到开场前 2 小时，之后要打电话或到柜台。每人每天 1 个预约，每人自己订自己的。","场地费开打前在馆里付。提前至少 2 小时取消，不然 no-show 或迟取消要罚 $12。"]},"cost":{"en":["Court fees are per person for a 1 hour 15 minute slot. UW students pay $8 singles and $4 doubles; Rec Well members $10 and $5; non-members $20 and $10.","Discounted rates for slots starting 10:30 a.m.–1:30 p.m. Mon–Thu: UW students $4 singles and $3 doubles.","Student Night: unlimited open rec tennis 6–9 p.m. for $5 a player. The page said fall 2026 dates would be posted soon.","Late cancellations and no-shows are billed $12, and you must pay it before you can book or play again."],"zh":["场地费按人头算，每场 1 小时 15 分。UW 学生单打 $8、双打 $4；Rec Well 会员 $10、$5；非会员 $20、$10。","周一到周四 10:30–13:30 开场的时段有折扣：UW 学生单打 $4、双打 $3。","Student Night：晚 6–9 点不限次数打 open rec 网球，每人 $5；官网说秋季日期稍后公布。","迟取消和 no-show 罚 $12，付清后才能再订场、再打球。"]},"tips":{"en":["The stadium can close early depending on the reservation schedule, and for tournaments. Call (608) 262-8244 (option 2) before a walk-in.","Badger home football days (Oct 24, Nov 7) are 7:45 a.m.–noon only.","Book from your phone the day your window opens: students can reserve three days ahead, starting at 7:45 a.m."],"zh":["馆里可能按预约情况提前关门，或因比赛关闭。临时去之前打 (608) 262-8244 按 2 确认。","Badger 橄榄球主场日（10/24、11/7）只开 7:45–12:00。","放号当天早上 7:45 用手机订：学生能提前 3 天订。"]}},"src":[["Rec Well – Nielsen Tennis Stadium","https://recwell.wisc.edu/locations/nielsen/"],["Rec Well – Tennis (court reservations and fees)","https://recwell.wisc.edu/tennis/"],["Rec Well – Member Services (equipment checkout)","https://recwell.wisc.edu/memberservices/"]],"unv":[],"chk":"2026-10-08","lat":43.079669,"lng":-89.430276,"stops":[["Highland at Marsh",100,"C J 28 38"],["Marsh at Highland",104,"80"],["Marsh at Lot 76",114,"65 80"]]},{"id":"outdoor-uw","cat":"fitness","n":{"en":"Outdoor UW (Memorial Union)","zh":"Outdoor UW 户外装备租赁 (Memorial Union)"},"kind":{"en":"Outdoor gear rentals","zh":"户外装备租赁"},"addr":"800 Langdon St, Madison, WI 53706","phone":"(608) 262-1630","web":"https://union.wisc.edu/events-and-activities/outdoor-uw","h":{"Mo":[],"Tu":[],"We":[[630,1080]],"Th":[[630,1080]],"Fr":[[630,1080]],"Sa":[[630,1080]],"Su":[[630,1080]]},"ht":{"en":"As posted in October 2026: Wed–Sun 10:30 a.m.–6 p.m., closed Mon and Tue. Lake paddling follows the UW Lifesaving Station's fall schedule, which runs to Oct 25 (10 a.m.–5:30 p.m. on Oct 21–25). Rentals can be off for severe weather or private groups.","zh":"2026 年 10 月官网：周三到周日 10:30–18:00，周一、周二不开。湖上划船跟着 UW Lifesaving 救生站的秋季时间走，排到 10/25（10/21–25 为 10:00–17:30）。恶劣天气或有私人团体时可能不出租。"},"sum":{"en":"Memorial Union desk that rents kayaks, canoes, paddleboards, camping and winter gear. UW students pay $15 an hour for a one-person craft.","zh":"Memorial Union 里的租赁台：皮划艇、独木舟、桨板、露营和冬季装备。学生单人艇 $15/小时。"},"kw":["Outdoor UW","Memorial Union","kayak","canoe","paddleboard","SUP","camping gear","rental","Lake Mendota","snowshoes","ice skates","Wisconsin Union","皮划艇","独木舟","桨板","租装备","露营","户外"],"sec":{"about":{"en":["Outdoor UW is the Wisconsin Union's outdoor desk, on the lower level of Memorial Union across from Mendota Lodge. It rents canoes, kayaks and stand-up paddleboards for Lake Mendota, camping, hiking and climbing gear all year, and snowshoes and ice skates in winter. It also runs short outdoor classes.","Outdoor UW is also the home of the Wisconsin Hoofers outdoor clubs. Community members can rent too, at slightly higher prices."],"zh":["Outdoor UW 是 Wisconsin Union 的户外装备台，在 Memorial Union 地下一层，正对 Mendota Lodge。全年租露营、徒步、攀岩装备，租 Lake Mendota 上用的皮划艇、独木舟和桨板 (SUP)，冬天租雪鞋和冰鞋，还开户外入门课。","Wisconsin Hoofers 户外社团也设在这里。校外的人也能租，价格比学生贵一点。"]},"offers":{"en":["Paddle rentals on Lake Mendota: one- and two-person kayaks, canoes, stand-up paddleboards, and an 8-person board called the SUPSquatch","Camping, hiking and climbing gear all year: tents, sleeping bags and pads, backpacks, stoves, cook sets, coolers, climbing helmets and shoes","Winter rentals (seasonal, weather dependent): snowshoes and ice skates for Lake Mendota; the main page also lists nordic skis","Outdoor Explorer Series classes for beginners (canoeing, car camping, fire building) and Wilderness First Responder courses","Staff will show you how to use any piece of gear you rent"],"zh":["Lake Mendota 上的桨类租赁：单人/双人皮划艇、独木舟、桨板，还有 8 人桨板 SUPSquatch","全年租露营、徒步、攀岩装备：帐篷、睡袋、防潮垫、背包、炉子、炊具、冷藏箱、攀岩头盔和鞋","冬季租雪鞋和冰鞋（看季节和天气），主页还列了越野滑雪板 (nordic skis)","Outdoor Explorer Series 入门课（独木舟、车载露营、生火）和荒野急救 (Wilderness First Responder) 课程","租什么都可以请工作人员现场示范怎么用"]},"howto":{"en":["Paddling: reserve through the Rent With Us link on the paddling page, or walk in; walk-ins are first come, first served. Call (608) 262-1630 for groups.","Camping gear: fill out the online rental request. Staff confirm by email with an invoice; pay before pickup, sign the waiver at pickup, and return gear during office hours.","Bring money and your ID for any rental. Renters must be 18+; for paddle craft, 16–17 year olds need a guardian-signed waiver.","Life jackets must be worn on the water. Be back 15 minutes before the Lifesaving Station closes.","Paddle craft go out only on green-flag days when UW Lifesaving is open. A north wind over 12 mph also closes paddling."],"zh":["划船：在桨类租赁页点 Rent With Us 预约，或直接去柜台（先到先得）；团体请打 (608) 262-1630。","露营装备：先在网上填租赁申请，工作人员邮件确认并发账单；取装备前付款，取时签免责声明，营业时间内归还。","任何租赁都带钱和证件。租借人须满 18 岁；桨类 16–17 岁要监护人签免责声明。","水上必须穿救生衣；救生站关门前 15 分钟要回到岸上。","只在 UW Lifesaving 升绿旗时出租桨类；北风超过 12 英里/时也不出租。"]},"cost":{"en":["Paddling is charged by the hour per craft, not per person. UW–Madison students pay $15 for a one-person kayak, canoe or SUP and $20 for a two-person craft; non-students $18 and $22. SUPSquatch $50.","Camping gear, weekend (Fri–Tue) / week: tent $20 / $25, sleeping bag $15 / $20, sleeping pad $8 / $10, backpack $15 / $20, stove $15 / $20.","Winter: snowshoes $8 an hour or $15 a day; ice skates $5 an hour for students, $7 for non-students.","Wisconsin Union members get 10% off paddling on Thursdays. Cancel at least 24 hours ahead for a refund; late and damage fees apply."],"zh":["桨类按小时、按船收费，不按人头。UW 学生单人艇 $15、双人艇 $20；非学生 $18、$22。8 人桨板 $50。","露营装备，周末（周五到周二）/ 整周：帐篷 $20 / $25，睡袋 $15 / $20，防潮垫 $8 / $10，背包 $15 / $20，炉子 $15 / $20。","冬季：雪鞋 $8/小时或 $15/天；冰鞋学生 $5/小时，非学生 $7。","Wisconsin Union 会员周四划船九折。提前 24 小时取消才退款；逾期和损坏要罚款。"]},"tips":{"en":["Fall paddling is ending. UW Lifesaving's posted schedule is Wed–Sun 10:30 a.m.–6 p.m. through Oct 18 and 10 a.m.–5:30 p.m. on Oct 21–25. Expect rentals to stop after Oct 25.","New to paddling? Stay near the mooring field. The recommended paddle area is between Picnic Point and Tenney Park.","Paddling to Picnic Point is a popular trip. You may beach on the sandy areas on the north side, but not tie boats to trees.","Weekend camping rentals run Friday to Tuesday; in the off-season they stretch to Wednesday because office hours are shorter.","Never paddled? Staff teach the basic strokes when you rent a canoe."],"zh":["秋季划船快结束了：救生站公布的时间是周三到周日，到 10/18 为 10:30–18:00，10/21–25 为 10:00–17:30；预计 10/25 之后停租。","新手留在系泊区附近；建议划行范围在 Picnic Point 和 Tenney Park 之间。","划到 Picnic Point 是常见玩法：北侧沙滩可以靠岸，但不能把船拴在树上。","露营装备周末租期是周五到周二；淡季办公时间短时延到周三。","没划过也行，租独木舟时工作人员会教基本划法。"],"exp":["2026-10-25",null,null,null,null]},"intl":{"en":["The rental liability waiver comes in English, Spanish and Mandarin."],"zh":["租赁免责声明有英文、西班牙文和中文（普通话）版本。"]}},"src":[["Wisconsin Union – Outdoor UW","https://union.wisc.edu/events-and-activities/outdoor-uw"],["Outdoor UW – About (hours, contact, location)","https://union.wisc.edu/events-and-activities/outdoor-uw/aboutouw"],["Outdoor UW – Equipment Rentals","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoor-rentals"],["Outdoor UW – Paddling Rentals","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoor-rentals/paddling-rentals"],["Outdoor UW – Camping, Hiking and Climbing Rentals","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoor-rentals/camping-and-hiking-rentals"],["Outdoor UW – Winter Rentals","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoor-rentals/winter-rentals"],["Outdoor UW – Rental Policies and Forms","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoor-rentals/policies-and-forms"],["Outdoor UW – Outdoor Explorer Series","https://union.wisc.edu/events-and-activities/outdoor-uw/outdoorexplorerseries"],["UWPD Lake Rescue & Safety – 2026 Hours of Operation","https://uwpd.wisc.edu/services/lake-rescue-safety/"],["Lakeshore Nature Preserve – Recreational Opportunities","https://lakeshorepreserve.wisc.edu/recreational-opportunities/"]],"unv":[],"chk":"2026-10-08","lat":43.07652,"lng":-89.4003,"stops":[["Langdon at N Park",66,"80 82"],["N Park at State",214,"81"],["N Lake at Langdon",276,"80 82"]]},{"id":"wisconsin-hoofers","cat":"fitness","n":{"en":"Wisconsin Hoofers","zh":"Wisconsin Hoofers 户外社团"},"kind":{"en":"Outdoor clubs","zh":"户外运动社团"},"addr":"800 Langdon St, Madison, WI 53706","phone":"(608) 262-1630","web":"https://www.hoofers.org/","h":null,"ht":{"en":"No fixed hours: each club meets on its own schedule (see the club sites and the events calendar). For questions, the Outdoor UW desk in the lower level of Memorial Union is open Wed–Sun 10:30 a.m.–6 p.m. as posted in October 2026.","zh":"没有固定开放时间：各俱乐部按自己的日程开会、出行（见各俱乐部网站和活动日历）。有问题可去 Memorial Union 地下一层的 Outdoor UW 柜台，2026 年 10 月官网写的是周三到周日 10:30–18:00。"},"sum":{"en":"Six outdoor clubs: sailing, outing, mountaineering, ski and snowboard, scuba, riding. UW students are already Union members, so you can join.","zh":"六个户外社团：帆船、户外、攀岩、滑雪、潜水、骑马。UW 学生自动是 Union 会员，可直接加入。"},"kw":["Hoofers","Wisconsin Hoofers","sailing","outing club","mountaineering","ski and snowboard","scuba","horseback riding","Memorial Union","Wisconsin Union","社团","帆船","攀岩","滑雪","潜水","骑马","户外"],"sec":{"about":{"en":["Wisconsin Hoofers is one of UW–Madison's oldest and largest student organizations, with more than 2,000 members. It has run outdoor instruction and trips since 1931. Its six clubs are Mountaineering, Outing, Riding, Sailing, SCUBA, and Ski and Snowboard.","Hoofers is student-led, and Wisconsin Union members can join any of the six clubs, so you will meet community members too. It is based at Outdoor UW in the lower level of Memorial Union."],"zh":["Wisconsin Hoofers 是 UW–Madison 历史最久、规模最大的学生组织之一，有 2000 多名成员，1931 年起就在组织户外教学和出游。下设 6 个俱乐部：登山攀岩 (Mountaineering)、户外 (Outing)、骑马 (Riding)、帆船 (Sailing)、潜水 (SCUBA)、滑雪板 (Ski and Snowboard)。","Hoofers 由学生主导，Wisconsin Union 会员也能加入任意一个俱乐部，所以会遇到校外成员。总部设在 Memorial Union 地下一层的 Outdoor UW。"]},"offers":{"en":["Sailing Club: lessons and boat use on Lake Mendota, with one of the biggest inland fleets in the US (dinghies, windsurfing boards, scows, keelboats)","Outing Club: backpacking, paddling, mountain biking, fly fishing and winter trips; club gear is available to members","Mountaineering Club: socials, clinics and trips (Devil's Lake, Red River Gorge), a gear locker, and discounts at the climbing wall in the Sett","Ski and Snowboard Club: weekly lessons and trips to Tyrol Basin, winter break trips, and the Jackson Hole spring break trip","SCUBA Club: year-round trips, training and socials, for certified and not-yet-certified divers","Riding Club: horseback riding lessons and schooling shows for beginners to advanced riders","Events and trips are posted on members.hoofers.org, where you sign up and pay"],"zh":["帆船俱乐部：在 Lake Mendota 上课、用船，船队是美国内陆数一数二的大（小艇、帆板、scow、龙骨艇）","户外俱乐部 (Outing)：背包徒步、划船、山地车、飞钓和冬季活动，可用俱乐部装备","登山攀岩俱乐部：社交、培训和出行（Devil's Lake、Red River Gorge），有装备库，Sett 攀岩墙有折扣","滑雪板俱乐部：每周课程和 Tyrol Basin 出行、寒假出行，以及春假 Jackson Hole 之旅","潜水俱乐部：全年出行、培训和聚会，有证没证的都能参加","骑马俱乐部：从新手到高级的骑马课和 schooling shows","活动和出行都在 members.hoofers.org 报名付款"]},"howto":{"en":["Pick a club and create an account at members.hoofers.org. You must be a Wisconsin Union member; UW–Madison students are granted Union membership automatically.","Buy the club membership in the portal (join as many clubs as you like), then sign up for events and trips there.","Clubs hold kickoff meetings during the year. The Sailing Club also takes sign-ups at the Outdoor Programs Office in Memorial Union during business hours, (608) 262-1630."],"zh":["在 members.hoofers.org 选俱乐部并建账号。必须是 Wisconsin Union 会员；UW–Madison 学生自动就是。","在系统里买俱乐部会员（想加几个都行），然后在同一处报活动和出行。","各俱乐部全年有 kickoff 会；帆船俱乐部也可到 Memorial Union 的 Outdoor Programs Office 现场报名，(608) 262-1630。"]},"cost":{"en":["UW–Madison students are Union members automatically, so there is no Union fee. Everyone else buys a Wisconsin Union annual membership for $55.","Sailing Club dues for students: fall term (Aug 15–Dec 31) $149, of which an $80 work-hour deposit is refundable by volunteering (net $69); first-semester trial $75 ($35 net); annual $299.","Outing Club: lessons are free and most equipment use is included. Trips cost gas, food and camping; the Oct 9–11 Pictured Rocks backpacking weekend is $125.","Dues for the other clubs were not on the public pages; check members.hoofers.org or each club's site."],"zh":["UW–Madison 学生自动是 Union 会员，不用另付；其他人买 Wisconsin Union 年度会员 $55。","帆船俱乐部学生会费：秋季学期 (8/15–12/31) $149，其中 $80 工时押金做志愿可退，实付 $69；首学期试用 $75（退押金后 $35）；全年 $299。","户外俱乐部：课程免费，大部分装备含在会费里，出行只付油费、伙食、营地费；10/9–11 Pictured Rocks 背包行 $125。","其他俱乐部的会费没在公开页面找到，请到 members.hoofers.org 或各俱乐部网站查。"]},"tips":{"en":["Most sailors start from zero: the Sailing Club says the vast majority of its members learned to sail there, with lessons from absolute beginner level up.","Sailing follows the lake. UW Lifesaving's posted fall schedule runs to Oct 25, and sailors must pass a rating test to sail under windier flags.","Signed up for something and unsure where to go? The Outdoor UW desk in Memorial Union can point you the right way."],"zh":["多数人是从零开始学帆船：帆船俱乐部说绝大多数成员是在这里学会的，从零基础到高级课程都有。","帆船季跟着湖走：救生站公布的秋季时间排到 10/25；风大的旗色下要通过评级 (rating) 才能出航。","报了活动但不知道去哪？去 Memorial Union 的 Outdoor UW 柜台问。"]},"intl":{"en":["No US outdoor experience needed: students are Union members automatically, and the clubs teach beginners.","Sailing Club work-hour refunds come as a check mailed to your address in 4–6 weeks, not back to your card. Redeem them before you leave Madison."],"zh":["不需要美国户外经验：学生自动是 Union 会员，各俱乐部都教新手。","帆船俱乐部的工时押金退款是寄支票（4–6 周），不退到银行卡；离开麦迪逊前要办好。"]}},"src":[["Wisconsin Hoofers – home","https://www.hoofers.org/"],["Wisconsin Hoofers – Clubs","https://www.hoofers.org/clubs"],["Wisconsin Union – Wisconsin Hoofers","https://union.wisc.edu/events-and-activities/outdoor-uw/wisconsin-hoofers"],["Outdoor UW – About (hours, contact, location)","https://union.wisc.edu/events-and-activities/outdoor-uw/aboutouw"],["Hoofers member portal – Purchase membership","https://members.hoofers.org/finance/membership/club?id=2"],["Hoofer Sailing Club – Membership","https://www.hoofersailing.org/membership"],["UWPD Lake Rescue & Safety – 2026 Hours of Operation","https://uwpd.wisc.edu/services/lake-rescue-safety/"]],"unv":[],"chk":"2026-10-08","lat":43.07652,"lng":-89.4003,"stops":[["Langdon at N Park",66,"80 82"],["N Park at State",214,"81"],["N Lake at Langdon",276,"80 82"]]},{"id":"college-library","cat":"study","n":{"en":"College Library","zh":"College 图书馆"},"kind":{"en":"Undergraduate library","zh":"本科生图书馆"},"addr":"600 N Park St, Madison, WI 53706","phone":"(608) 262-3245","web":"https://www.library.wisc.edu/college/","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1260]],"Sa":[[660,1260]],"Su":[[660,1440]]},"ht":{"en":"Fall semester (Sept 20–Dec 17, 2026): open 24 hours from Sunday 11 a.m. straight through to Friday 9 p.m.; Saturday 11 a.m.–9 p.m. Between midnight and 7 a.m. a valid UW–Madison ID is required. Closed Thanksgiving Thursday; open 24 hours every day Dec 11–16.","zh":"2026 秋季学期（9/20–12/17）：周日 11:00 开门，一直开到周五 21:00，中间 24 小时不关；周六 11:00–21:00。0:00–7:00 进馆要出示 UW–Madison 证件。感恩节周四闭馆；期末 12/11–12/16 每天 24 小时开。"},"sum":{"en":"Undergrad library in Helen C. White Hall, open around the clock from Sunday 11 a.m. to Friday 9 p.m. this fall. UW ID needed after midnight.","zh":"本科生图书馆，秋季周日 11:00 到周五 21:00 全天开放，午夜后要出示学校证件。"},"kw":["College Library","24-hour library","24小时图书馆","study overnight","通宵自习","InfoLab","computer lab","机房","Helen C. White","printing","打印","undergraduate library","本科生图书馆","group study room","Open Book Café"],"sec":{"about":{"en":["College Library is in Helen C. White Hall. The library says undergraduate students are its primary focus. It has the Open Book Café, a computer lab (InfoLab), digital-media and active-learning spaces, and several student services that offer drop-in help.","It runs 24-hour service five nights a week during the semester, Sunday night through Thursday night. When it is open overnight, you must show a valid UW–Madison ID to enter or use the library between midnight and 7 a.m."],"zh":["College 图书馆在 Helen C. White Hall 里，官方说法是以服务本科生为主。里面有 Open Book Café、机房 (InfoLab)、数字媒体和互动教室，还有几个可以直接去问的学生服务点。","学期里每周有五个晚上通宵开放：周日晚到周四晚。通宵开放时，午夜 0:00 到早上 7:00 进馆或使用都要出示有效的 UW–Madison 证件。"]},"offers":{"en":["Study space open around the clock from Sunday 11 a.m. to Friday 9 p.m. this fall","Group study areas where talking is fine: center areas on floors 1–3, Room 1250 and the Open Book Café, Room 2250 (Computer Lab), Room 3250 (WisCEL)","Quiet areas: Room 2191 and the north half of Room 3191; the south half of Room 3191 is silent","Computer Lab (InfoLab), Room 2250 on the 2nd floor: general-access computers, scanners, video-editing stations, a voice-recording booth and a large group study room (2258)","Reservable private group study rooms and a recording booth (Room 2256) through the online reservation system","Equipment checkout: laptops, video and still cameras, projectors, cables, power strips","Drop-in student services on the first floor, including a Writing Center satellite on Sunday to Wednesday evenings","Open Book Collection: borrow board games and video games for 14 days","Large-format poster printing, up to 43 inches wide"],"zh":["秋季从周日 11:00 到周五 21:00 全天开放的自习空间","可以说话的讨论区：一到三楼的中心区域、1250 室和 Open Book Café、2250 室（机房）、3250 室 (WisCEL)","安静区：2191 室和 3191 室北半边；3191 室南半边完全不能说话","二楼 2250 室机房 (InfoLab)：公用电脑、扫描仪、视频剪辑工位、录音间，还有 2258 大讨论室","可以在线预约的私密小组讨论室和录音间（2256 室）","设备外借：笔记本、摄像机、相机、投影仪、线材、插线板","一楼有几个可以直接去问的学生服务点，其中有 Writing Center 的周日到周三晚间驻点","Open Book 收藏：可借桌游和电子游戏，借期 14 天","大幅面海报打印，最宽 43 英寸"]},"howto":{"en":["Walk in any time it is open. Between midnight and 7 a.m., carry your Wiscard or another valid UW–Madison ID; it is required to enter or use the library.","Color printers are in the 1st-floor center area and the Computer Lab (Room 2250). Pay for printing with your Wiscard account or a Print Account.","To print from your own laptop, tablet or phone, first add the library printer queue to your device (wireless printing).","Printers default to single-sided, so choose double-sided in print preferences. The computer lab has a separate duplex queue.","Computer lab desk hours for equipment checkout, poster printing and tech help: Mon–Thu 8 a.m.–11 p.m., Fri 8 a.m.–9 p.m., Sat 11 a.m.–9 p.m., Sun 11 a.m.–11 p.m. At other times ask at the first-floor Information Desk.","Reserve a small group study room or the recording booth in the online group study room reservation system."],"zh":["开门时间直接进。0:00–7:00 进馆要带学生证 (Wiscard) 或其他有效的 UW–Madison 证件，没有不让进也不让用。","彩色打印机在一楼中心区域和 2250 室机房。打印用 Wiscard 账户或 Print Account 付费。","想用自己的笔记本、平板或手机打印，要先把图书馆打印机队列加到设备里（无线打印）。","打印机默认单面，双面要在打印设置里选；机房有专门的双面打印队列。","机房柜台（设备外借、海报打印、技术支持）的有人值守时间：周一到周四 8:00–23:00，周五 8:00–21:00，周六 11:00–21:00，周日 11:00–23:00。其他时间去一楼 Information Desk 问。","小组讨论室和录音间都在在线预约系统里订。"]},"cost":{"en":["Printing is 7¢ per side in black and white and 60¢ per side in color (first-floor center and Room 2250). Color 11 x 17 prints cost $1.25 per side.","No fee for adding money to a Wiscard Print Account.","Poster printing is $4.00 per square foot with a $4.00 minimum.","Visitors who are not with UW can get a guest print card at the 1st-floor Info Desk and add money with a credit card.","Lab computers and software are licensed for UW–Madison students, faculty and staff."],"zh":["打印黑白每面 7 美分，彩色（一楼中心区和 2250 室）每面 60 美分；11 x 17 彩色每面 $1.25。","给 Wiscard Print Account 充值不收手续费。","海报打印每平方英尺 $4.00，最低收费 $4.00。","不属于 UW 的访客可以在一楼 Info Desk 拿访客打印卡，用信用卡充值。","机房的电脑和软件只授权给 UW–Madison 的学生、教职工。"]},"tips":{"en":["It closes Friday at 9 p.m. and Saturday at 9 p.m. and reopens Sunday at 11 a.m., so plan all-nighters for Sunday through Thursday.","Finals: open 24 hours every day Dec 11–16. Thanksgiving Thursday it is closed.","The hours page links to 'How busy is College Library?'. Check it before you head over on a crowded night.","The computer lab is a collaborative space with no limit on talking, and food and drink are allowed. For focus, use Room 2191 or Room 3191.","To reach the main Writing Center (6171), use the Helen C. White door to the left of College Library's entrance. You cannot get there from inside College Library.","In 2025 the library lent Wisconsin state park day passes to Wiscard holders (one vehicle with Wisconsin plates) and ran out by April. Ask the desk if it comes back."],"zh":["周五和周六都是 21:00 关门，周日 11:00 才再开，所以通宵最好安排在周日到周四。","期末 12/11–12/16 每天 24 小时开；感恩节周四不开。","馆里的开放时间页面有个「How busy is College Library?」链接，晚上人多的时候先看一眼再去。","机房是讨论空间，说话不限，也能吃喝；要专心就去 2191 室或 3191 室。","去主 Writing Center (6171 室) 要走 College Library 入口左边的 Helen C. White 大门，从 College Library 里面进不去。","2025 年图书馆借过威斯康星州立公园一日通行证给 Wiscard 持有人（一辆威州牌照的车），4 月就发完了。想要的话问问柜台有没有再开。"]},"intl":{"en":["Your Wiscard is your library card at every campus library. Carry it for the overnight check, too."],"zh":["学生证 (Wiscard) 就是所有校园图书馆的借书证；夜里被查证件时也是它。"]}},"src":[["College Library – Library Hours","https://www.library.wisc.edu/college/about-college/library-hours/"],["College Library – Study Spaces","https://www.library.wisc.edu/college/spaces/study/"],["College Library – Computer Lab","https://www.library.wisc.edu/college/services-at-college/computer-lab/"],["Services at College Library","https://www.library.wisc.edu/college/services-at-college/"],["College Library – Print / Copy / Scan","https://www.library.wisc.edu/college/services-at-college/print-copy-scan"],["UW-Madison Libraries – Printing & Photocopies","https://www.library.wisc.edu/locations/printing"],["UW–Madison IT – Printing for students","https://it.wisc.edu/services/printing-for-students/"],["UW-Madison Writing Center – Make a Writing Appointment","https://writing.wisc.edu/make-a-writing-appointment/"],["College Library – Check Out a State Park! (Feb 2025)","https://www.library.wisc.edu/college/2025/02/20/check-out-a-state-park/"],["UW-Madison Libraries – Borrowing policies for undergraduates","https://www.library.wisc.edu/borrow-request/borrowing-policies/uw-madison-undergraduate-students/"]],"unv":[],"chk":"2026-10-08","lat":43.076685,"lng":-89.401312,"stops":[["Langdon at N Park",126,"80 82"],["Observatory at Bascom",206,"80 82"],["N Park at State",241,"81"]]},{"id":"doit-help-desk","cat":"study","n":{"en":"DoIT Help Desk","zh":"DoIT 技术帮助台 (Help Desk)"},"kind":{"en":"IT help desk","zh":"IT 技术支持"},"addr":"1210 W Dayton St, Madison, WI 53706","phone":"(608) 264-4357","web":"https://it.wisc.edu/services/help-desk/","h":{"Mo":[[465,1020]],"Tu":[[465,1020]],"We":[[465,1020]],"Th":[[465,1020]],"Fr":[[465,1020]],"Sa":[],"Su":[]},"ht":{"en":"In person (Computer Sciences building, 1210 W. Dayton St.): Mon–Fri 7:45 a.m.–5 p.m. Phone and email help is 7 a.m.–11 p.m. every day and live chat 8 a.m.–10 p.m. every day, except some holidays and breaks.","zh":"现场（Computer Sciences 楼，1210 W. Dayton St.）：周一到周五 7:45–17:00。电话和邮件支持每天 7:00–23:00，在线聊天每天 8:00–22:00（个别节假日和假期除外）。"},"sum":{"en":"Free IT help for UW students: NetID and Duo problems, virus checks, software, laptop loans. Walk in on weekdays at 1210 W. Dayton St.","zh":"免费 IT 帮助：NetID/Duo 问题、杀毒、软件、借笔记本；工作日可去 1210 W. Dayton St 现场。"},"kw":["DoIT","Help Desk","IT help","NetID","Duo","password reset","laptop loan","computer lending","virus removal","Tech Store","技术支持","重置密码","借笔记本","杀毒","Dayton St"],"sec":{"about":{"en":["The DoIT Help Desk is campus IT help for UW–Madison students, faculty and staff. It has one walk-in site, in the Computer Sciences building at 1210 W. Dayton St. Use the Dayton Street entrance; the desk is through the first doorway on the right.","The DoIT Tech Store that sold computers at this address closed in 2019. For a personal laptop, UW's IT site points students to the UW Bookstore Tech Center and to manufacturers' education pricing."],"zh":["DoIT Help Desk 是学校的 IT 帮助台，学生、教职工都能用。现场只有一处，在 Computer Sciences 楼（1210 W. Dayton St.）。走 Dayton Street 一侧的入口，第一个门洞往右就是。","以前在这个地址卖电脑的 DoIT Tech Store 已在 2019 年关门。想买自用笔记本，学校 IT 网站指的是 UW Bookstore Tech Center，以及各厂商的教育优惠。"]},"offers":{"en":["Walk-in help with most computer problems, plus immediate help resetting a NetID password and recovering or re-activating Duo","Free virus checks and removal","Free operating-system re-installs for students' personal devices; limited data transfer","Duo/MFA tokens and equipment checkout at the desk","Computer Lending Program: semester-long Dell or Apple laptops and week-long Verizon hot spot loans, first come, first served","Phone, email and chat help seven days a week (phone 608-264-4357)","No-charge campus software through the Campus Software Library, plus Microsoft 365 and Adobe Creative Cloud"],"zh":["现场帮你处理大多数电脑问题，还能当场重置 NetID 密码、恢复或重新激活 Duo","免费查杀病毒","免费为学生的个人设备重装操作系统；有限的数据转移服务","柜台可领 Duo/MFA 令牌 (token)，也能借设备","电脑出借项目 (Computer Lending Program)：整学期借 Dell 或 Apple 笔记本，一周借 Verizon 热点，先到先得","电话、邮件、在线聊天每天都有人（电话 608-264-4357）","校园软件库 (Campus Software Library) 的软件免费用，另外还有 Microsoft 365 和 Adobe Creative Cloud"]},"howto":{"en":["Walk in at 1210 W. Dayton St. on weekdays, 7:45 a.m.–5 p.m. You need a valid NetID.","By phone (608-264-4357), press 1 for NetID or Duo, or 3 for Learn@UW, Microsoft 365, campus internet and general computer problems.","The Help Desk cannot reset passwords or give out your NetID by email or chat. Call or visit in person.","To borrow a laptop or hot spot you need an active NetID and Wiscard. There are no reservations, so call ahead or ask at the desk to see what is in stock.","Get campus software from the Campus Software Library (login with your NetID; you need an active Wiscard)."],"zh":["工作日 7:45–17:00 直接去 1210 W. Dayton St.，要有有效的 NetID。","打电话 608-264-4357：按 1 处理 NetID 或 Duo，按 3 处理 Learn@UW、Microsoft 365、校园网络和一般电脑问题。","密码重置和查 NetID 不能通过邮件或聊天，必须打电话或到现场。","借笔记本或热点要有有效的 NetID 和 Wiscard。不接受预约，可以先打电话或到柜台问有没有货。","校园软件到 Campus Software Library 下载（用 NetID 登录，还要有有效的 Wiscard）。"]},"cost":{"en":["Help Desk support is free for UW students.","Virus removal and operating-system re-installs for personal devices are free.","The Help Desk can diagnose hardware problems and give repair options. DoIT's facilitated Dell and Apple repair covers departmentally owned computers.","Campus Software Library titles are no charge with a NetID and an active Wiscard.","Computer discounts come from manufacturers and stores such as Apple, Dell and Best Buy. Expect to verify your student status, often with a .edu email address."],"zh":["Help Desk 的支持对 UW 学生免费。","个人设备查杀病毒、重装系统都免费。","硬件问题 Help Desk 可以帮你诊断并给出维修选择。DoIT 代办的 Dell 和 Apple 维修只限学院、部门名下的电脑。","校园软件库里的软件用 NetID 加有效 Wiscard 就免费。","买电脑的优惠来自厂商和商店，比如 Apple、Dell、Best Buy。一般要验证学生身份，常用 .edu 邮箱。"]},"tips":{"en":["The desk is closed on weekends. Use phone or chat then.","Email replies can take up to 24 hours. If it is urgent, call.","The Tech Store is gone. For a laptop with education pricing, use the bookstore tech center or a manufacturer's education store, not the Help Desk.","Need a computer for a few hours? Libraries and the Help Desk lend laptops and other equipment.","The Help Desk gives best-effort support for nearly any IT issue, even outside DoIT services."],"zh":["周末现场不开，用电话或在线聊天。","邮件回复最多可能要等 24 小时，着急就打电话。","Tech Store 已经没有了。想用教育优惠买笔记本，去书店的 Tech Center 或厂商教育商店，别找 Help Desk。","只想借台电脑用几个小时？图书馆和 Help Desk 都有笔记本和其他设备可借。","几乎任何 IT 问题 Help Desk 都会尽力帮，不限于 DoIT 自己的服务。"]},"intl":{"en":["If you lose access to your Duo device, the Help Desk can recover or re-activate it right away at the desk."],"zh":["Duo 设备用不了了（丢手机、换手机），可以到柜台当场恢复或重新激活。"]}},"src":[["UW–Madison IT – Help Desk","https://it.wisc.edu/services/help-desk/"],["DoIT Help Desk Knowledgebase – Get Help from DoIT","https://kb.wisc.edu/helpdesk/1"],["UW–Madison IT – Repair","https://it.wisc.edu/services/repair/"],["UW–Madison IT – Computer lending program","https://it.wisc.edu/services/computer-lending-program/"],["UW–Madison IT – Software","https://it.wisc.edu/services/software/"],["UW–Madison IT – Computers & equipment for students","https://it.wisc.edu/learn/computers-equipment-students-what-do-i-need/"],["UW–Madison IT – Tech purchasing guide","https://it.wisc.edu/learn/tech-purchasing-guide/"],["Working at UW – DoIT announces changes to Tech Store, services (May 8, 2019)","https://working.wisc.edu/?p=5245"],["Working at UW – Final Markdowns at DoIT Tech Store, Help Desk Support Continues (May 29, 2019)","https://working.wisc.edu/?p=5299"]],"unv":[],"chk":"2026-10-08","lat":43.071559,"lng":-89.406707,"stops":[["Orchard",68,"A F"],["W Dayton at N Orchard",72,"80"],["W Johnson at N Orchard",116,"C D J O R"]]},{"id":"ebling-library","cat":"study","n":{"en":"Ebling Library","zh":"Ebling 健康科学图书馆"},"kind":{"en":"Health sciences library","zh":"健康科学图书馆"},"addr":"750 Highland Ave, Madison, WI 53705","phone":"(608) 262-2020","web":"https://ebling.library.wisc.edu/","h":{"Mo":[[540,1140]],"Tu":[[540,1140]],"We":[[540,1140]],"Th":[[540,1140]],"Fr":[[540,1020]],"Sa":[],"Su":[]},"ht":{"en":"Fall 2026, open to everyone: Mon–Thu 9 a.m.–7 p.m., Fri 9 a.m.–5 p.m. The general public is served on weekdays only. Students in the Schools of Medicine and Public Health, Nursing, Pharmacy and Veterinary Medicine have 24/7/365 badge access with a Wiscard.","zh":"2026 秋季，对所有人开放：周一到周四 9:00–19:00，周五 9:00–17:00，公众只在工作日服务。医学与公共卫生、护理、药学、兽医四个学院的学生可以用学生证 (Wiscard) 刷卡全年 24 小时进馆。"},"sum":{"en":"Health sciences library in the HSLC on Highland Ave. Open weekdays to all; medicine, nursing, pharmacy and vet students get 24/7 badge access.","zh":"Highland Ave 上的健康科学图书馆，工作日人人可用；医、护、药、兽医学生可刷卡 24 小时进。"},"kw":["Ebling Library","health sciences library","HSLC","medical library","nursing","pharmacy","veterinary","健康科学图书馆","医学图书馆","护理","药学","兽医","自习","24小时刷卡"],"sec":{"about":{"en":["Ebling Library is the health sciences library, inside the Health Sciences Learning Center (HSLC) at 750 Highland Avenue. It serves the Schools of Medicine and Public Health, Nursing, Pharmacy and Veterinary Medicine, and it is open to the public during the week.","Its InfoCommons computer area is spread across both library floors and is open to the whole UW–Madison community with a NetID. Some HSLC rooms, such as the 3rd-floor group study rooms, are booked through the HSLC Classroom & AV Support office, not the library."],"zh":["Ebling 是健康科学图书馆，在 Highland Avenue 750 号的 Health Sciences Learning Center (HSLC) 里。主要服务医学与公共卫生、护理、药学、兽医四个学院，工作日也对公众开放。","馆里的 InfoCommons 机房分布在两层楼，全校师生用 NetID 都能用。HSLC 里有些房间（比如三楼小组讨论室）不归图书馆管，要找 HSLC 的 Classroom & AV Support 预约。"]},"offers":{"en":["InfoCommons: iMac and Dell workstations on both floors, with NetID login","Laptop checkout (MacBook Air and Dell Latitude) plus camcorders, DSLR cameras, audio recorders and a projector","Printing, copying and scanning in two copy centers (2nd floor Room 2031A, 3rd floor Room 3332); scans go to email or a USB stick","Free outgoing fax within the US, arranged at the service desk","Exam proctoring for health sciences students (send the request form at least 7 days ahead)","Prayer and meditation room (HSLC 3367) inside the library; private rooms 2120 and 3208c, arranged through SMPH Student Services","24/7/365 badge access for students in the four health schools"],"zh":["InfoCommons：两层楼都有 iMac 和 Dell 电脑，用 NetID 登录","可借笔记本（MacBook Air 和 Dell Latitude），还能借摄像机、单反、录音设备和投影仪","两个复印中心（二楼 2031A 室、三楼 3332 室）可以打印、复印、扫描；扫描件发邮箱或存 U 盘","可以免费发美国国内传真，在服务台办理","健康科学学生的考试监考服务（至少提前 7 天交申请表）","馆内有祈祷静思室 (HSLC 3367)；2120 和 3208c 是私密房间，经 SMPH Student Services 申请使用","四个健康学院的学生可刷卡全年 24 小时进馆"]},"howto":{"en":["On weekdays, walk in during open hours. The public computers on the 2nd floor are near the service desk.","Nights and weekends, only Wiscard holders in the Schools of Medicine and Public Health, Nursing, Pharmacy or Veterinary Medicine can badge in.","There are three print stations: two on the 2nd floor and one on the 3rd. Pay with your Wiscard or a Guest Card print account; blank guest cards are at the Ebling Service Desk.","To borrow a laptop, bring your Wiscard. Your NetID must be activated, and checkout is during staffed hours.","Book HSLC rooms, including the 3rd-floor group study rooms, with Classroom & AV Support (261-1934 or reservations@hslc.wisc.edu). Ebling does not handle room reservations."],"zh":["工作日开放时间直接进。二楼的公共电脑在服务台附近。","晚上和周末只有医学与公共卫生、护理、药学、兽医学院的学生能用学生证 (Wiscard) 刷卡进。","有三台打印站：二楼两台、三楼一台。用 Wiscard 或访客打印卡 (Guest Card) 付费，空白访客卡在 Ebling Service Desk 领。","借笔记本要带学生证，NetID 必须已激活，只能在有人值守的时间借。","HSLC 的房间（包括三楼小组讨论室）找 Classroom & AV Support 预约：261-1934 或 reservations@hslc.wisc.edu。Ebling 自己不管房间预约。"]},"cost":{"en":["Black-and-white printing is 7¢ a page. Ebling's own pages put color at 50¢ a page, while the campus library printing page lists color at 60¢ a page.","Photocopying is 10¢ a page, paid with a Wiscard or Guest Card print account. Scanning is free.","The fax service is free (sending only, US only).","The library is open to the public on weekdays; the InfoCommons workstations are for current UW–Madison students, faculty and staff."],"zh":["黑白打印每页 7 美分。Ebling 自己的页面写彩色每页 50 美分，校图书馆的打印总页面写彩色 60 美分，以现场为准。","复印每页 10 美分，用 Wiscard 或访客打印卡付费；扫描免费。","传真免费（只能发，只发美国国内）。","工作日对公众开放；InfoCommons 电脑只给在读的 UW–Madison 学生和教职工用。"]},"tips":{"en":["If you are not in one of the four health schools, plan evenings and weekends elsewhere: the building has no public hours then.","Color printing is only in the 2nd-floor copy center (Room 2031A). The 3rd-floor copy center prints black and white only.","When you scan to email, type your address carefully: scans sent to a wrong address cannot be recovered. Use a wisc.edu or Gmail address, because some other providers choke on large PDFs.","Do not open Health Link or other patient records in the library. It is a public space, and UW Health policy prohibits it."],"zh":["不是这四个健康学院的学生，晚上和周末请去别的馆，这里那时不对公众开放。","只有二楼复印中心 (2031A) 有彩色打印；三楼复印中心只能黑白。","扫描发邮箱时邮箱地址要打对，发错了找不回来。最好用 wisc.edu 或 Gmail，别的邮箱容易收不下大 PDF。","别在馆里打开 Health Link 或其他病人资料：这是公共空间，UW Health 规定不能这么做。"]}},"src":[["Ebling Library – Visitor Information, Hours & Location","https://ebling.library.wisc.edu/about-us/hours-location/"],["Ebling Library – FAQ","https://ebling.library.wisc.edu/about-us/faq/"],["Ebling Library – About the InfoCommons","https://ebling.library.wisc.edu/infocommons/about-the-infocommons/"],["Ebling Library – Laptop & Equipment Checkout","https://ebling.library.wisc.edu/infocommons/laptop-equipment-checkout/"],["Ebling Library – Print/Copy/Scan/Fax","https://ebling.library.wisc.edu/infocommons/print-copy-scan-fax"],["UW-Madison Libraries – Printing & Photocopies","https://www.library.wisc.edu/locations/printing"]],"unv":[],"chk":"2026-10-08","lat":43.07775,"lng":-89.429789,"stops":[["Highland at Marsh",79,"C J 28 38 65 80 84"],["Highland at Observatory",89,"C J R 28 38 80 84"],["Marsh at Highland",117,"80"]]},{"id":"madison-public-library-central","cat":"study","n":{"en":"Madison Public Library – Central","zh":"Madison Public Library 中央馆"},"kind":{"en":"Public library","zh":"公共图书馆"},"addr":"201 W Mifflin St, Madison, WI 53703","phone":"(608) 266-6300","web":"https://www.madisonpubliclibrary.org/locations/central-library","h":{"Mo":[[540,1260]],"Tu":[[540,1260]],"We":[[540,1260]],"Th":[[540,1260]],"Fr":[[540,1080]],"Sa":[[540,1020]],"Su":[[780,1020]]},"ht":{"en":"Mon–Thu 9 a.m.–9 p.m. (Children's Room, Bubbler and Ground Floor close at 6 p.m.), Fri 9 a.m.–6 p.m., Sat 9 a.m.–5 p.m., Sun 1–5 p.m. (Labor Day to Memorial Day). No phone service on Sundays.","zh":"周一到周四 9:00–21:00（儿童区、Bubbler 和底层 18:00 关），周五 9:00–18:00，周六 9:00–17:00，周日 13:00–17:00（Labor Day 到 Memorial Day 期间）。周日不接电话。"},"sum":{"en":"Downtown city library: free first card, Bubbler art room, study rooms, a media lab, and borrowable bike passes and calculators.","zh":"市中心的市立图书馆，首张卡免费；有 Bubbler 艺术工坊、讨论室，可借自行车卡和计算器。"},"kw":["Madison Public Library","Central Library","public library","library card","图书馆卡","市立图书馆","Bubbler","art studio","study room","BCycle pass","graphing calculator","Library of Things","借物","Mifflin St"],"sec":{"about":{"en":["Central Library is Madison Public Library's downtown branch, on the Isthmus. It has the system's largest collection of meeting spaces, including 11 study rooms. Madison Public Library is a City of Madison agency, separate from the UW–Madison libraries.","You need a Madison Public Library card to borrow, and the first card is free. Besides books, the library lends bike-share passes, graphing calculators, light-therapy lamps and more."],"zh":["Central 是 Madison Public Library 在市中心（地峡 Isthmus 上）的主馆，会议和自习空间最多，有 11 间讨论室。Madison Public Library 属于市政府，和 UW–Madison 的图书馆是两套系统。","借书要办 Madison Public Library 的卡，第一张免费。除了书，这里还能借共享单车卡、图形计算器、光疗灯等东西。"]},"offers":{"en":["Books, music, film and e-books with a library card","Library of Things: BCycle bike passes and helmets, graphing calculators (Central), HappyLight lamps, disc golf kits, a portable record player and vinyl records","The Bubbler Room: a drop-in art-making space during regular hours, plus galleries on floors 1–3","Media Lab (1st floor) and the Personal Archiving Lab: digitize VHS tapes, cassettes, photos, slides and documents after a 20–30 minute tutorial","11 study rooms on floors 1 and 2, for 4 to 10 people","Public computers with Microsoft Office (3 hours a day) and free Wi-Fi with no password","Printing, copying and a free outgoing fax at the 2nd-floor Print/Copy Desk"],"zh":["有了借书证就能借书、音乐、电影和电子书","借物库 (Library of Things)：BCycle 单车卡和头盔、图形计算器（Central 有）、HappyLight 光疗灯、飞盘高尔夫套装、便携唱机和黑胶唱片","Bubbler Room：开放时间内随时可以进去做手工和艺术创作的空间；一到三楼还有展览","一楼 Media Lab 和个人档案数字化室 (Personal Archiving Lab)：上完 20–30 分钟的入门课，就能把录像带、磁带、照片、幻灯片、文件数字化","一、二楼有 11 间讨论室，可坐 4 到 10 人","公用电脑装有 Microsoft Office，每天限 3 小时；Wi-Fi 免费，不用密码","二楼 Print/Copy Desk 可以打印、复印，免费发出传真"]},"howto":{"en":["Apply at any Madison library or online. Bring a photo ID and proof of current address. An online application needs no proof of address, because the card is mailed to the address on the form.","A driver's license with your address is the easiest proof. Without one, bring a photo ID plus mail postmarked within 30 days, a current lease, or a current utility bill or bank statement. P.O. boxes do not count.","No proof of address yet? Ask for an Easy Access card (photo ID only): 3 items out and 2 holds at a time. Upgrade later with proof of address.","Study rooms: call 608-266-6300 for an advance booking (needs a library card), or ask at the desk for a walk-in room (no card needed).","To print from your laptop or phone, send the file through the library's web portal, the ePRINTit app or email, then release it and pay at a coin tower in any Madison library."],"zh":["在任何一家 Madison 公共图书馆当场办，或在线办。带照片 ID 和现住址证明。在线申请不用交地址证明，因为卡会邮寄到表上填的地址。","最简单的地址证明是带地址的驾照。没有驾照就带照片 ID，加上 30 天内邮戳的信件、现行租约，或现行水电账单、银行对账单中的任意一样。邮政信箱 (P.O. Box) 不算。","暂时没有地址证明？可以办 Easy Access 卡（只要照片 ID）：一次借 3 件、预约 2 件。以后补交地址证明再升级。","讨论室：提前订要打 608-266-6300（需要借书证）；当天直接去服务台问有没有空房（不需要借书证）。","想从电脑或手机打印：通过图书馆的网页、ePRINTit app 或发邮件把文件传上去，再到任一 Madison 图书馆的投币机 (coin tower) 取件付费。"]},"cost":{"en":["The first library card is free. One free replacement every 12 months; extra replacements cost $1.00. Full Use cards expire every 4 years.","Printing and copying are $0.10 per page in black and white and $0.50 per page in color. Print stations take credit cards (a $5 hold) and cash; most copy stations take cash only.","Sending a fax is free, but it has to be started and finished in person.","Bubbler drop-in making is free. Library of Things items are free to borrow with a card; BCycle passes are for card holders 18+, one per calendar month."],"zh":["第一张借书证免费。每 12 个月可免费补办一次，之后补卡 $1.00。Full Use 卡每 4 年到期。","打印和复印黑白每页 $0.10，彩色每页 $0.50。打印站收信用卡（会预扣 $5）和现金；大多数复印机只收现金。","发传真免费，但必须本人到场操作。","Bubbler 的随到随做手工免费。借物库的东西凭卡免费借；BCycle 卡限 18 岁以上持卡人，每个日历月一张。"]},"tips":{"en":["Sunday is short (1–5 p.m., Labor Day to Memorial Day) and nobody answers the phone that day.","Mon–Thu the Bubbler, Children's Room and Ground Floor close at 6 p.m., three hours before the rest of the building.","No credit card or smartphone for bike share? Card holders 18+ can borrow a BCycle Community Pass and a helmet for 7 days. Bikes must be docked every 60 minutes.","HappyLight lamps (10,000 lux) are first come, first served for 14 days, and no holds. Useful in the dark winter months.","A disc golf kit receipt works as a free play permit at four courses around Madison.","Personal Archiving Lab tutorials in October: Mondays 2–4 p.m. in the Media Lab on the 1st floor. On Oct 19 and 26 meet in the Local History room on the 2nd floor."],"zh":["周日开门时间短（Labor Day 到 Memorial Day 期间 13:00–17:00），而且当天没人接电话。","周一到周四 Bubbler、儿童区和底层 18:00 就关了，比主馆早 3 小时。","没有信用卡或智能手机，用不了共享单车？18 岁以上持卡人可以借 BCycle Community Pass 和头盔，借期 7 天，骑行每 60 分钟要还到桩上一次。","HappyLight 光疗灯（10,000 勒克斯）先到先得，借期 14 天，不能预约。冬天天黑得早，用得上。","借飞盘高尔夫套装的收据就是免费入场许可，在麦迪逊周边四个球场通用。","10 月个人档案数字化室入门课：每周一 14:00–16:00，在一楼 Media Lab；10/19 和 10/26 改到二楼 Local History 室。"],"exp":[null,null,null,null,null,"2026-10-26"]},"intl":{"en":["You do not need a US driver's license. Apply online and the card is mailed to your address, or show a photo ID plus a current lease as proof of address."],"zh":["不需要美国驾照。在线申请，卡会寄到你的地址；或者带照片 ID 加现行租约当地址证明。"]}},"src":[["Madison Public Library – Central Library","https://www.madisonpubliclibrary.org/locations/central-library"],["Madison Public Library – Library Card FAQ","https://www.madisonpubliclibrary.org/library-cards/get-a-card"],["Madison Public Library's Library of Things","https://www.madisonpubliclibrary.org/resources/madison-public-librarys-library-things"],["Madison Public Library – Study Rooms","https://www.madisonpubliclibrary.org/spaces/study-rooms"],["Madison Public Library – The Bubbler","https://www.madisonpubliclibrary.org/spaces/bubbler"],["The Bubbler – Central Library","https://www.madisonbubbler.org/libraries/central"],["Madison Public Library – Digitize Your Memories","https://www.madisonpubliclibrary.org/new/digitize-your-memories"],["Madison Public Library – Computers at Central","https://www.madisonpubliclibrary.org/locations/central-library/computers"],["Madison Public Library – Print, Photocopy, and Faxing Services","https://www.madisonpubliclibrary.org/resources/services/print-photocopy-and-faxing-services"]],"unv":[],"chk":"2026-10-08","lat":43.073589,"lng":-89.387534,"stops":[["W Washington at N Fairchild",92,"E 75"],["W Washington at S Carroll",171,"E 75"],["State Street",205,"A B F"]]},{"id":"memorial-library","cat":"study","n":{"en":"Memorial Library","zh":"Memorial 图书馆"},"kind":{"en":"Campus library","zh":"校园图书馆"},"addr":"728 State St, Madison, WI 53706","phone":"(608) 262-3343","web":"https://www.library.wisc.edu/memorial/","h":{"Mo":[[510,1380]],"Tu":[[510,1380]],"We":[[510,1380]],"Th":[[510,1380]],"Fr":[[510,1260]],"Sa":[[720,1260]],"Su":[[720,1380]]},"ht":{"en":"Fall semester (Sept 2–Dec 18, 2026): Mon–Thu 8:30 a.m.–11 p.m., Fri 8:30 a.m.–9 p.m., Sat noon–9 p.m., Sun noon–11 p.m. Closed Thanksgiving Thursday through Saturday. You need a UW ID to enter.","zh":"2026 秋季学期（9/2–12/18）：周一到周四 8:30–23:00，周五 8:30–21:00，周六 12:00–21:00，周日 12:00–23:00。感恩节周四到周六闭馆。进馆要出示学生证 (Wiscard)。"},"sum":{"en":"State Street library with quiet and group study areas, reservable rooms, a computer lab and printing. Open until 11 p.m. Mon–Thu.","zh":"State Street 上的图书馆：安静区、讨论区、可预约讨论室、机房和打印，周一到周四开到 23:00。"},"kw":["Memorial Library","library","study","quiet study","group study room","printing","computer lab","East Asian Reading Room","图书馆","自习","安静","讨论室","打印","机房","东亚阅览室"],"sec":{"about":{"en":["Memorial Library sits at the corner of Lake Street and State Street, facing the University Bookstore building. The library says it supports study and teaching at UW–Madison through its collections, research help and services.","Study areas are sorted by noise. Talking is fine in the group areas (the first-floor Computer Lab 140, the first- and second-floor West Corridors, Reference Reading Room 262). Reading rooms 112, 116, 212, 412 and 424, the fourth-floor West Corridor and all carrels are quiet. Room 124 is silent."],"zh":["Memorial 图书馆在 Lake Street 和 State Street 的路口，正对 University Bookstore 那栋楼。图书馆自己的说法是：用馆藏、研究咨询和各种服务支持 UW–Madison 的学习和教学。","自习区按噪音分级。可以说话的是讨论区（一楼机房 140、一二楼的 West Corridor、参考阅览室 262）；112、116、212、412、424 阅览室、四楼 West Corridor 和所有隔间 (carrel) 要安静；124 室完全不能说话。"]},"offers":{"en":["Group study areas where talking is allowed: Computer Lab (140), West Corridors on floors 1 and 2, Reference Reading Room (262)","Quiet reading rooms (112, 116, 212, 412, 424), the 4th-floor West Corridor and all carrels; Room 124 is silent","Twelve group study rooms in the South Stacks that you reserve online; quiet talking is allowed","Computer Lab (Room 140): Mac and Windows computers, laptops for checkout, color and black-and-white printing, flatbed scanners","East Asian Reading Room (412): reference books and current popular periodicals in Chinese, Japanese and Korean (they stay in the room)","Mills Music Library and Special Collections are inside the building","Food is allowed in most of the library (not the ninth floor); a vending machine is in the first-floor West Corridor"],"zh":["可以说话的讨论区：一楼机房 (140)、一二楼 West Corridor、参考阅览室 (262)","安静阅览室 (112、116、212、412、424)、四楼 West Corridor 和所有隔间；124 室禁止说话","South Stacks 里有 12 间小组讨论室，在线预约，可以小声交谈","机房 (140)：Mac 和 Windows 电脑、可借笔记本、彩色和黑白打印、平板扫描仪","东亚阅览室 (412)：参考书和一些常见的中日韩文现刊（只能在室内看）","Mills 音乐图书馆 (Mills Music Library) 和特藏部 (Special Collections) 都在这栋楼里","大部分区域可以吃东西（九楼除外）；一楼 West Corridor 有自动售货机"]},"howto":{"en":["Show your Wiscard (or another UW System ID) to the staff at the Welcome Desk to get in.","Reserve a group study room online with your NetID. One person or group can book at most 4 hours a day across all rooms.","Print at the 1st-floor stations (West Corridor, entrance lobby) or the 2nd floor (Reference Reading Room 262, West Corridor). Color printing is in the 1st-floor West Corridor Computer Lab and needs a NetID login.","Pay with Wiscard Campus Cash or a Wiscard Print Account. Add money at go.wisc.edu/print. Visitors can use a guest print card from the Circulation Desk on the 1st floor.","To print from your own laptop, set up wireless printing first (go.wisc.edu/WirelessPrinting). Printers default to single-sided, so pick double-sided in the print settings."],"zh":["进馆时在 Welcome Desk 给工作人员看学生证 (Wiscard) 或其他 UW System 的证件。","用 NetID 在线预约讨论室。同一个人或团体一天在所有讨论室加起来最多订 4 小时。","打印机在一楼（West Corridor、入口大厅）和二楼（参考阅览室 262、West Corridor）。彩色打印在一楼 West Corridor 的机房，要用 NetID 登录。","用 Wiscard Campus Cash 或 Wiscard Print Account 付费，在 go.wisc.edu/print 充值。访客可以在一楼 Circulation Desk 拿访客打印卡。","想从自己电脑打印，先设置无线打印 (go.wisc.edu/WirelessPrinting)。打印机默认单面，要双面得在打印设置里选。"]},"cost":{"en":["Printing is 7¢ per page (per side) in black and white and 60¢ per page in color, charged to your Wiscard account.","Adding money: no fee for a Wiscard Print Account; adding to Wiscard Campus Cash by credit card carries a 2% fee.","Visitors without a card can get a day pass at the Welcome Desk once every 7 days with valid ID.","Computer Lab computers and services are for UW–Madison students, faculty and staff only.","Refunds for printing problems are available."],"zh":["打印黑白每页（每面）7 美分，彩色每页 60 美分，从 Wiscard 账户里扣。","充值：Wiscard Print Account 不收手续费；用信用卡给 Wiscard Campus Cash 充值收 2%。","没有证件的访客可以在 Welcome Desk 凭有效证件拿日通行证，每 7 天一次。","机房的电脑和服务只给 UW–Madison 的学生、教职工用。","打印出问题可以申请退款。"]},"tips":{"en":["Memorial is not a 24-hour library: it closes at 11 p.m. Mon–Thu and 9 p.m. Fri and Sat. Check College Library for all-night study.","On Saturday and Sunday it opens at noon, not in the morning.","No food deliveries: the library does not allow deliveries of any kind, so meet the courier outside.","Someone loud in a quiet area? Tell the Circulation Desk on the first floor; staff can ask people to move.","The library site lets you view study spaces by volume level before you pick a room."],"zh":["Memorial 不是 24 小时馆：周一到周四 23:00 关，周五周六 21:00 关。要通宵自习请看 College Library。","周六周日中午 12:00 才开门，早上去会扑空。","不让送外卖进馆，任何配送都不行，让骑手在楼外等。","安静区有人大声说话，可以告诉一楼 Circulation Desk，工作人员会请人换地方。","图书馆网站可以按安静程度查看各个自习空间，挑房间前先看一眼。"]},"intl":{"en":["Your Wiscard is your library card at every campus library; there is no separate sign-up.","The East Asian Reading Room (412) keeps current popular Chinese, Japanese and Korean periodicals and the East Asian reference collection."],"zh":["学生证 (Wiscard) 就是所有校园图书馆的借书证，不用另外办。","东亚阅览室 (412) 有东亚参考书，还有一些常见的中日韩文现刊。"]}},"src":[["Memorial Library – Library Hours","https://www.library.wisc.edu/memorial/about-memorial/library-hours/"],["Visit Memorial Library","https://www.library.wisc.edu/memorial/about-memorial/visit-memorial-library/"],["Memorial Library – Directions & Parking","https://www.library.wisc.edu/memorial/about-memorial/directions-parking/"],["Memorial Library – Study Places","https://www.library.wisc.edu/memorial/spaces/study-places/"],["Memorial Library – Group Study Rooms","https://www.library.wisc.edu/memorial/spaces/study-places/group-study-rooms/"],["Memorial Library – Reading Rooms","https://www.library.wisc.edu/memorial/spaces/study-places/reading-rooms/"],["Memorial Library – Computer Lab (140)","https://www.library.wisc.edu/memorial/spaces/also-in-memorial/infolab-doit-140/"],["Memorial Library – General Building Rules","https://www.library.wisc.edu/memorial/about-memorial/policies/general-building-rules/"],["Memorial Library – Printing","https://www.library.wisc.edu/memorial/services/print-copy-scan/print"],["UW–Madison IT – Printing for students","https://it.wisc.edu/services/printing-for-students/"],["UW-Madison Libraries – Borrowing policies for undergraduates","https://www.library.wisc.edu/borrow-request/borrowing-policies/uw-madison-undergraduate-students/"]],"unv":[],"chk":"2026-10-08","lat":43.075022,"lng":-89.397986,"stops":[["N Lake at Langdon",86,"80 82"],["Langdon at N Lake",113,"81"],["Langdon at N Park",195,"81"]]},{"id":"steenbock-library","cat":"study","n":{"en":"Steenbock Library","zh":"Steenbock 图书馆"},"kind":{"en":"Science and engineering library","zh":"理工农医图书馆"},"addr":"550 Babcock Dr, Madison, WI 53706","phone":"(608) 262-1371","web":"https://www.library.wisc.edu/steenbock/","h":{"Mo":[[480,1410]],"Tu":[[480,1410]],"We":[[480,1410]],"Th":[[480,1410]],"Fr":[[480,1200]],"Sa":[[720,1200]],"Su":[[720,1410]]},"ht":{"en":"Fall semester (Sept 2–Dec 18, 2026): Mon–Thu 8 a.m.–11:30 p.m., Fri 8 a.m.–8 p.m., Sat noon–8 p.m., Sun noon–11:30 p.m. Closed Thanksgiving Thursday through Saturday.","zh":"2026 秋季学期（9/2–12/18）：周一到周四 8:00–23:30，周五 8:00–20:00，周六 12:00–20:00，周日 12:00–23:30。感恩节周四到周六闭馆。"},"sum":{"en":"Science and engineering library with a quiet floor, group study rooms, an InfoLab, laptop loans and a new courtyard-level entrance (July 2026).","zh":"理工农医类图书馆：有安静楼层、讨论室、机房、可借笔记本，一楼翻新后 7 月重开。"},"kw":["Steenbock Library","science library","engineering library","理工图书馆","group study room","讨论室","InfoLab","laptop checkout","借笔记本","poster printing","海报打印","STEM Commons","Babcock Dr","自习"],"sec":{"about":{"en":["Steenbock Library serves agricultural, life and physical sciences, engineering and veterinary medicine. You can enter at street level on the 2nd floor or through the new courtyard-level entrance on the east (Babcock Street) side.","Floors are labeled by noise level: the 4th floor is the quiet study floor, and the 2nd and 3rd floors are group study floors. The first floor reopened on July 27, 2026 after a yearlong renovation, with study booths, group study rooms and STEM Commons. Members of the public not affiliated with UW may also use the library for research and study."],"zh":["Steenbock 图书馆服务农学、生命科学、物理科学、工程和兽医。可以从二楼街面入口进，也可以走东边（Babcock Street 一侧）新开的庭院层入口。","楼层按噪音分：四楼是安静自习层，二、三楼是小组讨论层。一楼经过一年翻修，2026 年 7 月 27 日重新开放，有卡座、讨论室和 STEM Commons。不是 UW 的访客也可以来做研究、自习。"]},"offers":{"en":["Quiet study on the 4th floor; group study floors on 2 and 3, with group study cubbies on the 3rd","Group study rooms on the 1st floor (rooms 111–115, 127, 139, 160–176), including a reservable 12-person conference room","InfoLab on the 2nd floor (entrance level): desktops with a full range of software, flatbed scanners, black-and-white and color laser printers","Laptop checkout at the 2nd-floor Circulation Desk: MacBook Airs and Dell laptops, 7-day loan","Poster printing on the 2nd floor; copiers that also scan on floors 3 and 4","STEM Commons: space for WISCIENCE events, workshops, advising, tutoring and more","Writing Center satellite in Room 139 on Sunday and Wednesday evenings","Prayer & Reflection Space on the 4th floor; lactation and feeding room on the 3rd floor","Vending machines, a microwave and casual seating just inside the courtyard-level entrance"],"zh":["四楼安静自习；二、三楼是小组讨论层，三楼还有讨论小隔间 (cubbies)","一楼有讨论室（111–115、127、139、160–176 室），其中有一间可预约的 12 人会议室","二楼（入口层）InfoLab 机房：装有各种软件的台式机、平板扫描仪、黑白和彩色激光打印机","二楼 Circulation Desk 借笔记本：MacBook Air 和 Dell，借期 7 天","二楼有海报打印；三、四楼的复印机也能扫描","STEM Commons：WISCIENCE 的活动、工作坊、咨询、辅导等都在这里","139 室有 Writing Center 周日和周三晚上的驻点","四楼有祈祷与静思空间 (Prayer & Reflection Space)；三楼有哺乳室","庭院层入口里面有自动售货机、微波炉和休息座位"]},"howto":{"en":["The main entrance is on the 2nd floor at street level. The courtyard-level entrance is on the east (Babcock Street) side, just under it.","Reserve a group study room online. During the semester you can book up to 14 days ahead.","To print, pick the Libraries-B&W queue for the black-and-white printers on floors 1 and 2, or Libraries_COLOR for the color printer on floor 2.","Pay with a Wiscard Print Account (set up or add money at go.wisc.edu/print) or Wiscard Campus Cash. For wireless printing, add the printer to your laptop first.","Check out a laptop at the 2nd-floor Circulation Desk with your Wiscard. You cannot reserve one in advance."],"zh":["主入口在二楼街面层；庭院层入口在东边（Babcock Street 一侧），就在主入口正下方。","讨论室在线预约。学期中最多提前 14 天订。","打印时选 Libraries-B&W 队列，打到一、二楼的黑白打印机；彩色选 Libraries_COLOR，打到二楼的彩色打印机。","用 Wiscard Print Account（在 go.wisc.edu/print 开户或充值）或 Wiscard Campus Cash 付费。想无线打印，要先把打印机加到自己电脑上。","借笔记本去二楼 Circulation Desk，出示学生证 (Wiscard)。不能提前预约。"]},"cost":{"en":["Printing is 7¢ per side in black and white and 60¢ per side in color. No fee for adding money to a Wiscard Print Account.","Copying is 10¢ per side (20¢ for ledger size), paid with a Wiscard or Wiscard Print Account. There is no color copying in the building.","Poster printing is $4.00 per square foot with a $4.00 minimum.","Scanning to email from the copiers is free.","InfoLab computers are open to UW students, staff and faculty with a valid Wiscard."],"zh":["打印黑白每面 7 美分，彩色每面 60 美分。给 Wiscard Print Account 充值不收手续费。","复印每面 10 美分（大幅面 20 美分），用 Wiscard 或 Wiscard Print Account 付费。馆里没有彩色复印。","海报打印每平方英尺 $4.00，最低收费 $4.00。","用复印机扫描发到邮箱是免费的。","InfoLab 的电脑给持有效 Wiscard 的 UW 学生、教职工用。"]},"tips":{"en":["Friday and Saturday it closes at 8 p.m., and Saturday opens at noon. Sunday to Thursday it stays open until 11:30 p.m.","Adobe Creative Suite is only on the InfoLab desktop computers, not on the checkout laptops.","Classrooms 102, 105 and 108 can be used for study when no class or event is scheduled. The room schedule is posted outside each door.","Science and engineering librarians have offices on the 1st floor (rooms 116–119) if you need research help.","No transparency or glossy printing here; try College Library's Computer & Media Center or a local copy shop.","If a print job goes wrong, request a refund with the DoIT Computer Lab Refund Form."],"zh":["周五、周六 20:00 关门，周六中午才开。周日到周四开到 23:30。","Adobe Creative Suite 只装在 InfoLab 的台式机上，外借笔记本里没有。","102、105、108 教室没课也没活动的时候可以用来自习，门外贴有每个房间的使用安排。","一楼 116–119 室是理工科馆员的办公室，要查资料可以去找他们。","这里不能打印透明胶片或亮面纸；需要的话去 College Library 的 Computer & Media Center 或校外打印店。","打印出问题，可以填 DoIT Computer Lab Refund Form 申请退款。"]}},"src":[["Steenbock Library – Library Hours","https://www.library.wisc.edu/steenbock/about-steenbock/library-hours/"],["Steenbock Library – Building Use Policies for Visitors","https://www.library.wisc.edu/steenbock/spaces/policies/building-use-policies-for-visitors/"],["Steenbock Library Renovation Update","https://www.library.wisc.edu/steenbock/spaces/active-learning-space-updates/"],["Steenbock Library – Floor Plans","https://www.library.wisc.edu/steenbock/spaces/floor-plans/"],["Steenbock Library – Spaces","https://www.library.wisc.edu/steenbock/spaces/"],["Steenbock Library – Group Study Room reservations","https://www.library.wisc.edu/steenbock/room-reservations-group-study-room-extended-use/"],["Steenbock Library – Desktop Computers","https://www.library.wisc.edu/steenbock/services-at-steenbock/computers/desktop-computers/"],["Steenbock Library – Laptops & Laptop Checkout","https://www.library.wisc.edu/steenbock/services-at-steenbock/computers/laptops/"],["Steenbock Library – Print / Copy / Scan","https://www.library.wisc.edu/steenbock/services-at-steenbock/print-copy-scan-2/"],["UW-Madison Libraries – Printing & Photocopies","https://www.library.wisc.edu/locations/printing"],["UW-Madison Writing Center – Make a Writing Appointment","https://writing.wisc.edu/make-a-writing-appointment/"]],"unv":[],"chk":"2026-10-08","lat":43.076104,"lng":-89.413372,"stops":[["Observatory at Babcock",46,"28 38 65 80"],["Babcock at Linden",98,"28 38 65 80"],["Linden at Babcock",116,"28 38 65 80 84"]]},{"id":"writing-center","cat":"study","n":{"en":"The Writing Center","zh":"写作中心 (Writing Center)"},"kind":{"en":"Writing tutoring","zh":"写作辅导"},"addr":"600 N Park St, Madison, WI 53706","phone":"(608) 263-1992","web":"https://writing.wisc.edu/","h":{"Mo":[[600,1005]],"Tu":[[600,1005]],"We":[[600,1005]],"Th":[[600,1005]],"Fr":[[600,870]],"Sa":[],"Su":[]},"ht":{"en":"Main center (Room 6171), Sept 2–Dec 9, 2026: Mon–Thu 10 a.m.–4:45 p.m., Fri 10 a.m.–2:30 p.m., Central time. Closed Labor Day and Thanksgiving recess (Nov 26–29). Evening satellite sessions in dorms and libraries start Sept 20; Virtual Meetings and Written Feedback are online.","zh":"主中心（6171 室），9/2–12/9：周一到周四 10:00–16:45，周五 10:00–14:30（中部时间）。劳动节和感恩节假期（11/26–11/29）不开。宿舍和图书馆的晚间驻点从 9/20 开始；网上有视频会面和书面反馈。"},"sum":{"en":"Free writing help from UW instructors for any class or application: in person, by video, or as written feedback. Book in WCOnline.","zh":"免费写作辅导，作业、申请文书都能约；当面、视频或书面反馈三种方式，在 WCOnline 预约。"},"kw":["Writing Center","writing help","tutoring","essay","paper","WCOnline","Helen C. White","ESL","multilingual","写作中心","写作辅导","论文","作业","文书","改稿"],"sec":{"about":{"en":["The Writing Center is a free service for currently enrolled UW–Madison undergraduate and graduate students. Instructors are professional staff and doctoral teaching assistants. They work with you on any writing project at any stage, from choosing a topic to drafting and revising.","Appointments last 40 minutes. The main center is at 6171 Helen C. White Hall. Satellite sites in dorms and libraries open from Sept 20, and you can also meet online."],"zh":["写作中心对在读的 UW–Madison 本科生和研究生免费。老师是专职人员和博士生助教，从选题、写初稿到修改，哪个阶段的写作都可以带来聊。","每次预约 40 分钟。主中心在 Helen C. White Hall 6171 室。宿舍和图书馆里的驻点从 9/20 开始，也可以在线见面。"]},"offers":{"en":["40-minute one-on-one appointments in person at the main center (6171 Helen C. White Hall)","Satellite sessions at College Library, Steenbock Library (Room 139), Dejope and Witte halls, the Center for Cultural Enrichment and the Multicultural Student Center (Red Gym); mostly evenings","Virtual Meetings: real-time video and audio with a shared whiteboard and chat, Monday to Thursday","Written Feedback: upload a draft in WCOnline and get written comments by the next business day","Help with thesis statements, organization, sources and citations, resumes, cover letters, scholarship, internship and grad-school applications; for grad students also literature reviews, theses and grant proposals","Free workshops (register in advance) and fall writing groups","Writing mentorships: the same instructor every week or every other week for a long project","An online Writer's Handbook for quick grammar and citation questions"],"zh":["主中心（Helen C. White Hall 6171 室）当面一对一，每次 40 分钟","驻点：College Library、Steenbock Library（139 室）、Dejope 和 Witte 宿舍、Center for Cultural Enrichment、Multicultural Student Center（Red Gym）；大多是晚上","视频会面 (Virtual Meetings)：实时视频语音，有共享白板和聊天，周一到周四","书面反馈 (Written Feedback)：在 WCOnline 上传草稿，下一个工作日收到书面意见","可以帮你看论点句、结构、引用和查资料、简历和求职信、奖学金/实习/研究生申请；研究生还可以谈文献综述、学位论文、基金申请书","免费工作坊（要提前报名）和秋季写作小组","长期写作辅导 (writing mentorship)：长项目可以固定每周或隔周找同一位老师","网上有写作手册 (Writer's Handbook)，语法和引用的小问题可以直接查"]},"howto":{"en":["Create a WCOnline account with your NetID (use the Make an Appointment button), then book a 40-minute slot. Slots often fill several days ahead.","Main center: enter Helen C. White Hall by the door to the left of College Library's entrance (you cannot get there from inside College Library), take the elevator to floor 6, turn right, then right again. Room 6171 is the first door on the left.","Bring anything that explains the assignment, and know what you want to work on.","Cancel in WCOnline at least 24 hours ahead. No-shows and very late cancellations can cost you the chance to book more that semester.","Call 608-263-1992 during in-person hours. Email to wcenter@writing.wisc.edu gets an answer within 2 business days but cannot book or cancel."],"zh":["先用 NetID 在 WCOnline 建账号（点 Make an Appointment），再订 40 分钟的时段。号经常提前好几天就满了。","去主中心：走 College Library 入口左边的 Helen C. White Hall 大门（从 College Library 里面进不去），坐电梯到 6 楼，右转再右转，6171 室是左手第一扇门。","带上作业要求之类能说明任务的材料，先想好这次想改哪方面。","要取消请至少提前 24 小时在 WCOnline 上取消。爽约或很晚才取消，这学期可能就不让再约了。","开放时间内可打电话 608-263-1992。发邮件到 wcenter@writing.wisc.edu 两个工作日内回复，但不能用邮件订号或取消。"]},"cost":{"en":["Free for all currently enrolled UW–Madison undergraduate and graduate students. Student tuition funds it.","Alumni, faculty and staff: limited one-on-one consultations as staffing allows. Call to ask.","People who are not with UW can use Madison Writing Assistance, a partnership with Madison libraries.","Workshops are free but need advance registration."],"zh":["在读的 UW–Madison 本科生和研究生全部免费，经费来自学生学费。","校友、教职工：看人手情况提供有限的一对一，请打电话问。","不属于 UW 的人可以用 Madison Writing Assistance，是写作中心和 Madison 图书馆合作的项目。","工作坊免费，但要提前报名。"]},"tips":{"en":["Come early in the semester and come often, and leave time to revise after each visit.","Exam week is short: appointments run only 10 a.m.–2:30 p.m. on Dec 10, 11 and 14.","Thanksgiving: closed Nov 26–29, and the center closes at 2:30 p.m. on Wed, Nov 25.","Instructors do not edit or proofread your paper. They help you learn to revise it yourself.","The FAQ calls dorm and library sessions first come, first served, while the appointment page says to sign up in WCOnline. Check WCOnline first.","Working on a thesis, a dissertation or many papers? Ask about a writing mentorship with the same instructor."],"zh":["学期初就开始来，多来几次，每次之后留出时间修改。","期末周很短：12/10、12/11、12/14 只有 10:00–14:30 有预约。","感恩节：11/26–11/29 不开，11/25（周三）14:30 就关门。","老师不会替你改稿或校对，而是教你怎么自己修改。","FAQ 说宿舍和图书馆驻点是先到先得，预约页却说要在 WCOnline 报名。建议先看 WCOnline 有没有号。","写毕业论文或一学期要写很多篇的话，可以问问固定同一位老师的 writing mentorship。"]},"intl":{"en":["The Writing Center does not teach ESL or conversational English. For ESL courses it points to the ESL Program in Helen C. White Hall (room 5134 on its page).","Multilingual writers are a big share of visitors: a 2018 staff post says they use upwards of 50% of appointments, and the Center has an ESL Liaison shared with the ESL Program.","Written Feedback suits you if you are in a different time zone or have an unreliable connection."],"zh":["写作中心不教 ESL，也不教英语口语。ESL 课程请找 Helen C. White Hall 里的 ESL Program（它自己页面写的是 5134 室）。","多语写作者占了很大一部分：2018 年中心员工的一篇文章说，他们占了超过 50% 的预约；中心还有和 ESL Program 共用的 ESL 联络员。","人在不同时区或网络不稳定的话，书面反馈最合适。"]}},"src":[["UW-Madison Writing Center – Make a Writing Appointment","https://writing.wisc.edu/make-a-writing-appointment/"],["UW-Madison Writing Center – Hours and Locations","https://writing.wisc.edu/hoursandlocations/"],["UW-Madison Writing Center – How to Reach Us","https://writing.wisc.edu/aboutus/contact/"],["UW-Madison Writing Center – Frequently Asked Questions","https://writing.wisc.edu/aboutus/faq/"],["UW-Madison Writing Center – What We Can Do for You","https://writing.wisc.edu/aboutus/doforyou/"],["UW-Madison Writing Center – Writing Groups","https://writing.wisc.edu/writinggroups/"],["Another Word – Writing Center + ESL Program (Dec 2018)","https://dept.writing.wisc.edu/blog/writing-center-esl-program-collaboration-in-support-of-multilingual-writers/"]],"unv":[],"chk":"2026-10-08","lat":43.076685,"lng":-89.401312,"stops":[["Langdon at N Park",126,"80 82"],["Observatory at Bascom",206,"80 82"],["N Park at State",241,"81"]]},{"id":"wendt-commons","cat":"study","n":{"en":"Wendt Commons","zh":"Wendt Commons 工程学习楼"},"kind":{"en":"Engineering building","zh":"工程学院大楼"},"addr":"215 N Randall Ave, Madison, WI 53706","phone":"(608) 571-7023","web":"https://making.engr.wisc.edu/directions-hours-parking/","h":{"Mo":[[420,1320]],"Tu":[[420,1320]],"We":[[420,1320]],"Th":[[420,1320]],"Fr":[[420,1080]],"Sa":[[450,1020]],"Su":[[480,1320]]},"ht":{"en":"Building, fall 2026: Mon–Thu 7 a.m.–10 p.m., Fri 7 a.m.–6 p.m., Sat 7:30 a.m.–5 p.m. (closed on home football game days), Sun 8 a.m.–10 p.m. No student card access outside these hours. The Design Innovation Lab @ Wendt is open Mon–Thu 9 a.m.–9 p.m., Fri 9 a.m.–6 p.m., Sun noon–4 p.m.","zh":"大楼（2026 秋季）：周一到周四 7:00–22:00，周五 7:00–18:00，周六 7:30–17:00（本校主场橄榄球赛日不开），周日 8:00–22:00。这些时间之外学生刷卡进不去。楼里的 Design Innovation Lab @ Wendt：周一到周四 9:00–21:00，周五 9:00–18:00，周日 12:00–16:00。"},"sum":{"en":"Engineering college building with the student makerspace and study space. It is no longer a library: Wendt Library closed in 2018.","zh":"工程学院大楼，有学生创客空间和自习空间。这里已不是图书馆：Wendt 图书馆 2018 年关闭。"},"kw":["Wendt Commons","Wendt Library","Design Innovation Lab","makerspace","创客空间","engineering","工程学院","3D printing","laser cutter","M-Pass","study space","自习","Undergraduate Learning Center","tutoring"],"sec":{"about":{"en":["Wendt Commons is a College of Engineering building at 215 N Randall Ave. It used to house the Wendt engineering library. That library closed on May 18, 2018, and its staff, services and books moved to Steenbock Library.","Today the building holds the Design Innovation Lab @ Wendt (the college makerspace, main entrance on the 2nd floor), classrooms and study space, and the Kohler Innovation Visualization Studio on the 1st floor. A 2022 College of Engineering tour guide also puts the Undergraduate Learning Center (tutoring) on the 4th floor."],"zh":["Wendt Commons 是工程学院的楼，地址 215 N Randall Ave。以前这里是 Wendt 工程图书馆，2018 年 5 月 18 日关闭，馆员、服务和书都搬到了 Steenbock 图书馆。","现在楼里有 Design Innovation Lab @ Wendt（学院的创客空间，主入口在二楼）、教室和自习空间，一楼还有 Kohler Innovation Visualization Studio。工程学院 2022 年的参观手册还写四楼是本科生学习中心 (Undergraduate Learning Center，提供辅导)。"]},"offers":{"en":["Design Innovation Lab @ Wendt: the college makerspace, with a Canvas lab orientation, laser cutter training and optional shop training","Design consultations and CAD support: book a design consultation if you are stuck","Open workshops and events for users from across campus","Classrooms and study space on the 3rd floor, open during building hours","Undergraduate Learning Center (ULC): free drop-in tutoring and study space for more than 50 engineering, math and science courses (4th floor per the College's 2022 tour guide)","Kohler Innovation Visualization Studio on the 1st floor (VR/AR rooms), not available for checkout this year because of construction"],"zh":["Design Innovation Lab @ Wendt：学院创客空间，有 Canvas 上的实验室入门课、激光切割培训，还有自选的木工/车间培训","设计咨询和 CAD 支持：卡住了可以约一次设计咨询 (design consultation)","对全校用户开放的工作坊和活动","三楼有教室和自习空间，大楼开放时间内都能用","本科生学习中心 (ULC)：免费的随到随问辅导，覆盖 50 多门工程、数学、理科课程，也可以在那里自习（工程学院 2022 年参观手册写在四楼）","一楼的 Kohler Innovation Visualization Studio（VR/AR 房间）：今年因为施工不能借用"]},"howto":{"en":["The Design Innovation Lab's main entrance is on the 2nd floor of Wendt Commons.","To use the lab you must be an enrolled College of Engineering (CoE) student in a CoE course, an active member of a CoE student organization, or CoE faculty or staff. Other UW degree students and faculty or staff can apply for an M-Pass.","For an M-Pass, request it online and finish the Lab Orientation Canvas module. Laser training is optional. Shop training is by request and not guaranteed.","CoE undergrads pay nothing, but the lab's Fusion system asks you to buy a zero-dollar fee before you can reserve machines and training sessions.","Questions: maker-contact@engr.wisc.edu or (608) 571-7023."],"zh":["Design Innovation Lab 的主入口在 Wendt Commons 二楼。","用这个实验室要满足其一：选了工程学院 (CoE) 课程的在读 CoE 学生、CoE 学生组织的活跃成员、CoE 教职工。其他 UW 学位生和教职工可以申请 M-Pass。","申请 M-Pass：在线提交申请，再完成 Canvas 上的 Lab Orientation。激光切割培训可选，车间培训要主动申请，不保证一定有。","CoE 本科生不用付费，但实验室的 Fusion 系统要你先「购买」一个 0 美元的费用，才能预约机器和培训。","有问题发邮件 maker-contact@engr.wisc.edu 或打 (608) 571-7023。"]},"cost":{"en":["CoE undergraduates, faculty and staff pay no access fee.","CoE graduate students pay a $100 access fee per semester. TA fees are waived automatically.","Other UW students and staff use the Wendt lab with an M-Pass: $150 per semester. It does not cover materials, and ECB equipment is off limits with it.","Drop-in tutoring at the ULC is free."],"zh":["CoE 本科生、教职工不用交使用费。","CoE 研究生每学期 $100 使用费，助教 (TA) 的费用会自动减免。","其他 UW 学生和教职工用 M-Pass 进 Wendt 实验室：每学期 $150，不含材料费，也不能用 ECB 的设备。","ULC 的随到随问辅导免费。"]},"tips":{"en":["Student cards open the doors only during building hours. There is no student card access outside them.","Saturday hours are cancelled on home football game days.","Wendt Library is gone. For engineering books and librarians, go to Steenbock Library.","Lab rules: never work alone, no headphones in fabrication spaces, and keep food in clean, designated areas.","ULC drop-in sessions run Sunday to Thursday evenings in most weeks of fall and spring. The current schedule is on the ULC intranet behind a UW login.","The Kohler Studio cannot be booked this year because of 1st-floor construction. Email the lab for alternatives."],"zh":["学生证只在大楼开放时间内能刷开门，其余时间刷卡进不去。","本校主场橄榄球赛日，周六不开放。","Wendt 图书馆已经不在了。找工程类的书和馆员，去 Steenbock 图书馆。","实验室规矩：不能一个人干活；车间里不许戴耳机；吃东西只能在干净的指定区域。","ULC 随到随问的辅导，秋春两学期大多数周的周日到周四晚上有。最新时间表在要 UW 登录的 ULC 内网里。","一楼施工，今年 Kohler Studio 不能预约，有需要发邮件问实验室有没有替代方案。"]}},"src":[["College of Engineering – Open Hours and Buildings","https://facilities.engr.wisc.edu/buildings/"],["Design Innovation Lab – Directions, Hours and Parking","https://making.engr.wisc.edu/directions-hours-parking/"],["Grainger Engineering Design Innovation Lab","https://making.engr.wisc.edu/"],["Design Innovation Lab – Access","https://making.engr.wisc.edu/access/"],["Design Innovation Lab – M-Pass","https://making.engr.wisc.edu/access/m-pass/"],["Design Innovation Lab – Kohler Innovation Visualization Studio","https://making.engr.wisc.edu/kohler-innovation-visualization-studio/"],["Design Innovation Lab – Policies","https://making.engr.wisc.edu/policies/"],["UW-Madison Libraries – Libraries Complete Transitioning Services Out of Wendt Commons, Into Steenbock (2018)","https://www.library.wisc.edu/news/2018/04/23/libraries-to-complete-transitioning-services-out-of-wendt-commons-into-steenbock"],["College of Engineering – Campus walking tour (2022)","https://engineering.wisc.edu/wp-content/uploads/2022/01/COE_WalkingTour_2022.pdf"],["College of Engineering – Undergraduate Learning Center","https://engineering.wisc.edu/student-services/undergraduate-learning-center"],["UW–Madison Guide – College of Engineering resources","https://guide.wisc.edu/undergraduate/engineering/engineering_resourcestext.pdf"]],"unv":["phone"],"chk":"2026-10-08","lat":43.071509,"lng":-89.408633,"stops":[["N Randall at W Dayton",26,"D O"],["N Randall at Engineering",71,"D O 80"],["W Johnson at N Orchard",108,"C D J O R"]]},{"id":"apple-hilldale","cat":"shop","n":{"en":"Apple Hilldale","zh":"Apple Hilldale 苹果店"},"kind":{"en":"Apple Store","zh":"苹果官方店"},"addr":"444 N Midvale Blvd, Madison, WI 53705","phone":"(608) 827-9840","web":"https://www.apple.com/retail/hilldale/","h":{"Mo":[[600,1200]],"Tu":[[600,1200]],"We":[[600,1200]],"Th":[[600,1200]],"Fr":[[600,1200]],"Sa":[[600,1200]],"Su":[[660,1080]]},"ht":{"en":"Fall 2026: Mon–Sat 10 a.m.–8 p.m., Sun 11 a.m.–6 p.m. Holiday hours can differ; Apple's store page shows each day's hours.","zh":"2026 年秋季：周一到周六 10:00–20:00，周日 11:00–18:00。节假日可能不一样，Apple 的店铺页面会列出每天的时间。"},"sum":{"en":"The Apple Store at Hilldale: buy Apple products, get Genius Bar repairs by appointment, and check education savings on Mac and iPad.","zh":"Hilldale 的 Apple Store：买苹果产品、预约 Genius Bar 维修，学生可走教育优惠。"},"kw":["Apple Store","苹果店","Apple Hilldale","Hilldale","Genius Bar","iPhone","MacBook","iPad","Apple Watch","AirPods","repair","维修","screen replacement","换屏","education discount","教育优惠","UNiDAYS","trade-in","以旧换新","Today at Apple"],"sec":{"about":{"en":["Apple Hilldale is the Apple Store in the Hilldale Shopping Center on the west side of Madison, at 444 N Midvale Blvd.","The University Book Store's Tech Center names this store as the closest place for full Apple repair, so it is where UW students go when a Mac, iPhone or iPad needs real service."],"zh":["Apple Hilldale 是开在麦迪逊西侧 Hilldale 购物中心里的 Apple Store，地址 N Midvale Blvd 444 号。","University Book Store 的 Tech Center 自己写明：苹果设备要全面检修，最近的地方就是这家店。所以 Mac、iPhone、iPad 出了问题，UW 学生一般来这里。"]},"offers":{"en":["Shop Apple products in person and get advice from staff","Genius Bar and Genius Support: device setup, Apple Account recovery, screen replacement","Order pickup in store: buy online and collect it here","Education savings on Mac, iPad and Apple Watch for eligible students","Trade in an old iPhone toward a new one","Today at Apple sessions and Apple Vision Pro demos"],"zh":["到店看实物买苹果产品，店员当面给建议","Genius Bar 和 Genius Support：设备设置、找回 Apple 账户、换屏","到店取货 (Order pickup)：网上下单，来这里取","符合条件的学生买 Mac、iPad、Apple Watch 可以走教育优惠","旧 iPhone 折价换新机 (trade-in)","Today at Apple 课程和 Apple Vision Pro 体验"]},"howto":{"en":["Genius Bar is by appointment only. Use \"Make a reservation\" on the store page.","For the education price, get verified online before you visit (Apple uses UNiDAYS). Apple says this saves time in the store.","To skip the wait, buy online and choose pickup at this store.","In-store trade-in needs a valid photo ID."],"zh":["Genius Bar 只接受预约。在店铺页面点 \"Make a reservation\"。","想用教育价，到店前先在网上验证身份（Apple 用 UNiDAYS）。Apple 说这样到店能省时间。","不想排队，就网上下单，选这家店取货。","到店做 trade-in 要出示有效的带照片证件。"]},"cost":{"en":["Education savings apply to Mac, iPad and Apple Watch. They are open to current and newly accepted college students and their parents, plus faculty, staff and homeschool teachers.","The exact discount amounts are on Apple's education store page and change over time; check it before you buy.","Trade-in value depends on the device's condition, year and configuration, and not every device qualifies. You must be at least the age of majority to trade in."],"zh":["教育优惠适用于 Mac、iPad 和 Apple Watch。对象是在读和刚被录取的大学生及其家长，还有教职员工和家庭教学教师。","具体优惠多少，看 Apple 教育商店页面，会变动，买之前先查。","trade-in 折价看设备的成色、年份和配置，不是所有设备都能折。要达到法定成年年龄才能折价。"]},"tips":{"en":["Sunday hours are shorter (11 a.m.–6 p.m.) than the rest of the week.","The University Book Store's Tech Center also sells Apple products, but only gives basic triage and limited service. Full Apple diagnostics and repair is here.","Hilldale also has other shops and restaurants around the store; see the Hilldale Shopping Center entry."],"zh":["周日营业时间短（11:00–18:00），比一周里其他天短。","University Book Store 的 Tech Center 也卖苹果产品，但只做基础排查和有限服务。全面检测和维修要来这家店。","店周围还有别的商店和餐厅，见 Hilldale Shopping Center 那一条。"]}},"src":[["Apple Hilldale - Apple","https://www.apple.com/retail/hilldale/"],["Apple Education Store","https://www.apple.com/us-edu/store"],["University Book Store - Tech Center","https://www.uwbookstore.com/Tech"]],"unv":[],"chk":"2026-10-08","lat":43.072094,"lng":-89.453123,"stops":[["N Midvale at Hilldale Row",144,"63"],["N Midvale at Heather",188,"63"],["Segoe",321,"A F"]]},{"id":"best-buy-west-madison","cat":"shop","n":{"en":"Best Buy (West Madison)","zh":"Best Buy 百思买（West Madison 店）"},"kind":{"en":"Electronics store","zh":"电子产品店"},"addr":"7357 W Towne Way, Madison, WI 53719","phone":"(608) 829-1188","web":"https://stores.bestbuy.com/wi/madison/7357-w-towne-way-208.html","h":{"Mo":[[600,1260]],"Tu":[[600,1260]],"We":[[600,1260]],"Th":[[600,1260]],"Fr":[[600,1260]],"Sa":[[600,1260]],"Su":[[600,1200]]},"ht":{"en":"Fall 2026: Mon–Sat 10 a.m.–9 p.m., Sun 10 a.m.–8 p.m. The store page lists separate curbside hours. Holiday hours differ; check the store page.","zh":"2026 年秋季：周一到周六 10:00–21:00，周日 10:00–20:00。店铺页面另有路边取货 (curbside) 的时间。节假日时间不同，看店铺页面。"},"sum":{"en":"The Best Buy closest to campus: laptops, monitors, phones and small appliances, with Geek Squad repair and an Apple shop inside the store.","zh":"离校园最近的 Best Buy：电脑、显示器、手机、小家电都有，店里有 Geek Squad 维修和 Apple 专区。"},"kw":["Best Buy","百思买","electronics","电子产品","laptop","笔记本电脑","monitor","显示器","Geek Squad","mini fridge","小冰箱","Apple","Samsung","trade-in","返校","back to school","student deals","return policy","退货","West Towne Way"],"sec":{"about":{"en":["This Best Buy is at 7357 W Towne Way on the West Side, near West Towne. Of the two Madison stores it is the one closer to campus; the other is on the East Side.","It is the place to buy electronics you want to see first: laptops, tablets, TVs, monitors, phones, headphones, small appliances. Geek Squad handles repairs and installs."],"zh":["这家 Best Buy 在西区 W Towne Way 7357 号，靠近 West Towne。麦迪逊有两家 Best Buy，这家离校园近，另一家在东区。","想先看实物再买电子产品就来这里：笔记本、平板、电视、显示器、手机、耳机、小家电。Geek Squad 管维修和安装。"]},"offers":{"en":["Computers and tablets, TVs, video games, cell phones, audio, appliances, cameras, wearables","Apple Shop inside the store (Mac, iPad, iPhone, Apple TV) and an Apple Authorized Service Provider listing","Samsung, LG and Google Home experience areas","Geek Squad services: schedule a repair online or track one that is in progress","Trade-In for old devices","Back-to-school items such as mini fridges (shown on bestbuy.com; check store stock first)","Curbside pickup (hours are listed on the store page)"],"zh":["电脑和平板、电视、游戏、手机、音响、家电、相机、可穿戴设备","店里有 Apple 专区 (Apple Shop)，售 Mac、iPad、iPhone、Apple TV，并列为 Apple 授权服务商","Samsung、LG 和 Google Home 体验区","Geek Squad 服务：网上预约维修，或查询送修进度","旧设备折价 (Trade-In)","返校季商品，比如小冰箱（网站上有，去之前先查店里库存）","路边取货 (curbside)，时间在店铺页面上"]},"howto":{"en":["Check stock on bestbuy.com before you go. Items marked Sold Out or Check Stores cannot be ordered by phone, and phone agents cannot say what is in stock.","Book Geek Squad service ahead (\"Schedule a service\" on the store page). Appointments fill up fast near the holidays.","Student deals: bestbuy.com's Back to School page offers coupon codes on some items.","Getting here without a car: the nearest Madison Metro stops are listed on this page. For a laptop or monitor, ordering for pickup is easier than carrying it on the bus."],"zh":["去之前先在 bestbuy.com 查库存。显示 Sold Out 或 Check Stores 的商品不能打电话订，电话客服也答不了有没有货。","Geek Squad 服务要提前约（店铺页面的 \"Schedule a service\"）。节假日前后约位很快满。","学生优惠：bestbuy.com 的 Back to School 页面上，部分商品有优惠码。","没车怎么来：离这家店最近的 Madison Metro 公交站列在本页。笔记本、显示器这类东西，下单到店取比坐公交扛回去省事。"]},"cost":{"en":["Student discount: Best Buy says to use coupon codes for \"a special student discount on some items\". It does not list a fixed percentage.","Standard return window: 15 days for most products and 14 days for phones and other activatable devices. My Best Buy Plus and Total members get 60 days on most products.","Restocking fee: $45 on activatable devices, 15% on drones, digital cameras, camcorders and projectors. There is no fee if the product is unopened."],"zh":["学生优惠：Best Buy 写的是用优惠码拿 \"部分商品的学生折扣\"，没有写固定折扣比例。","标准退货期：大部分商品 15 天，手机等可激活设备 14 天。My Best Buy Plus 和 Total 会员大部分商品 60 天。","重新上架费 (restocking fee)：可激活设备 $45，无人机、数码相机、摄像机、投影仪收 15%。没拆封的不收。"]},"tips":{"en":["Sunday closing is 8 p.m., an hour earlier than the other days.","The other Madison store is Best Buy East Madison at 2452 E Springs Dr, (608) 242-0701.","For Apple repairs the University Book Store's Tech Center sends you to the Apple Store at Hilldale (see the Apple Hilldale entry); this store's own service list includes Apple Authorized Service Provider."],"zh":["周日 20:00 关门，比其他天早一小时。","麦迪逊另一家是东区的 Best Buy East Madison，E Springs Dr 2452 号，电话 (608) 242-0701。","苹果设备维修，University Book Store 的 Tech Center 会让你去 Hilldale 的 Apple Store（见 Apple Hilldale 那一条）；这家店自己的服务列表里写有 Apple 授权服务商 (Apple Authorized Service Provider)。"]},"intl":{"en":["Best Buy does not accept mail-in returns shipped from outside the US. Settle a return before you fly home."],"zh":["Best Buy 不接受从美国境外寄回的退货。要退的话，回国前先办完。"]}},"src":[["Best Buy West Madison - store page","https://stores.bestbuy.com/wi/madison/7357-w-towne-way-208.html"],["Best Buy East Madison - store page","https://stores.bestbuy.com/wi/madison/2452-e-springs-dr-59.html"],["Best Buy - Back to School hub","https://www.bestbuy.com/site/misc/back-to-school/pcmcat334100050000.c?id=pcmcat334100050000"],["Best Buy - Return & Exchange Policy","https://www.bestbuy.com/site/help-topics/return-exchange-policy/pcmcat260800050014.c?id=pcmcat260800050014"],["University Book Store - Tech Center","https://www.uwbookstore.com/Tech"]],"unv":[],"chk":"2026-10-08","lat":43.055562,"lng":-89.511163,"stops":[["Watts at Sky Ridge",520,"D 62"],["S High Point at D'Onofrio",549,"R"]]},{"id":"east-towne-mall","cat":"shop","n":{"en":"East Towne Mall","zh":"East Towne Mall 购物中心"},"kind":{"en":"Shopping mall","zh":"室内购物中心"},"addr":"89 East Towne Mall, Madison, WI 53704","phone":"(608) 244-1387","web":"https://www.shopeasttowne-mall.com/","h":{"Mo":[[600,1200]],"Tu":[[600,1200]],"We":[[600,1200]],"Th":[[600,1200]],"Fr":[[600,1200]],"Sa":[[600,1200]],"Su":[[660,1080]]},"ht":{"en":"Mall hours: Mon–Sat 10 a.m.–8 p.m., Sun 11 a.m.–6 p.m. Stores with outside doors may keep their own hours. Thanksgiving: closed Thu Nov 26; Fri Nov 27 is 7 a.m.–9 p.m.","zh":"商场营业时间：周一到周六 10:00–20:00，周日 11:00–18:00。有外门的店可能有自己的时间。感恩节：11 月 26 日（周四）关门，11 月 27 日（周五）7:00–21:00。"},"sum":{"en":"Indoor mall on the East Side anchored by Dick's Sporting Goods, JCPenney, Barnes & Noble and a movie theater with in-theater dining.","zh":"东区的室内商场，主力店有 Dick's 运动用品、JCPenney、Barnes & Noble 和能边吃边看的电影院。"},"kw":["East Towne Mall","East Towne","mall","商场","购物中心","Dick's Sporting Goods","JCPenney","Barnes & Noble","Flix Brewhouse","movie theater","电影院","Thrill Factory","Black Friday","黑五","bus","公交"],"sec":{"about":{"en":["East Towne Mall is an indoor mall at 89 East Towne Mall on Madison's East Side. The mall's site says it is anchored by DICK'S Sporting Goods, Flix Brewhouse, Thrill Factory, JCPenney and Barnes & Noble.","The site says the mall is just off I-90 and also has specialty shops and everyday services."],"zh":["East Towne Mall 是室内商场，在麦迪逊东区，地址 89 East Towne Mall。商场官网说主力店是 DICK'S Sporting Goods、Flix Brewhouse、Thrill Factory、JCPenney 和 Barnes & Noble。","官网说商场就在 I-90 公路旁边，另有各类专卖店和日常服务。"]},"offers":{"en":["DICK'S Sporting Goods","JCPenney department store","Barnes & Noble bookstore","Flix Brewhouse: movies with in-theater dining","Thrill Factory, a place to play","Food spots such as Popper's Tea and Kato's Cajun, plus everyday services"],"zh":["DICK'S Sporting Goods 运动用品店","JCPenney 百货店","Barnes & Noble 书店","Flix Brewhouse：边吃边看电影的影院","Thrill Factory：玩乐场所","Popper's Tea、Kato's Cajun 这类小吃店，以及日常服务类商家"]},"howto":{"en":["Check the mall's directory page for each store's own hours before you go.","Mall management: (608) 244-1387. Mall security: (608) 235-7585.","Getting here without a car: the nearest Madison Metro stops are listed on this page. It is on the East Side, so allow time for the ride from campus."],"zh":["出发前在商场官网的 Directory 页查各家店自己的营业时间。","商场管理处：(608) 244-1387。商场保安：(608) 235-7585。","没车怎么来：离商场最近的 Madison Metro 公交站列在本页。它在东区，从校园过来要留出车程的时间。"]},"cost":{"en":["Entering and walking around the mall is free. Each store sets its own prices.","The mall's site states no student discount. Ask each store."],"zh":["进商场逛不要钱，价格由各家店定。","商场官网没写学生折扣，要问各家店。"]},"tips":{"en":["Thanksgiving week: closed Thu Nov 26, then open 7 a.m.–9 p.m. on Fri Nov 27, then back to normal hours on Sat Nov 28.","Some businesses have outside doors and can open and close at different times from the mall.","West Towne Mall on the west side has the same mall hours and lists Sephora, Von Maur and Nordstrom Rack (see its entry)."],"zh":["感恩节那周：11 月 26 日（周四）关门，11 月 27 日（周五）7:00–21:00 营业，11 月 28 日（周六）恢复正常时间。","有些店有对外的门，开关门时间可能和商场不同。","西边的 West Towne Mall 商场营业时间一样，官网列有 Sephora、Von Maur 和 Nordstrom Rack（见它自己那一条）。"],"exp":["2026-11-30",null,null]}},"src":[["East Towne Mall - About (address, phone, anchors)","https://www.shopeasttowne-mall.com/about"],["East Towne Mall - Hours","https://www.shopeasttowne-mall.com/hours"],["East Towne Mall - Home","https://www.shopeasttowne-mall.com/"],["West Towne Mall - About","https://www.shopwesttowne-mall.com/about"],["West Towne Mall - Hours","https://www.shopwesttowne-mall.com/hours"]],"unv":[],"chk":"2026-10-08","lat":43.1252318,"lng":-89.3051986,"stops":[["Eagan at East Towne",311,"G"],["Independence",374,"A"],["Independence at E Washington",452,"G P 60"]]},{"id":"goodwill-monona","cat":"shop","n":{"en":"Goodwill (Monona)","zh":"Goodwill 二手店（Monona 店）"},"kind":{"en":"Thrift store","zh":"慈善二手店"},"addr":"2501 Royal Ave, Monona, WI 53713","phone":"","web":"https://goodwillscwi.org/locations/monona/","h":{"Mo":[[540,1200]],"Tu":[[540,1200]],"We":[[540,1200]],"Th":[[540,1200]],"Fr":[[540,1200]],"Sa":[[540,1200]],"Su":[[600,1080]]},"ht":{"en":"Mon–Sat 9 a.m.–8 p.m., Sun 10 a.m.–6 p.m. (October 2026). The store lists no phone of its own; Goodwill's home office answers (608) 246-3140 on weekdays 8 a.m.–4:30 p.m.","zh":"周一到周六 9:00–20:00，周日 10:00–18:00（2026 年 10 月）。这家店没有公开自己的电话；Goodwill 总部电话 (608) 246-3140，工作日 8:00–16:30 有人接。"},"sum":{"en":"Goodwill's closest store to campus; cheap clothes, kitchenware and furniture, with 10% off for students every Thursday.","zh":"离校园最近的 Goodwill，衣服、锅碗、家具都便宜，每周四学生证再打九折。"},"kw":["Goodwill","thrift","二手店","second-hand","二手","Monona","Royal Ave","student discount","学生折扣","winter clothes","冬衣","kitchenware","厨具","furniture","二手家具","donate","捐赠","color tag"],"sec":{"about":{"en":["Goodwill of South Central Wisconsin is a local nonprofit. It runs 14 retail stores, one outlet and one attended donation center. Store sales fund job training and supported employment for people with barriers to work, and housing for people living with chronic mental illness.","This store is on Royal Ave in the city of Monona, southeast of campus. By straight-line distance it is the closest of Goodwill's Madison-area stores."],"zh":["Goodwill of South Central Wisconsin 是本地非营利组织，有 14 家零售店、1 家 outlet 和 1 个有人值守的捐赠点。店里的收入用来支持有就业障碍的人培训和就业，也用来给长期精神疾病患者提供住房。","这家店在 Monona 市的 Royal Ave，在校园东南方向。按直线距离算，它是 Goodwill 在麦迪逊一带离校园最近的一家。"]},"offers":{"en":["Clothing, accessories and shoes","Household items and kitchenware","Furniture","Books, media, toys and games","Electrical items and computer equipment","Free electronics recycling at the store, any brand, working or not (through the Dell Reconnect program)"],"zh":["衣服、配饰和鞋子","家居用品和厨具","家具","书、影音、玩具和游戏","电器和电脑设备","店里免费回收电子产品，任何品牌、坏的也收 (Dell Reconnect 项目)"]},"howto":{"en":["Walk in during store hours. The pages I read mention no membership or sign-up for shopping.","To donate, bring items in reusable condition. The \"What can I donate?\" page lists what is accepted and what is not.","If you cannot drive, Goodwill has a home pickup service run by a partner company, ReSupply. Pickups are priced by piece, and you book a date 48 hours to 2 weeks ahead.","For questions about a store visit, use the form on the Contact page and name the store and the date and time."],"zh":["营业时间内直接进店买东西就行，我查的官网页面没提要办会员或注册。","要捐东西，物品要是还能再用的状态。“What can I donate?”页面列了收什么、不收什么。","没车的话，Goodwill 有上门取货服务，由合作公司 ReSupply 负责。按件计价，可以预约 48 小时到 2 周之后的时间。","对某次到店有意见或问题，用 Contact 页面的表单，写清楚是哪家店、什么日期和时间。"]},"cost":{"en":["Every Thursday is Student & Teacher Day: students and teachers with a valid school ID get 10% off the entire purchase.","Weekly color tag sale: 50% off any item with the designated color tag.","Tuesday is Senior Day (55 and older get 10% off) and every day is Military Day (10% off). These are not student discounts.","Electronics recycling is free."],"zh":["每周四是学生和老师日：持有效学生证的学生和老师整单打九折。","每周有一种颜色的标签半价：带当周指定颜色标签的商品打五折。","周二是 55 岁以上的老年日 (10% off)，军人每天都有 10% off。这两项和学生无关。","电子产品回收免费。"]},"tips":{"en":["Shop on Thursday with your school ID, and look for the weekly color tag. A tagged item on Thursday gets both discounts, but the website does not say whether they stack, so ask at the register.","Goodwill does not take mattresses, box springs, large appliances, infant furniture or unassembled furniture. For move-out, plan another place for those.","Goodwill's page sends building materials to the Habitat for Humanity of Dane County ReStore.","Other Madison-area stores include Nakoma (4530 Verona Rd). Pick the store on the website's Find a Store page by your zip code."],"zh":["周四带学生证来，再看当周的标签颜色。标签商品周四理论上能叠两个折扣，但官网没说能不能叠，结账时问收银员。","Goodwill 不收床垫、弹簧床垫、大型家电、婴儿家具和没组装的家具。搬家时这些东西要另找去处。","建筑材料 Goodwill 页面建议送 Habitat for Humanity of Dane County 的 ReStore。","麦迪逊一带还有别的分店，比如 Nakoma 店 (4530 Verona Rd)。可以在官网 Find a Store 页面按邮编找店。"]},"intl":{"en":["For the Thursday discount, show a valid school ID. The page does not name which IDs count, so carry your Wiscard and ask at the register."],"zh":["周四折扣要出示有效的学生证。页面没写哪些证件算数，带上你的 Wiscard，在收银台问一句。"]}},"src":[["Goodwill of South Central Wisconsin - Monona store","https://goodwillscwi.org/locations/monona/"],["Goodwill of South Central Wisconsin - Contact","https://goodwillscwi.org/contact/"],["Goodwill of South Central Wisconsin - Shop","https://goodwillscwi.org/shop/"],["Goodwill of South Central Wisconsin - Weekly Discounts","https://goodwillscwi.org/shop/weekly-discounts/"],["Goodwill of South Central Wisconsin - What can I donate?","https://goodwillscwi.org/donate/what-can-i-donate/"],["Goodwill of South Central Wisconsin - Home Pickup","https://goodwillscwi.org/donate/home-pickup/"],["Goodwill of South Central Wisconsin - Nakoma store","https://goodwillscwi.org/locations/nakoma/"]],"unv":[],"chk":"2026-10-08","lat":43.043453,"lng":-89.359905,"stops":[["South Towne at Royal",442,"G 61 64"],["South Towne at Industrial",577,"G 61 64"]]},{"id":"habitat-restore-east","cat":"shop","n":{"en":"Habitat for Humanity ReStore (East)","zh":"Habitat for Humanity ReStore 家居二手店（东店）"},"kind":{"en":"Home goods resale store","zh":"家居建材二手店"},"addr":"4207 Monona Dr, Madison, WI 53716","phone":"(608) 661-2813","web":"https://habitatdane.org/restore/","h":{"Mo":[],"Tu":[[540,1020]],"We":[[540,1020]],"Th":[[540,1020]],"Fr":[[540,1020]],"Sa":[[540,1020]],"Su":[]},"ht":{"en":"Tue–Sat 9 a.m.–5 p.m. Closed Sun and Mon. Donation drop-off is shorter: Tue–Sat 9 a.m.–3 p.m. (October 2026).","zh":"周二到周六 9:00–17:00，周日和周一不开。收捐赠的时间短一些：周二到周六 9:00–15:00（2026 年 10 月）。"},"sum":{"en":"Habitat for Humanity's resale store for used furniture, appliances and tools at deep discounts; open Tuesday to Saturday only.","zh":"Habitat for Humanity 开的二手家居店，旧家具、电器、工具都卖得很便宜，只有周二到周六开。"},"kw":["Habitat","ReStore","Habitat for Humanity","second-hand furniture","二手家具","二手","appliances","二手电器","tools","工具","home goods","dresser","书桌","sofa","沙发","Monona Drive"],"sec":{"about":{"en":["The Habitat ReStore is owned and run by Habitat for Humanity of Dane County. It resells donated furniture, appliances, home accessories and building materials at deeply discounted prices, and the profits pay for new houses and exterior repairs on owner-occupied homes in the community.","Dane County has two ReStores: ReStore East at 4207 Monona Drive (this entry) and ReStore West at 6201 Odana Road, (608) 442-9919. Both use the same hours."],"zh":["Habitat ReStore 由 Habitat for Humanity of Dane County 开办。店里把别人捐的家具、电器、家居小件和建材低价卖出去，利润用来盖新房子，以及给本地自住房做外墙维修。","Dane County 有两家 ReStore：东店在 4207 Monona Drive（就是这个条目），西店在 6201 Odana Road，电话 (608) 442-9919。两家营业时间一样。"]},"offers":{"en":["Furniture: dressers, tables, chairs, sofas, shelving, framed mirrors, bed frames (frames only)","Appliances: washers, dryers, refrigerators, stoves, microwaves and similar, listed as clean and in working order","Tools: power tools, hand tools, toolboxes and storage","Lighting, cabinets, flooring, plumbing and building materials","Home decor","Stock changes every day, since new donations come in daily"],"zh":["家具：五斗柜、桌子、椅子、沙发、置物架、带框镜子、床架（只有床架，不带床垫）","电器：洗衣机、烘干机、冰箱、炉灶、微波炉等，官网要求干净且能正常用","工具：电动工具、手工具、工具箱和收纳","灯具、橱柜、地板、水管和建材","家居装饰品","库存天天变，因为每天都有新捐赠进来"]},"howto":{"en":["Walk in during store hours. Stock is first-come, first-served, and the store cannot hold an item until you pay in full.","After you pay, the store holds your purchase for up to seven days. Use that time to find a car or a rideshare big enough.","To see current items before you go, use the ReStore's Facebook page, which is linked from the ReStore page.","To donate: drop off Tue–Sat 9 a.m.–3 p.m. at either store, or request a free pickup online or by calling the donation hotline, (608) 663-1191. The wait for a free pickup is three to five days on average.","A priority pickup in 48 hours is offered through Resupply, from $99; they can pick up from several floors and take furniture apart."],"zh":["营业时间内直接进店。东西先到先得，没付全款店里不能帮你留。","付完款后，店里会帮你保留最多 7 天。这几天用来找一辆装得下的车或网约车。","去之前想看现货，可以看 ReStore 的 Facebook 页面，ReStore 官网页面上有链接。","要捐东西：周二到周六 9:00–15:00 送到任一家店，或者在网上申请免费上门取货，也可以打捐赠热线 (608) 663-1191。免费取货平均要等 3 到 5 天。","想 48 小时内取货，可以通过 Resupply 的优先服务，$99 起；他们能上楼取货，也能把家具拆开。"]},"cost":{"en":["Prices are \"deeply discounted\" on the store's wording; the website gives no price list or student discount.","All sales are final, except appliances, which have a 14-day return policy.","Donors get a receipt for tax-deductible donations each time they donate."],"zh":["官网说价格“大幅折扣”，但没有价目表，也没有学生折扣。","所有商品卖出后不退不换，只有电器有 14 天退货期。","捐赠每次都能拿到可抵税的捐赠收据。"]},"tips":{"en":["The store is closed on Sunday and Monday, so plan a weekday or Saturday trip.","If you need a specific piece, call the store before you go to ask whether it is in stock.","The ReStore does not accept donations of office items, file cabinets, entertainment centers, recliners, futons or pressboard furniture as donations.","The Furniture Bank is a separate program for families in transitional housing. It works only through referrals from partner agencies, so it is not the way for a student to buy a desk.","The website does not say whether the store delivers purchases. Ask on the phone before you buy a large piece."],"zh":["周日和周一不开，安排周中或周六去。","想要某件具体的东西，出发前先打电话问有没有现货。","ReStore 不收办公家具、文件柜、娱乐柜、躺椅、日式折叠沙发床 (futon) 和压缩板家具的捐赠。","Furniture Bank 是另一个项目，面向住在过渡性住房的家庭，必须由合作机构转介，学生想买书桌不走这条路。","官网没写店里送不送货。买大件之前先打电话问。"]}},"src":[["Habitat ReStore of Dane County","https://habitatdane.org/restore/"],["Habitat ReStore - Shop at the ReStore","https://habitatdane.org/restore/shop/"],["Habitat for Humanity of Dane County - Contact Us","https://habitatdane.org/about/contact-us/"],["Habitat ReStore Furniture Bank","https://habitatdane.org/furniture-bank/"]],"unv":[],"chk":"2026-10-08","lat":43.074971,"lng":-89.326545,"stops":[["Monona at Coldspring",210,"L 38"],["Monona at Buckeye",549,"L 38"],["Buckeye at Monona",566,"61"]]},{"id":"hilldale-shopping-center","cat":"shop","n":{"en":"Hilldale Shopping Center","zh":"Hilldale Shopping Center 购物中心"},"kind":{"en":"Shopping center","zh":"购物中心"},"addr":"726 N Midvale Blvd, Madison, WI 53705","phone":"(608) 284-8162","web":"https://hilldale.com/","h":{"Mo":[[600,1200]],"Tu":[[600,1200]],"We":[[600,1200]],"Th":[[600,1200]],"Fr":[[600,1200]],"Sa":[[600,1200]],"Su":[[660,1080]]},"ht":{"en":"Shops: Mon–Sat 10 a.m.–8 p.m., Sun 11 a.m.–6 p.m. Restaurants, fitness and grocery may keep different hours, so check each one before you go.","zh":"商店：周一到周六 10:00–20:00，周日 11:00–18:00。餐厅、健身房和超市的时间可能不一样，出发前先查那一家。"},"sum":{"en":"West Side shopping center with Apple, Ace Hardware, Metcalfe's Market, a University Book Store branch, a bank and many restaurants.","zh":"西区的购物中心：有 Apple、Ace 五金、Metcalfe's 超市、书店分店、银行和不少餐厅。"},"kw":["Hilldale","shopping center","mall","购物中心","商场","Apple Store","Ace Hardware","五金","Metcalfe's","University Book Store","Chase","Sephora","Macy's","Warby Parker","restaurants","餐厅","farmers market","农夫市集","West Side","西区"],"sec":{"about":{"en":["Hilldale is a shopping center at 726 N Midvale Blvd on Madison's West Side, west of campus. Its own site calls it a strollable setting. There are shops, restaurants, fitness studios and a grocery store, plus a lawn called The Green.","The store directory lists national chains and local shops. This entry covers what is useful to students; the Apple Store is also listed separately as Apple Hilldale."],"zh":["Hilldale 在麦迪逊西区，地址 N Midvale Blvd 726 号，在校园西边。官网说这里适合散步逛。里面有商店、餐厅、健身房和超市，还有一块叫 The Green 的草坪。","官网的店铺目录里有全国连锁，也有本地店。这一条只讲对学生有用的；Apple Store 另有一条 Apple Hilldale。"]},"offers":{"en":["Apple Store and a University Book Store branch (Badger clothing, school supplies, general books)","Ace Hardware and Metcalfe's Market (grocery)","Chase Bank, Spectrum, Hilldale Barber and Right Size Alteration Services","Eyewear: Warby Parker, Ulla Eyewear; beauty: Sephora, Bluemercury, Lush Handmade Cosmetics","Clothes and shoes: Macy's, Levi's, lululemon, L.L. Bean, Morgan's Shoes, Stride Rite and more","Food and drink: Shake Shack, Sweetgreen, Café Hollander, Crescendo Espresso Bar, bartaco, Bambu, Muramoto Hilldale, FreshFin, Blended","Fitness and sports: solidcore, Title Nine, Morgan's Good Form Running"],"zh":["Apple Store 和 University Book Store 分店（Badger 服装、文具、普通图书）","Ace Hardware 五金店和 Metcalfe's Market 超市","Chase 银行、Spectrum、Hilldale Barber 理发店、Right Size 衣物修改店","眼镜：Warby Parker、Ulla Eyewear；美妆：Sephora、Bluemercury、Lush","服装和鞋：Macy's、Levi's、lululemon、L.L. Bean、Morgan's Shoes、Stride Rite 等","吃喝：Shake Shack、Sweetgreen、Café Hollander、Crescendo Espresso Bar、bartaco、Bambu、Muramoto Hilldale、FreshFin、Blended","健身运动：solidcore、Title Nine、Morgan's Good Form Running"]},"howto":{"en":["The full list of stores is on hilldale.com under Explore (Store Directory); it also has a PDF map.","The University Book Store at Hilldale is at 454 N Midvale Blvd and keeps the same hours as the center. Phone (608) 238-8455.","Getting here without a car: the nearest Madison Metro stops to the center are listed on this page."],"zh":["完整店铺名单在 hilldale.com 的 Explore（Store Directory）里，还有 PDF 地图。","University Book Store 的 Hilldale 分店在 N Midvale Blvd 454 号，营业时间和购物中心一样。电话 (608) 238-8455。","没车怎么来：离购物中心最近的 Madison Metro 公交站列在本页。"]},"cost":{"en":["Walking around Hilldale costs nothing. Each store sets its own prices.","Hilldale's site states no student discount. Ask each store, and see the Apple Hilldale entry for Apple's education savings."],"zh":["进 Hilldale 逛不要钱，价格由各家店自己定。","Hilldale 官网没写学生折扣，要问各家店。Apple 的教育优惠见 Apple Hilldale 那一条。"]},"tips":{"en":["The Hilldale Farmers Market runs Wednesdays and Saturdays, 8 a.m.–1 p.m., behind L.L. Bean off Segoe Road. The 2026 season ends Oct 31.","Friendly, leashed dogs are welcome at the farmers market.","Hilldale posts a 24-hour security number, seven days a week: (608) 209-1738.","Metcalfe's Market is a grocery store here and is covered in the groceries section; its hours can differ from the mall's."],"zh":["Hilldale 农夫市集 (Farmers Market) 每周三和周六 8:00–13:00，在 L.L. Bean 后面，靠 Segoe Road 一侧。2026 年这一季到 10 月 31 日结束。","农夫市集允许带拴绳的友善狗狗。","Hilldale 公布了每天 24 小时的保安电话：(608) 209-1738。","Metcalfe's Market 是这里的超市，在超市分类里另有一条；它的营业时间可能和商场不同。"],"exp":["2026-10-31",null,null,null]}},"src":[["Hilldale - Contact (address, phone, hours, security)","https://hilldale.com/contact/"],["Hilldale - About (hours)","https://hilldale.com/about/"],["Hilldale - Store Directory","https://hilldale.com/explore/"],["Hilldale - Farmers Market","https://hilldale.com/about/farmers-market/"],["University Book Store - Locations & Hours (Hilldale branch)","https://www.uwbookstore.com/StoreHours"]],"unv":[],"chk":"2026-10-08","lat":43.074452,"lng":-89.451243,"stops":[["N Midvale at University",41,"63"],["Midvale",92,"A F"],["University at N Midvale",95,"63"]]},{"id":"isthmus-true-value-hardware","cat":"shop","n":{"en":"Isthmus True Value Hardware","zh":"Isthmus True Value 五金店"},"kind":{"en":"Hardware store","zh":"五金店"},"addr":"555 W Washington Ave, Madison, WI 53703","phone":"(608) 286-1505","web":"https://www.truevalue.com/find-a-store/wisconsin/9891-isthmus-true-value-hardware/","h":{"Mo":[[480,1080]],"Tu":[[480,1080]],"We":[[480,1080]],"Th":[[480,1080]],"Fr":[[480,1080]],"Sa":[[540,1020]],"Su":[[600,960]]},"ht":{"en":"Mon–Fri 8 a.m.–6 p.m., Sat 9 a.m.–5 p.m., Sun 10 a.m.–4 p.m. (True Value store page, October 2026).","zh":"周一到周五 8:00–18:00，周六 9:00–17:00，周日 10:00–16:00（True Value 门店页面，2026 年 10 月）。"},"sum":{"en":"Small independent hardware store in a former bank near downtown student housing; go for tools, batteries, rope and small home fixes.","zh":"市中心学生公寓区里的独立五金店，开在一栋旧银行楼里，买工具、电池、绳子和修东西的小件。"},"kw":["hardware","五金","hardware store","五金店","tools","工具","batteries","电池","extension cord","插线板","keys","配钥匙","rope","caulk","True Value","Isthmus Hardware","downtown"],"sec":{"about":{"en":["Isthmus True Value Hardware is a True Value store owned by Greg Norman and Jason Shaw, who ran the old Dorn True Value store downtown before it closed in 2018. It opened in early 2021 in a former bank building at the corner of West Washington Avenue and South Bedford Street.","In 2021 the Wisconsin State Journal called it the only hardware store in Madison's Downtown, and said the area around it is full of student housing, apartments and houses. The store is about 3,000 square feet."],"zh":["Isthmus True Value Hardware 是 True Value 连锁的加盟店，老板是 Greg Norman 和 Jason Shaw。他们原来管市中心的 Dorn True Value 店，那家 2018 年关门了。新店 2021 年初开业，在 West Washington Avenue 和 South Bedford Street 路口的一栋旧银行楼里。","2021 年《威斯康星州报》(Wisconsin State Journal) 说它是麦迪逊市中心唯一一家五金店，周围是学生公寓、普通公寓和住宅。店面大约 3,000 平方英尺。"]},"offers":{"en":["General hardware: fuses, batteries, rope, caulk (as reported when the store opened)","Tools and everyday home repair supplies","A local weekly ad and the True Value Rewards program"],"zh":["常见五金件：保险丝、电池、绳子、密封胶 (caulk)（店里开业时的报道）","工具和日常家里修修补补用的东西","有本地每周特价单和 True Value Rewards 会员计划"]},"howto":{"en":["Walk in during store hours. The store phone is (608) 286-1505.","The store page does not list its services. Before you bring a key, call and ask whether they cut keys of that type.","For one specific item (an extension cord, a drill bit), call first, because this is a small store."],"zh":["营业时间内直接进店。店里电话 (608) 286-1505。","门店页面没列服务项目。要配钥匙的话，先打电话问他们能不能配你这种钥匙，再带钥匙过去。","想买某样具体的东西（比如插线板、钻头），先打电话问，因为这是家小店。"]},"cost":{"en":["The pages I read give no prices and no student discount. The store page links to the True Value Rewards program and a local ad."],"zh":["我查的页面里没有价格，也没有学生折扣。门店页面链接了 True Value Rewards 会员计划和本地特价单。"]},"tips":{"en":["Hours come from the True Value store locator. Sunday is the shortest day (10 a.m.–4 p.m.), so call ahead if you need something on a Sunday.","The store is small, about 3,000 square feet, so lumber, big tools and many specialty items may not be in stock. Call to ask."],"zh":["营业时间来自 True Value 的门店查询页。周日最短（10:00–16:00），周日要买东西最好先打电话。","店面小，约 3,000 平方英尺，木材、大件工具和很多专门的东西可能没有现货。先打电话问。"]}},"src":[["True Value - Isthmus True Value Hardware store page","https://www.truevalue.com/find-a-store/wisconsin/9891-isthmus-true-value-hardware/"],["HBSDealer - Isthmus True Value gets in the groove (March 2021)","https://hbsdealer.com/isthmus-true-value-gets-groove"],["The Hardware Connection - Hardware store opens with a drive-thru","https://thehardwareconnection.com/hardware-store-opens-with-a-drive-thru/"],["Wisconsin State Journal - On Retail: Isthmus Hardware seeks help","https://madison.com/business/article_f8425bd6-a5de-53f1-8ddf-9400d17f168d.html"]],"unv":[],"chk":"2026-10-08","lat":43.068759,"lng":-89.392018,"stops":[["W Washington at S Bedford",23,"E 75 81"],["W Washington at N Bedford",43,"E 75"],["W Washington at N Bassett",159,"E 75"]]},{"id":"st-vinnys-thrift-williamson-street","cat":"shop","n":{"en":"St. Vinny's Thrift Store (Williamson Street)","zh":"St. Vinny's 二手店（Williamson Street 店，即 Willy Street 店）"},"kind":{"en":"Thrift store","zh":"慈善二手店"},"addr":"1309 Williamson St, Madison, WI 53703","phone":"(608) 278-2920","web":"https://svdpmadison.org/store/williamson-street-store/","h":{"Mo":[[600,1140]],"Tu":[[600,1140]],"We":[[600,1140]],"Th":[[600,1140]],"Fr":[[600,1140]],"Sa":[[600,1140]],"Su":[[600,1020]]},"ht":{"en":"Store and donation hours are the same: Mon–Sat 10 a.m.–7 p.m., Sun 10 a.m.–5 p.m. (as listed on the store page in October 2026). Holiday hours may differ.","zh":"营业和收捐赠的时间一样：周一到周六 10:00–19:00，周日 10:00–17:00（2026 年 10 月店铺页面所列）。节假日可能不同。"},"sum":{"en":"The original St. Vinny's thrift store on the east side: cheap furniture, kitchenware and clothes, plus donation drop-off for move-out.","zh":"St. Vinny's 的原店，便宜的家具、锅碗和衣服都有，搬家时也能捐东西。"},"kw":["St. Vinny's","St. Vincent de Paul","SVdP","thrift","二手店","Willy Street","Williamson","furniture","二手家具","kitchenware","厨具","winter coat","冬衣","donate","捐赠","voucher","代金券"],"sec":{"about":{"en":["This is the original thrift store of the Society of St. Vincent de Paul — Madison, on Willy Street in the Williamson-Marquette neighborhood on the east side. The store sells donated clothing, furniture, music and household goods, and sales fund the charity's programs in Dane County.","St. Vinny's runs seven stores. Three are in Madison: this one, Odana Road (6301 Odana Road) and the Dig & Save outlet. The other four are in Stoughton, Sun Prairie, Verona and Waunakee."],"zh":["这是 St. Vincent de Paul 麦迪逊分会的原店，开在东区 Williamson-Marquette 街区的 Willy Street 上。店里卖别人捐的衣服、家具、唱片和家居用品，收入用来支持 Dane County 的慈善项目。","St. Vinny's 一共有七家店，麦迪逊市内三家：这家、Odana Road 店（6301 Odana Road）和 Dig & Save 折扣仓；另外四家在 Stoughton、Sun Prairie、Verona 和 Waunakee。"]},"offers":{"en":["Furniture, with a mattress area (the store was remodeled and expanded)","Clothes, including the Rendu section of name-brand and vintage pieces, and dressing rooms","Household goods and kitchenware for setting up an apartment","Music and accessories","Drive-through donation bay for your own move-out","Free home pickup of donated furniture, boxed clothes and small household items"],"zh":["家具，另有床垫区（店面重新装修扩建过）","衣服，其中 Rendu 区是品牌货和复古款，店里有试衣间","家居用品和厨具，布置新公寓够用","唱片和配饰","有开车直接卸货的捐赠口，搬家时可以把不要的东西捐掉","家具、整箱衣服和小件家居用品可以预约上门免费取走"]},"howto":{"en":["The store page lists a phone with extension: (608) 278-2920, then extension 199 for this store.","To donate, drive to the drive-through bay at the store and hand over your donation. Do not leave items unattended near the drop-off area.","Pack small items in a fully enclosed box or bag. Keep furniture assembled in most cases.","Free home pickup is booked on the St. Vinny's donation page; ask the receptionist if a piece must be taken apart first.","The Tax Donation Receipt for donated goods is a form you download from the donation page."],"zh":["店铺页面写的电话带分机：打 (608) 278-2920，再拨分机 199 就是这家店。","要捐东西就开车到店里的 drive-through 卸货口交给工作人员。别把东西丢在卸货区无人看管。","小件东西装进封好的箱子或袋子。大多数情况下家具要保持组装好的状态。","上门免费取货在 St. Vinny's 捐赠页面预约；某件家具要不要先拆开，可以问接待员。","捐赠物品的税务收据 (Tax Donation Receipt) 是一张表，从捐赠页面下载。"]},"cost":{"en":["Item prices are marked in the store; the website lists no price list.","Clothing vouchers are worth $50 per eligible adult and can be redeemed at any St. Vinny's store in Dane County. You may qualify every six months.","Furniture vouchers: you may qualify once every five years. They are filled at the Dig & Save outlet, by appointment, and St. Vinny's does not deliver.","Both vouchers require that you live in Dane County. St. Vinny's says all assistance is given without regard to documented status."],"zh":["店里每件东西自己标价，官网没有价目表。","衣物券 (clothing voucher) 每位符合条件的成年人 $50，可以在 Dane County 任何一家 St. Vinny's 使用，每 6 个月可以申请一次。","家具券 (furniture voucher) 每 5 年可以申请一次。要在 Dig & Save 折扣仓预约领取，St. Vinny's 不送货。","两种券都要求住在 Dane County。St. Vinny's 说所有援助不看是否有合法身份 (documented status)。"]},"tips":{"en":["For winter clothes on a budget, also check Dig & Save at 1900 S. Park Street. It is a pay-by-the-pound outlet: clothing is $1.50 per pound, and it is open 10 a.m.–5 p.m. daily.","Furniture, electronics and large items at Dig & Save are priced one by one, not by weight.","The store page does not say whether it delivers purchases. Plan how to carry furniture home, or use a rideshare or a friend's car.","At move-out, a drive-through donation or a free home pickup is easier than leaving furniture on the curb.","Check the St. Vinny's events page for special sales; the site says to arrive early because items sell fast."],"zh":["想便宜地买冬衣，也可以去 1900 S. Park Street 的 Dig & Save 折扣仓。那里按重量卖：衣服 $1.50 一磅，每天 10:00–17:00 开。","Dig & Save 的家具、电子产品和大件东西是单件标价，不按重量。","店铺页面没写买的东西能不能送货。要想好家具怎么带回去，用网约车或朋友的车。","搬家时，开车去卸货口捐掉，或者约上门免费取货，比把家具扔路边省事。","St. Vinny's 的活动页有特卖信息；官网提醒要早点到，东西很快被拿走。"]},"intl":{"en":["To apply for a clothing or furniture voucher you call the number below. The site does not list an ID requirement, so ask on the phone what to bring.","Clothing voucher line: (608) 278-2920. Furniture voucher and general help line: (608) 257-0919, Mon–Fri 8 a.m.–4:30 p.m."],"zh":["申请衣物券或家具券要打电话。官网没写要什么证件，电话里问清楚要带什么。","衣物券电话 (608) 278-2920；家具券和综合求助电话 (608) 257-0919，周一到周五 8:00–16:30。"]}},"src":[["St. Vinny's - Williamson Street Store","https://svdpmadison.org/store/williamson-street-store/"],["St. Vinny's Thrift Stores","https://svdpmadison.org/shop/"],["St. Vinny's - Donate Goods","https://svdpmadison.org/donate/donate-goods/"],["St. Vinny's - Clothing Vouchers","https://svdpmadison.org/program/clothing/"],["St. Vinny's - Furniture Vouchers","https://svdpmadison.org/program/furniture/"],["St. Vinny's - Get Help","https://svdpmadison.org/get-help/"],["St. Vinny's - Dig & Save Outlet Store","https://svdpmadison.org/store/dig-save-store/"]],"unv":[],"chk":"2026-10-08","lat":43.084581,"lng":-89.361929,"stops":[["Williamson at S Baldwin",22,"C 38"],["S Baldwin at Williamson",54,"C 38"],["Jenifer at S Few",238,"C 38"]]},{"id":"university-book-store-state-street","cat":"shop","n":{"en":"University Book Store (State Street)","zh":"University Book Store 校园书店（State Street 店）"},"kind":{"en":"Campus bookstore","zh":"校园书店"},"addr":"711 State St, Madison, WI 53703","phone":"(608) 257-3784","web":"https://www.uwbookstore.com/StoreHours","h":{"Mo":[[540,1140]],"Tu":[[540,1140]],"We":[[540,1140]],"Th":[[540,1140]],"Fr":[[540,1050]],"Sa":[[540,1050]],"Su":[[630,1020]]},"ht":{"en":"Fall 2026: Mon–Thu 9 a.m.–7 p.m., Fri–Sat 9 a.m.–5:30 p.m., Sun 10:30 a.m.–5 p.m. Special hours Fri Oct 23 (9 a.m.–7 p.m.) and Sat Oct 24 (8:30 a.m.–5:30 p.m.). IKEA order pick-up has its own shorter hours.","zh":"2026 年秋季：周一到周四 9:00–19:00，周五、周六 9:00–17:30，周日 10:30–17:00。10 月 23 日（周五）9:00–19:00、10 月 24 日（周六）8:30–17:30 是特殊营业时间。IKEA 取货有单独的、更短的时间。"},"sum":{"en":"UW's main bookstore on the Library Mall: textbooks and rentals, Badger gear, dorm and school supplies, and a Tech Center for laptops.","zh":"图书馆广场旁的学校主书店：买租教材、Badger 周边、宿舍文具，还有卖电脑的 Tech Center。"},"kw":["University Book Store","UBS","bookstore","书店","textbooks","教材","textbook rental","租教材","Badger gear","校服","Tech Center","laptop","笔记本电脑","MacBook","IKEA pickup","IKEA 取货","price match","State Street","Library Mall"],"sec":{"about":{"en":["The University Book Store has served UW–Madison since 1894. The flagship store at 711 State St is on the Library Mall, across from the Memorial Library. It is a local store, not a national chain.","It has departments for clothing and gifts, school and dorm supplies, tech, books and textbooks, plus a Moka Coffee Bar. Its Tech Department is listed as an authorized campus store."],"zh":["University Book Store 从 1894 年起就在服务 UW–Madison。主店在 State Street 711 号，Library Mall 旁边，正对 Memorial Library。它是本地店，不是全国连锁。","店里分服装礼品、学习和宿舍用品、电子产品、图书和教材几个部门，还有一家 Moka Coffee Bar 咖啡吧。电子产品部门标明是授权校园商店 (Authorized Campus Store)。"]},"offers":{"en":["Textbooks and course materials, new and used, plus rentals","Official Badger clothing, gifts and accessories for men, women and kids","Dorm, school and office supplies, fine pens and art supplies, custom framing","Tech Center: Apple (MacBook, iPad, AirPods, Apple Watch), Dell, Lenovo and Microsoft Surface, plus calculators, cables, cases and headphones","Campus Shipping Center inside the store","IKEA order pick-up: order online from IKEA and collect the order here"],"zh":["教材和课程资料：新书、二手书，也能租","官方 Badger 服装、礼品和周边，男装、女装、童装都有","宿舍、学习和办公用品，高档笔、美术用品，还能做装裱 (custom framing)","Tech Center：Apple（MacBook、iPad、AirPods、Apple Watch）、Dell、Lenovo、微软 Surface，以及计算器、数据线、保护壳、耳机","店里设有校园快递中心 (Campus Shipping Center)","IKEA 订单取货：在 IKEA 官网下单，到这里取货"]},"howto":{"en":["Look up your course list on the store's textbook pages (\"Check Your Schedule\") to see what each class needs.","Tech Center questions or orders: email tech@uwbookstore.com or call 608-310-5927.","IKEA pick-up is on the 711 State St store's schedule: Mon–Thu 10 a.m.–5:30 p.m., Fri–Sat 10 a.m.–5 p.m., Sun noon–4:30 p.m. The shipping center closes half an hour before the store.","Rental books go back to the text department. Tell the employee that the book was a rental."],"zh":["在书店网站的 “Check Your Schedule” 里填课程，就能看到每门课要什么书。","Tech Center 咨询或下单：发邮件到 tech@uwbookstore.com，或打 608-310-5927。","IKEA 取货时间：周一到周四 10:00–17:30，周五、周六 10:00–17:00，周日 12:00–16:30。快递中心比书店早半小时关门。","租的书要还到教材部 (text department)，还书时告诉店员这是租的。"]},"cost":{"en":["Textbook price match: the store matches the price of a new textbook (same ISBN) from Amazon, Barnes & Noble and other qualified US sellers. Show the lower price within three days of buying; you get the difference as a store gift card, up to $100 per item.","Price match does not cover rentals, used or digital books, access codes or international editions.","Rentals: no extra fee if you return the book by the last day of exams in resalable condition. A lost or damaged rental is charged the shelf price minus what you paid to rent, plus a 20% fee.","Tech returns: within 15 days, with receipt, in new condition. An opened but resalable item has a 15% restocking fee. Opened computers and iPads may not be returnable at all.","No student or education discount for tech is stated on the Tech Center page."],"zh":["教材比价 (price match)：同一 ISBN 的新书，如果 Amazon、Barnes & Noble 等合格美国卖家更便宜，书店会按那个价。买后三天内拿出更低价格，差价以书店礼品卡形式退给你，每本最多 $100。","二手书、租书、电子书、访问码 (access code) 和国际版不在比价范围内。","租书：只要在期末考试最后一天前还回、书况能再卖，就没有额外费用。丢了或损坏，按书架标价减去租金，再加 20% 手续费收费。","电子产品退货：15 天内、带收据、全新状态。拆封但还能卖的收 15% 重新上架费 (restocking fee)。拆封的电脑和 iPad 可能完全不能退。","Tech Center 页面上没有写学生折扣或教育优惠。"]},"tips":{"en":["The Tech Center gives only basic triage and limited tech service. For full Apple repair the store points you to the Apple Store at Hilldale; for Windows devices, contact the maker for warranty or authorized repair.","For NetID, Duo, campus network or virus problems, use the DoIT Help Desk, not the bookstore.","IKEA orders can be picked up here; check IKEA's own site for what it can deliver to a pick-up point. IKEA has also announced a small Madison store at 215 Junction Rd (far west side), scheduled for fall 2026 with no fixed date.","Online orders from the store cannot ship internationally at this time. Ship things to a US address, or buy in store.","Special hours on Fri Oct 23 and Sat Oct 24 are for that weekend only."],"zh":["Tech Center 只做基础排查和有限的技术服务。苹果设备要全面检修，书店建议去 Hilldale 的 Apple Store；Windows 设备请联系厂家走保修或授权维修。","NetID、Duo、校园网或中毒问题，去 DoIT Help Desk，不是书店。","IKEA 的订单可以送到这里取，能不能送到取货点看 IKEA 官网的说明。另外 IKEA 已宣布在西边 215 Junction Rd 开一家小店，计划 2026 年秋天开，没有确切日期。","书店网店目前不能寄国际地址。东西请寄美国地址，或者直接到店买。","10 月 23 日（周五）和 24 日（周六）的特殊营业时间只适用于那个周末。"],"exp":[null,null,null,null,"2026-10-24"]},"intl":{"en":["Online orders cannot ship outside the US right now, so buy in store or use a US address."],"zh":["网店订单目前不能寄到美国以外，所以到店买，或者填美国地址。"]}},"src":[["University Book Store - Location & Hours","https://www.uwbookstore.com/StoreHours"],["University Book Store - Location & Hours (text site)","https://text.uwbookstore.com/StoreHours"],["University Book Store - About Us","https://text.uwbookstore.com/StoreAbout"],["University Book Store - Tech Center","https://www.uwbookstore.com/Tech"],["University Book Store - Customer Help (returns, rental FAQ)","https://www.uwbookstore.com/Customer-Help"],["University Book Store - Price Match Guarantee","https://www.uwbookstore.com/Price-Match"],["In Business Madison - IKEA opens pickup location at University Book Store","https://www.ibmadison.com/business-report/ikea-opens-pickup-location-at-university-book-store-on-state-street-mall/article_c32e11d1-037c-4804-86a9-9d40e9023d3c.html"],["The Daily Reporter - IKEA to open 54,000-square-foot store in Madison (May 2026)","https://dailyreporter.com/2026/05/07/ikea-open-54000-square-foot-store-madison-fall-2026/"]],"unv":[],"chk":"2026-10-08","lat":43.074668,"lng":-89.397843,"stops":[["N Lake at Langdon",109,"80 82"],["Langdon at N Lake",135,"81"],["East Campus",167,"B"]]},{"id":"uw-swap-surplus-with-a-purpose","cat":"shop","n":{"en":"UW SWAP (Surplus With A Purpose)","zh":"UW SWAP 学校二手拍卖（Surplus With A Purpose）"},"kind":{"en":"University surplus auction","zh":"学校淘汰品拍卖"},"addr":"1061 Thousand Oaks Trail, Verona, WI 53593","phone":"(608) 497-4420","web":"https://veronaoperations.businessservices.wisc.edu/swap/public/","h":{"Mo":[[510,930]],"Tu":[[510,930]],"We":[[510,930]],"Th":[[510,930]],"Fr":[[510,930]],"Sa":[],"Su":[]},"ht":{"en":"Payments and pick-up only, Mon–Fri 8:30 a.m.–3:30 p.m. Closed on state holidays. There is no walk-in shopping for the public: you buy online, then collect.","zh":"只办付款和取货，周一到周五 8:30–15:30，州假日不开。没有对外开放的逛店时间：先在网上拍，再去取。"},"sum":{"en":"UW sells its used desks, chairs, shelves and electronics through an online auction; you collect your win at the Verona warehouse.","zh":"学校把淘汰的桌椅、书架、电子设备放到网上拍卖，拍到后自己去 Verona 仓库取货。"},"kw":["SWAP","surplus","UW surplus","auction","拍卖","second-hand furniture","二手家具","office chair","办公椅","desk","书桌","Verona","swapauction.wisc.edu"],"sec":{"about":{"en":["SWAP is the university's surplus department at the Verona Operations building. It first offers unwanted campus property to other UW departments and public agencies, and sells what is left to the public.","Since March 2020, SWAP sells only online. The old in-person public sales ended, and the Verona building is a pick-up point, not a store you can browse."],"zh":["SWAP 是学校处理淘汰物品的部门，设在 Verona Operations 大楼。校内别的部门和州政府机构先挑，剩下的卖给公众。","2020 年 3 月起 SWAP 只在网上卖。以前的线下公开销售已经没有了，Verona 那栋楼现在只是取货点，不是能逛的商店。"]},"offers":{"en":["Furniture: desks, chairs, bookcases, file cabinets (the largest category on the auction site)","Electronics and computer accessories","Shop tools, lab and business equipment, bikes, household items","New items are added every weekday","Auction listings and some \"Buy Now\" fixed-price listings"],"zh":["家具：书桌、椅子、书架、文件柜（拍卖网站上数量最多的一类）","电子产品和电脑配件","工具、实验和办公设备、自行车、家居杂物","每个工作日都会上新","有竞拍，也有一口价 (Buy Now) 的商品"]},"howto":{"en":["Register and bid at swapauction.wisc.edu. Read each listing's description and photos closely, because you cannot walk in and look at items first.","After you win, an invoice comes by email. Pay online or call (608) 497-4420; payment details sent by voicemail or email will not be processed.","Pick-up is at the northeast corner of the building: from the main parking lot, go left to the bay #2 overhead door and ring the doorbell next to the walk-in door.","You can inspect the item at the loading dock before taking it. If it does not match the listing, you get a refund; once it leaves the premises there are no refunds or exchanges.","First-time buyers of a computer, and any purchase over $1,000, must show a government-issued photo ID and the invoice. The name must match the auction account."],"zh":["在 swapauction.wisc.edu 注册并出价。出价前把商品描述和照片看仔细，因为没法先走进仓库看实物。","拍到后会收到电子邮件发票。可以在线付款，或打 (608) 497-4420；通过语音留言或邮件发来的付款信息不会被处理。","取货口在大楼东北角：从主停车场进去后往左走到 2 号卸货门 (bay #2)，按 walk-in 门旁边的门铃。","取货时可以在装卸台当场检查。和描述不符就能退款；东西一旦离开学校场地，不退不换。","第一次买电脑的人，以及任何超过 $1,000 的订单，取货时要出示政府签发的带照片证件和发票，姓名必须和拍卖账号一致。"]},"cost":{"en":["Prices come from bidding. On Oct 8, 2026 a chair was listed at a $7 Buy Now price and another office chair at $50; a lot of 2 tall bookcases sold for $37.","Sales delivered in Wisconsin carry 5.5% sales tax.","Pay within 5 business days of the winning-bid notice, and remove the item within 10 business days of the invoice, or it may be disposed of and the payment lost.","SWAP does not ship, and it does not pack or load for you. Buyers pay for their own transport."],"zh":["价格靠竞拍。2026 年 10 月 8 日网站上有一把椅子一口价 $7，另一把办公椅 $50；两个高书架一组以 $37 成交。","送到威斯康星州内的订单要加 5.5% 销售税。","中标通知后 5 个工作日内付款，发票开出后 10 个工作日内把东西拿走，否则可能被处理掉，已付的钱也拿不回来。","SWAP 不寄送，也不帮你打包装车，运输费用自己出。"]},"tips":{"en":["Verona is outside Madison. Plan the ride before you bid: bring a friend with a car, or book a rideshare big enough for a chair or desk.","Public customers should bring someone to help with hand-loading. SWAP can load with a forklift if you ask.","Do not make a trip for one cheap item. Bundle several wins into one pick-up day.","A third person can pick up for you only with prior written authorization from SWAP.","Public Surplus is a different auction site that SWAP also links to. Check which site a listing is on before you bid."],"zh":["Verona 在麦迪逊市区外面。出价前先想好怎么去：找有车的朋友，或者叫一辆装得下椅子、桌子的网约车。","公众买家最好带人帮忙搬。需要的话可以提前联系，SWAP 能用叉车帮你装。","别为一件便宜东西专门跑一趟。几件拍到的东西攒一起，一次取走。","别人替你取货，要提前拿到 SWAP 的书面授权。","Public Surplus 是另一个拍卖网站，SWAP 的页面也会链到它。出价前先看清这件商品在哪个网站上。"]},"intl":{"en":["Some categories of items (for example lab and technical equipment) may need citizenship verification for export control at pick-up. Ask SWAP before bidding on those.","Bring a government-issued photo ID when you pick up a computer or any purchase over $1,000. The terms do not list which kinds of ID count, so ask SWAP if you only have a passport."],"zh":["有些类别的物品（比如实验和技术设备）取货时可能要核实国籍，用于出口管制。想拍这类东西前，先问 SWAP。","取电脑或任何超过 $1,000 的订单，要带政府签发的带照片证件。条款没写哪些证件算数，如果你只有护照，先问 SWAP。"]}},"src":[["Verona Operations - SWAP: For the Public","https://veronaoperations.businessservices.wisc.edu/swap/public/"],["Verona Operations - Surplus With A Purpose (SWAP)","https://veronaoperations.businessservices.wisc.edu/swap/"],["SWAP Online Auction - home","https://swapauction.wisc.edu/"],["SWAP Online Auction - Terms and Conditions","https://swapauction.wisc.edu/Home/Terms"]],"unv":[],"chk":"2026-10-08","lat":42.969484,"lng":-89.505364,"stops":[]},{"id":"walmart-supercenter-monona","cat":"shop","n":{"en":"Walmart Supercenter (Monona, Royal Ave)","zh":"Walmart 沃尔玛大超市（Monona 店，Royal Ave）"},"kind":{"en":"Discount superstore","zh":"平价大超市"},"addr":"2151 Royal Ave, Monona, WI 53713","phone":"(608) 226-0913","web":"https://www.walmart.com/store/3857-monona-wi","h":{"Mo":[[360,1380]],"Tu":[[360,1380]],"We":[[360,1380]],"Th":[[360,1380]],"Fr":[[360,1380]],"Sa":[[360,1380]],"Su":[[360,1380]]},"ht":{"en":"Store open daily 6 a.m.–11 p.m. Sensory-friendly hours daily 8–10 a.m. Service Desk daily 8 a.m.–10 p.m. The pharmacy, auto care and other counters keep their own hours; check the store page.","zh":"商店每天 6:00–23:00 营业。感官友好时段 (sensory-friendly hours) 每天 8:00–10:00。服务台 (Service Desk) 每天 8:00–22:00。药房、汽车保养等柜台有各自的时间，看商店页面。"},"sum":{"en":"The Walmart Supercenter closest to campus: groceries, dorm basics and a pharmacy, plus online pickup and delivery. Open daily 6 a.m.–11 p.m.","zh":"离校园最近的 Walmart 大超市：食品、宿舍用品、药房都有，每天 6:00–23:00，可网上订货取货或送货。"},"kw":["Walmart","沃尔玛","supermarket","超市","Monona","Royal Ave","dorm supplies","宿舍用品","bedding","床品","pharmacy","药房","flu shot","流感疫苗","grocery pickup","grocery delivery","取货","送货","Walmart+","Walmart+ Student","学生会员","cheap","平价"],"sec":{"about":{"en":["Walmart Supercenter #3857 is at 2151 Royal Ave in Monona, the small city next to Madison's southeast side. Of the Madison-area Walmart stores it is the closest to campus.","It is a full-size store: groceries with a bakery and deli, a liquor department, clothing, electronics, home goods and a pharmacy under one roof."],"zh":["Walmart Supercenter #3857 在 Monona 的 Royal Ave 2151 号。Monona 是紧挨着麦迪逊东南边的小城。麦迪逊一带的 Walmart 里，这家离校园最近。","这是一家完整规模的大店：食品（有面包房和熟食区）、酒类、衣服、电子产品、家居用品和药房都在一个屋顶下。"]},"offers":{"en":["Groceries, bakery and deli","Dorm and apartment basics: the store lists bedding, kitchen supplies, furniture, school supplies and luggage departments","Electronics, plus a wireless services counter","Pharmacy with flu shots and other immunizations","Vision Center, Photo Center and Auto Care Center","Grocery Pickup and Delivery from this store","Financial Services counter, open daily 7 a.m.–10 p.m."],"zh":["食品、面包房和熟食区","宿舍和公寓日用品：商店页面列有床品、厨房用品、家具、学习用品和行李箱等部门","电子产品，另有手机业务柜台 (wireless services)","药房，可以打流感疫苗和其他疫苗","配镜中心 (Vision Center)、照片冲印 (Photo Center)、汽车保养 (Auto Care Center)","这家店提供网上订货后取货和送货 (Grocery Pickup and Delivery)","金融服务柜台 (Financial Services)，每天 7:00–22:00"]},"howto":{"en":["To order online for pickup or delivery, choose this store (\"Make this my store\") on walmart.com or in the Walmart app first.","The Service Desk is open daily 8 a.m.–10 p.m.","For a flu shot or other immunization, call the pharmacy at (608) 226-8671.","Getting here without a car: the Madison Metro stops nearest to the store are listed on this page. If the trip is too long for heavy items, order pickup or delivery instead."],"zh":["想网上下单取货或送货，先在 walmart.com 或 Walmart App 里把这家店设成你的店 (\"Make this my store\")。","服务台每天 8:00–22:00 开。","打流感疫苗或其他疫苗，打药房电话 (608) 226-8671。","没车怎么来：离这家店最近的 Madison Metro 公交站列在本页。东西太重不好带，就改用取货或送货。"]},"cost":{"en":["Walmart+ membership gives free delivery from the store on orders over $35 (as of October 2026).","Walmart+ Student: college students can join for $49 a year or $6.47 a month (as of October 2026), half the regular price.","Without Walmart+, delivery has fees. The Walmart+ page puts non-member Express delivery fees at $17.95–$19.95, and says fees may vary by location."],"zh":["加入 Walmart+ 会员后，从这家店送货、订单超过 $35 免运费（2026 年 10 月的信息）。","Walmart+ Student：大学生每年 $49 或每月 $6.47（2026 年 10 月的信息），是正常价格的一半。","不是会员的话，送货要收费。Walmart+ 页面写非会员的加急送货 (Express) 费用是 $17.95–$19.95，各地可能不同。"]},"tips":{"en":["Sensory-friendly hours run daily 8–10 a.m.: the store describes them as a calmer shopping environment. Good if crowds and noise bother you.","The two other Walmart Supercenters in Madison are at 4198 Nakoosa Trl (east side) and 7202 Watts Rd (west side). Both are farther from campus.","IKEA announced a small Madison store at 215 Junction Rd (Prairie Towne Center), planned for fall 2026 with no firm opening date. Check ikea.com for the date before you plan a furniture trip."],"zh":["感官友好时段每天 8:00–10:00：商店说这段时间购物环境更安静。怕人多、怕吵就挑这个点来。","麦迪逊另外两家 Walmart Supercenter 在 Nakoosa Trl 4198 号（东边）和 Watts Rd 7202 号（西边），都比这家离校园远。","IKEA 宣布要在 Junction Rd 215 号（Prairie Towne Center）开一家小店，计划 2026 年秋天开，还没有确切日期。要买家具先去 ikea.com 查开业日期。"],"exp":[null,null,"2026-12-31"]}},"src":[["Walmart Supercenter #3857 - Monona, WI","https://www.walmart.com/store/3857-monona-wi"],["Walmart+ Free Delivery","https://www.walmart.com/plus/free-delivery"],["WPR - IKEA to open second Wisconsin location with new store in Madison","https://www.wpr.org/economy/ikea-second-wisconsin-location-madison"],["Hoodline - IKEA moves into Madison's big-box ghost with bite-size store","https://hoodline.com/2026/05/ikea-moves-into-madison-s-big-box-ghost-with-bite-size-store/"]],"unv":[],"chk":"2026-10-08","lat":43.0424673,"lng":-89.3498957,"stops":[["South Towne at Royal",343,"G 61 64"],["South Towne at Industrial",452,"G 61 64"],["W Broadway at Frazier",511,"G 61 64"]]},{"id":"west-towne-mall","cat":"shop","n":{"en":"West Towne Mall","zh":"West Towne Mall 购物中心"},"kind":{"en":"Shopping mall","zh":"室内购物中心"},"addr":"66 West Towne Mall, Madison, WI 53719","phone":"(608) 833-6330","web":"https://www.shopwesttowne-mall.com/","h":{"Mo":[[600,1200]],"Tu":[[600,1200]],"We":[[600,1200]],"Th":[[600,1200]],"Fr":[[600,1200]],"Sa":[[600,1200]],"Su":[[660,1080]]},"ht":{"en":"Mall hours: Mon–Sat 10 a.m.–8 p.m., Sun 11 a.m.–6 p.m. Stores with outside doors may keep their own hours. Thanksgiving: closed Thu Nov 26; Fri Nov 27 is 7 a.m.–9 p.m.","zh":"商场营业时间：周一到周六 10:00–20:00，周日 11:00–18:00。有外门的店可能有自己的时间。感恩节：11 月 26 日（周四）关门，11 月 27 日（周五）7:00–21:00。"},"sum":{"en":"Big indoor mall on the West Side: Sephora, Von Maur, The Cheesecake Factory, a fitness center, an arcade and a spa.","zh":"西区的大型室内商场：有 Sephora、Von Maur、Cheesecake Factory、健身房和游戏厅。"},"kw":["West Towne Mall","West Towne","mall","商场","购物中心","Sephora","Von Maur","Cheesecake Factory","Nordstrom Rack","Barnes & Noble","ULTA","Pandora","Athleta","arcade","游戏厅","Black Friday","黑五","bus","公交"],"sec":{"about":{"en":["West Towne Mall is an indoor mall at 66 West Towne Mall on Madison's West Side. The mall's site lists national retailers such as Athleta, Dry Goods, Sephora, The Cheesecake Factory and Pandora, and the department store Von Maur.","Open-air centers attached to the mall add Nordstrom Rack, Barnes & Noble and ULTA. The site also lists a spa, an arcade and a fitness center."],"zh":["West Towne Mall 是室内商场，在麦迪逊西区，地址 66 West Towne Mall。商场官网列出的全国品牌有 Athleta、Dry Goods、Sephora、The Cheesecake Factory、Pandora，还有百货店 Von Maur。","商场旁边连着的露天区还有 Nordstrom Rack、Barnes & Noble 和 ULTA。官网还列了水疗、游戏厅 (arcade) 和健身中心。"]},"offers":{"en":["Clothes, beauty and gifts: Sephora, Athleta, Pandora, Von Maur","Nordstrom Rack, Barnes & Noble and ULTA in the attached open-air centers","Dining: The Cheesecake Factory, plus smaller food spots such as Mocha Boba and Flame N Crepe","Spa treatments, specialty services, an arcade and a fitness center","Black Friday and holiday sales; see the mall's Deals page"],"zh":["衣服、美妆、礼物：Sephora、Athleta、Pandora、Von Maur","连着的露天区有 Nordstrom Rack、Barnes & Noble 和 ULTA","吃饭：The Cheesecake Factory，还有 Mocha Boba、Flame N Crepe 这类小店","水疗、各类服务、游戏厅和健身中心","黑五和节日促销，看商场官网的 Deals 页"]},"howto":{"en":["Check the mall's directory page for each store's own hours before you go.","Mall management: (608) 833-6330. Mall security: (608) 347-1626.","Getting here without a car: the nearest Madison Metro stops are listed on this page. It is on the West Side, so allow time for the ride from campus."],"zh":["出发前在商场官网的 Directory 页查各家店自己的营业时间。","商场管理处：(608) 833-6330。商场保安：(608) 347-1626。","没车怎么来：离商场最近的 Madison Metro 公交站列在本页。它在西区，从校园过来要留出车程的时间。"]},"cost":{"en":["Entering and walking around the mall is free. Each store sets its own prices.","The mall's site states no student discount. Ask each store."],"zh":["进商场逛不要钱，价格由各家店定。","商场官网没写学生折扣，要问各家店。"]},"tips":{"en":["Thanksgiving week: closed Thu Nov 26, then open 7 a.m.–9 p.m. on Fri Nov 27, then back to normal hours on Sat Nov 28.","Some businesses have outside doors and can open and close at different times from the mall.","East Towne Mall on the east side has the same mall hours; it has Dick's Sporting Goods, JCPenney and a movie theater instead (see its entry)."],"zh":["感恩节那周：11 月 26 日（周四）关门，11 月 27 日（周五）7:00–21:00 营业，11 月 28 日（周六）恢复正常时间。","有些店有对外的门，开关门时间可能和商场不同。","东边的 East Towne Mall 商场营业时间一样；那边是 Dick's Sporting Goods、JCPenney 和电影院（见它自己那一条）。"],"exp":["2026-11-30",null,null]}},"src":[["West Towne Mall - About (address, phone, retailers)","https://www.shopwesttowne-mall.com/about"],["West Towne Mall - Hours","https://www.shopwesttowne-mall.com/hours"],["West Towne Mall - Home","https://www.shopwesttowne-mall.com/"],["East Towne Mall - About","https://www.shopeasttowne-mall.com/about"],["East Towne Mall - Hours","https://www.shopeasttowne-mall.com/hours"]],"unv":[],"chk":"2026-10-08","lat":43.0571926,"lng":-89.5060214,"stops":[["West Towne Ring at West Towne Mall",166,"H J"],["S Gammon at Odana",279,"H J"],["Odana at S Gammon",310,"J"]]},{"id":"badger-bus-uw-campus","cat":"transport","n":{"en":"Badger Bus (UW Campus stop)","zh":"Badger Bus 长途巴士（UW 校园站）"},"kind":{"en":"Bus to Milwaukee","zh":"去密尔沃基的巴士"},"addr":"200 N Lake St, Madison, WI 53703","phone":"","web":"https://badgerbus.com/pickup-dropoff-locations","h":null,"ht":{"en":"Curb stop, no office. Madison to Milwaukee departures from the N Lake St stop: 6:30 a.m., 10 a.m., 3 p.m. and 5:30 p.m. daily, plus 12:30 p.m. and 8:45 p.m. on Fridays and Sundays (Badger Bus schedule page, October 2026). Schedules can change, so check the ticket site.","zh":"这是路边站，没有办公室。从 N Lake St 站去密尔沃基每天 6:30、10:00、15:00、17:30 发车，周五和周日另加 12:30 和 20:45（Badger Bus 时刻表页，2026 年 10 月）。时刻可能变，以购票网站为准。"},"sum":{"en":"Badger Bus runs from N Lake St on campus to Milwaukee's Mitchell Airport and the downtown Amtrak station, with extra Friday and Sunday trips.","zh":"Badger Bus 从校园旁 N Lake St 发车，去密尔沃基机场和市中心 Amtrak 站，周五周日加班。"},"kw":["Badger Bus","bus","巴士","大巴","Milwaukee","密尔沃基","Mitchell airport","MKE","机场","Amtrak","Minneapolis","Mall of America","Lake Street","luggage","行李"],"sec":{"about":{"en":["Badger Bus is a Madison bus company. Its UW Madison Campus stop is in the 200 block of N Lake St, across the street from Witte Hall. The bus picks up on N Lake St between Johnson St and Dayton St, by the two city bus shelters.","The same block is also Van Galder's stop for Chicago buses. Make sure you stand where the Badger Bus sign is."],"zh":["Badger Bus 是一家麦迪逊本地的巴士公司。UW Madison Campus 站在 N Lake St 的 200 号段，Witte Hall 对面。车停在 N Lake St，Johnson St 和 Dayton St 之间，两个市内公交候车亭旁边。","同一段路也是 Van Galder 去芝加哥的上车点，别站错，要找 Badger Bus 的牌子。"]},"offers":{"en":["Six daily trips between UW Madison, Johnson Creek, Goerke's Corners, the Milwaukee Amtrak Intermodal station and Milwaukee Mitchell Airport.","Mitchell Airport: the bus picks up and drops off outside Baggage Claim Door #2.","Milwaukee Intermodal (Amtrak and Greyhound station), 433 W St Paul Ave, Gate 6: the only downtown Milwaukee stop.","Fridays and Sundays: extra trips to Menomonie, Eau Claire, IKEA at the Mall of America, and the University of Minnesota.","Onboard WiFi and a restroom on every bus."],"zh":["每天 6 班车，连接 UW Madison、Johnson Creek、Goerke's Corners、密尔沃基 Amtrak Intermodal 车站和 Milwaukee Mitchell 机场。","Mitchell 机场：车在 Baggage Claim 2 号门外上下客。","Milwaukee Intermodal（Amtrak 和 Greyhound 车站），433 W St Paul Ave，6 号门：这是市中心唯一的一站。","周五和周日加开去 Menomonie、Eau Claire、Mall of America 旁的 IKEA 和明尼苏达大学的车。","每辆车都有车载 WiFi 和洗手间。"]},"howto":{"en":["Buy a ticket online on Badger Bus's ticket site. You do not need an account. Online tickets must be bought at least 30 minutes before the first stop on the route to guarantee a seat.","Be at the stop 10 to 15 minutes before departure. Drivers do not come inside any buildings to announce departures, and many stops are \"load and go\".","Show the email confirmation to the driver when you board.","No online ticket? You can pay the driver in exact-change cash, one way only. You board after online passengers, if there is space.","Questions about tickets or schedules: email ticketinfo@badgerbus.com. Badger Bus asks you not to call about schedules."],"zh":["在 Badger Bus 的购票网站上网购，不需要注册账号。要保证有座，网票必须在这条线第一个站发车前至少 30 分钟买。","发车前 10 到 15 分钟到站。司机不会进楼里喊人，很多站是「到了就走」(load and go)。","上车时给司机看邮件确认单。","没买网票的话，可以向司机付现金，只能付准确的零钱，只卖单程。你要等网票乘客上完，有空位才能上。","票务和时刻问题发邮件到 ticketinfo@badgerbus.com。Badger Bus 要求不要打电话问时刻。"]},"cost":{"en":["Cash fares on the bus are higher than online fares. Madison to Milwaukee Intermodal is $30 cash, and Madison to Milwaukee Airport is $35 cash.","Online tickets are non-refundable. You can change the date or time for a 10% fee, at least 1 hour before departure.","Online payment accepts Visa or Mastercard.","Bags: each adult ticket allows 1 piece of luggage under the bus and 1 small carry-on. A second piece under the bus costs $5.","A bicycle costs $10 each way, in exact-change cash only."],"zh":["车上付现金比网购贵。麦迪逊到 Milwaukee Intermodal 现金 $30，到 Milwaukee 机场现金 $35。","网购车票不能退。出发前至少 1 小时可以改日期或时间，收 10% 手续费。","网上付款接受 Visa 或 Mastercard。","行李：每张成人票可以放 1 件到车底，加 1 件小随身包。车底第 2 件收 $5。","自行车每程 $10，只收准确的零钱现金。"]},"tips":{"en":["Buy online to guarantee a seat. Badger Bus calls Fridays, Sundays and holiday travel days \"high travel days\".","Under-bus bags must weigh no more than 50 pounds and be fully enclosed.","Badger Bus does not guarantee arrival times and does not refund a missed flight or connection. Give yourself a buffer before an international flight.","A child aged 2 to 11 travelling with a full-fare adult is half price if the tickets are bought together.","Other Madison stops (E Johnson St at N Pinckney St, E Washington Ave) are online-only. The Lake St stop is the one for campus."],"zh":["网购才能保证有座。Badger Bus 把周五、周日和节假日出行日称为「高峰日」(high travel days)。","放车底的行李不能超过 50 磅，而且要完全封好。","Badger Bus 不保证到达时间，错过航班或转乘也不退钱。赶国际航班要多留缓冲时间。","2 到 11 岁的孩子，和全价成人一起买票，可以半价。","Madison 的其他站（E Johnson St 和 N Pinckney St 路口、E Washington Ave）只接受网购。校园用的是 Lake St 这个站。"]},"intl":{"en":["Mitchell Airport is Milwaukee's airport. If your flight leaves from there, the bus drops you outside Baggage Claim Door #2.","Cash must be exact change because drivers do not make change."],"zh":["Mitchell 是密尔沃基的机场。航班从那里起飞的话，车在 Baggage Claim 2 号门外放你下车。","付现金必须是准确的零钱，司机不找零。"]}},"src":[["Badger Bus - home","https://badgerbus.com/"],["Badger Bus - Pickup / Dropoff Locations","https://badgerbus.com/pickup-dropoff-locations"],["Badger Bus - Schedule","https://badgerbus.com/schedule"],["Badger Bus - Bus Ticket FAQs","https://badgerbus.com/route-faq"],["Coach USA - Van Galder Stop Information","https://www.coachusa.com/airport-transportation/van-galder/stop-information"]],"unv":["phone"],"chk":"2026-10-08","lat":43.071033,"lng":-89.397635,"stops":[["N Lake at W Johnson",99,"80 82"],["W Johnson at East Campus",106,"C D R 28 38 65"],["East Campus",133,"A B F"]]},{"id":"budget-bicycle-center","cat":"transport","n":{"en":"Budget Bicycle Center","zh":"Budget Bicycle Center 自行车店"},"kind":{"en":"Bike shop","zh":"自行车店"},"addr":"1230 Regent St, Madison, WI 53715","phone":"(608) 251-8413","web":"https://www.budgetbicyclecenter.com/storelocator/","h":{"Mo":[[600,1080]],"Tu":[[600,1080]],"We":[[600,1080]],"Th":[[600,1080]],"Fr":[[600,1080]],"Sa":[[600,1020]],"Su":[[720,1020]]},"ht":{"en":"New bikes and rentals, 1230 Regent St: Mon–Fri 10 a.m.–6 p.m., Sat 10 a.m.–5 p.m., Sun noon–5 p.m. (October 2026). The service shop at 1124 Regent St has the same hours; the used-bike store at 930 Regent St opens at 11 a.m. on Sunday.","zh":"新车和租车店 (1230 Regent St)：周一到周五 10:00–18:00，周六 10:00–17:00，周日 12:00–17:00（2026 年 10 月）。1124 Regent St 的维修店时间相同；930 Regent St 的二手车店周日 11:00 开门。"},"sum":{"en":"Regent St bike shop in three buildings: new bikes, one of the biggest used-bike stores around, repairs and day, week or month rentals.","zh":"Regent St 上三栋楼的自行车店：新车、规模很大的二手车店、维修，还能按天、周、月租车。"},"kw":["bike shop","自行车","单车","bicycle","used bikes","二手自行车","repair","维修","tune-up","rental","租车","Regent Street","trade-in","helmet","头盔","lock","车锁"],"sec":{"about":{"en":["Budget Bicycle Center has been in Madison since 1979. It has three stores on Regent Street, just south of the UW–Madison campus: new bikes and rentals at 1230 Regent St, bicycle service and accessories at 1124 Regent St, and used bikes at 930 Regent St.","The address above is the new-bike and rental store. The shop calls its used-bike store the largest used bicycle store in the world, with over 3,000 bicycles in stock."],"zh":["Budget Bicycle Center 1979 年起就在麦迪逊开店。三家店都在 Regent Street，UW–Madison 校园南边：1230 Regent St 卖新车和租车，1124 Regent St 是维修和配件店，930 Regent St 是二手车店。","上面的地址是新车和租车店。店家自称二手车店是世界上最大的二手自行车店，库存超过 3000 辆。"]},"offers":{"en":["New bikes: mountain, comfort, city, hybrid, BMX, cruiser and kids' bikes, plus trailers and fitness equipment.","Used bikes at 930 Regent St, and bike trade-ins for credit toward a new bike.","Repairs and tune-ups at 1124 Regent St, with most service back in 24 hours.","Rentals by the day, week or month; helmets, maps and locks are included.","Parts, helmets, locks, car racks and cycling clothing."],"zh":["新车：山地、舒适、城市、混合、BMX、巡航和儿童自行车，另有拖车和健身器材。","930 Regent St 卖二手车，旧车可以折价换新车。","1124 Regent St 做维修和保养，大部分维修 24 小时内取车。","按天、周或月租车，头盔、地图和锁都包含在内。","零件、头盔、车锁、车载架和骑行服。"]},"howto":{"en":["Repairs: walk in. The shop takes maintenance walk-ins and works first come, first served. If it cannot start right away, it gives you a time and cost estimate. Bring the bike to 1124 Regent St.","Rentals: no reservations unless your group is 10 people or more. The shop helps you pick a bike and set it up.","Group rentals of 10 or more: one rental form with one person taking full responsibility. Call (608) 251-8413 or stop by 1230 Regent St.","Road bike rentals are at the 930 Regent St location."],"zh":["修车：直接去。店里接受不预约的保养，先到先修。要是没法马上开始修，会告诉你时间和费用估价。把车推到 1124 Regent St。","租车：不接受预约，除非是 10 人以上的团体。店员帮你选车，也帮你调整。","10 人以上团体租车：填一张租车单，由一个人负全责。打 (608) 251-8413 或到 1230 Regent St 询问。","公路自行车在 930 Regent St 那家店租。"]},"cost":{"en":["Tune-ups (parts not included, 90-day service warranty): Check-up $150, Full Tune $275, Overhaul $500. Full-suspension and TT bikes cost $25 more on the Full Tune and Overhaul.","A la carte: new tube or tire installed $20, wheel truing $30–70+, chain replacement $30–45, shift or brake cable $35–40.","Rentals per day / week / month: hybrid bikes $30 / $150 / $400; road and tandem bikes $75 / $375 / $800; kids' 16\" and 20\" bikes $20 / $100 / $250; kids' 24\" bikes $30 / $150 / $400.","Rent first, buy later: any amount you paid to rent a bicycle can go toward buying that bicycle. Keep your receipt."],"zh":["保养套餐（不含零件，90 天保修）：Check-up $150，Full Tune $275，Overhaul $500。全避震和 TT 车，Full Tune 和 Overhaul 要多加 $25。","单项：换内胎或外胎 $20，调钢圈 $30–70+，换链条 $30–45，换变速或刹车线 $35–40。","租金（每天 / 每周 / 每月）：混合车 $30 / $150 / $400；公路车和双人车 $75 / $375 / $800；儿童 16\" 和 20\" 车 $20 / $100 / $250；儿童 24\" 车 $30 / $150 / $400。","先租后买：租车花的钱可以抵这辆车的售价。保留好收据。"]},"tips":{"en":["Ask for the free written estimate before you leave a bike for repair.","Listed repair prices do not include replacement parts, so the final bill can be higher.","The shop offers free parking during your rental period, subject to availability.","The three stores are close enough to walk between on a bike."],"zh":["修车前要一份免费的书面估价单再留车。","列出的修车价格不含更换的零件，最后的账单可能更高。","租车期间店里提供免费停车，看有没有位置。","三家店离得很近，骑车就能在店之间来回。"]}},"src":[["Budget Bicycle Center - Store locator and hours","https://www.budgetbicyclecenter.com/storelocator/"],["Budget Bicycle Center - About","https://budgetbicyclectr.com/about"],["Budget Bicycle Center - Bike Rentals","https://www.budgetbicyclecenter.com/articles/bike-rentals-pg183.htm"],["Budget Bicycle Center - Bike Service & Repair","https://www.budgetbicyclecenter.com/articles/bike-service-repair-pg184.htm"],["Budget Bicycle Center - Bike Trade-In","https://www.budgetbicyclecenter.com/articles/bike-trade-in-pg186.htm"]],"unv":[],"chk":"2026-10-08","lat":43.067927,"lng":-89.406787,"stops":[["Regent at S Randall",150,"E 64 82"],["N Randall at Regent",167,"O"],["Regent at N Mills",192,"E 64"]]},{"id":"dane-county-regional-airport","cat":"transport","n":{"en":"Dane County Regional Airport (MSN)","zh":"Dane County 地区机场 (MSN)"},"kind":{"en":"Airport","zh":"机场"},"addr":"4000 International Ln, Madison, WI 53704","phone":"(608) 246-3380","web":"https://www.msnairport.com/","h":null,"ht":{"en":"No single set of hours; ticket counters and flights follow each airline's schedule. Check your flight on the airport's departures page. Metro Route D2 to the airport runs every 30 minutes on weekdays and hourly on weeknights and weekends.","zh":"机场没有统一的营业时间，值机柜台和航班按各航空公司安排。查航班看机场官网的 Departures 页。去机场的 Metro D2 路公交，工作日每 30 分钟一班，晚上和周末每小时一班。"},"sum":{"en":"Madison's airport. American, Delta, United and others fly nonstop to about 20 cities; Metro Route D2 and rideshare connect it to campus.","zh":"麦迪逊的机场，直飞约 20 个城市；Metro D2 路公交和打车都能到校园。"},"kw":["MSN","airport","机场","Dane County Regional Airport","flight","航班","Metro D2","Uber","Lyft","taxi","出租车","rideshare","打车","American Airlines","Delta","United","Breeze","Frontier","Sun Country"],"sec":{"about":{"en":["Dane County Regional Airport (MSN) is Madison's commercial airport, at 4000 International Lane. The airport says you can reach anywhere in the world in one stop or less.","Most students fly from here to a hub (Chicago, Minneapolis, Atlanta, Detroit and so on) and connect. For a flight out of the country, you will change planes at least once."],"zh":["Dane County 地区机场 (MSN) 是麦迪逊的民航机场，地址 4000 International Lane。机场官网说，从这里转一次机或不转机，能飞到世界上任何地方。","多数学生从这里飞到一个枢纽（芝加哥、明尼阿波利斯、亚特兰大、底特律等）再转机。出国的航班至少要转一次机。"]},"offers":{"en":["Airlines: American, Breeze, Delta, Frontier, Sun Country and United.","Nonstop destinations include Atlanta, Boston, Charlotte, Chicago, Dallas/Fort Worth, Denver, Detroit, Fort Myers, Los Angeles, Miami, Minneapolis/St. Paul, New York, Newark, Orlando, Philadelphia, Phoenix, Raleigh, Tampa and Washington D.C.","Chicago O'Hare flights are on American and United.","Some routes are seasonal, for example Sun Country to Fort Myers in fall and winter.","Ground transport: Metro bus, taxi, Uber/Lyft, rental cars and hotel courtesy vans.","A free Cell Phone Lot where a friend can wait to pick you up."],"zh":["航空公司：American、Breeze、Delta、Frontier、Sun Country 和 United。","直飞目的地包括亚特兰大、波士顿、夏洛特、芝加哥、达拉斯/沃思堡、丹佛、底特律、迈尔斯堡、洛杉矶、迈阿密、明尼阿波利斯/圣保罗、纽约、纽瓦克、奥兰多、费城、凤凰城、罗利、坦帕和华盛顿特区。","飞芝加哥 O'Hare 的有 American 和 United。","有些航线是季节性的，比如 Sun Country 飞迈尔斯堡只在秋冬。","地面交通：Metro 公交、出租车、Uber/Lyft、租车和酒店接驳车。","有免费的 Cell Phone Lot，朋友来接你可以在那里等。"]},"howto":{"en":["Bus to the airport: take Metro's D2 route. At the airport it leaves from outside Door 6, bus stop sign on the roadway median. Look for buses marked \"D2 EPIC CAMPUS\" or \"D2 VERONA\".","Rideshare (Uber, Lyft) pick-up is outside Door 6 to the right, along the terminal curb. Taxis wait at the north end of baggage claim, Door 7.","Pay a Metro fare by tapping a contactless credit card or virtual wallet, or tap your ASM student bus pass. Use the same card each time so the 2-hour transfer works.","Taxi companies: Madison Taxi (608) 255-8294, Union Cab (608) 242-2000.","Rental car booths are at baggage claim and the rental car lot is outside Door 6. Hotel courtesy vans stop at Door 5."],"zh":["坐公交去机场：乘 Metro 的 D2 路。在机场它从 Door 6 外面发车，站牌立在道路中间的安全岛上。认准车上写 \"D2 EPIC CAMPUS\" 或 \"D2 VERONA\" 的车。","Uber、Lyft 在 Door 6 右侧，沿航站楼路边上车。出租车在行李提取区北头的 Door 7。","Metro 车费可以用非接触式信用卡或虚拟钱包感应付款，也可以直接刷 ASM 学生公交卡。每次用同一张卡，2 小时换乘才能自动生效。","出租车公司：Madison Taxi (608) 255-8294，Union Cab (608) 242-2000。","租车柜台在行李提取区，租车场在 Door 6 外面。酒店接驳车停在 Door 5。"]},"cost":{"en":["Metro bus: $2 adult fare, with a free 2-hour transfer window. UW students ride free with the ASM student bus pass.","Taxi and rideshare fares are not published by the airport; ask the company or check the app.","The Cell Phone Lot is free."],"zh":["Metro 公交：成人 $2，含 2 小时免费换乘。UW 学生用 ASM 学生公交卡免费坐。","出租车和 Uber/Lyft 的价格机场官网没写，问公司或看 app。","Cell Phone Lot 免费停。"]},"tips":{"en":["Federal rules do not allow cars to wait for long at the terminal curb. A friend picking you up should wait in the Cell Phone Lot until you call.","Some area hotels run a courtesy vehicle to the airport. Use the courtesy phone between Bag Claims 1 and 2 to call the hotel.","Metro Customer Service, (608) 266-4466, is open weekdays 6:15 a.m.–6 p.m. and weekends and holidays 8 a.m.–4:30 p.m., if the bus does not show.","The airport's Information Help Desk can answer bus questions."],"zh":["联邦规定不允许车在航站楼路边久等。朋友来接你，请他在 Cell Phone Lot 等你打电话。","有些周边酒店有机场接驳车。用 Bag Claim 1 和 2 之间的酒店电话牌打给酒店。","公交没来的话，Metro 客服 (608) 266-4466，工作日 6:15–18:00，周末和假日 8:00–16:30。","机场的 Information Help Desk 也能回答公交问题。"]},"intl":{"en":["For flights to China and other countries, you will connect through a hub such as Chicago, Detroit or Minneapolis. Book enough layover time."],"zh":["飞中国和其他国家要在芝加哥、底特律或明尼阿波利斯这类枢纽转机，转机时间要订够。"]}},"src":[["Dane County Regional Airport - home","https://www.msnairport.com/"],["Dane County Regional Airport - Where We Fly","https://www.msnairport.com/flight_travel/where"],["Dane County Regional Airport - Airlines","https://www.msnairport.com/flight_travel/airlines"],["Dane County Regional Airport - Ground Transportation","https://www.msnairport.com/parking_transportation/ground_transportation"],["Dane County Regional Airport - Cell Phone Lot","https://www.msnairport.com/parking_transportation/cell"],["UW Transportation Services - UW Student Bus Pass Program","https://transportation.wisc.edu/commuter-solutions/bus/student-bus-pass-program/"]],"unv":["hours"],"chk":"2026-10-08","lat":43.13568,"lng":-89.34584,"stops":[["Airport at Terminal Door 6",187,"D"]]},{"id":"flixbus-greyhound-madison-campus","cat":"transport","n":{"en":"FlixBus and Greyhound (Madison Campus stop)","zh":"FlixBus 和 Greyhound（Madison Campus 站）"},"kind":{"en":"Intercity bus stop","zh":"长途巴士站"},"addr":"200 N Lake St, Madison, WI 53703","phone":"(800) 231-2222","web":"https://greyhound.com/en-us/bus-station-502029","h":null,"ht":{"en":"Curb stop with no office or waiting room. Be at the shelter before the departure time on your ticket.","zh":"这是路边站，没有办公室也没有候车室。按车票上的发车时间提前到候车亭。"},"sum":{"en":"The campus stop for FlixBus and Greyhound on N Lake St by Gordon Commons. Cheap long-distance buses to Chicago, Minneapolis, Milwaukee and beyond.","zh":"FlixBus 和 Greyhound 在 N Lake St 的共用站，可去芝加哥、明尼阿波利斯等地。"},"kw":["FlixBus","Greyhound","bus","巴士","大巴","长途","Chicago","芝加哥","Minneapolis","Milwaukee","Madison Campus WI","Lake Street","luggage","行李","cheap","便宜"],"sec":{"about":{"en":["FlixBus and Greyhound share one Madison stop near campus, listed as \"Madison (Madison Campus WI)\" at 200 North Lake St. Buses board from the bus shelters on N Lake Street next to the Gordon Commons terrace.","Both companies also use Madison's Dutch Mill Park & Ride, about 4 miles from this stop, off the Beltline and Stoughton Road. Check the stop name on your ticket before you leave."],"zh":["FlixBus 和 Greyhound 在校园附近共用一个站，网站上叫 \"Madison (Madison Campus WI)\"，地址 200 North Lake St。车从 N Lake Street 上、Gordon Commons 平台旁边的候车亭上车。","两家公司也用 Madison 的 Dutch Mill Park & Ride，距这个站约 4 英里，在 Beltline 和 Stoughton Road 旁边。出门前先看清车票上写的是哪个站。"]},"offers":{"en":["FlixBus lists about 20 destinations from Madison, including Chicago, Minneapolis and Milwaukee.","Free Wi-Fi, power outlets and extra legroom on FlixBus buses.","Seat reservation during booking, depending on availability.","A real-time bus tracker for FlixBus trips.","Greyhound trips from the same stop; FlixBus says the baggage rules are the same on buses Greyhound operates."],"zh":["FlixBus 从 Madison 出发能到约 20 个目的地，包括芝加哥、明尼阿波利斯和密尔沃基。","FlixBus 的车有免费 Wi-Fi、电源插座和更宽的腿部空间。","购票时可以选座，看有没有位置。","FlixBus 有实时车辆追踪 (Real-Time Bus Tracker)。","Greyhound 的班次也从同一个站发车；FlixBus 说 Greyhound 运营的车行李规定一样。"]},"howto":{"en":["Book on flixbus.com or greyhound.com, or in the FlixBus app. Your ticket shows the exact stop address.","Online FlixBus tickets come as a PDF with a QR code, or are stored in the app. You do not need to print them; show the driver the ticket on your phone.","Pay online by credit card (Visa, Mastercard, Maestro, Amex, Diners Club, JCB, Discover), PayPal, Google Pay or Apple Pay. Cash is possible at a sales point.","Wait at the bus shelter on N Lake Street. FlixBus, Greyhound, Badger Bus and Van Galder all use this block, so check the company name on the bus.","Greyhound customer phone listed for this stop: (800) 231-2222."],"zh":["在 flixbus.com、greyhound.com 或 FlixBus app 上订票。车票上有这个站的准确地址。","FlixBus 网购车票是带二维码的 PDF，或者存在 app 里。不用打印，把手机上的车票给司机看就行。","网上可以用信用卡 (Visa、Mastercard、Maestro、Amex、Diners Club、JCB、Discover)、PayPal、Google Pay 或 Apple Pay 付款。销售点可以付现金。","在 N Lake Street 的候车亭等车。FlixBus、Greyhound、Badger Bus 和 Van Galder 都用这一段路，上车前看清车上的公司名。","这个站页面上列的 Greyhound 客服电话：(800) 231-2222。"]},"cost":{"en":["FlixBus says prices on trips to Madison start at $12.48. Fares change with demand, time of day and how far ahead you book; early booking is usually cheapest.","Each FlixBus ticket includes 1 small duffle bag or backpack and 1 stored bag, free.","Extra bags and bulky items cost extra. Add them at checkout under Extras, or in Manage My Booking.","Bikes: FlixBus says e-bikes, tandems and tricycles are not allowed, and bike space varies by route."],"zh":["FlixBus 说到 Madison 的车票 $12.48 起。价格随需求、时间段和提前多久订而变，一般越早订越便宜。","每张 FlixBus 车票免费带 1 个小行李袋或背包，加 1 件托运行李 (stored bag)。","多出来的行李和大件要另付费。结账时在 Extras 里加，或者在 Manage My Booking 里加。","自行车：FlixBus 说电动自行车、双人自行车和三轮车不能带，其他的看路线有没有位置。"]},"tips":{"en":["Book early for the lowest fares, and check off-peak times such as early mornings or midweek.","Label every bag with your name, address and phone number. FlixBus recommends it, and lost bags go through a Lost & Found form.","Keep valuables like ID and electronics in the small bag you carry on, not the stored bag.","Excess baggage space is limited. Book extra bags early.","Your ticket has the most up-to-date address, so trust it over this page if the stop moves."],"zh":["早订最便宜，也可以看清晨或周中这类低峰时段。","每件行李都写上姓名、地址和电话。FlixBus 建议这样做，丢了行李要填 Lost & Found 表。","身份证件、电脑这类贵重东西放进随身的小包，别放进托运行李。","多余行李的空间有限，要早点预订。","车票上的地址最新，如果站点搬了，以车票为准。"]},"intl":{"en":["FlixBus accepts Visa, Mastercard, Maestro, Amex, Diners Club, JCB and Discover, and also PayPal, Google Pay and Apple Pay.","Both the FlixBus and Greyhound sites have a Chinese-language option in the language menu."],"zh":["FlixBus 接受 Visa、Mastercard、Maestro、Amex、Diners Club、JCB 和 Discover，也能用 PayPal、Google Pay 和 Apple Pay。","FlixBus 和 Greyhound 的官网语言菜单里都有中文可选。"]}},"src":[["Greyhound - bus stop: Madison (Madison Campus WI)","https://greyhound.com/en-us/bus-station-502029"],["FlixBus - bus stations and stops in Madison, WI","https://www.flixbus.com/bus/madison-wi"],["FlixBus - Baggage","https://www.flixbus.com/service/baggage"],["Badger Bus - Pickup / Dropoff Locations","https://badgerbus.com/pickup-dropoff-locations"],["Coach USA - Van Galder Stop Information","https://www.coachusa.com/airport-transportation/van-galder/stop-information"]],"unv":[],"chk":"2026-10-08","lat":43.071033,"lng":-89.397635,"stops":[["N Lake at W Johnson",99,"80 82"],["W Johnson at East Campus",106,"C D R 28 38 65"],["East Campus",133,"A B F"]]},{"id":"madison-bcycle","cat":"transport","n":{"en":"Madison BCycle (Memorial Union station)","zh":"Madison BCycle 共享电助力单车（Memorial Union 站）"},"kind":{"en":"E-bike share","zh":"共享电助力单车"},"addr":"699 N Park St, Madison, WI 53706","phone":"(800) 473-4743","web":"https://madison.bcycle.com/","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1440]],"Sa":[[0,1440]],"Su":[[0,1440]]},"ht":{"en":"Bikes are available 24/7 during the riding season, March 15 – December 15. The system is closed the rest of the year. Customer service by phone: Mon–Fri 8 a.m.–8 p.m.; by text or email: every day 8 a.m.–10 p.m.","zh":"每年 3 月 15 日到 12 月 15 日骑行季节内 24 小时都能租车，其余时间停运。客服电话：周一到周五 8:00–20:00；短信和邮件：每天 8:00–22:00。"},"sum":{"en":"Pay-by-app e-bike share with docks all over campus. UW students get a $10/month or $90/season pass with an @wisc.edu email.","zh":"用 app 租的共享电助力单车，校园到处有桩。UW 学生用 @wisc.edu 邮箱可买 $10/月或 $90/季的卡。"},"kw":["BCycle","bike share","共享单车","e-bike","电动自行车","电助力","rental","租车","student discount","学生优惠","WISCSTUDENT","Memorial Union","Capital City Trail","app"],"sec":{"about":{"en":["Madison BCycle is an electric bike share system that connects the University of Wisconsin, State Street and the Capital City Trail across the isthmus during the spring, summer and fall riding season. The address above is the Memorial Union station on N Park St, one of the stations on campus.","It is dock-based. You unlock a bike in the BCycle app and return it to any station at the end of your trip."],"zh":["Madison BCycle 是电助力共享单车系统，春夏秋骑行季里连接 UW 校园、State Street 和 Capital City Trail，覆盖整个地峡区。上面的地址是 N Park St 上的 Memorial Union 站，校园里的站点之一。","是有桩的共享单车。在 BCycle app 里解锁，骑完还到任何一个站都行。"]},"offers":{"en":["E-bikes with pedal assist up to 17 mph, a basket (up to 20 lbs), a bell, a phone holder and a 3-speed shifter.","Stations at UW–Madison, Madison College, downtown and other popular places in the city.","The app shows the nearest station, how many bikes and docks are free, and your trip history.","Repair requests and customer service through the app."],"zh":["电助力单车：踩踏板时电机助力，最高 17 mph；有车筐（最多放 20 磅）、车铃、手机架和 3 档变速。","站点在 UW–Madison、Madison College、市中心和其他热门地点。","app 里能看最近的站、剩多少车和空桩，也能看骑行记录。","app 里可以报修、联系客服。"]},"howto":{"en":["Download the BCycle app and buy a pass in it.","Open the app, find a nearby station and unlock a bike. The bike number is on the left side of the frame.","Ride, then dock the bike at any BCycle station to end your trip. Lock your bike only at BCycle stations.","UW students: create your BCycle account with your @wisc.edu email. The Student Annual Membership needs promo code WISCSTUDENT; the monthly UW discount needs no code.","Help: text or call 800-473-4743, or email Madison@bcycle.com."],"zh":["下载 BCycle app，在 app 里买卡。","打开 app，找附近的站，解锁一辆车。车号在车架左侧。","骑完把车停进任何一个 BCycle 站的桩里就算还车。锁车只能锁在 BCycle 站点。","UW 学生：用 @wisc.edu 邮箱注册 BCycle 账号。学生年卡要输优惠码 WISCSTUDENT；月卡的 UW 优惠不用码。","需要帮助：发短信或打 800-473-4743，或发邮件到 Madison@bcycle.com。"]},"cost":{"en":["UW–Madison Monthly Member: $10 a month, auto-renews, unlimited 30-minute trips for 30 days.","Student Annual Membership: $90 a season (50% off), unlimited 1-hour trips March 15 – December 15.","Regular prices: Single Trip $8 (up to 30 minutes), Guest Pass $20 for 24 hours of 1-hour trips, Monthly $35, Annual $180 billed once ($20 a month).","Going over the free time costs $8 for each extra 30 minutes until you dock.","Prices and the discount are from the BCycle site, October 2026."],"zh":["UW–Madison 月卡 (Monthly Member)：每月 $10，自动续费，30 天内每次骑行 30 分钟以内不限次。","学生年卡 (Student Annual Membership)：每季 $90（半价），3 月 15 日到 12 月 15 日，每次 1 小时以内不限次。","原价：单次 $8（最多 30 分钟）；Guest Pass $20，24 小时内每次 1 小时以内不限次；月卡 $35；年卡一次收 $180（折合每月 $20）。","超过免费时间，每多 30 分钟收 $8，直到你还车为止。","价格和优惠来自 BCycle 官网，2026 年 10 月。"]},"tips":{"en":["Bike share works best for short trips. Dock the bike before your free time runs out; the extra-time fee is $8 per 30 minutes.","The monthly UW pass gives 30-minute trips; the annual pass gives 1-hour trips. Choose by how long your usual ride is.","On campus, ride slowly in busy pedestrian zones, yield to walkers and get off where riding is marked as not allowed.","On the Capital City Trail, stay right, pass on the left and ring your bell.","The system stops after December 15 and restarts March 15."],"zh":["共享单车适合短途。免费时间用完之前先还车；超时每 30 分钟 $8。","UW 月卡每次 30 分钟，年卡每次 1 小时。按你平时一趟骑多久来选。","在校园里人多的地方慢点骑，让行人先走，有「禁止骑行」标志的地方要下车推。","在 Capital City Trail 上靠右骑，从左边超车，超车前按铃。","12 月 15 日以后停运，3 月 15 日重新开始。"]}},"src":[["Madison BCycle - home","https://madison.bcycle.com/"],["Madison BCycle - How it Works","https://madison.bcycle.com/how-it-works/"],["Madison BCycle - Pass Options","https://madison.bcycle.com/pricing/"],["Madison BCycle - Student & Faculty Discounts","https://madison.bcycle.com/student-faculty-discounts/"],["Madison BCycle - station list (GBFS data feed)","https://gbfs.bcycle.com/bcycle_madison/station_information.json"]],"unv":[],"chk":"2026-10-08","lat":43.077042,"lng":-89.4006,"stops":[["Langdon at N Park",129,"80 82"],["N Park at State",272,"81"],["Observatory at Bascom",274,"80 82"]]},{"id":"madison-metro-transit","cat":"transport","n":{"en":"Madison Metro Transit","zh":"麦迪逊公交 (Madison Metro Transit)"},"kind":{"en":"City bus system","zh":"市内公交"},"addr":"1245 E Washington Ave, Suite 201, Madison, WI 53703","phone":"(608) 266-4466","web":"https://www.cityofmadison.com/metro","h":{"Mo":[[450,990]],"Tu":[[450,990]],"We":[[450,990]],"Th":[[450,990]],"Fr":[[450,990]],"Sa":[],"Su":[]},"ht":{"en":"Administration Office (1245 E Washington Ave, Suite 201): Mon–Fri 7:30 a.m.–4:30 p.m. The customer service phone line, (608) 266-4466, is open Mon–Fri 6:15 a.m.–6 p.m. and weekends and holidays 8 a.m.–4:30 p.m. (October 2026).","zh":"行政办公室 (1245 E Washington Ave, Suite 201)：周一到周五 7:30–16:30。客服电话 (608) 266-4466：周一到周五 6:15–18:00，周末和假日 8:00–16:30（2026 年 10 月）。"},"sum":{"en":"City bus system. UW students ride free with the ASM student bus pass from UW Transportation Services; Metro's office handles fares and Fast Fare.","zh":"市内公交。UW 学生凭 ASM 学生公交卡免费坐，卡在交通服务处领；这里讲车费和 Metro 办公室。"},"kw":["Madison Metro","Metro Transit","bus","公交","bus pass","公交卡","ASM","Wiscard","Rapid Route A","BRT","Fast Fare","fare","车费","customer service","客服"],"sec":{"about":{"en":["Madison Metro Transit is the city's bus system. UW–Madison students ride all Metro buses, BRT routes and paratransit vehicles for free with an ASM student bus pass, a tap card. The pass is not handed out at Metro's office. You pick it up from UW Transportation Services (21 N Park St, Suite 1200, or 610 Walnut St, Room 124).","The address above is Metro's Administration Office, the place for Metro-specific questions, Fast Fare cards and Metro customer service. If you only need the student pass, go to Transportation Services instead."],"zh":["Madison Metro Transit 是市里的公交系统。UW–Madison 学生有 ASM 学生公交卡（一张感应卡），坐所有 Metro 公交、BRT 快线和 paratransit 都不用付钱。这张卡不在 Metro 办公室发，要去 UW 交通服务处 (Transportation Services) 领：21 N Park St, Suite 1200，或 610 Walnut St, 124 室。","上面的地址是 Metro 的行政办公室，办 Metro 自己的事（Fast Fare 卡、客服）才来这里。只想领学生卡的话，直接去交通服务处。"]},"offers":{"en":["Free rides on all Metro buses with the ASM student bus pass (tap it on the fare reader when you board).","Rapid Route A: the bus rapid transit (BRT) line running east–west through downtown and campus, every 15 minutes on weekdays until 8 p.m. and Saturdays until 7 p.m.","Routes B and F also board at the BRT stations along the Route A corridor.","Routes 80, 81, 82 and 84 on campus: no fare for anyone, no pass needed.","Fast Fare cards, which you can pick up at this office, any Madison Public Library, or by mail.","Half-price fares for youth, seniors, people with disabilities and low-income riders after eligibility is verified."],"zh":["有 ASM 学生公交卡就能免费坐所有 Metro 公交，上车时在读卡器上刷一下。","Rapid Route A：东西向的快速公交 (BRT)，穿过市中心和校园，工作日 8 点前、周六 7 点前每 15 分钟一班。","B 线和 F 线走 A 线沿线时，也在 BRT 车站上车。","校园里的 80、81、82、84 路：谁坐都免费，不用刷卡。","Fast Fare 卡可以在这个办公室、任意 Madison Public Library 分馆领，或者邮寄。","青少年、老人、残障人士和低收入乘客，验证资格后可以半价。"]},"howto":{"en":["Get the student pass: bring your Wiscard (or another photo ID) to a Transportation Services office. It works as soon as you pick it up. Questions: studentbuspass@fpm.wisc.edu.","Pay with a contactless credit or debit card, Apple/Google/Samsung Pay or a Fast Fare card if you do not have the student pass. Tap the same card every time you ride so the 2-hour transfer works.","Cash is accepted only at ordinary bus stops with blue metal signs. At BRT stations, buy a ticket at the vending machine on the platform first.","BRT buses are boarded through the middle and rear doors, and every door has a fare reader.","Metro customer service: call (608) 266-4466 or email mymetrobus@cityofmadison.com. Wisconsin Relay Service is 711."],"zh":["领学生卡：带学生证 (Wiscard)（或其他带照片的证件）去交通服务处的办公室。领到就能用。有问题发邮件 studentbuspass@fpm.wisc.edu。","没有学生卡的话，可以用非接触式信用卡/借记卡、Apple/Google/Samsung Pay 或 Fast Fare 卡付款。每次坐车刷同一张卡，2 小时换乘才能自动生效。","只有蓝色金属牌的普通公交站可以付现金。BRT 车站要先在站台的售票机买票。","BRT 公交从中门和后门上车，每个门都有读卡器。","Metro 客服：打 (608) 266-4466 或发邮件 mymetrobus@cityofmadison.com。Wisconsin Relay Service 拨 711。"]},"cost":{"en":["Student bus pass: no charge. The program is funded by the Associated Students of Madison, and the transportation fee is part of your segregated fees.","A lost pass costs $25 to replace at Transportation Services.","Without the pass: adult fare $2.00 a ride, and the fare works as a 2-hour pass. The daily cap is $5.00, the weekly cap $16.25 and the monthly cap $65.00 (October 2026).","Children under 5 with a chaperone ride free."],"zh":["学生公交卡：免费。这个项目由学生会 ASM 出钱，学费里的交通费 (segregated fee) 已经包含。","卡丢了，在交通服务处补办 $25。","没有学生卡：成人单程 $2.00，车费等于一张 2 小时票。当天封顶 $5.00，一周封顶 $16.25，一个月封顶 $65.00（2026 年 10 月）。","5 岁以下孩子有大人陪同免费。"]},"tips":{"en":["Keep your pass. You use it for as long as you are an eligible student, so there is no new pass each semester.","After you graduate or withdraw, the pass works until the first day of classes of the next semester. Then return it to Transportation Services.","Graduate students who delay paying segregated fees can still get a pass.","Rapid Route B is not running yet. The north–south BRT line is still in the construction stage. The regular Route B bus does run and uses the BRT stations on the Route A corridor.","Plan trips and see real-time arrivals with Metro's Track Your Bus page; this site shows the nearest stops to each place."],"zh":["卡要留好。只要你还是符合条件的学生就一直能用，不用每学期换新卡。","毕业或退学后，卡可以用到下个学期开学第一天，之后要还给交通服务处。","延迟缴 segregated fees 的研究生也能领卡。","Rapid Route B 还没开通，南北向的 BRT 线还在施工前阶段。现在有的是普通 B 线，它在 A 线沿线会用 BRT 车站。","查路线和实时到站用 Metro 官网的 Track Your Bus；这个网站会给每个地点标出最近的站。"]},"intl":{"en":["You do not need a US bank card to ride. With the student pass you just tap, and on standard buses you can pay the $2.00 fare in cash."],"zh":["坐车不一定要有美国银行卡。有学生卡就直接刷，没有的话普通公交站上车可以付现金 $2.00。"]}},"src":[["Metro Transit - Contact Us","https://www.cityofmadison.com/metro/contact/"],["Metro Transit - Fares","https://www.cityofmadison.com/metro/fares"],["Metro Transit - Bus Rapid Transit (BRT)","https://www.cityofmadison.com/metro/routes-schedules/bus-rapid-transit"],["Metro Transit - North-South BRT Line","https://www.cityofmadison.com/metro/routes-schedules/bus-rapid-transit/north-south-brt-line"],["Metro Transit - BRT Frequently Asked Questions","https://www.cityofmadison.com/metro/routes-schedules/bus-rapid-transit/frequently-asked-questions"],["UW Transportation Services - UW Student Bus Pass Program","https://transportation.wisc.edu/commuter-solutions/bus/student-bus-pass-program/"],["UW Academic Staff - New Bus Rapid Transit to Ease Campus Commute","https://acstaff.wisc.edu/2024/12/16/new-bus-rapid-transit-to-ease-campus-commute-according-to-madison-metro/"]],"unv":[],"chk":"2026-10-08","lat":43.086541,"lng":-89.367078,"stops":[["Baldwin",81,"A B"],["E Johnson at N Baldwin",368,"D"],["E Gorham at N Baldwin",388,"D 28"]]},{"id":"motorless-motion-bicycles","cat":"transport","n":{"en":"Motorless Motion Bicycles","zh":"Motorless Motion 自行车店"},"kind":{"en":"Bike shop","zh":"自行车店"},"addr":"640 W Washington Ave, Madison, WI 53703","phone":"(608) 443-0640","web":"https://www.motorlessmotionbicycles.com/","h":{"Mo":[[660,1080]],"Tu":[[660,1080]],"We":[[660,1080]],"Th":[[660,1080]],"Fr":[[660,1080]],"Sa":[[600,1080]],"Su":[[660,960]]},"ht":{"en":"Mon–Fri 11 a.m.–6 p.m., Sat 10 a.m.–6 p.m., Sun 11 a.m.–4 p.m. (October 2026).","zh":"周一到周五 11:00–18:00，周六 10:00–18:00，周日 11:00–16:00（2026 年 10 月）。"},"sum":{"en":"Full-service bike shop in the old train depot downtown: walk-in repairs with a free estimate, tune-ups, and hybrid rentals from $40 a day.","zh":"市中心老火车站里的综合自行车店，修车可直接来、先免费报价，也租自行车，混合款一天 $40。"},"kw":["bike shop","自行车店","bicycle repair","修车","tune-up","flat tire","补胎","bike rental","租自行车","Motorless Motion","train depot","commuter","W Washington"],"sec":{"about":{"en":["Motorless Motion has served Madison cyclists since 2016. It sits in Madison's historic train depot downtown, right along the Southwest commuter bike path. The shop sells and services bikes in every category and says it has Dane County's largest selection of recumbent trikes.","For a student, it is mainly a place to get a bike fixed without an appointment, to rent a hybrid bike for a few days, or to buy a commuter bike."],"zh":["Motorless Motion 从 2016 年起就在麦迪逊开店，位置在市中心的老火车站 (historic train depot) 里，紧挨着 Southwest 通勤自行车道。店里什么类型的车都卖也都修，自称有 Dane County 最多的卧式三轮车 (recumbent trike)。","对学生来说，主要是三件事：不用预约就能修车，短期租一辆混合款自行车，或者买一辆通勤车。"]},"offers":{"en":["Bike service and repair, walk-ins welcome","Tune-up packages and individual repairs (new tube or tire, chain, cables, racks)","Hybrid bike rental for adults, with a helmet and a lock","New bikes in every category, plus parts, apparel and accessories","Local group rides through the shop's ride club"],"zh":["修车和保养，欢迎直接来","整套保养 (tune-up) 套餐，也可以单项维修（换内胎或外胎、链条、线缆、货架）","成人混合款自行车出租，含头盔和车锁","各种类型的新车，另有零件、骑行服和配件","店里的骑行俱乐部会组织本地集体骑行"]},"howto":{"en":["Walk in for maintenance. If the mechanics cannot start right away, the shop gives you a time and cost estimate. Bikes are worked on first come, first served.","Ask for the free written estimate before you leave the bike.","To rent, walk in or contact the shop first to reserve; a reservation makes sure a bike in your size is ready.","The shop's phone is (608) 443-0640."],"zh":["修车可以直接进店。机修马上排不上的话，店里会告诉你预计时间和费用。车按先到先修的顺序处理。","把车留下之前，先要一份免费的书面报价 (free written estimate)。","租车可以直接来，也可以先联系店里预订；预订能保证有你尺码的车等着。","店里电话 (608) 443-0640。"]},"cost":{"en":["Tune-up packages: Basic Tune $150, Full Tune $275, Overhaul from $500. All tune-ups come with a 90-day service warranty.","Single jobs: new tube or tire installed $20, chain replacement $30–45, shift or brake cable $35–40, fender $40. Prices do not include replacement parts.","Hybrid rental: $40 a day, $200 a week or $400 a month. Electric and gravel rentals are $100 a day."],"zh":["整套保养：基础 (Basic Tune) $150，全面 (Full Tune) $275，大修 (Overhaul) $500 起。所有保养享 90 天质保。","单项维修：装新内胎或外胎 $20，换链条 $30–45，换变速线或刹车线 $35–40，装挡泥板 $40。价格不含更换的零件。","混合款租车：一天 $40，一周 $200，一个月 $400。电助力车和砾石公路车一天 $100。"]},"tips":{"en":["For a flat or a loose chain, ask for single jobs, not a tune-up package. A package makes sense for a bike you have not serviced for a year.","Hours are 11 a.m. to 6 p.m. on weekdays, so a morning errand does not work. Check the day's hours before you ride over.","The campus has free help too: the University Bicycle Resource Center runs free classes (flat tires, brakes, winter biking) and a do-it-yourself space for tune-ups.","The pages I read do not mention used bikes or winter (studded) tires. Ask the shop if you need either."],"zh":["爆胎或链条松了，只做单项维修就行，不用买整套保养。一年没保养的车才适合做整套。","工作日 11:00 才开门，早上办不了事。出发前看一下当天的营业时间。","校内也有免费帮助：University Bicycle Resource Center 有免费课程（补胎、刹车、冬季骑行），还有自己动手保养的空间。","我查的页面里没提二手车和冬季（防滑钉）轮胎。需要的话直接问店里。"]}},"src":[["Motorless Motion Bicycles - home","https://www.motorlessmotionbicycles.com/"],["Motorless Motion Bicycles - Location","https://www.motorlessmotionbicycles.com/about/location-pg141.htm"],["Motorless Motion Bicycles - Bike Service & Repair","https://www.motorlessmotionbicycles.com/articles/bike-service-repair-pg186.htm"],["Motorless Motion Bicycles - Bike Rentals","https://www.motorlessmotionbicycles.com/articles/bike-rentals-pg191.htm"],["UW Housing - Maintenance Minute: Biking on Campus","https://www.housing.wisc.edu/2026/09/maintenance-minute-biking-on-campus/"]],"unv":[],"chk":"2026-10-08","lat":43.068055,"lng":-89.39372,"stops":[["W Washington at Regent",110,"E 75"],["W Washington at N Bedford",149,"E 75"],["W Washington at S Bedford",166,"E 75 81"]]},{"id":"van-galder-bus-uw-campus","cat":"transport","n":{"en":"Van Galder Bus (UW Campus stop)","zh":"Van Galder 长途巴士（UW 校园站）"},"kind":{"en":"Bus to Chicago","zh":"去芝加哥的巴士"},"addr":"250 N Lake St, Madison, WI 53703","phone":"","web":"https://www.coachusa.com/airport-transportation/van-galder/stop-information","h":null,"ht":{"en":"Curb stop, no office or counter. Buses run every day on the same schedule all year; check the posted timetable for your departure.","zh":"这是路边站，没有办公室或柜台。巴士全年每天按同一张时刻表发车，出发前先查时刻表。"},"sum":{"en":"Coach USA's Van Galder bus to Chicago O'Hare Airport and downtown leaves from the UW Campus stop on N Lake St, next to Gordon Commons.","zh":"Van Galder 巴士在 Gordon Commons 旁发车，去芝加哥 O'Hare 机场和市中心。"},"kw":["Van Galder","Coach USA","bus","巴士","大巴","Chicago","芝加哥","O'Hare","奥黑尔","airport","机场","Union Station","长途","Lake Street","luggage","行李"],"sec":{"about":{"en":["Van Galder Bus Company, now part of Coach USA, runs the main bus between Madison and Chicago. The UW Campus stop is on the 200 block of North Lake Street, between Dayton and Johnson Streets, next to the Gordon Commons terrace. Use \"250 N. Lake St.\" for GPS.","Madison has a second stop, Dutch Mill Park & Ride, on the east side (Highway 51 and Broadway). Most students use the Lake St stop."],"zh":["Van Galder Bus Company 现在属于 Coach USA，是麦迪逊到芝加哥最主要的大巴。UW Campus 站在 North Lake Street 的 200 号段，Dayton St 和 Johnson St 之间，Gordon Commons 平台旁边。导航输入 \"250 N. Lake St.\"。","麦迪逊还有第二个站 Dutch Mill Park & Ride，在东边 (Highway 51 和 Broadway 路口)。多数学生用 Lake St 这个站。"]},"offers":{"en":["Buses to Chicago O'Hare Airport, dropping off at Terminals 1, 2, 3 or 5.","Buses to downtown Chicago, with a stop at Amtrak/Union Station.","The same timetable 365 days a year.","Coaches with USB charging ports, footrests and seat belts.","Other stops on the way: Janesville, South Beloit and Rockford."],"zh":["去芝加哥 O'Hare 机场的车，在 1、2、3 或 5 号航站楼下车。","也有开往芝加哥市中心的车，停 Amtrak/Union Station。","全年 365 天用同一张时刻表。","车上有 USB 充电口、脚踏和安全带。","沿途还停 Janesville、South Beloit 和 Rockford。"]},"howto":{"en":["Buy a ticket online on the Coach USA Van Galder page or in the Coach USA app. You can also buy at the stop if you have no ticket.","Van Galder's own ticket page says online tickets must be printed because phone screens cannot be accepted. Print the PDF from the \"Your e-Tickets\" email before you leave. If the app now says something different, follow the app.","At O'Hare, tell the driver your terminal when you board; the luggage is loaded by terminal.","Coming back from O'Hare, buses leave from the Multi-Modal Facility (MMF), 10255 W Zemke Blvd, Bus Bays 5, 6 or 7. Take the Airport Transit System from any terminal.","In downtown Chicago the pick-up and drop-off curb is on Canal Street, near 225 S Canal Street. The sign says \"Amtrak Thruway Bus\"."],"zh":["在 Coach USA 的 Van Galder 页面或 Coach USA app 上网购票。没票的话也能在站上现买。","Van Galder 自己的购票页面说网购车票必须打印，手机屏幕不被接受。出发前把 \"Your e-Tickets\" 邮件里的 PDF 打印出来。如果 app 现在写的不一样，按 app 的说明来。","到 O'Hare 时上车就告诉司机你去哪个航站楼，行李按航站楼分开装。","从 O'Hare 回麦迪逊，要去 Multi-Modal Facility (MMF) 坐车，地址 10255 W Zemke Blvd，Bus Bays 5、6 或 7。从任意航站楼坐 Airport Transit System 过去。","芝加哥市中心的上下车点在 Canal Street 路边，靠近 225 S Canal Street，牌子上写着 \"Amtrak Thruway Bus\"。"]},"cost":{"en":["Madison to O'Hare: $47.00 one way if you pay at the stop, $38.10 one way online, $68.60 round trip online.","Madison to downtown Chicago: $48.00 walk-up, $39.20 one way online, $70.25 round trip online.","These are the base fares on Van Galder's fare table (effective Jan 8, 2025, still posted in October 2026). Walk-up fares add a fuel surcharge; online fares add a fuel surcharge and service fees.","Bags: up to 2 bags under the bus (50 lbs each) and 1 carry-on per adult fare. Extra bags cost $10 each, space permitting."],"zh":["麦迪逊到 O'Hare：现场付 $47.00 单程，网购 $38.10 单程，往返网购 $68.60。","麦迪逊到芝加哥市中心：现场付 $48.00，网购单程 $39.20，往返网购 $70.25。","这是 Van Galder 价格表上的基础票价（2025 年 1 月 8 日起生效，2026 年 10 月官网仍是这张）。现场买的票价另加燃油附加费；网购另加燃油附加费和服务费。","行李：车底最多 2 件（每件不超过 50 磅），每位成人票可以带 1 件随身包。多出来的每件 $10，看空位。"]},"tips":{"en":["Buy online: Van Galder says you save up to $6.80 on a one-way trip and up to $21.75 on a round trip.","Leave extra time. Van Galder warns that traffic can delay buses and tells riders to allow ample time.","Check Van Galder's Service Advisories and Holiday Schedule Changes page before a holiday trip.","Van Galder's main page also mentions Midway, but its Madison-to-Midway search shows no schedules (October 2026). Plan for O'Hare or downtown.","Going on to a train in Chicago or other ground transport from O'Hare? Van Galder recommends the airport shuttle drop-off at Terminal 2.","Coming back from O'Hare, go to the MMF. The old pick-up spots (Terminal 5, Bus Shuttle Center) are no longer used."],"zh":["网上买更划算：Van Galder 说单程最多省 $6.80，往返最多省 $21.75。","多留时间。Van Galder 提醒，堵车会让车晚点，要给自己留足时间。","节假日出行前，看一下 Van Galder 官网的 Service Advisories and Holiday Schedule Changes 页面。","Van Galder 的主页也提到 Midway，但官网查麦迪逊到 Midway 显示没有班次（2026 年 10 月）。按 O'Hare 或市中心规划。","到 O'Hare 后要转火车或别的交通？Van Galder 建议在 2 号航站楼下车。","从 O'Hare 回来要去 MMF 坐车。老的上车点 (Terminal 5、Bus Shuttle Center) 已经不用了。"]},"intl":{"en":["Terminal 5 is O'Hare's international terminal, and the bus drops off there. Tell the driver \"Terminal 5\" when you board for an international flight."],"zh":["Terminal 5 是 O'Hare 的国际航站楼，这趟车会停。坐国际航班就在上车时告诉司机 \"Terminal 5\"。"]}},"src":[["Coach USA - Van Galder Bus Services","https://www.coachusa.com/airport-transportation/van-galder"],["Coach USA - Van Galder Stop Information","https://www.coachusa.com/airport-transportation/van-galder/stop-information"],["Coach USA - Van Galder Airport Information","https://www.coachusa.com/airport-transportation/van-galder/airport-information"],["Coach USA - Van Galder Fares","https://www.coachusa.com/airport-transportation/van-galder/fares"],["Coach USA - Baggage policy","https://help.coachusa.com/portal/en/kb/articles/baggage"],["Van Galder - Printer Required for Online Ticketing","https://web.coachusa.com/info/vangalder/ss.onlinetickets.asp"],["Coach USA - Van Galder Bus Company","https://www.coachusa.com/van-galder-bus-company"],["Van Galder - Madison to Chicago Midway schedule lookup","https://web.coachusa.com/vangalder/ss.listing.asp?action=Lookup&c1=Madison&s1=WI&c2=Chicago+Midway+Airport&s2=IL"],["Van Galder - Madison to O'Hare schedule","https://web.coachusa.com/vangalder/ss.details.asp?action=Lookup&c1=Madison&s1=WI&c2=Chicago+O%27Hare+Airport&s2=IL&resultId=165926&order=&dayFilter=&scheduleChoice=&nt=&sitePageName=&cbid=580411518212"],["Van Galder - Madison to Chicago Downtown schedule","https://web.coachusa.com/vangalder/ss.details.asp?action=Lookup&c1=Madison&s1=WI&c2=Chicago+Downtown&s2=IL&resultId=17051&order=&dayFilter=&scheduleChoice=&nt=&sitePageName=&cbid=1"]],"unv":["phone"],"chk":"2026-10-08","lat":43.071554,"lng":-89.397636,"stops":[["N Lake at W Johnson",45,"80 82"],["W Johnson at East Campus",54,"C D R 28 38 65"],["East Campus",96,"A B F"]]},{"id":"amazon-hub-sellery-hall","cat":"money","n":{"en":"Amazon pickup site (Sellery Residence Hall)","zh":"Amazon 取件点 (Sellery 宿舍楼)"},"kind":{"en":"Amazon package pickup","zh":"Amazon 包裹自提点"},"addr":"821 W Johnson St, Madison, WI 53706","phone":"","web":"https://www.housing.wisc.edu/undergraduate/services/desks/","h":null,"ht":{"en":"Current hours not found. UW's 2017 launch announcement listed 9 a.m.–9 p.m. weekdays and noon–9 p.m. Saturdays and Sundays; check Amazon.com/UWMadison before you go.","zh":"没找到现行营业时间。UW 2017 年开业公告写的是工作日 9:00–21:00，周六日 12:00–21:00；去之前先看 Amazon.com/UWMadison。"},"sum":{"en":"Amazon pickup site connected to Sellery Residence Hall, listed by UW Housing: ship orders there and drop off returns. Hours not confirmed.","zh":"UW Housing 列出的 Amazon 取件点，连着 Sellery 宿舍楼，可取货退货。时间未核实。"},"kw":["Amazon","Amazon Hub","Amazon Locker","Amazon@UWMadison","亚马逊","自提","取件","locker","包裹柜","Sellery","package pickup","returns","退货"],"sec":{"about":{"en":["UW Housing's Hall Desks page tells residents they can ship Amazon orders to \"the Amazon pickup site connected to Sellery Residence Hall\". It is the only Amazon pickup point I could confirm near campus.","UW's own description of the site is from its 2017 opening announcement: a 2,500-square-foot site on the east side of Sellery Hall, with self-service lockers. The current page gives no hours or details, so treat the rest of this entry as unconfirmed."],"zh":["UW Housing 的 Hall Desks 页面告诉住宿生，可以把 Amazon 订单寄到「连着 Sellery 宿舍楼的 Amazon 取件点」。这是我能确认的、校园附近唯一的 Amazon 取件点。","UW 对这个点的详细介绍出自 2017 年的开业公告：Sellery 楼东侧、2,500 平方英尺、有自助取件柜。现行页面没写营业时间和细节，下面其余内容请当作未核实。"]},"offers":{"en":["Pick up Amazon orders from a self-service locker","Free returns on Prime items (as announced in 2017)","Residents get expedited delivery options and secure pickup, per UW Housing"],"zh":["从自助取件柜取 Amazon 订单","Prime 商品免费退货（2017 年公告的内容）","UW Housing 说住宿生还能用加急送货，取件更安全"]},"howto":{"en":["As UW described it in 2017: choose Amazon@UWMadison as the shipping address at checkout.","You get an email or app notification. When the order is ready, click the link in the email to generate a barcode.","Go to Sellery Residence Hall, scan the barcode and take the order from the locker.","Whether this still works exactly like this in fall 2026 is not confirmed; start from Amazon.com/UWMadison."],"zh":["按 UW 2017 年的说法：下单时把收货地址选成 Amazon@UWMadison。","你会收到邮件或 App 通知。订单备好后，点邮件里的链接生成条形码。","到 Sellery 宿舍楼扫条形码，从取件柜里拿走包裹。","2026 年秋天是不是仍然照这个流程走，没有核实；请从 Amazon.com/UWMadison 开始。"]},"cost":{"en":["In 2017 UW announced free one-day pickup on orders placed before 10 p.m. for Amazon Prime customers. Current terms are not confirmed."],"zh":["2017 年 UW 公告写的是：Prime 会员晚上 10 点前下的单，次日免费取件。现行条件未核实。"]},"tips":{"en":["UW Housing's page speaks to residents. The 2017 announcement said UW students, faculty and staff; whether non-residents can use it now is not confirmed.","For returns when the site does not work for you, the FedEx Office on W Washington Ave takes Amazon returns with a QR code and no box.","Packages sent to a residence hall address arrive at that hall's front desk instead; Sellery's desk is at 821 W Johnson St, (608) 262-1076."],"zh":["UW Housing 的页面是写给住宿生的。2017 年公告写的是 UW 的学生、教职工；现在非住宿生能不能用，没有核实。","这个点不方便退货时，W Washington Ave 的 FedEx Office 收 Amazon 退货，用二维码，不用盒子。","寄到宿舍楼地址的包裹会送到那栋楼的前台。Sellery 前台在 821 W Johnson St，电话 (608) 262-1076。"]}},"src":[["UW Housing - Hall Desks (Amazon Hub section)","https://www.housing.wisc.edu/undergraduate/services/desks/"],["UW-Madison News - Amazon package pickup center open in Sellery Residence Hall (2017)","https://news.wisc.edu/amazon-package-pickup-center-open-in-sellery-residence-hall/"],["FedEx Office Print & Ship Center - 654 W Washington Ave","https://local.fedex.com/en-us/wi/madison/office-0416"]],"unv":["hours","phone"],"chk":"2026-10-08","lat":43.071745,"lng":-89.399333,"stops":[["East Campus",57,"A B F"],["W Johnson at East Campus",108,"C D R 28 38 65"],["W Dayton at N Park",115,"80 82"]]},{"id":"associated-bank-monroe-street","cat":"money","n":{"en":"Associated Bank (Monroe Street branch)","zh":"Associated Bank 银行 (Monroe Street 分行)"},"kind":{"en":"Bank branch and ATM","zh":"银行分行和 ATM"},"addr":"1603 Monroe St, Madison, WI 53711","phone":"(608) 259-2000","web":"https://www.associatedbank.com/locations/wi/madison/1603-monroe","h":{"Mo":[[540,1020]],"Tu":[[540,1020]],"We":[[540,1020]],"Th":[[540,1020]],"Fr":[[540,1020]],"Sa":[],"Su":[]},"ht":{"en":"Lobby and drive-thru open Mon–Fri 9 a.m.–5 p.m.; closed Sat and Sun (Associated Bank branch page, October 2026). The page does not list holiday hours.","zh":"大堂和汽车通道 (drive-thru) 周一到周五 9:00–17:00，周六日不开（Associated Bank 分行页面，2026 年 10 月）。页面没写假日营业时间。"},"sum":{"en":"Associated Bank branch on Monroe Street near Camp Randall, with a lobby ATM, instant-issue debit cards and a $25-to-open checking account.","zh":"Monroe Street 上的 Associated Bank 分行，有大堂 ATM，25 美元起开支票账户。"},"kw":["Associated Bank","bank","银行","ATM","checking","支票账户","Access Checking","Monroe Street","Camp Randall","debit card","借记卡","international student","留学生","W-8","开户"],"sec":{"about":{"en":["Associated Bank's Madison location list names five branches: 1603 Monroe, East Towne Blvd, Cottage Grove Rd, McKee Rd and Mineral Point Rd. The Monroe Street branch is the only one on the near-campus side of town.","It is a full branch with a lobby, a drive-thru and a lobby ATM."],"zh":["Associated Bank 官网的麦迪逊网点列了 5 家：1603 Monroe、East Towne Blvd、Cottage Grove Rd、McKee Rd 和 Mineral Point Rd。Monroe Street 这家是唯一靠近校园的。","这是全业务分行，有大堂、汽车通道和一台大堂 ATM。"]},"offers":{"en":["Open a checking or savings account","Instant issue of debit cards","Lobby ATM: withdraw cash, deposit cash or checks, transfer funds","Safe deposit boxes","Investment and insurance representative, and a mortgage office","Schedule an appointment online (the page also has a Spanish link)"],"zh":["开支票或储蓄账户","借记卡当场发卡 (instant issue)","大堂 ATM：取现金、存现金或支票、转账","保险箱","有投资和保险顾问，还有房贷办公室","可以在线预约（页面也有西班牙语入口）"]},"howto":{"en":["Use the Schedule an Appointment button on the branch page, or call (608) 259-2000.","Bring photo ID such as a driver's license. Associated's account agreement says it may ask for a driver's license or other identifying documents.","Non-U.S. persons: Associated says documentation, including a W-8 form, is required instead of a U.S. tax ID.","ATM deposits made after 6:30 p.m. are available the next business day."],"zh":["点分行页面上的 Schedule an Appointment 预约，或者打 (608) 259-2000。","带带照片的证件，比如驾照。Associated 的账户协议说银行可能要驾照或其他身份证明文件。","非美国人 (non-U.S. person)：Associated 说要提供文件，包括 W-8 表，代替美国税号。","晚上 6:30 以后在 ATM 存的钱，下一个工作日才到账。"]},"cost":{"en":["Associated Access Checking has no monthly maintenance fee and no balance minimum. The minimum deposit to open it is $25.","Associated Balanced Checking and Choice Checking need $100 to open. Balanced Checking has a $9 monthly fee unless you keep a $1,000 minimum daily balance or meet another test; Choice Checking's fee is $25.","Associated and MoneyPass ATMs are free for Associated customers. Other ATM owners may charge a fee, and international fees may apply."],"zh":["Associated Access Checking 没有月费，也没有最低余额要求，开户最低存款 25 美元。","Balanced Checking 和 Choice Checking 开户要 100 美元。Balanced 月费 9 美元，日均余额保持 1,000 美元或满足别的条件可免；Choice 月费 25 美元。","Associated 和 MoneyPass 网络的 ATM 对 Associated 客户免费。其他 ATM 的运营方可能收费，还可能有国际费用。"]},"tips":{"en":["Lobby and drive-thru both close at 5 p.m. and the branch is closed on weekends, so go on a weekday.","If you only want the cheapest account, ask for Access Checking by name. The branch page does not say which account the banker will offer first.","UW's International Student Services says many students use UW Credit Union and that you are not required to; compare banks before you choose.","Customer Care for the whole bank is 800-236-8866, Monday through Saturday."],"zh":["大堂和汽车通道都是 17:00 关门，周末不开，要工作日去。","只想要最便宜的账户，就直接说 Access Checking。分行页面没写柜员会先推荐哪种账户。","UW 国际学生服务办公室 (ISS) 说不少学生用 UW Credit Union，但没有强制要求；开户前多比较几家。","全行客服电话 800-236-8866，周一到周六接听。"]},"intl":{"en":["UW ISS says you do not need an SSN for receiving service at a bank.","Associated's account agreement requires a Federal Tax ID (SSN) from U.S. persons and says documentation, including a W-8 form, is required for non-U.S. persons.","The pages do not say whether an I-20, DS-2019 or passport alone is enough, or whether an ITIN is needed. Ask the branch before you go (unverified)."],"zh":["UW 国际学生服务办公室 (ISS) 说：在银行办业务不需要社安号 (SSN)。","Associated 的账户协议要求美国人提供联邦税号 (SSN)，非美国人则要提供文件，包括 W-8 表。","页面没说单凭 I-20、DS-2019 或护照够不够，也没说要不要 ITIN。去之前先问分行（未核实）。"]}},"src":[["Associated Bank - 1603 Monroe, Madison","https://www.associatedbank.com/locations/wi/madison/1603-monroe"],["Associated Bank - Madison, WI locations","https://www.associatedbank.com/locations/wi/madison/"],["Associated Bank - Deposit Account Disclosures and Agreement","https://www.associatedbank.com/deposit-account-disclosures-and-agreement"],["Associated Bank - Checking account comparison","https://www.associatedbank.com/checking-comparison"],["Associated Bank - Access Checking","https://www.associatedbank.com/personal/personal-checking/checking-accounts/access-checking"],["Associated Bank - Balanced Checking","https://www.associatedbank.com/personal/personal-checking/checking-accounts/balanced-checking"],["Associated Bank - Personal checking","https://www.associatedbank.com/personal/personal-checking"],["UW ISS - Social Security Number (SSN)","https://iss.wisc.edu/employment/social-security/"],["UW ISS - Becoming a Global Badger","https://iss.wisc.edu/becoming-a-global-badger/"]],"unv":[],"chk":"2026-10-08","lat":43.06723,"lng":-89.413464,"stops":[["Monroe at S Breese",24,"D"],["Regent at S Breese",55,"E 64 82"],["Regent at N Breese",102,"E 64"]]},{"id":"chase-bank-downtown-madison","cat":"money","n":{"en":"Chase Bank (Downtown Madison branch)","zh":"Chase 银行 (Madison 市中心分行)"},"kind":{"en":"Bank branch and ATM","zh":"银行分行和 ATM"},"addr":"22 E Mifflin St, Madison, WI, 53703","phone":"(608) 282-6020","web":"https://www.chase.com/locator/banking/us/wi/madison/22-e-mifflin-st","h":{"Mo":[[540,1020]],"Tu":[[540,1020]],"We":[[540,1020]],"Th":[[540,1020]],"Fr":[[540,1020]],"Sa":[[540,780]],"Su":[]},"ht":{"en":"Mon–Fri 9 a.m.–5 p.m., Sat 9 a.m.–1 p.m., Sun closed, as read from Chase's branch page in October 2026 (the page prints the times without a.m./p.m.). The ATM vestibule is open 24 hours.","zh":"周一到周五 9:00–17:00，周六 9:00–13:00，周日关门（2026 年 10 月 Chase 分行页面，页面上的时间没标 AM/PM）。ATM 的小隔间全天开放。"},"sum":{"en":"Chase's branch on the Capitol Square side of downtown; the only downtown Chase, with a 24-hour ATM and student checking.","zh":"市中心唯一的 Chase 分行，靠近 Capitol Square，有 24 小时 ATM，能开学生账户。"},"kw":["Chase","Chase Bank","JPMorgan Chase","bank","银行","ATM","student checking","Secure Banking","开户","international student","留学生","Mifflin","downtown"],"sec":{"about":{"en":["This is the Chase branch in downtown Madison, at 22 E Mifflin St near the Capitol Square. Chase's locator lists only three Madison branches, and this is the only one downtown. The other two are East Towne and Sauk Creek."],"zh":["这是 Chase 在麦迪逊市中心的分行，在 Capitol Square 附近的 22 E Mifflin St。Chase 官网只列了 3 家麦迪逊分行，市中心就这一家，另外两家是 East Towne 和 Sauk Creek。"]},"offers":{"en":["Open a checking or savings account with a banker","ATM that takes cash and check deposits, gives $5, $20 and $100 bills, and works in Chinese and other languages","ATM bill pay and transfers","Meetings with bankers on investing, home lending and Chase Private Client","Safe deposit boxes, based on availability"],"zh":["和柜员 (banker) 一起开支票或储蓄账户","ATM 可以存现金和支票，出 5、20、100 美元面额的钞票，有中文等多种语言界面","ATM 上可以缴账单、转账","和 banker 约时间谈投资、房贷和 Chase Private Client","保险箱，看有没有空位"]},"howto":{"en":["Book a meeting from the branch page, or just walk in during opening hours.","Bring two original IDs: a primary (passport) and a secondary (student ID with photo, I-20 or DS-2019). Chase says it cannot take copies or screenshots, and none may be expired.","One of the two IDs must show a U.S. address. Chase also recommends a full U.S. address with your apartment or dorm number, and a valid phone number.","Chase's student checking is called Secure Banking. You can open it online or at a branch."],"zh":["可以在分行页面约时间，也可以营业时间直接去。","带两份原件：一份主要证件（护照）加一份次要证件（带照片的学生证、I-20 或 DS-2019）。Chase 说不收复印件和截图，也不能过期。","两份证件里至少一份要有美国地址。Chase 还建议填完整的美国地址（带公寓或宿舍房号）和有效电话。","Chase 的学生账户现在叫 Secure Banking，网上或去分行都可以开。"]},"cost":{"en":["Secure Banking has no monthly service fee for account owners aged 17–24. Otherwise the fee is $4.95, waived with $250 or more in qualifying electronic deposits each month.","Chase lists no minimum deposit to open Secure Banking.","ATM deposit and bill-pay services are for Chase debit card holders only."],"zh":["Secure Banking 对 17–24 岁的账户持有人不收月费。其他人月费 4.95 美元，每月有 250 美元以上的合格电子入账就免。","Chase 页面写的是开 Secure Banking 没有最低存款要求。","ATM 存款和缴账单只给 Chase 借记卡持卡人用。"]},"tips":{"en":["Go on a weekday morning if you can; Sunday is closed and Saturday closes at 1 p.m.","You can walk up to the ATM vestibule at any hour, but only for ATM services.","Chase College Checking is no longer offered to new customers, so ask for Secure Banking."],"zh":["尽量工作日上午去；周日不开，周六 13:00 关门。","ATM 小隔间任何时间都能进，但只能用 ATM。","Chase College Checking 已经不再给新客户开了，开户时要说 Secure Banking。"]},"intl":{"en":["Chase says international students may not need a U.S. phone number or an SSN to open a checking account. Its ID list for non-residents without a Green Card accepts a passport, U.S. employment authorization card, student ID, I-20 and DS-2019.","An ITIN is not mentioned on Chase's ID list. Ask the branch before you go if you have neither an SSN nor an ITIN (unverified).","Chase says people from OFAC-sanctioned countries may face extra ID requirements; ask the branch."],"zh":["Chase 说留学生开支票账户可能不需要美国手机号和社安号 (SSN)。没有绿卡的非居民证件清单里，护照、工作许可卡、学生证、I-20 和 DS-2019 都收。","Chase 的证件清单没提 ITIN。既没有 SSN 也没有 ITIN 的话，去之前先问分行（未核实）。","Chase 说来自受 OFAC 制裁国家的客户可能有额外证件要求，请直接问分行。"]}},"src":[["Chase - Capital Madison branch page (22 E Mifflin St)","https://www.chase.com/locator/banking/us/wi/madison/22-e-mifflin-st"],["Chase - Madison, WI branch list","https://www.chase.com/locator/us/wi/madison"],["Chase Secure Banking","https://www.chase.com/personal/checking/student-checking"],["Chase - Acceptable forms of identification (PDF)","https://www.chase.com/content/dam/chase-ux/documents/personal/checking/acceptable-forms-of-identification.pdf"],["Chase - Opening a bank account as an international student","https://www.chase.com/personal/banking/education/basics/bank-accounts-for-international-students"]],"unv":["hours"],"chk":"2026-10-08","lat":43.076229,"lng":-89.384846,"stops":[["E Mifflin at N Pinckney",27,"E R 75"],["Capitol Square",57,"A B F"],["W Johnson at Wisconsin",184,"D 28"]]},{"id":"fedex-office-west-washington-ave","cat":"money","n":{"en":"FedEx Office Print & Ship Center (W Washington Ave)","zh":"FedEx Office 打印和寄件中心 (W Washington Ave)"},"kind":{"en":"Print and ship center","zh":"打印和寄件中心"},"addr":"654 W Washington Ave, Madison, WI 53703","phone":"","web":"https://local.fedex.com/en-us/wi/madison/office-0416","h":{"Mo":[[480,1140]],"Tu":[[480,1140]],"We":[[480,1140]],"Th":[[480,1140]],"Fr":[[480,1140]],"Sa":[[540,1080]],"Su":[[720,1080]]},"ht":{"en":"Mon–Fri 8 a.m.–7 p.m., Sat 9 a.m.–6 p.m., Sun noon–6 p.m. (store page, October 2026). Last FedEx Express drop-off is 6 p.m. weekdays and noon on Saturday; last Ground drop-off is 5 p.m. weekdays and 2 p.m. on Saturday; no Sunday pickup.","zh":"周一到周五 8:00–19:00，周六 9:00–18:00，周日 12:00–18:00（门店页面，2026 年 10 月）。FedEx Express 最晚收件：工作日 18:00、周六 12:00；Ground 最晚收件：工作日 17:00、周六 14:00；周日不取件。"},"sum":{"en":"The FedEx Office nearest campus: print, ship, hold packages for pickup, passport photos, and Amazon returns with a QR code and no box.","zh":"离校园最近的 FedEx Office：打印、寄件、代收包裹、拍护照照片，Amazon 退货只要二维码，不用盒子。"},"kw":["FedEx","FedEx Office","Kinko's","printing","打印","copy","复印","shipping","寄快递","Amazon returns","亚马逊退货","hold at FedEx","passport photo","护照照片","packing","shredding","laminating"],"sec":{"about":{"en":["FedEx Office Print & Ship Center at 654 W Washington Ave is the FedEx Office nearest campus that the FedEx locator lists. The other one I found is at 7805 Mineral Point Rd, on the far west side.","Closer to campus there are two FedEx locations that are not FedEx Offices: Campus Shipping Center at 711 State St (a FedEx Authorized ShipCenter) and FedEx at Walgreens at 311 E Campus Mall."],"zh":["654 W Washington Ave 这家是 FedEx 官网列出的、离校园最近的 FedEx Office。我查到的另一家在西边很远的 7805 Mineral Point Rd。","离校园更近的有两个 FedEx 网点，但不是 FedEx Office：711 State St 的 Campus Shipping Center（FedEx 授权寄件点）和 311 E Campus Mall 的 FedEx at Walgreens。"]},"offers":{"en":["Ship with FedEx, including international shipping, and get a shipping label; max package weight 150 lb","Packing service and packing supplies","Hold package for pickup: have a FedEx delivery held at this store","Amazon and QR code returns","Self-service copying, printing, faxing and scanning, plus Print & Go from the cloud, USB or email","Banners, signs, posters, business cards and flyers","Passport photos, shredding and a free Wi-Fi hotspot with computer all-access stations"],"zh":["FedEx 寄件（含国际），可以打印运单；单件最重 150 磅","代打包服务和包装材料","代收包裹 (Hold package for pickup)：让 FedEx 把你的包裹送到这家店，你自己来取","Amazon 和二维码退货","自助复印、打印、传真和扫描，还有 Print & Go（从云盘、U 盘或邮件打印）","横幅、标牌、海报、名片和传单","护照照片、碎纸，还有免费 Wi-Fi 和电脑 (all access stations)"]},"howto":{"en":["Amazon return: in your Amazon account choose QR code drop-off and pick FedEx Office. Bring the item and the QR code. No box or label is needed for eligible returns. Only QR codes generated for FedEx Office are accepted.","Hold a package here: sign in to FedEx Delivery Manager and request that the package be held or redirected to this location.","Print from email: email your files to printandgo@fedex.com, get a retrieval code, then choose PRINT at a self-service machine and enter the code.","Notary here is online only: FedEx Online Notary runs remotely on your own device. The store helps with scanning before and printing after the session."],"zh":["Amazon 退货：在 Amazon 账号里选 QR code drop-off，再选 FedEx Office，带上物品和二维码就行。符合条件的退货不用盒子和标签。只收为 FedEx Office 生成的二维码。","代收包裹：登录 FedEx Delivery Manager，申请把包裹留在或转送到这家店。","邮件打印：把文件发到 printandgo@fedex.com，收到取件码后，在自助机上选 PRINT 并输入取件码。","公证只有线上版：FedEx Online Notary 在你自己的设备上远程完成。店里帮你在公证前扫描、公证后打印。"]},"cost":{"en":["Self-service printing starts at $0.23 a page for black and white and $0.71 for color.","Passport photos: $15.95 for two 2\" x 2\" photos.","Shredding is $1.49 per lb. Self-service laminating starts at $1.50 for cards and $2.75 for 8.5\" x 11\" pages.","Faxing starts at $2.19 to send a local fax and $2.49 for a domestic fax.","FedEx advertises that One Rate shipping can cost less than the Post Office (exclusions apply)."],"zh":["自助打印黑白每页 0.23 美元起，彩色 0.71 美元起。","护照照片：两张 2 x 2 英寸的 15.95 美元。","碎纸每磅 1.49 美元。自助塑封卡片 1.50 美元起，8.5 x 11 英寸文件 2.75 美元起。","发传真：本地 2.19 美元起，美国国内 2.49 美元起。","FedEx 宣传 One Rate 统一价寄件可能比邮局便宜（有例外）。"]},"tips":{"en":["Open on Sunday, noon to 6 p.m., so it is a Sunday option for printing and shipping.","The latest Ground drop-off is 5 p.m. on weekdays, earlier than the store closes. Express drop-off is 6 p.m.","FedEx Office says it is not a passport acceptance facility and does not issue passports. It only takes passport photos here.","Campus Shipping Center at 711 State St Ste 100 (FedEx Authorized ShipCenter) is open 9 a.m.–7 p.m. Mon–Thu, 9 a.m.–5:30 p.m. Fri–Sat and noon–5 p.m. Sun, with the last Ground drop-off at 2:30 p.m. weekdays.","This store cannot accept a code made for another drop-off place. QR codes for UPS, Kohl's or Whole Foods do not work here."],"zh":["周日 12:00–18:00 也开，周日要打印或寄件可以来。","工作日 Ground 最晚收件是 17:00，比关门早。Express 是 18:00。","FedEx Office 说自己不是护照受理点 (passport acceptance facility)，也不签发护照，这里只能拍护照照片。","711 State St Ste 100 的 Campus Shipping Center（FedEx 授权寄件点）周一到周四 9:00–19:00，周五周六 9:00–17:30，周日 12:00–17:00，工作日 Ground 最晚收件 14:30。","门店不收为别处生成的二维码。给 UPS、Kohl's 或 Whole Foods 生成的二维码在这里没用。"]},"intl":{"en":["International shipping is listed among the store's shipping services. Ask staff about customs paperwork when you ship abroad (unverified).","Amazon returns here are a way to return items without finding a box or printing a label."],"zh":["门店服务里列了国际寄件。寄国外的话，向店员问清海关文件怎么填（未核实）。","在这里退 Amazon 的货不用自己找盒子、打印标签。"]}},"src":[["FedEx Office Print & Ship Center - 654 W Washington Ave","https://local.fedex.com/en-us/wi/madison/office-0416"],["FedEx Office Print & Ship Center - 7805 Mineral Point Rd","https://local.fedex.com/en-us/wi/madison/office-0449"],["FedEx Authorized ShipCenter - Campus Shipping Center, 711 State St","https://local.fedex.com/en-us/wi/madison/90193"]],"unv":["phone"],"chk":"2026-10-08","lat":43.067717,"lng":-89.395043,"stops":[["Regent at W Washington",60,"E"],["W Washington at Regent",66,"E 75"],["N Bedford at W Mifflin",243,"81"]]},{"id":"the-ups-store-regent-street","cat":"money","n":{"en":"The UPS Store (Regent Street)","zh":"The UPS Store (Regent Street 店)"},"kind":{"en":"Shipping, printing and mailbox store","zh":"快递打印和私人邮箱店"},"addr":"1360 Regent St, Madison, WI 53715","phone":"(608) 255-3391","web":"https://locations.theupsstore.com/wi/madison/1360-regent-st","h":{"Mo":[[480,1110]],"Tu":[[480,1110]],"We":[[480,1110]],"Th":[[480,1110]],"Fr":[[480,1110]],"Sa":[[540,960]],"Su":[[600,900]]},"ht":{"en":"Open 7 days: Mon–Fri 8 a.m.–6:30 p.m., Sat 9 a.m.–4 p.m., Sun 10 a.m.–3 p.m. (store page, October 2026). Notary: Mon–Fri 10 a.m.–6:30 p.m., Sat 10 a.m.–3 p.m., not on Sunday. Last UPS pickup is 5:40 p.m. on weekdays; Saturday air pickup is 1:30 p.m.; no Sunday pickup.","zh":"每天营业：周一到周五 8:00–18:30，周六 9:00–16:00，周日 10:00–15:00（门店页面，2026 年 10 月）。公证 (notary) 周一到周五 10:00–18:30，周六 10:00–15:00，周日没有。UPS 工作日最后一次取件 17:40，周六只有空运 13:30 取件，周日不取件。"},"sum":{"en":"The UPS Store near Camp Randall: ship packages worldwide, print, rent a mailbox, and store a student's things over summer.","zh":"Camp Randall 附近的 The UPS Store：寄国内外包裹、打印、租私人邮箱，还能存学生的暑期行李。"},"kw":["UPS","The UPS Store","shipping","快递","寄包裹","printing","打印","mailbox","私人邮箱","notary","公证","passport photo","护照照片","student storage","暑期存储","international shipping","国际邮寄","Regent Street"],"sec":{"about":{"en":["The UPS Store lists five Madison stores. The Regent Street store at 1360 Regent St is the one on the campus side of town. It is locally owned and sits on the corner of Regent St and Randall Ave, with parking from the Randall St entrance.","The other Madison stores are at East Towne, N Sherman Ave, University Ave in Shorewood Hills and Odana Rd."],"zh":["The UPS Store 官网列了麦迪逊 5 家店。1360 Regent St 这家靠近校园，是本地人开的加盟店，在 Regent St 和 Randall Ave 路口，停车从 Randall St 入口进。","另外几家在 East Towne、N Sherman Ave、Shorewood Hills 的 University Ave 和 Odana Rd。"]},"offers":{"en":["Ship with UPS and USPS, domestic and international, with packing and moving boxes","International: UPS Worldwide Express Plus, Worldwide Express, Worldwide Saver, Worldwide Expedited, UPS Standard, and USPS International Services","Printing and copies, binding, laminating, posters, business cards","Private mailbox with a real street address that accepts packages from all carriers","Student Storage for UW–Madison and Edgewood College: summer storage and one- or two-semester storage, with scheduled pickup and delivery","Notary, shredding, faxing and scanning","Passport photos and ID photos"],"zh":["用 UPS 和 USPS 寄国内外包裹，卖包装箱和搬家箱","国际：UPS Worldwide Express Plus、Worldwide Express、Worldwide Saver、Worldwide Expedited、UPS Standard，以及 USPS 国际服务","打印复印、装订、塑封、海报、名片","私人邮箱：有真实的街道地址，所有快递公司的包裹都收","学生存储 (Student Storage)：服务 UW–Madison 和 Edgewood College，暑期存储，也有一学期或两学期的，可约时间上门取送","公证、碎纸、传真和扫描","护照照片和证件照"]},"howto":{"en":["Use the store page's Estimate Shipping Cost tool before you go, or call (608) 255-3391.","Notary and passport photos can be booked with the Schedule Appointment button on the store page.","Student Storage: reserve online from the Student Storage page, or contact the store.","To open a mailbox, contact the store; the page also has a Download Mailbox Agreement link.","Parking is from the Randall St entrance."],"zh":["去之前先用门店页面的 Estimate Shipping Cost 估一下运费，也可以打 (608) 255-3391。","公证和护照照片可以点门店页面的 Schedule Appointment 预约。","学生存储：在 Student Storage 页面网上预订，或者联系门店。","开私人邮箱要联系门店，页面上也有 Download Mailbox Agreement（邮箱协议）可下载。","停车从 Randall St 入口进。"]},"cost":{"en":["The store pages show no prices for shipping, printing, mailboxes or storage. Use the Estimate Shipping Cost tool or ask the store (unverified).","The store page advertises 3 months of free mailbox service, terms and conditions apply (offer seen in October 2026)."],"zh":["门店页面没写寄件、打印、邮箱和存储的价格。用 Estimate Shipping Cost 估算，或者直接问店里（未核实）。","门店页面写着私人邮箱可免费用 3 个月，有附加条款（2026 年 10 月看到的优惠）。"]},"tips":{"en":["This store is open 7 days, including Sunday 10 a.m.–3 p.m., which the USPS counters near campus are not.","UPS Ground pickup is weekdays only (last pickup 5:40 p.m.). Drop packages before that to go out the same day.","A private mailbox comes with a real street address and takes packages from all carriers, which the store contrasts with a PO Box. Read the mailbox agreement before you sign.","For summer storage, reserve early; the page says the service has run for over 15 years for UW–Madison and Edgewood students."],"zh":["这家每天营业，周日也开（10:00–15:00），校园附近的 USPS 邮局周日都不开。","UPS Ground 只在工作日取件（最后 17:40）。想当天发出，要在这之前把包裹送到。","私人邮箱有真实的街道地址，所有快递公司的包裹都收，店里拿它和 PO Box 做对比。签约前先看邮箱协议。","暑期存储要早点订。页面说这项服务已为 UW–Madison 和 Edgewood 的学生做了 15 年以上。"]},"intl":{"en":["A private mailbox street address lets you receive packages from home from any carrier.","For shipping abroad, the store sells UPS Worldwide services and USPS International Services in one place. Ask which fits your deadline (unverified)."],"zh":["私人邮箱的街道地址可以收家里从任何快递公司寄来的包裹。","寄国际的话，这家店 UPS Worldwide 系列和 USPS 国际服务都能办，可以问哪种赶得上你的时间（未核实）。"]}},"src":[["The UPS Store - Regent Street, Madison","https://locations.theupsstore.com/wi/madison/1360-regent-st"],["The UPS Store - Madison, WI locations","https://locations.theupsstore.com/wi/madison"],["The UPS Store Regent Street - International shipping","https://locations.theupsstore.com/wi/madison/1360-regent-st/international-shipping"],["The UPS Store Regent Street - Mailbox services","https://locations.theupsstore.com/wi/madison/1360-regent-st/mailbox-services"],["The UPS Store Regent Street - Student storage","https://locations.theupsstore.com/wi/madison/1360-regent-st/student-storage"],["The UPS Store Regent Street - Passport photos","https://locations.theupsstore.com/wi/madison/1360-regent-st/passport-photos"],["The UPS Store Regent Street - Notary","https://locations.theupsstore.com/wi/madison/1360-regent-st/notary"],["The UPS Store Regent Street - Printing services","https://locations.theupsstore.com/wi/madison/1360-regent-st/all-printing-services"]],"unv":[],"chk":"2026-10-08","lat":43.067877,"lng":-89.408628,"stops":[["N Randall at Regent",25,"O"],["Regent at S Randall",25,"E 64 82"],["S Randall at Regent",58,"O"]]},{"id":"us-bank-university-square","cat":"money","n":{"en":"U.S. Bank (University Square campus branch)","zh":"U.S. Bank 银行 (University Square 校园分行)"},"kind":{"en":"Bank branch and ATM","zh":"银行分行和 ATM"},"addr":"389 East Campus Mall, Madison, WI 53715","phone":"(608) 255-0836","web":"https://www.usbank.com/locations/wisconsin/madison/389-east-campus-mall-bank-atm/","h":{"Mo":[[540,1020]],"Tu":[[540,1020]],"We":[[540,1020]],"Th":[[540,1020]],"Fr":[[540,1020]],"Sa":[],"Su":[]},"ht":{"en":"Lobby open Mon–Fri 9 a.m.–5 p.m.; closed Sat and Sun (branch page, October 2026). Closed on federal holidays such as Labor Day, Columbus Day, Veterans Day and Thanksgiving. Christmas Eve 9 a.m.–1 p.m.; New Year's Eve 9 a.m.–5 p.m. The walk-up ATM is open 24 hours.","zh":"大堂周一到周五 9:00–17:00，周六日不开（分行页面，2026 年 10 月）。劳动节、哥伦布日、退伍军人节、感恩节等假日关门；平安夜 9:00–13:00，除夕 9:00–17:00。户外 ATM 全天开放。"},"sum":{"en":"U.S. Bank's campus branch on East Campus Mall, with a 24-hour walk-up ATM and student checking that waives the $12 fee at ages 18–24.","zh":"U.S. Bank 校园分行，有 24 小时 ATM，18–24 岁学生账户免月费。"},"kw":["U.S. Bank","US Bank","usbank","bank","银行","ATM","student checking","Smartly Checking","学生账户","开户","international student","留学生","W-8BEN","campus banking","East Campus Mall","University Square"],"sec":{"about":{"en":["This is U.S. Bank's campus branch and ATM, listed on the bank's site as the University Square Madison Branch at 389 East Campus Mall. The page links to a campus banking page for students new to campus banking.","U.S. Bank's Madison branch list has seven entries. The other one near campus is the Capitol Square branch at 1 S Pinckney St, (608) 252-4000. The rest are East Towne, Fitchburg, Hilldale, Sauk Trails and West Towne."],"zh":["这是 U.S. Bank 的校园分行和 ATM，官网上叫 University Square Madison Branch，地址 389 East Campus Mall。页面上还有给校园新用户看的 campus banking 专页链接。","U.S. Bank 在麦迪逊官网列了 7 个网点。离校园最近的另一家是 Capitol Square 分行 (1 S Pinckney St，电话 (608) 252-4000)，其余是 East Towne、Fitchburg、Hilldale、Sauk Trails 和 West Towne。"]},"offers":{"en":["Open a checking or savings account with a banker","Set up direct deposit, order debit cards, get help with online banking and the mobile app","Notarizing documents (appointment required)","Walk-up ATM, open 24 hours","At most U.S. Bank ATMs you can check balances, deposit cash and checks, and transfer money between your accounts"],"zh":["和柜员 (banker) 一起开支票或储蓄账户","办直接存款 (direct deposit)、补办或申请借记卡、请人教你用网银和手机 App","公证 (notarizing)，要先预约","户外 ATM，全天开放","多数 U.S. Bank 的 ATM 可以查余额、存现金和支票、在自己的账户间转账"]},"howto":{"en":["Book a time on U.S. Bank's appointment page: you pick the date, the reason for the visit, and branch, phone or video.","The page does not say whether walk-ins are served for account opening, so call (608) 255-0836 first (unverified).","For most appointments, bring a valid driver's license, state-issued photo ID or valid passport.","Non-citizens: U.S. Bank asks for a W-8BEN with supporting documents, plus a foreign passport, visa or I-9.","You need $25 to activate a new checking account once approved. It can come from a prepaid, debit or credit card, or a transfer from another U.S. Bank account or another bank."],"zh":["在 U.S. Bank 预约页选日期、办事原因，还可以选到分行、电话或视频。","页面没说开户能不能直接走进去办，去之前先打 (608) 255-0836 问一下（未核实）。","大部分预约要带有效的驾照、州发的带照片身份证或有效护照。","非美国公民：U.S. Bank 要一份 W-8BEN 加证明文件，再加外国护照、签证或 I-9。","账户批准后要存 25 美元才能激活。可以用预付卡、借记卡、信用卡，或从别的 U.S. Bank 账户、别的银行转入。"]},"cost":{"en":["U.S. Bank Smartly Checking has a $12 monthly maintenance fee, always waived for young adults and students aged 18–24.","No minimum balance is required for the young adult and student checking accounts.","The minimum opening deposit is $25.","U.S. Bank says MoneyPass is a surcharge-free ATM network for cash withdrawals. Deposits are not accepted at non-U.S. Bank ATMs."],"zh":["U.S. Bank Smartly Checking 的月费是 12 美元，18–24 岁的年轻人和学生一律免。","年轻人和学生账户不要求最低余额。","开户最低存款 25 美元。","U.S. Bank 说 MoneyPass 网络的 ATM 取现不收附加费。存款不能在非 U.S. Bank 的 ATM 上办。"]},"tips":{"en":["The lobby is closed on weekends and on federal holidays. Columbus Day is Mon Oct 12, 2026, so the lobby is shut that day.","U.S. Bank sets its two student pages differently: the branch page lists a W-8BEN for non-citizens, while the student checking page lists a Social Security number as the first thing to bring. Ask the branch which applies to you.","UW's International Student Services says many students use UW Credit Union and that you are not required to; compare banks before you choose.","UW's Bursar takes tuition by eCheck with no fee, but only from a personal U.S. checking or savings account. Card payments carry a 2.95% fee (4.25% for international cards). Ask the banker for your routing and account numbers in writing."],"zh":["大堂周末和联邦假日都关。哥伦布日是 2026 年 10 月 12 日（周一），那天不开。","U.S. Bank 两个页面说法不一样：分行页写非公民用 W-8BEN，学生账户页第一条却写要社安号。去之前问分行你该按哪个来。","UW 国际学生服务办公室 (ISS) 说不少学生用 UW Credit Union，但没有强制要求；开户前多比较几家。","UW 学费用 eCheck 缴不收手续费，但只能用美国银行的个人支票或储蓄账户；刷卡要加 2.95% 手续费（国际卡 4.25%）。开户时让柜员把 routing number 和 account number 写给你。"],"exp":["2026-10-12",null,null,null]},"intl":{"en":["UW ISS says you do not need an SSN for receiving service at a bank.","A U.S. Bank campus banker said in a 2024 company article that international students typically do not need an SSN but must fill out IRS forms that ask for a foreign taxpayer ID number, and that the team has a cheat sheet for every country.","The branch page lists a foreign passport, visa or I-9 for non-citizens. It does not mention an I-20 or DS-2019 (unverified)."],"zh":["UW 国际学生服务办公室 (ISS) 说：在银行办业务不需要社安号 (SSN)。","U.S. Bank 2024 年的一篇公司文章里，校园银行员工说留学生通常不用社安号，但要填 IRS 表格，里面要外国纳税人号码；他们每个国家都有填写对照表。","分行页面给非公民列的是外国护照、签证或 I-9，没提 I-20 和 DS-2019（未核实）。"]}},"src":[["U.S. Bank - University Square Madison Branch","https://www.usbank.com/locations/wisconsin/madison/389-east-campus-mall-bank-atm/"],["U.S. Bank - Madison, WI branch list","https://www.usbank.com/locations/wisconsin/madison/"],["U.S. Bank - Capitol Square WI Branch","https://www.usbank.com/locations/wisconsin/madison/1-s-pinckney-st-bank-atm"],["U.S. Bank - Young adult and student checking account","https://www.usbank.com/bank-accounts/checking-accounts/student-checking-account.html"],["UW ISS - Social Security Number (SSN)","https://iss.wisc.edu/employment/social-security/"],["UW ISS - Becoming a Global Badger","https://iss.wisc.edu/becoming-a-global-badger/"],["U.S. Bank - Team helps international college students navigate U.S. banking system","https://www.usbank.com/about-us-bank/company-blog/article-library/team-helps-international-college-students-navigate-us-banking-system.html"],["UW Bursar - ePayments (online payment)","https://bursar.wisc.edu/student-tuition-account/payment-methods/epayments-online-payment"]],"unv":[],"chk":"2026-10-08","lat":43.072942,"lng":-89.39889,"stops":[["East Campus",46,"B"],["University at East Campus",107,"C D R 28 38 65 81"],["N Lake at University",131,"80 82"]]},{"id":"usps-capitol-station-post-office","cat":"money","n":{"en":"USPS Capitol Station Post Office","zh":"USPS Capitol Station 邮局"},"kind":{"en":"Post office","zh":"邮局"},"addr":"2 E Mifflin St Ste 103, Madison, WI 53703","phone":"(608) 250-6485","web":"https://tools.usps.com/locations/details/1492395","h":{"Mo":[[480,1020]],"Tu":[[480,1020]],"We":[[480,1020]],"Th":[[480,1020]],"Fr":[[480,1020]],"Sa":[],"Su":[]},"ht":{"en":"Retail counter Mon–Fri 8 a.m.–5 p.m.; closed Sat and Sun (USPS locator, October 2026). Last collection of outgoing mail is 5 p.m. Mon–Fri. Package pickup is also open Sat 8–11 a.m., and PO Box access is Mon–Fri 6:30 a.m.–5 p.m. and Sat 7–11 a.m.","zh":"柜台周一到周五 8:00–17:00，周六日不开（USPS 官网，2026 年 10 月）。寄出信件最后一次收取是周一到周五 17:00。周六 8:00–11:00 可以取包裹；PO Box 区周一到周五 6:30–17:00，周六 7:00–11:00。"},"sum":{"en":"Downtown USPS Post Office next to Capitol Square: PO boxes, package pickup and prepaid-label shipping. No passport service.","zh":"Capitol Square 旁的市中心 USPS 邮局，可租邮箱、取包裹、寄预付标签包裹，不办护照。"},"kw":["USPS","post office","邮局","mail","package","包裹","PO Box","邮箱","shipping","寄快递","Capitol Station","Mifflin","downtown","customs form","海关单"],"sec":{"about":{"en":["USPS lists this location as Capitol Station Retail, in Suite 103 at 2 E Mifflin St, by the Capitol Square. It is the downtown Post Office in USPS's locator.","The USPS service list for this location is short: PO Box, package pickup, Label Broker, gift cards and greeting cards. The University Post Office on N Lake St is nearer to campus, and South Side is the one that lists passports."],"zh":["USPS 官网把这里叫 Capitol Station Retail，地址是 2 E Mifflin St 的 103 室，在 Capitol Square 旁边，是 USPS 查询页上的市中心邮局。","官网列的服务不多：PO Box、取包裹、Label Broker、礼品卡和贺卡。离校园更近的是 N Lake St 的 University 邮局，列了护照业务的是 South Side。"]},"offers":{"en":["Rent a PO Box (apply online, finish in person)","Pick up package notices and held mail: Pickup Accountable Mail, Pickup Hold Mail and Pickup Notice Left Mail are all listed","Retail Label Broker: print a prepaid domestic shipping label at the counter","Gift cards and greeting cards","Drop off outgoing mail before the last collection"],"zh":["租邮政信箱 (PO Box)（网上申请，到现场办完手续）","取通知单上的包裹和代管邮件：官网列了 Pickup Accountable Mail、Pickup Hold Mail、Pickup Notice Left Mail 三项","Retail Label Broker：在柜台打印预付的美国国内邮寄标签","礼品卡和贺卡","寄出的信件在最后一次收取时间前投入"]},"howto":{"en":["PO Box: apply on usps.com and choose a size and a 3-, 6- or 12-month term. Within 30 days, bring the printed PS Form 1093 and two forms of acceptable U.S. identification to the Post Office where you reserved the box, to get your keys.","Label Broker: bring the QR code or the 8–10 character Label Broker ID. You get it by email when you choose Print later at Post Office in Click-N-Ship, or from a store that sends you a return label. The label is printed and put on the package at the counter.","Shipping abroad: anything that is not documents needs a computer-generated customs form. Fill it in at home with USPS's Customs Form Online tool or Click-N-Ship, or hand a handwritten form to a retail associate. This location's list does not show Priority Mail International; South Side's does."],"zh":["PO Box：在 usps.com 申请，选大小和 3、6 或 12 个月的期限。30 天内带打印好的 PS Form 1093 和两份可接受的美国证件，到你预订邮箱的那家邮局领钥匙。","Label Broker：带上二维码或 8–10 位的 Label Broker ID。在 Click-N-Ship 里选 Print later at Post Office 会收到邮件，或者商家发退货标签时会带。标签在柜台打印并当场贴到包裹上。","寄国际：只要不是文件，就必须有电脑生成的海关单。可以在家用 USPS 的 Customs Form Online 或 Click-N-Ship 填写，也可以把手写的海关单交给柜员。这家的服务列表里没有 Priority Mail International，South Side 有。"]},"cost":{"en":["USPS says Label Broker printing is free.","A PO Box is rented in 3-, 6- or 12-month terms. Price depends on box size and the Post Office; the online application shows it (not checked for this location)."],"zh":["USPS 说 Label Broker 打印标签不收费。","PO Box 按 3、6 或 12 个月租。价格看箱子大小和邮局，网上申请时会显示（这家的价格没核实）。"]},"tips":{"en":["Weekday hours end at 5 p.m., earlier than the University Post Office's 6 p.m.","On Saturday only package pickup (8–11 a.m.) and PO Box access (7–11 a.m.) are listed. The retail counter is closed.","USPS lists passport appointments and walk-ins at South Side (820 W Wingra Dr, (608) 250-6514), not here.","Label Broker labels cannot be taken home or given extra services, and labels that need a customs form are not eligible."],"zh":["工作日 17:00 关门，比 University 邮局的 18:00 早。","周六只列了取包裹（8:00–11:00）和 PO Box 区（7:00–11:00），柜台不开。","护照预约和直接去办 USPS 列在 South Side（820 W Wingra Dr，(608) 250-6514），这里没有。","Label Broker 的标签不能带回家、不能加额外服务，需要海关单的标签也不能用。"]},"intl":{"en":["USPS asks for a list of what is in the package, with specific names and values for the customs form. Example: \"men's cotton shirts\", not \"clothing\".","The PO Box rule asks for two forms of acceptable U.S. identification. Which ones an international student can use is not stated here; call (608) 250-6485 before you go (unverified)."],"zh":["海关单要写清包里每样东西和价值，要具体。USPS 的例子是写 men's cotton shirts，不要只写 clothing。","PO Box 要两份可接受的美国证件。留学生能用哪些，这里的页面没写；去之前打 (608) 250-6485 问（未核实）。"]}},"src":[["USPS Locator - Capitol Station Retail, Madison","https://tools.usps.com/locations/details/1492395"],["USPS Locator - University Post Office, Madison","https://tools.usps.com/locations/details/1448458"],["USPS Locator - South Side Post Office, Madison","https://tools.usps.com/locations/details/1382279"],["USPS - Label Broker","https://www.usps.com/ship/label-broker.htm"],["USPS FAQ - Label Broker feature","https://faq.usps.com/s/article/Label-Broker"],["USPS FAQ - PO Box: The Basics","https://faq.usps.com/s/article/PO-Box-The-Basics"],["USPS - How to Send an International Package","https://www.usps.com/international/preparing-international-shipments.htm"]],"unv":[],"chk":"2026-10-08","lat":43.075565,"lng":-89.385211,"stops":[["Capitol Square",23,"A B F"],["E Mifflin at N Pinckney",68,"E R 75"],["W Johnson at Wisconsin",193,"D 28"]]},{"id":"usps-university-post-office","cat":"money","n":{"en":"USPS University Post Office","zh":"USPS University 邮局"},"kind":{"en":"Post office","zh":"邮局"},"addr":"441 N Lake St, Madison, WI 53715","phone":"(608) 250-1932","web":"https://tools.usps.com/locations/details/1448458","h":{"Mo":[[480,1080]],"Tu":[[480,1080]],"We":[[480,1080]],"Th":[[480,1080]],"Fr":[[480,1080]],"Sa":[[510,960]],"Su":[]},"ht":{"en":"Retail counter Mon–Fri 8 a.m.–6 p.m., Sat 8:30 a.m.–4 p.m., Sun closed (USPS locator, October 2026). Last collection of outgoing mail is 5 p.m. Mon–Fri and 4 p.m. Sat. On Saturday, package pickup pauses from 11:30 a.m. to 12:30 p.m.","zh":"柜台周一到周五 8:00–18:00，周六 8:30–16:00，周日不开（USPS 官网，2026 年 10 月）。寄出信件的最后一次收取是周一到周五 17:00、周六 16:00。周六取包裹 11:30–12:30 暂停。"},"sum":{"en":"The USPS Post Office nearest campus, on N Lake St: PO boxes, package pickup and prepaid-label shipping. No passport service.","zh":"离校园最近的 USPS 邮局，在 N Lake St，可租邮箱、取包裹、寄预付标签的包裹，不办护照。"},"kw":["USPS","post office","邮局","mail","package","包裹","PO Box","邮箱","shipping","寄快递","international shipping","国际邮寄","Lake Street","University Station","customs form","海关单"],"sec":{"about":{"en":["USPS lists this branch as the University Post Office at 441 N Lake St, the one nearest the UW campus in USPS's locator. Capitol Station, near the Capitol Square, is the downtown option. South Side is the one that lists passports and international parcels."],"zh":["USPS 官网把这家叫 University Post Office，地址 441 N Lake St，是 USPS 查询页上离 UW 校园最近的邮局。市中心的是 Capitol Station（Capitol Square 附近）。列了护照和国际包裹业务的是 South Side。"]},"offers":{"en":["Rent a PO Box (apply online, finish in person)","Pick up package notices and held mail: Pickup Accountable Mail, Pickup Hold Mail and Pickup Notice Left Mail are all listed","Retail Label Broker: print a prepaid domestic shipping label at the counter","Gift cards and greeting cards","Drop off outgoing mail before the last collection"],"zh":["租邮政信箱 (PO Box)（网上申请，到现场办完手续）","取通知单上的包裹和代管邮件：官网列了 Pickup Accountable Mail、Pickup Hold Mail、Pickup Notice Left Mail 三项","Retail Label Broker：在柜台打印预付的美国国内邮寄标签","礼品卡和贺卡","寄出的信件在最后一次收取时间前投入"]},"howto":{"en":["PO Box: apply on usps.com and choose a size and a 3-, 6- or 12-month term. Within 30 days, bring the printed PS Form 1093 and two forms of acceptable U.S. identification to this Post Office to get your keys.","Label Broker: bring the QR code or the 8–10 character Label Broker ID. You get it by email when you choose Print later at Post Office in Click-N-Ship, or from a store that sends you a return label.","A Label Broker label is printed at the counter and put on the package there. You cannot take it home, and USPS says you cannot add extra services to it. Labels that need a customs form are not eligible, so this is for domestic packages.","Shipping abroad: anything that is not documents needs a computer-generated customs form. Fill it in at home with USPS's Customs Form Online tool or Click-N-Ship, or hand a handwritten form to a retail associate, who will make a computer-generated one."],"zh":["PO Box：在 usps.com 申请，选大小和 3、6 或 12 个月的期限。30 天内带打印好的 PS Form 1093 和两份可接受的美国证件到这家邮局领钥匙。","Label Broker：带上二维码或 8–10 位的 Label Broker ID。在 Click-N-Ship 里选 Print later at Post Office 会收到邮件，或者商家给你发退货标签时会带。","Label Broker 的标签在柜台打印并当场贴在包裹上，不能带回家，USPS 说也不能加额外服务。需要海关单的标签不能用，所以只适合美国国内包裹。","寄国际：只要不是文件，就必须有电脑生成的海关单。可以在家用 USPS 的 Customs Form Online 或 Click-N-Ship 填写，也可以把手写的海关单交给柜员，他会帮你重新生成一份。"]},"cost":{"en":["USPS says Label Broker printing is free.","A PO Box is rented in 3-, 6- or 12-month terms. Price depends on box size and the Post Office; the online application shows it (not checked for this branch)."],"zh":["USPS 说 Label Broker 打印标签不收费。","PO Box 按 3、6 或 12 个月租。价格看箱子大小和邮局，网上申请时会显示（这家的价格没核实）。"]},"tips":{"en":["USPS's service list for this branch has no passport service. For passports, South Side (820 W Wingra Dr, (608) 250-6514) lists passport appointments and walk-ins, plus photos.","This branch's list does not include Priority Mail International. South Side lists it at the counter.","Saturday package pickup closes for lunch (11:30 a.m. to 12:30 p.m.), while the retail counter does not.","For a domestic package, the simplest route is to buy postage in Click-N-Ship, choose Print later at Post Office, and take the package and code to the counter."],"zh":["USPS 列的这家服务里没有护照业务。办护照要去 South Side（820 W Wingra Dr，(608) 250-6514），官网列了护照预约、直接去办和拍照。","这家的服务里没有 Priority Mail International（国际优先邮件）。South Side 的柜台有。","周六取包裹 11:30–12:30 午休，柜台本身不午休。","寄美国国内包裹，最省事的是在 Click-N-Ship 买邮资，选 Print later at Post Office，再带着包裹和二维码到柜台。"]},"intl":{"en":["USPS asks for a list of what is in the package, with specific names and values for the customs form. Example: \"men's cotton shirts\", not \"clothing\".","Starting July 1, 2026, packages of merchandise worth up to €150 sent to countries that follow EU customs rules may face new import duties and requirements.","The PO Box rule asks for two forms of acceptable U.S. identification. Which ones an international student can use is not stated here; check USPS's identification page or call (608) 250-1932 (unverified)."],"zh":["海关单要写清包里每样东西和价值，要具体。USPS 的例子是写 men's cotton shirts，不要只写 clothing。","2026 年 7 月 1 日起，往遵循欧盟海关规则的国家寄价值不超过 150 欧元的商品包裹，可能有新的进口关税和要求。","PO Box 要两份可接受的美国证件。留学生能用哪些，这里的页面没写；去之前查 USPS 的证件页或打 (608) 250-1932 问（未核实）。"]}},"src":[["USPS Locator - University Post Office, Madison","https://tools.usps.com/locations/details/1448458"],["USPS Locator - Capitol Station Retail, Madison","https://tools.usps.com/locations/details/1492395"],["USPS Locator - South Side Post Office, Madison","https://tools.usps.com/locations/details/1382279"],["USPS - Label Broker","https://www.usps.com/ship/label-broker.htm"],["USPS FAQ - Label Broker feature","https://faq.usps.com/s/article/Label-Broker"],["USPS - PO Boxes","https://www.usps.com/manage/po-boxes.htm"],["USPS FAQ - PO Box: The Basics","https://faq.usps.com/s/article/PO-Box-The-Basics"],["USPS - How to Send an International Package","https://www.usps.com/international/preparing-international-shipments.htm"]],"unv":[],"chk":"2026-10-08","lat":43.073928,"lng":-89.397296,"stops":[["N Lake at University",95,"80 82"],["East Campus",141,"B"],["N Lake at Langdon",178,"80 82"]]},{"id":"uw-credit-union-state-street","cat":"money","n":{"en":"UW Credit Union (State Street branch)","zh":"UW Credit Union 威大信用社 (State Street 分行)"},"kind":{"en":"Credit union branch","zh":"信用社分行"},"addr":"662 State Street, Madison, WI 53703","phone":"(608) 232-5000","web":"https://www.uwcu.org/branches-and-atms/state-street","h":{"Mo":[[540,1050]],"Tu":[[540,1050]],"We":[[540,1050]],"Th":[[540,1050]],"Fr":[[540,1050]],"Sa":[],"Su":[]},"ht":{"en":"Lobby open Mon–Fri 9 a.m.–5:30 p.m.; closed Sat and Sun (UWCU branch page, October 2026). Closed on Labor Day, Thanksgiving Day and Christmas Day; closes at 1 p.m. on Christmas Eve and New Year's Eve.","zh":"大堂周一到周五 9:00–17:30，周六日不开门（UWCU 分行页面，2026 年 10 月）。劳动节、感恩节、圣诞节关门；平安夜和除夕 13:00 关门。"},"sum":{"en":"UW Credit Union's branch at State St and Lake St, a short walk from the library and Bascom Hill; open a student checking account or use the ATM.","zh":"State St 和 Lake St 路口的学校信用社分行，离图书馆和 Bascom Hill 很近，可开学生支票账户。"},"kw":["UW Credit Union","UWCU","credit union","信用社","bank","银行","checking","支票账户","ATM","State Street","Campus Package","开户","debit card","借记卡"],"sec":{"about":{"en":["UW Credit Union (UWCU) is a member-owned financial institution with a branch at the corner of State Street and Lake Street. The branch page describes it as a full-service credit union that offers checking and savings, credit cards, home and auto loans and retirement planning.","UWCU has other Madison branches too, including one inside Union South on campus."],"zh":["UW Credit Union (UWCU) 是会员所有的非营利金融机构，这家分行在 State Street 和 Lake Street 路口。官网说它是全业务分行：支票和储蓄账户、信用卡、房贷车贷、退休规划都能办。","UWCU 在麦迪逊还有别的分行，校内 Union South 里就有一家。"]},"offers":{"en":["Open a checking or savings account, in the branch or online","Campus Package: a student checking account with a starter Visa credit card option","Debit cards, including Badger designs with Bucky","ATM at the branch","Student loans and refinancing of existing student loans","Free credit score tracking in digital banking and the app"],"zh":["开支票或储蓄账户，可以在柜台办，也可以网上办","Campus Package：给大学生的支票账户，可搭配入门信用卡","借记卡，有带 Bucky 的威大图案可选","分行有 ATM","学生贷款，也可以把已有的学生贷款转过来重新贷","网银和 App 里可以免费看信用分"]},"howto":{"en":["Apply online (about 15 minutes) or walk into any branch. You can also book an appointment on the branch page.","Bring a government photo ID (a passport counts), your Social Security number or Tax ID with ITIN documents, your current physical and mailing address, a phone number and email, and money to fund the account.","Pick \"Campus Package\" when you open the account online, or ask the staff for it at the branch.","UWCU says anyone who is a student at UW–Madison (or an employee or alum) can join. Another route is living, working or going to school within 5 miles of a branch."],"zh":["网上申请约 15 分钟，也可以直接去任何一家分行。分行页面上还能预约时间。","带政府签发的带照片证件（护照可以）、社安号或税号加 ITIN 文件、现居住址和邮寄地址、手机号和邮箱，再带一笔存入账户的钱。","网上开户时选「Campus Package」，在分行就直接跟工作人员说。","UWCU 说 UW–Madison 的学生（以及教职工、校友）都可以加入。另一条路是住在、工作在或上学在任一分行 5 英里内。"]},"cost":{"en":["At least $5 is needed to open an account.","The Campus Package has no monthly fee, according to UWCU.","Balance Backup can cover an overdraft, but a $5 fee applies (capped at $5 per business day). Read the terms before you turn it on."],"zh":["开户最少存 5 美元。","UWCU 说 Campus Package 没有月费。","Balance Backup 可以在余额不够时垫付，但要收 5 美元手续费（每个工作日最多收 5 美元）。开之前先看条款。"]},"tips":{"en":["The branch is closed on weekends. Come on a weekday, and avoid the lunch hour if you can.","The Union South branch is open 9 a.m.–5 p.m. on weekdays and may be closer if you live on the west side of campus.","Bring originals of your documents. The online form asks for the same items as the branch."],"zh":["周末不开门，工作日来，尽量避开午饭时间。","住校园西边的话，Union South 里的分行（工作日 9:00–17:00）可能更近。","证件带原件。网上表格要填的东西和柜台要的一样。"]},"intl":{"en":["UWCU's join page lists a passport as accepted ID and asks for a Social Security number \"if applicable\". The sign-up page says you can give a Tax ID number with ITIN documents instead.","UWCU's pages do not say what happens if you have neither an SSN nor an ITIN. Call (608) 232-5000 or ask at the branch before you go (unverified)."],"zh":["UWCU 的加入页面写明护照可以当证件，社安号「如适用」才要。注册页面说也可以用税号加 ITIN 文件代替。","官网没说既没有 SSN 也没有 ITIN 怎么办。去之前先打 (608) 232-5000 或问柜台（未核实）。"]}},"src":[["UW Credit Union - State St Branch","https://www.uwcu.org/branches-and-atms/state-street"],["UW Credit Union - Union South Branch","https://www.uwcu.org/branches-and-atms/union-south"],["UW Credit Union - Campus Package","https://www.uwcu.org/checking/campus-package"],["UW Credit Union - Membership Eligibility","https://www.uwcu.org/about-us/membership-eligibility"],["UW Credit Union - Open an Account (what you'll need)","https://secure.uwcu.org/getstarted/Welcome/Home/Start"]],"unv":[],"chk":"2026-10-08","lat":43.075108,"lng":-89.396822,"stops":[["N Lake at Langdon",56,"80 82"],["Langdon at N Lake",66,"81"],["N Lake at University",229,"80 82"]]},{"id":"uw-credit-union-union-south","cat":"money","n":{"en":"UW Credit Union (Union South branch)","zh":"UW Credit Union 威大信用社 (Union South 分行)"},"kind":{"en":"Credit union branch","zh":"校内信用社分行"},"addr":"1308 W Dayton Street, Madison, WI 53715","phone":"(608) 232-5000","web":"https://www.uwcu.org/branches-and-atms/union-south","h":{"Mo":[[540,1020]],"Tu":[[540,1020]],"We":[[540,1020]],"Th":[[540,1020]],"Fr":[[540,1020]],"Sa":[],"Su":[]},"ht":{"en":"Lobby open Mon–Fri 9 a.m.–5 p.m.; closed Sat and Sun (UWCU branch page, October 2026). Closed on Labor Day, Thanksgiving Day and the day after Thanksgiving.","zh":"大堂周一到周五 9:00–17:00，周六日不开门（UWCU 分行页面，2026 年 10 月）。劳动节、感恩节和感恩节后一天关门。"},"sum":{"en":"UW Credit Union's campus branch on the first floor of Union South; open a student account, get a replacement debit card or use the ATM.","zh":"UW Credit Union 开在 Union South 一楼的校内分行，可以开学生账户、补办借记卡、用 ATM。"},"kw":["UW Credit Union","UWCU","credit union","信用社","Union South","bank","银行","ATM","debit card","借记卡","开户","Dayton"],"sec":{"about":{"en":["UW Credit Union's campus branch is on the first floor of Union South, across from the Welcome Desk. From the main entrance off Campus Drive, go straight; it sits between the Campus & Visitor Relations Desk and Gallery 1308.","It runs on the same account rules as UWCU's other branches."],"zh":["UW Credit Union 的校内分行在 Union South 一楼，正对着 Welcome Desk。从 Campus Drive 那边的正门进，一直往前走，在 Campus & Visitor Relations 服务台和 Gallery 1308 之间。","开户规则和 UWCU 其他分行一样。"]},"offers":{"en":["Checking and savings accounts","Replacement debit card","Student loan information","Auto loans and a Bucky credit card","ATM"],"zh":["支票账户和储蓄账户","补办借记卡","学生贷款咨询","车贷和 Bucky 信用卡","ATM"]},"howto":{"en":["Apply online (about 15 minutes) or walk in. You can also book an appointment on the branch page.","Bring a government photo ID (a passport counts), your Social Security number or Tax ID with ITIN documents, your addresses, phone number, email and money to fund the account.","Students of UW–Madison qualify for membership, according to UWCU's eligibility page."],"zh":["网上申请约 15 分钟，也可以直接走进去办。分行页面上可以预约。","带政府签发的带照片证件（护照可以）、社安号或税号加 ITIN 文件、住址和邮寄地址、手机号、邮箱，再带一笔存入账户的钱。","按 UWCU 的会员资格页面，UW–Madison 的学生有资格加入。"]},"cost":{"en":["At least $5 is needed to open an account."],"zh":["开户最少存 5 美元。"]},"tips":{"en":["Open weekdays only. The State Street branch stays open until 5:30 p.m. if you need later hours."],"zh":["只有工作日开门。想晚一点去，State Street 分行开到 17:30。"]},"intl":{"en":["UWCU's join page lists a passport as accepted ID and asks for a Social Security number \"if applicable\". The sign-up page says a Tax ID number with ITIN documents also works.","UWCU's pages do not say what happens with neither an SSN nor an ITIN. Call (608) 232-5000 first (unverified)."],"zh":["UWCU 的加入页面写明护照可以当证件，社安号「如适用」才要。注册页面说税号加 ITIN 文件也行。","官网没说两样都没有怎么办。先打 (608) 232-5000 问（未核实）。"]}},"src":[["UW Credit Union - Union South Branch","https://www.uwcu.org/branches-and-atms/union-south"],["UW Credit Union - State St Branch","https://www.uwcu.org/branches-and-atms/state-street"],["UW Credit Union - Membership Eligibility","https://www.uwcu.org/about-us/membership-eligibility"],["UW Credit Union - Open an Account (what you'll need)","https://secure.uwcu.org/getstarted/Welcome/Home/Start"]],"unv":[],"chk":"2026-10-08","lat":43.072211,"lng":-89.408637,"stops":[["N Randall at Engineering",45,"D O 80"],["W Johnson at N Orchard",70,"C D J O R"],["N Randall at W Dayton",97,"D O"]]},{"id":"madison-police-central-district","cat":"help","n":{"en":"Madison Police Department, Central District","zh":"麦迪逊市警察局 Central District"},"kind":{"en":"City police office","zh":"市警察分局"},"addr":"211 S Carroll St, Madison, WI 53703","phone":"(608) 261-9694","web":"https://www.cityofmadison.com/police/inside-mpd/districts/central","h":{"Mo":[[480,960]],"Tu":[[480,960]],"We":[[480,960]],"Th":[[480,960]],"Fr":[[480,960]],"Sa":[],"Su":[]},"ht":{"en":"Public hours (front desk): Mon–Fri 8 a.m.–4 p.m. Patrol officers cover the district 24/7. Non-emergency dispatch: (608) 255-2345. Property Room: Tue and Thu 8 a.m.–4 p.m. from the week of Oct 18, 2026.","zh":"前台对外开放：周一到周五 8:00–16:00。巡逻警察全天 24 小时负责本区。非紧急调度电话 (608) 255-2345。证物/失物室从 2026 年 10 月 18 日那周起，周二、周四 8:00–16:00 对外。"},"sum":{"en":"City police office in the City-County Building: off-campus reports, lost property and $9 visa clearance letters.","zh":"市警察分局：校外报案、失物，还能开 $9 的警察清查证明信。"},"kw":["MPD","Madison police","市警察","police report","报案","non-emergency","非紧急","clearance letter","visa criminal check","无犯罪记录","police clearance","lost property","失物","City-County Building"],"sec":{"about":{"en":["The Madison Police Department (MPD) is the city police, split into districts. Central District works from the lower level of the City-County Building at 211 S Carroll St. It has about 40 patrol officers covering the district 24/7 and a Computer/Financial Crimes detective unit.","On campus, UWPD takes reports. For incidents elsewhere in the City of Madison, MPD is the city's police department, and UWPD's own FAQ points people to MPD's district offices."],"zh":["麦迪逊市警察局 (MPD) 是市警察，分成几个区。Central District 在 City-County Building 的地下一层，地址 211 S Carroll St。有约 40 名巡逻警察全天 24 小时负责本区，另有计算机/金融犯罪侦探组。","校内报案找 UWPD。校外、麦迪逊市内的事归 MPD，UWPD 自己的 FAQ 也会指引大家去 MPD 的分局。"]},"offers":{"en":["Reports of crimes that already happened, by phone to non-emergency dispatch or through an online self-report page for some incidents.","Clearance or visa criminal check letter for the City of Madison, notarized, $9.00.","Lost property: found items are held 45 days and listed on MPD's website; the Property Room returns them.","Public records and police report requests, online, by phone or at the City-County Building.","Anonymous crime tips through Madison Area Crime Stoppers."],"zh":["已经发生的案件，可以打非紧急调度电话报案，部分事件也可在线自助报案。","麦迪逊市的警察清查证明信 (clearance/visa criminal check)，经过公证，$9.00。","失物：警察捡到的物品保管 45 天，名单发在 MPD 网站上，由证物室 (Property Room) 归还。","公共记录和警方报告申请，可在线、电话或到 City-County Building 办理。","通过 Madison Area Crime Stoppers 匿名提供线索。"]},"howto":{"en":["Emergency or a crime happening now: call 911.","A crime that already happened, not an emergency: call (608) 255-2345, or use the self-report page for non-vehicle incidents on the City of Madison police site.","To visit, use the public entrance at 210 Martin Luther King Jr. Blvd (City-County Building) and follow the signs to the lower level. The front desk phone is (608) 261-9694.","Clearance or visa letter: request in person or by mail only, prepay $9.00 per person, address it to Madison Police Court Services, Backgrounds, Room GR10, phone (608) 261-8015. For a letter mailed abroad, send an addressed, prepaid envelope.","Lost property: contact the Property Room first, (608) 266-4955 or PDProperty@cityofmadison.com. Bring photo ID."],"zh":["紧急情况或案件正在发生：打 911。","案件已经发生、不紧急：打 (608) 255-2345，或用市警察网站的自助报案页面（非车辆类事件）。","上门去：走 210 Martin Luther King Jr. Blvd（City-County Building）的公共入口，按指示牌下到地下一层。前台电话 (608) 261-9694。","清查证明信：只能当面或邮寄申请，每人预付 $9.00，寄给 Madison Police Court Services, Backgrounds, Room GR10，电话 (608) 261-8015。信要寄国外的话，附上写好地址、付好邮资的信封。","找失物：先联系证物室，(608) 266-4955 或 PDProperty@cityofmadison.com。取东西要带有照片的证件。"]},"cost":{"en":["Clearance or visa letter: $9.00 per person, paid before the letter is processed.","Public records: MPD says there are fees for some requests, depending on the format and how long staff need to collect the records."],"zh":["清查证明信：每人 $9.00，处理前先付。","公共记录：MPD 说部分申请要收费，看记录的格式和工作人员收集所需的时间。"]},"tips":{"en":["The clearance letter lists City of Madison arrests since age 17 only. For all of Wisconsin MPD points to the state Department of Justice, and for the whole U.S. to the FBI.","Allow 7–10 business days for the letter, plus mailing time if it goes abroad.","MPD says public records requests average about 5 months, so ask early for anything you need later.","The Property Room opens Tuesdays and Thursdays 8 a.m.–4 p.m. starting the week of Oct 18, 2026. Call or email to set a time.","Found-property lists cover the last 45 days. Check the MPD lost property page if you lost something off campus."],"zh":["清查证明信只列 17 岁以后在麦迪逊市的逮捕记录。全威斯康星的查询 MPD 指向州司法部 (Department of Justice)，全美国的指向 FBI。","信要 7–10 个工作日，寄国外还要加邮寄时间。","MPD 说公共记录申请平均要约 5 个月，以后要用的东西早点申请。","证物室从 2026 年 10 月 18 日那周起，周二、周四 8:00–16:00 开放。先打电话或发邮件约时间。","失物名单只覆盖最近 45 天。校外丢了东西，看 MPD 的失物页面。"]},"intl":{"en":["The clearance or visa letter is what to ask about if a visa, immigration or home-country application wants a local police check. It covers Madison only, so ask the agency whether that is enough."],"zh":["签证、移民或国内手续要求本地警察证明时，就问这封清查证明信。它只覆盖麦迪逊市，先问清要信的机构这样够不够。"]}},"src":[["City of Madison Police - Central District","https://www.cityofmadison.com/police/inside-mpd/districts/central"],["City of Madison Police - Police Directory","https://www.cityofmadison.com/police/contact/directory"],["City of Madison Police - Report an Incident","https://www.cityofmadison.com/police/report-an-incident"],["City of Madison Police - Records Requests","https://www.cityofmadison.com/police/data-records/records-requests"],["City of Madison Police - Clearance or Visa Criminal Checks","https://www.cityofmadison.com/police/data-records/records-requests/clearance-or-visa-criminal-checks"],["City of Madison Police - Evidence & Property, Lost Property","https://www.cityofmadison.com/police/contact/evidence-property"],["UWPD - Frequently Asked Questions","https://uwpd.wisc.edu/about-us/faqs/"]],"unv":[],"chk":"2026-10-08","lat":43.072204,"lng":-89.382685,"stops":[["W Wilson at M L K Junior",84,"C 38"],["E Doty at M L K Junior",156,"C 38"],["Capitol Square",161,"A B F"]]},{"id":"wisconsin-dmv-madison-southwest","cat":"help","n":{"en":"Madison Southwest DMV Service Center","zh":"威斯康星 DMV 车管所（Madison Southwest）"},"kind":{"en":"DMV license and ID office","zh":"车管所（驾照/州 ID）"},"addr":"2344 S Park St, Madison, WI 53713","phone":"(608) 264-7447","web":"https://wisconsindot.gov/Pages/online-srvcs/find-dmv/default.aspx","h":{"Mo":[[510,1005]],"Tu":[[510,1005]],"We":[[510,1005]],"Th":[[510,1005]],"Fr":[[510,1005]],"Sa":[],"Su":[]},"ht":{"en":"Mon–Fri 8:30 a.m.–4:45 p.m., closed Sat–Sun (WisDOT, October 2026). The written exam takes about 45 minutes, so arrive well before closing. The phone is the statewide Driver Services line, answered 7:30 a.m.–4:30 p.m. weekdays.","zh":"周一到周五 8:30–16:45，周末关门（WisDOT，2026 年 10 月）。笔试约 45 分钟，别快关门才到。电话是全州 Driver Services 热线，工作日 7:30–16:30 有人接。"},"sum":{"en":"The Madison DMV closest to campus: Wisconsin ID cards, driver licenses and permit tests. Book an appointment to skip the wait.","zh":"离校园最近的 DMV：办威州 ID 卡、驾照、学习证，先预约不用排队。"},"kw":["DMV","driver license","驾照","state ID","州ID","ID card","permit","学习驾照","limited term","Temporary Visitor","车管所","road test","路考","knowledge test","MV3001","MV3004","MV3741","Park St"],"sec":{"about":{"en":["The Wisconsin Division of Motor Vehicles (DMV) issues state ID cards and driver licenses. Madison has two service centers: Madison Southwest (2344 S Park St), the closer one to campus, and Madison East (2001 Bartillon Dr). Both handle licenses and ID cards.","Non-citizens can get a card too. It is marked limited term and expires on the date your immigration document does. A Wisconsin ID is not proof of your immigration status."],"zh":["威斯康星州车辆管理局 (DMV) 负责发州 ID 卡和驾照。麦迪逊有两个办理中心：离校园较近的 Madison Southwest (2344 S Park St)，和 Madison East (2001 Bartillon Dr)，都能办驾照和 ID 卡。","非美国公民也能办。卡上会标 limited term，到期日和你的移民文件到期日一致。州 ID 不能证明你的移民身份。"]},"offers":{"en":["Wisconsin state ID card: first-time application, renewal and duplicate.","Driver license and instruction permit applications, with the knowledge, road-sign and vision tests done at the center.","A photo taken on the spot; the ID card is mailed to you, and a paper receipt with your photo serves as ID until it arrives.","A card that works as photo ID for things like opening a bank account."],"zh":["办威州 ID 卡：首次申请、续期、补办。","申请驾照和学习证 (instruction permit)，知识、路标、视力测试都在这里考。","现场拍照；ID 卡之后邮寄，卡到之前用带照片的纸质收据当证件。","拿到的卡可当带照片的证件用，比如开银行账户。"]},"howto":{"en":["Fill in the form first: MV 3001 for a driver license, MV 3004 for an ID card. Tick the Temporary Visitor box.","Use the DMV's online Driver License/ID Guide to pre-fill forms and book an in-office appointment, which skips the wait. New slots are added through the week. Road tests are booked separately.","Bring originals, not photocopies: passport with visa, most recent I-94, I-20 or DS-2019, and a photo ID from a U.S. university such as your Wiscard.","Bring two proofs of your Wisconsin address with your name, such as a utility bill, a local bank statement or a phone bill.","Give your Social Security number. If you are not eligible for one, sign form MV 3741 at the DMV instead.","Pay by cash, check, money order, debit card, or Visa, MasterCard, American Express or Discover."],"zh":["先填表：驾照用 MV 3001，ID 卡用 MV 3004。勾选 Temporary Visitor（临时访客）。","用 DMV 官网的在线 Driver License/ID Guide 预填表格并预约到店时间，可以免排队，每周都会放新号。路考要另外约。","带原件，不收复印件：护照（含签证）、最新 I-94、I-20 或 DS-2019，再加一张美国大学发的带照片证件，比如 Wiscard。","带两份写着你名字的威州住址证明，比如水电费账单、本地银行对账单或手机账单。","要填社安号 (SSN)。没资格办 SSN 的话，在 DMV 现场签 MV 3741 表。","可用现金、支票、汇票、借记卡，或 Visa、MasterCard、American Express、Discover 信用卡。"]},"cost":{"en":["ID card: $28 for an original 8-year card. Driver license: $42.50 for an original 8-year Class D license.","Instruction permit (18 months): $35. Knowledge and sign tests: $0. Skills (road) exam: $15, charged for every appointment not canceled 24 hours in advance.","The fee table does not say whether a shorter limited-term card costs less."],"zh":["ID 卡：首次办 8 年卡 $28。驾照：8 年期 Class D 首次办 $42.50。","学习证 (instruction permit，18 个月) $35。知识和路标考试 $0。路考 (skills exam) $15，提前不到 24 小时取消的预约也照收。","收费表没写期限更短的 limited term 卡是否更便宜。"]},"tips":{"en":["Check your I-20/DS-2019 dates first. ISS says a driver license needs a document valid at least one year in total with more than 6 months left. For an ID card: more than 6 months in total and more than 3 months left.","Non-citizens must show legal-presence documents every time they apply for a license, permit or ID card.","If your I-94 has a misspelled name or the name order is wrong, get it corrected with CBP before you go.","You cannot hold a driver license and a state ID at the same time.","Madison East (2001 Bartillon Dr) is farther from campus but opens Saturday 8:30 a.m.–noon.","If the ID card has not come within 10 business days, contact the DMV by email.","Carry copies of your passport, visa, I-94 and I-20 anyway: a Wisconsin ID does not prove your legal status."],"zh":["先查 I-20/DS-2019 的日期。ISS 说办驾照要求文件总有效期至少 1 年且剩余超过 6 个月；办 ID 卡要求总有效期超过 6 个月、剩余超过 3 个月。","非美国公民每次申请驾照、学习证或 ID 卡，都要出示合法停留文件。","I-94 上名字拼错或顺序不对的话，去 DMV 前先找 CBP 更正。","驾照和州 ID 不能同时持有。","Madison East (2001 Bartillon Dr) 离校园更远，但周六 8:30–12:00 开门。","ID 卡 10 个工作日还没到，就发邮件联系 DMV。","护照、签证、I-94、I-20 的复印件或电子版照常随身带：州 ID 证明不了你的合法身份。"]},"intl":{"en":["With a valid license from an eligible home country you may drive on it for up to 1 year. Bring an International Driving Permit or an English translation. After 1 year you need a Wisconsin license.","No SSN yet? The DMV still processes your application; you sign MV 3741 (SSN non-eligibility statement).","Wisconsin requires liability insurance for drivers. Do not drive without it."],"zh":["持有符合条件国家的有效驾照，可以用它在威州开车最长 1 年。要带国际驾照 (IDP) 或英文翻译件。满 1 年后要换威州驾照。","还没有 SSN？DMV 照样受理，你在现场签 MV 3741（SSN 无资格声明）。","威州要求司机必须有责任险。没保险别开车。"]}},"src":[["WisDOT - Find My DMV map data: Madison service centers","https://dotmaps.wi.gov/arcgis/rest/services/agohub/DMV_SERVICE_CENTER/MapServer/0/query?where=STN_CITY%3D%27Madison%27&outFields=STN_NAME%2CSTN_ADDR_LINE%2CSTN_ZPCD%2CSTN_HRS_MON%2CSTN_HRS_TUE%2CSTN_HRS_WED%2CSTN_HRS_THUR%2CSTN_HRS_FRI%2CSTN_HRS_SAT%2CSTN_HRS_SUN%2CDRV_DL_FL%2CDRV_IDCARD_FL&returnGeometry=false&f=pjson"],["WisDOT - DMV customer service centers","https://wisconsindot.gov/Pages/online-srvcs/find-dmv/default.aspx"],["WisDOT news release - Madison West DMV moves to South Park Street","https://wisconsindot.gov/Pages/about-wisdot/newsroom/news-rel/051424dmvmovesw.aspx"],["WisDOT - Contact DMV","https://wisconsindot.gov/Pages/about-wisdot/contact-us/dmv-contact.aspx"],["WisDOT - How to apply: driver license and ID card appointments","https://wisconsindot.gov/Pages/dmv/license-drvs/how-to-apply/get-lic-or-id.aspx"],["WisDOT - Documentation requirements (online appointment scheduler)","https://wisconsindot.gov/Pages/dmv/license-drvs/how-to-apply/documentation.aspx"],["WisDOT - DMV fees","https://wisconsindot.gov/Pages/dmv/vehicles/title-plates/dmv-fees.aspx"],["WisDOT - Proof of citizenship or legal status","https://wisconsindot.gov/Pages/dmv/license-drvs/how-to-apply/citizen-leg-pres.aspx"],["WisDOT - Acceptable documents for a Wisconsin driver license or ID card (BDS316)","https://wisconsindot.gov/Documents/dmv/shared/bds316-english.pdf"],["WisDOT - Social Security number requirement","https://wisconsindot.gov/Pages/dmv/license-drvs/how-to-apply/socialsecuritynumber.aspx"],["WisDOT - Obtaining an identification (ID) card","https://wisconsindot.gov/Pages/dmv/license-drvs/how-to-apply/id-card.aspx"],["UW-Madison ISS - Wisconsin driver's license or identification card","https://iss.wisc.edu/students/current-students/license-or-id/"]],"unv":["phone"],"chk":"2026-10-08","lat":43.040031,"lng":-89.394399,"stops":[["S Park at Hughes",13,"B 64"],["Hughes at S Park",25,"G H O"],["W Badger at S Park",169,"G 61 64"]]},{"id":"uw-safewalk","cat":"help","n":{"en":"SAFEwalk","zh":"SAFEwalk 夜间陪走服务"},"kind":{"en":"Night walking escort","zh":"夜间陪走服务"},"addr":"610 Walnut St, Madison, WI 53726","phone":"(608) 262-5000","web":"https://transportation.wisc.edu/commuter-solutions/safewalk/","h":{"Mo":[[1140,1500]],"Tu":[[1140,1500]],"We":[[1140,1500]],"Th":[[1140,1500]],"Fr":[[1140,1500]],"Sa":[[1140,1500]],"Su":[[1140,1500]]},"ht":{"en":"7 p.m.–1 a.m. from Oct 1 to Mar 31; 8 p.m.–1 a.m. from Apr 1 to Sep 30. No service on legal holidays or from Dec 18, 2026 to Jan 10, 2027. The official page gives hours but not weekdays.","zh":"10 月 1 日到 3 月 31 日 19:00–次日 1:00；4 月 1 日到 9 月 30 日 20:00–次日 1:00。法定假日和 2026 年 12 月 18 日到 2027 年 1 月 10 日不提供。官网只写了时段，没写星期几。"},"sum":{"en":"Free night walking escort on and near campus: call or text (608) 262-5000 and a two-person student team meets you.","zh":"免费夜间陪走：打电话或发短信 (608) 262-5000，两人学生小组来接你。"},"kw":["SAFEwalk","safe walk","escort","陪走","夜间","night","walking","safety","安全","UW Transportation Services","Lightway","262-5000"],"sec":{"about":{"en":["SAFEwalk is a free walking companionship service run by UW–Madison Transportation Services. Two-person teams of student walkers meet you and walk with you to your destination at night, around campus and to or from nearby places.","It is not a ride and not an office you visit. You call or text a dispatcher and a team comes to you. The address on this card is the coordinator's office, not a pick-up point."],"zh":["SAFEwalk 是 UW–Madison Transportation Services 运营的免费夜间陪走服务。两人一组的学生陪走员到你所在的位置，陪你走到目的地，范围是校园和附近地点。","它不是接送车，也不是要去的办公室。你给调度员打电话或发短信，小组会来找你。本页地址是协调员办公室，不是接人地点。"]},"offers":{"en":["A walking escort from where you are to where you are going, inside the service boundaries.","Walks set up in advance, for example after a late class or a work shift.","Teams carry a two-way radio and can act as a mobile emergency phone.","Teams also watch for suspicious situations and answer transportation and safety questions.","A PDF map of the service boundaries and the lit Lightway paths."],"zh":["从你所在的位置陪你走到目的地，范围在服务边界内。","可以提前预约，比如晚课或下班之后。","陪走小组带对讲机，可以当移动紧急电话用。","小组还会留意可疑情况，也能回答交通和安全方面的问题。","官网有服务边界和 Lightway 照明步道的 PDF 地图。"]},"howto":{"en":["Call or text (608) 262-5000 during service hours. Tell the dispatcher your first name, where you are and where you are going.","The dispatcher decides from your location and destination whether you are eligible, then sends a team to you.","Give the number you are calling from and stay by that phone. The walkers may call you if they cannot find you.","To book a walk ahead of time, call or text the same number.","Service boundaries do not include far west campus, such as UW Hospital and Eagle Heights.","Look for bright orange clothing with the SAFE Walk logo."],"zh":["在服务时段内打电话或发短信到 (608) 262-5000。告诉调度员你的名字（只要名）、所在位置和目的地。","调度员根据你的位置和目的地判断能否服务，然后派小组去找你。","说清你用的电话号码，并留在电话旁。陪走员找不到你时会打给你。","想提前约，打或发短信到同一个号码。","服务边界不包括校园远西侧，比如 UW Hospital 和 Eagle Heights。","认准印有 SAFE Walk 标志的亮橙色衣服。"]},"cost":{"en":["Free for all students, faculty, staff and UW visitors."],"zh":["对所有学生、教职工和 UW 访客免费。"]},"tips":{"en":["No service on legal holidays or from Dec 18, 2026 to Jan 10, 2027, so plan another way home during the finals break.","The Lightway is a network of well-lit sidewalks and paths marked with yellow reflective signs. Use it when you walk alone.","Campus emergency phones usually have a blue light and a 911-Emergency label: lift the handset, push the button, wait for the UWPD dispatcher.","At night you can walk into the foyer of any University Residence Hall if you need a safe place.","UWPD's BadgerSAFE app also works as a personal safety tool on your phone.","SAFEride, the old late-night cab program, ended in 2012. SAFEwalk is what UW offers now.","Outside SAFEwalk hours or boundaries, UW Transportation Services lists Madison Taxi, (608) 255-8294, and Union Cab, (608) 242-2000."],"zh":["法定假日和 2026 年 12 月 18 日到 2027 年 1 月 10 日不服务，期末假期要另外想办法回家。","Lightway 是一片照明好的人行道和步道，用黄色反光牌标出。一个人走时尽量走这些路。","校内紧急电话一般有蓝灯和 911-Emergency 标签：拿起听筒，按按钮，等 UWPD 调度员接听。","晚上需要安全的地方，可以走进任何一栋 University Residence Hall 的门厅。","UWPD 的 BadgerSAFE 手机 App 也能当个人安全工具用。","老的深夜出租车项目 SAFEride 2012 年就停了，现在 UW 提供的是 SAFEwalk。","SAFEwalk 时段外或范围外，UW Transportation Services 列了 Madison Taxi (608) 255-8294 和 Union Cab (608) 242-2000。"]},"intl":{"en":["If speaking English on the phone is hard, text (608) 262-5000. The service takes texts."],"zh":["电话里说英语有压力的话，可以发短信到 (608) 262-5000，这个服务接受短信。"]}},"src":[["UW Transportation Services - SAFEwalk","https://transportation.wisc.edu/commuter-solutions/safewalk/"],["UWPD - Walk Smart","https://uwpd.wisc.edu/walk-smart/"],["UW-Madison News - SAFEride cab service discontinued (2012)","https://news.wisc.edu/saferide-cab-service-discontinued/"]],"unv":[],"chk":"2026-10-08","lat":43.076109,"lng":-89.424979,"stops":[["Walnut at Observatory",21,"82"],["Observatory at Walnut",60,"28 38 65 80"],["Walnut at Gifford Pinchot",201,"82"]]},{"id":"social-security-office-madison","cat":"help","n":{"en":"Social Security Administration Office (Madison)","zh":"社会安全局 (SSA) 麦迪逊办事处"},"kind":{"en":"Federal SSN office","zh":"社安号办理处"},"addr":"6011 Odana Rd, Madison, WI 53719","phone":"(866) 770-2262","web":"https://www.ssa.gov/locator/","h":{"Mo":[[540,960]],"Tu":[[540,960]],"We":[[540,960]],"Th":[[540,960]],"Fr":[[540,960]],"Sa":[],"Su":[]},"ht":{"en":"Mon–Fri 9 a.m.–4 p.m. (SSA's field-office list, October 2026). Closed on federal holidays. Make an appointment before you go.","zh":"周一到周五 9:00–16:00（SSA 办事处名单，2026 年 10 月）。联邦假日关门。去之前先预约。"},"sum":{"en":"Where F-1/J-1 students apply in person for a first Social Security number (SSN), by appointment, after the ISS letter and SSA's online form.","zh":"F-1/J-1 学生办第一个社安号 (SSN) 的地方，要预约，带原件。"},"kw":["SSN","Social Security","social security number","社安号","社保号","SS-5","SSA","社安局","F-1","J-1","appointment","预约","Odana"],"sec":{"about":{"en":["The Madison office of the Social Security Administration (SSA), the federal agency that issues Social Security numbers (SSN). An SSN is a 9-digit number that employers use to report your wages. SSA gives one to a noncitizen only if the person has permission to work in the U.S.","Students do not just walk in. For an on-campus job, ISS first approves a UW–Madison SSN letter in Terra Dotta, you finish SSA's online application to get a reference number, and then you go to the Odana Rd office on your appointment day with original documents."],"zh":["美国联邦社会安全局 (SSA) 在麦迪逊的办事处，负责发放社安号 (SSN)。SSN 是 9 位数字，雇主用它向政府报你的工资。外国人只有获准在美国工作，SSA 才会给号。","不能空手直接去。有校内工作的话，先在 Terra Dotta 向 ISS 申请 UW–Madison SSN 信，再在 SSA 网站填在线申请拿到参考号，最后带原件按预约时间来 Odana Rd 这个办事处。"]},"offers":{"en":["First-time SSN for F-1 and J-1 students who have work permission: on-campus job, CPT, OPT, or J-1 on-campus work or Academic Training.","A check of your original documents: passport with admission stamp, I-94, I-20 (F-1) or DS-2019 (J-1), and proof of the job.","A letter saying you applied for an SSN, which your employer can use while you wait for the card.","The card itself comes later by mail, not at the counter."],"zh":["给有工作许可的 F-1/J-1 学生办第一个社安号：校内工作、CPT、OPT，或 J-1 校内工作/Academic Training。","当场核对原件：带入境章的护照、I-94、I-20 (F-1) 或 DS-2019 (J-1)，还有工作证明。","开一封「已申请 SSN」的信，卡没到之前雇主可以用它。","卡之后寄到家，柜台上不发卡。"]},"howto":{"en":["Check you are eligible. A first-semester F-1 student can apply only after UW registers the SEVIS record (within 30 days of the first day of the semester) and issues a new I-20 marked Continued Attendance.","On-campus job: request the UW–Madison SSN Letter in Terra Dotta; ISS usually approves it within 15 business days. The job letter should show UW's EIN, 39-6006492. If it does not, bring your latest UW pay statement.","Start SSA's online application and write down the reference number. SSA cannot retrieve your application without it. Print the SS-5 form too.","Book a time at the Madison office. ISS says you must have an appointment and recommends Madison over other SSA offices.","Bring originals, not photocopies: passport, latest I-94, latest I-20 (off-campus CPT/OPT: the one with the authorization) or DS-2019, job letter or pay statement, SS-5, reference number, UW SSN letter.","When the card arrives, show it with your passport at the Registrar's Office, 333 E Campus Mall, so UW can update your record."],"zh":["先确认能办。F-1 新生要等学校在 SEVIS 里完成注册（开学后 30 天内），拿到写着 Continued Attendance 的新 I-20，才能申请。","有校内工作：在 Terra Dotta 申请 UW–Madison SSN 信，ISS 一般 15 个工作日内批。工作信上应写明学校的 EIN 39-6006492，没写就带最近一张 UW 工资单。","先在 SSA 网站开始在线申请，记下参考号 (reference number)，没有它 SSA 调不出你的申请。再把 SS-5 表打印出来。","预约麦迪逊办事处的时间。ISS 说必须预约，并建议选麦迪逊，不要选别的办事处。","只认原件，不收复印件：护照、最新 I-94、最新 I-20（校外 CPT/OPT 要带有授权的那份）或 DS-2019、工作信或工资单、SS-5、参考号、UW SSN 信。","卡寄到后，带卡和护照去教务处 (Registrar's Office, 333 E Campus Mall)，让学校更新你的档案。"]},"cost":{"en":["Free. SSA says you can request a first Social Security number at no charge.","The card is mailed 5 to 10 business days after SSA approves the application (SSA website, October 2026)."],"zh":["免费。SSA 官网写明第一个社安号不收费。","SSA 批准后，卡在 5 到 10 个工作日内寄到（SSA 官网，2026 年 10 月）。"]},"tips":{"en":["Book ahead. SSA says an appointment lets you skip the line, and ISS tells students an appointment is required.","Skip the day before and the day after a federal holiday. The office is closed on federal holidays and the days around them are very busy (ISS tip).","SSA cannot process your application if your on-campus or CPT job starts more than 30 days after your application date. Go close to your start date.","SSA does not require an SSN before you start work. Ask your employer's HR what they need in the meantime.","No job, only a scholarship or fellowship? SSA does not issue an SSN just for enrolling. ISS has a page on the ITIN for that case."],"zh":["提前约。SSA 说预约可以免排队，ISS 也要求学生必须预约。","避开联邦假日的前一天和后一天。联邦假日办事处关门，前后几天人特别多（ISS 的提醒）。","如果校内工作或 CPT 的开始日期比申请日晚 30 天以上，SSA 不会受理。离开工日近一点再去。","开工前不一定要有 SSN，SSA 不强制。拿到号之前要什么材料，问雇主的 HR。","没有工作、只有奖学金？SSA 不会只因为你上学就发 SSN。这种情况看 ISS 的 ITIN 页面。"]},"intl":{"en":["F-2 dependents cannot get an SSN. J-2 dependents can if they have work authorization.","You do not need an SSN to receive bank service, register for school, or buy private health insurance.","SSA's national line, 1-800-772-1213, answers 8 a.m.–7 p.m. on weekdays and gives free interpreters on request."],"zh":["F-2 家属不能办 SSN。J-2 家属有工作许可才能办。","开银行账户、注册课程、买私人医疗保险都不需要 SSN。","SSA 全国电话 1-800-772-1213，周一到周五 8:00–19:00 有人接，可以免费要求口译。"]}},"src":[["SSA - Field office addresses and open/close times (data file)","https://www.ssa.gov/data/FO-Address-Open-Close-Times.csv"],["SSA - Field Office Locator","https://www.ssa.gov/locator/"],["SSA - Request a Social Security number for the first time","https://www.ssa.gov/number-card/request-number-first-time"],["SSA - International Students and Social Security Numbers (Publication 05-10181)","https://www.ssa.gov/pubs/EN-05-10181.pdf"],["SSA - Contact Social Security by phone","https://www.ssa.gov/agency/contact/phone.html"],["UW-Madison ISS - Social Security Number (SSN)","https://iss.wisc.edu/employment/social-security/"],["UW-Madison ISS - Tips on Applying for a Social Security Number","https://iss.wisc.edu/tips-on-applying-for-a-social-security-number/"]],"unv":[],"chk":"2026-10-08","lat":43.052404,"lng":-89.4847,"stops":[["Odana at Research Park",169,"J"],["Odana at Tokay",257,"J"],["Odana at Medical",578,"J"]]},{"id":"tenant-resource-center","cat":"help","n":{"en":"Tenant Resource Center (UW–Madison campus office)","zh":"租户资源中心 Tenant Resource Center（校园办公室）"},"kind":{"en":"Renter rights help","zh":"租房权益咨询"},"addr":"333 E Campus Mall, Madison, WI 53715","phone":"(608) 292-5608","web":"https://www.tenantresourcecenter.org/uw_madison_office","h":{"Mo":[],"Tu":[[600,1080]],"We":[],"Th":[[600,1080]],"Fr":[],"Sa":[],"Su":[]},"ht":{"en":"Campus office (Student Activity Center, Room 3158): drop-in Tue and Thu 10 a.m.–6 p.m. Main office, 2510 Winnebago St: Mon 9–6 drop-in; Tue 9–6 by appointment; Wed appointments 9–1, drop-in 1–6; Thu appointments 9–1, drop-in 1–4.","zh":"校内办公室（Student Activity Center 3158 室）：周二、周四 10:00–18:00 随到随办。总部 2510 Winnebago St：周一 9–18 随到；周二 9–18 需预约；周三上午 9–13 预约、13–18 随到；周四上午 9–13 预约、13–16 随到。"},"sum":{"en":"Free, confidential help with leases, deposits, repairs and evictions. The campus office is open Tue and Thu; the hotline is (608) 257-0006.","zh":"免费保密的租房咨询：合同、押金、维修、驱逐。校内办公室周二、周四开放。"},"kw":["TRC","tenant","租房","租客权益","lease","合同","security deposit","押金","repairs","维修","eviction","驱逐","landlord","房东","break lease","退租","Rental Rights Hotline"],"sec":{"about":{"en":["The Tenant Resource Center (TRC) is a Madison nonprofit that gives tenants and landlords information on Wisconsin rental law. Its housing counselors answer questions about earnest money, security deposits, breaking a lease, repairs and eviction. Dane County residents can talk to a counselor for free and in confidence.","TRC runs a campus office in the Student Activity Center, 333 E Campus Mall, Room 3158. Its main office is at 2510 Winnebago St. Rights for student tenants are the same as for other tenants, and students are a protected class in Madison."],"zh":["租户资源中心 (TRC) 是麦迪逊的非营利组织，给租客和房东讲解威斯康星的租房法律。住房顾问回答定金、押金、提前退租、维修、驱逐这些问题。Dane County 居民可以免费、保密地咨询。","TRC 在校内有办公室：Student Activity Center，333 E Campus Mall 3158 室。总部在 2510 Winnebago St。学生租客的权利和其他租客一样，而且在麦迪逊学生是受保护群体。"]},"offers":{"en":["Housing counseling by phone or in person: earnest money, security deposits, breaking a lease, repairs, eviction.","Rental Rights Hotline: (608) 257-0006, toll-free 877-238-RENT (7368).","Free mediation between tenants and landlords on eviction, noise complaints, security deposits, unpaid rent and other lease violations.","Your Rights pages and sample letters on the website, plus a student guide to renting in Madison, roommates, repairs, ending a lease and deposits.","Help for people facing eviction court in Dane County through the Eviction Diversion and Defense Partnership (EDDP).","An online eviction prevention screening for renters who are behind on rent.","Counseling in Spanish and Hmong."],"zh":["住房咨询（电话或当面）：定金、押金、提前退租、维修、驱逐。","租客权益热线 (Rental Rights Hotline)：(608) 257-0006，免费长途 877-238-RENT (7368)。","租客和房东之间的免费调解：驱逐、噪音投诉、押金、欠租和其他违反合同的问题。","官网有 Your Rights 权益文章和信件模板，还有学生版指南：在麦迪逊租房、室友、维修、解约和押金。","通过驱逐防御合作项目 (EDDP) 帮助在 Dane County 面临驱逐诉讼的人。","欠租的租客可以在网上做驱逐预防筛查 (eviction prevention screening)。","提供西班牙语和苗语咨询。"]},"howto":{"en":["Campus office: Student Activity Center, 333 E Campus Mall, Room 3158. Drop in on Tuesdays and Thursdays from 10 a.m. to 6 p.m., or call (608) 292-5608.","Main office, 2510 Winnebago St: Monday is drop-in only, 9 a.m.–6 p.m. Tuesday is by appointment. Wednesday and Thursday have appointments in the morning and drop-in hours in the afternoon.","By phone: Rental Rights Hotline (608) 257-0006. Or fill in the contact form on the website; it asks whether you are a tenant or landlord, your lease type and your lease start and end dates.","Have your lease and its dates ready before you call or drop in."],"zh":["校内办公室：Student Activity Center，333 E Campus Mall 3158 室。周二、周四 10:00–18:00 随到随办，也可以打 (608) 292-5608。","总部 2510 Winnebago St：周一只接待随到的人，9:00–18:00。周二需预约。周三、周四上午预约，下午随到。","电话：租客权益热线 (608) 257-0006。也可以填官网的联系表，会问你是租客还是房东、合同类型、合同起止日期。","打电话或上门前，把租约和日期准备好。"]},"cost":{"en":["Housing counseling is free and confidential for Dane County residents.","Mediation is free."],"zh":["Dane County 居民的住房咨询免费且保密。","调解免费。"]},"tips":{"en":["Ask before you sign. TRC covers earnest money, application fees and credit checks, not only problems after move-in.","For deposits, counselors cover how to get as much of the deposit back as possible and what to do if a landlord withholds part of it.","TRC gives information, not legal advice. It keeps an attorney referral list for legal help.","Behind on rent? Use the online eviction prevention screening. It is not an application for money and funding is not guaranteed.","The campus office is open only on Tuesdays and Thursdays. On other days go to the main office or call the hotline.","Discrimination against students as tenants is illegal in Madison."],"zh":["签约前先问。TRC 管的不只是入住后的纠纷，还包括定金、申请费和信用查询。","押金方面，顾问会讲怎样尽量全额拿回押金，以及房东扣押金怎么办。","TRC 提供信息，不提供法律意见。需要法律帮助可以看它的律师转介名单。","欠租了？先做官网的驱逐预防筛查。这不是申请补助，也不保证有资金。","校内办公室只有周二、周四开。其他日子去总部或打热线。","在麦迪逊，因为是学生而歧视租客是违法的。"]},"intl":{"en":["TRC lists Spanish and Hmong counseling. A Chinese-language service is not listed, so bring a friend if you need help with English."],"zh":["TRC 列出的咨询语言是西班牙语和苗语，没有列中文服务。英语吃力的话，带个朋友一起去。"]}},"src":[["Tenant Resource Center - home, hours and locations","https://www.tenantresourcecenter.org/"],["Tenant Resource Center - Services for UW Students","https://www.tenantresourcecenter.org/uw_madison_office"],["Tenant Resource Center - Housing Counseling","https://www.tenantresourcecenter.org/counseling"],["Tenant Resource Center - Mediation","https://www.tenantresourcecenter.org/mediation"],["Tenant Resource Center - Contact a Housing Counselor","https://www.tenantresourcecenter.org/contact_a_housing_counselor"]],"unv":[],"chk":"2026-10-08","lat":43.072488,"lng":-89.398932,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"the-open-seat","cat":"help","n":{"en":"The Open Seat Food Pantry","zh":"The Open Seat 学生食品银行"},"kind":{"en":"Student food pantry","zh":"学生食品银行"},"addr":"333 E Campus Mall, Madison, WI 53715","phone":"","web":"https://basicneeds.students.wisc.edu/the-open-seat/","h":{"Mo":[[840,1080]],"Tu":[[600,780]],"We":[],"Th":[[840,1200]],"Fr":[[840,1080]],"Sa":[],"Su":[]},"ht":{"en":"East Campus Mall pantry, fall hours as listed in October 2026: Mon 2–6 p.m., Tue 10 a.m.–1 p.m., Thu 2–8 p.m., Fri 2–6 p.m. Closed Wed; no weekend hours listed. Appointment required. Eagle Heights pick-up: Wednesdays 5–6:30 p.m.","zh":"East Campus Mall 食品库，秋季开放时间（2026 年 10 月官网）：周一 14:00–18:00，周二 10:00–13:00，周四 14:00–20:00，周五 14:00–18:00；周三不开，没列周末时间。需要预约。Eagle Heights 取货：周三 17:00–18:30。"},"sum":{"en":"Free groceries and hygiene items for any UW–Madison student. Book a 15-minute shopping slot online before you go.","zh":"UW 学生免费领食品和日用品。先在网上约 15 分钟的购物时段。"},"kw":["food pantry","食品银行","free food","免费食物","groceries","Open Seat","ASM","food insecurity","hygiene","日用品","Eagle Heights","基本需求"],"sec":{"about":{"en":["The Open Seat is UW–Madison's first student-run, student-serving food pantry. Undergraduates started it with the Associated Students of Madison (ASM), and it has been in the Student Activity Center, 333 E Campus Mall, 3rd floor, Room 3136, since it opened in 2016.","A second site, a weekly pick-up of pre-ordered food at the Eagle Heights Community Center, 611 Eagle Heights Dr, started in 2021."],"zh":["The Open Seat 是 UW–Madison 第一个由学生运营、为学生服务的食品库。由本科生和学生会 (ASM) 一起创办，开办以来一直在 Student Activity Center（333 E Campus Mall，3 楼 3136 室）。","第二个点是 Eagle Heights Community Center（611 Eagle Heights Dr）的每周取货，2021 年开始，需要提前订。"]},"offers":{"en":["Fresh produce, eggs, milk, meats, soup, pasta, rice, canned vegetables, snacks and other shelf-stable foods.","Hygiene products: menstrual products, soap, deodorant, toothpaste, toothbrushes and more.","Eagle Heights pick-up: order online, then collect it in a shopping time slot on Wednesday evening.","Information on other basic-needs resources on campus and in Madison."],"zh":["新鲜蔬果、鸡蛋、牛奶、肉、汤、意面、大米、蔬菜罐头、零食和其他耐储存食品。","日用品：卫生用品、肥皂、止汗露、牙膏、牙刷等。","Eagle Heights 取货：网上下单，周三晚上在分配的购物时段来取。","可以了解校内和麦迪逊其他基本生活需求的资源。"]},"howto":{"en":["Book a 15-minute shopping appointment through the link on the Open Seat page, up to a week ahead. You need one to shop.","Go to Room 3136 in the Student Activity Center, 333 E Campus Mall, 3rd floor. Show the front-desk staff your confirmation email on your phone.","Bring your own bags or a tote if you can. Bags and boxes are sometimes provided.","Eagle Heights: submit the order form the week before, check your emailed shopping time, then go to the Eagle Heights Community Center. The page gives two deadlines (Monday 11:59 p.m. and Friday noon), so check the form.","Questions: email openseat@asm.wisc.edu."],"zh":["通过 Open Seat 页面的链接预约 15 分钟的购物时段，最多提前一周。没有预约不能购物。","去 Student Activity Center（333 E Campus Mall）3 楼 3136 室，给前台工作人员看手机里的确认邮件。","尽量自带购物袋。有时会提供袋子和纸箱。","Eagle Heights：前一周提交订单，看邮件里分配的取货时间，再去 Eagle Heights Community Center。页面写了两个截止时间（周一 23:59 和周五中午），以订单表为准。","有问题发邮件：openseat@asm.wisc.edu。"]},"cost":{"en":["Free for UW–Madison students, according to UW Basic Needs.","Please limit visits to once per week per household. A few items have limits."],"zh":["对 UW–Madison 学生免费（UW Basic Needs 的说法）。","请每个家庭每周最多来一次。少数商品有数量限制。"]},"tips":{"en":["The East Campus Mall pantry is closed on Wednesdays, which is the Eagle Heights day. Thursday is the longest day, until 8 p.m.","Some items are past their best-by dates. The Open Seat follows USDA guidance that these are not expiration dates. Skip anything that smells, looks or feels off.","The short form you fill in lets the pantry report how many people it serves to its food source, Second Harvest Foodbank of Southern Wisconsin.","Stock comes from Second Harvest at a discount and from donors such as Target on State Street.","Hours are the fall hours on the UW Basic Needs page in October 2026. Check the page before you go, because the schedule is set per term."],"zh":["East Campus Mall 食品库周三不开，周三是 Eagle Heights 取货日。周四最晚，开到 20:00。","有些食品过了 best-by 日期。Open Seat 按美国农业部 (USDA) 的说法，这些日期不是保质期。闻起来、看起来、摸起来不对的就别要。","要填的简短表格是为了向食物来源 Second Harvest Foodbank of Southern Wisconsin 报告服务了多少人。","货源来自打折购买的 Second Harvest 食品，还有 State Street 上的 Target 等捐赠方。","时间是 UW Basic Needs 页面上 2026 年 10 月的秋季时间。每学期的安排不同，去之前再看一眼页面。"]},"intl":{"en":["Eligibility is being a UW–Madison undergraduate, graduate or professional degree student. The page lists no citizenship or visa condition.","The Open Seat says your name, email and pantry-use history are not shared with UW offices, law enforcement or ICE without your permission, unless the law requires it."],"zh":["资格是 UW–Madison 的本科、研究生或专业学位学生。页面没有写国籍或签证方面的条件。","Open Seat 表示，你的姓名、邮箱和使用记录，未经你同意不会提供给 UW 各部门、执法部门或 ICE，法律要求时除外。"]}},"src":[["UW Basic Needs - The Open Seat","https://basicneeds.students.wisc.edu/the-open-seat"],["UW Basic Needs - Food Resources","https://basicneeds.students.wisc.edu/food-resources/"]],"unv":["phone"],"chk":"2026-10-08","lat":43.072488,"lng":-89.398932,"stops":[["East Campus",63,"A B F"],["W Johnson at East Campus",95,"C D R 28 38 65"],["N Lake at W Johnson",112,"81"]]},{"id":"uw-madison-police-department","cat":"help","n":{"en":"UW–Madison Police Department (UWPD)","zh":"威斯康星大学麦迪逊分校警察局 (UWPD)"},"kind":{"en":"Campus police","zh":"校园警察局"},"addr":"1429 Monroe St, Madison, WI 53711","phone":"(608) 264-2677","web":"https://uwpd.wisc.edu/","h":{"Mo":[[0,1440]],"Tu":[[0,1440]],"We":[[0,1440]],"Th":[[0,1440]],"Fr":[[0,1440]],"Sa":[[0,1440]],"Su":[[0,1440]]},"ht":{"en":"The department is open 24/7, 365 days a year; call dispatch any time. The lobby is staffed Mon–Fri 8 a.m.–5 p.m. Property release is by appointment, usually Mon–Fri 8 a.m.–4 p.m. (fall 2026).","zh":"警察局全天 24 小时、全年无休，随时可打调度电话。大厅工作日 8:00–17:00 有人值守。领失物要预约，一般周一到周五 8:00–16:00（2026 秋季）。"},"sum":{"en":"Campus police headquarters near Camp Randall: reports, lost property and safety help. Call 911 in an emergency, (608) 264-2677 otherwise.","zh":"校园警察总部，在 Camp Randall 球场对面：报案、失物、求助。紧急打 911。"},"kw":["UWPD","police","警察","campus police","校园警察","non-emergency","非紧急电话","lost and found","失物招领","police report","报案","911","BadgerSAFE","Camp Randall","Monroe St"],"sec":{"about":{"en":["UWPD is the campus police department. It is open 24 hours a day, 365 days a year, and its headquarters is at 1429 Monroe St, across from Camp Randall Stadium. Its officers are deputized, so they have jurisdiction in all of Dane County, and they also enforce UW administrative codes and Wisconsin state law.","In an emergency, call 911. For anything else, such as filing a report or asking to speak with an officer, call the dispatch center at (608) 264-2677."],"zh":["UWPD 是校园警察局，全天 24 小时、全年无休，总部在 1429 Monroe St，Camp Randall 球场对面。警察是被授权的 (deputized)，在整个 Dane County 都有执法权，同时执行 UW 校规和威州法律。","紧急情况打 911。其他事情，比如报案、想跟警察谈，打调度中心 (608) 264-2677。"]},"offers":{"en":["Police reports taken by phone through dispatch; UWPD cannot take reports online or by email.","Lost and found for items of significant value, such as phones, laptops and cash. Keys go to the UW Lock Shop.","Release of recovered property by appointment: call (608) 512-9532 to set a time with the property team.","Copies of police reports from the Records Unit, $0.10 per page.","A MedDrop box in the lobby for leftover or expired medicine, open 24/7. Illegal drugs are not accepted.","Court Services Office for tickets and court dates: (608) 262-4522, Mon–Fri 8 a.m.–4 p.m.","Friend Walk in the BadgerSAFE app: share your location with a contact who can virtually walk with you."],"zh":["报案通过调度中心电话办理，UWPD 不接受网上或邮件报案。","失物招领只收贵重物品，如手机、笔记本电脑、现金。钥匙送 UW Lock Shop。","找回的物品要预约领取：打 (608) 512-9532 跟失物组约时间。","警方报告副本找记录处 (Records Unit) 申请，每页 $0.10。","大厅有药品回收箱 (MedDrop)，24 小时可用，收剩余或过期药品，违禁药品不收。","罚单和出庭日期找法院服务办公室 (Court Services)：(608) 262-4522，周一到周五 8:00–16:00。","BadgerSAFE 手机 App 里的 Friend Walk：把位置分享给联系人，对方可以远程陪你走。"]},"howto":{"en":["Emergency: dial 911. Campus emergency phones, including the blue-light phones, dial 911 at the push of a button and connect to the UWPD dispatcher.","To report a crime or speak with an officer, call (608) 264-2677. UWPD asks you to call, not email.","To get property back, call (608) 512-9532 first to make an appointment. Do not just show up.","Lost something inside a building? Ask that building's manager first. For keys, contact the UW Lock Shop; after hours, found keys can go in the key box in the UWPD lobby.","Public parking at headquarters is at metered spots."],"zh":["紧急情况打 911。校园里的紧急电话（包括蓝灯电话）一按键就拨 911，直接接到 UWPD 调度员。","报案或想跟警察谈，打 (608) 264-2677。UWPD 要求打电话，别发邮件。","要取回物品，先打 (608) 512-9532 预约，别直接去。","东西丢在某栋楼里，先问那栋楼的管理员。钥匙找 UW Lock Shop；下班后捡到的钥匙可以投进 UWPD 大厅的钥匙箱。","总部的公共停车位是计时收费车位。"]},"cost":{"en":["Police report copies cost $0.10 per page, including electronic delivery. Charges of $5.00 or less are waived (UWPD fee schedule effective April 1, 2023)."],"zh":["警方报告副本每页 $0.10，电子版也一样。总额 $5.00 及以下不收费（UWPD 收费表，2023 年 4 月 1 日起生效）。"]},"tips":{"en":["Save 911 for danger. Use the non-emergency number for everything else.","A parking ticket on campus comes from UW Transportation Services, not UWPD. Tickets from the City of Madison come from Madison Police.","If you got a citation, the police report is available only after your first court appearance.","For incidents elsewhere in the City of Madison, the Madison Police Department is the city police. Its non-emergency number is (608) 255-2345.","For a walking escort at night, UWPD points students to SAFEwalk, which UW Transportation Services runs."],"zh":["911 留给有危险的情况，其他事用非紧急电话。","校内停车罚单来自 UW Transportation Services，不是 UWPD。City of Madison 的罚单来自麦迪逊市警察。","如果收到了传票 (citation)，要等第一次出庭之后才能拿到警方报告。","麦迪逊市内、校外的事，归麦迪逊市警察局 (MPD) 管。它的非紧急电话是 (608) 255-2345。","晚上想有人陪着走，UWPD 建议用 UW Transportation Services 运营的 SAFEwalk。"]},"intl":{"en":["UWPD says your immigration status does not affect your ability to file a police report, and it does not take part in ICE immigration enforcement.","UWPD officers should not routinely ask about immigration status, and UW–Madison will not disclose students' immigration status unless required by law."],"zh":["UWPD 说明：移民身份不影响你报案，UWPD 也不参与 ICE 的移民执法。","UWPD 警察不应例行询问移民身份，UW–Madison 除非法律要求，也不会披露学生的移民身份。"]}},"src":[["UW–Madison Police Department - home","https://uwpd.wisc.edu/"],["UWPD - Contact Us","https://uwpd.wisc.edu/about-us/contact-us/"],["UWPD - Frequently Asked Questions","https://uwpd.wisc.edu/about-us/faqs/"],["UWPD - Records Requests and fees","https://uwpd.wisc.edu/data-policies-resources/records-request/"],["UWPD - MedDrop Prescription Drug Disposal","https://uwpd.wisc.edu/services/meddrop/"],["UWPD - Walk Smart","https://uwpd.wisc.edu/walk-smart/"],["UWPD - Immigration Enforcement Practices","https://uwpd.wisc.edu/data-policies-resources/uwpd-immigration-practices/"],["City of Madison Police - Police Directory","https://www.cityofmadison.com/police/contact/directory"]],"unv":[],"chk":"2026-10-08","lat":43.069142,"lng":-89.409963,"stops":[["N Randall at Monroe",106,"O"],["Monroe at N Randall",113,"D"],["Regent at N Randall",149,"E 64"]]},{"id":"allen-centennial-garden","cat":"fun","n":{"en":"Allen Centennial Garden","zh":"Allen Centennial 花园"},"kind":{"en":"Campus garden","zh":"校园花园"},"addr":"620 Babcock Dr, Madison, WI 53706","phone":"(608) 576-2501","web":"https://allencentennialgarden.wisc.edu/plan-your-visit/","h":null,"ht":{"en":"Open every day from dawn to dusk. Free, no sign-up.","zh":"每天从天亮到天黑开放，免费，不用报名。"},"sum":{"en":"Free 2.5-acre garden with 27 garden styles, right on the west side of campus. Dawn-to-dusk benches, dogs on leash welcome.","zh":"校园西侧免费小花园，2.5 英亩里有 27 种造园风格。天亮到天黑开放，可以带狗（牵绳）。"},"kw":["Allen Centennial Garden","garden","ACG","flowers","campus garden","free","dog friendly","花园","花","校园","免费","拍照","photo"],"sec":{"about":{"en":["Allen Centennial Garden is a UW–Madison garden at 620 Babcock Drive, on the west side of campus. On just 2.5 acres it has 27 different styles of gardening, most of them perennials.","Its stated mission is to create garden experiences that deepen relationships among people and plants. It runs workshops, tours and a few public events a year."],"zh":["Allen Centennial Garden 是 UW–Madison 的花园，地址 620 Babcock Drive，在校园西侧。只有 2.5 英亩，却有 27 种不同的造园风格，大部分种的是多年生植物。","官网写的使命是让人和植物建立更深的联系。每年有工作坊、导览和几场公开活动。"]},"offers":{"en":["Walking paths through themed gardens, with benches placed around the grounds","A kitchen garden and a dye garden, both mentioned on the garden's news page","Seasonal events: summer concerts, a Harvest Folk Festival in early October (the 2025 one was on Oct 4), and a yearly wreath-making workshop","Plant Finder on the website to look up what is growing there","Photography is welcome","Volunteer, internship and student-involvement programs"],"zh":["主题花园之间有步道，园里到处摆着长椅","官网动态里提到有菜园 (Kitchen Garden) 和染料植物园 (Dye Garden)","季节活动：夏季音乐会、10 月初的 Harvest Folk Festival（2025 年是 10/4）、每年一次的花环工作坊","官网有 Plant Finder，可以查园里种了什么","欢迎拍照","有志愿者、实习和学生参与项目"]},"howto":{"en":["Walk in any time between dawn and dusk. No ticket, no registration.","Parking: two-hour timed stalls on Babcock Drive (mobile-pay meters that do not take coins) or the Lot 36 ramp on Observatory Drive.","No public restroom in the garden. Neighboring campus buildings are open to the public; a portable restroom is in the northwest corner from mid-April to early October.","Dogs are welcome on a leash and on the path at all times.","Posed, professional or commercial photo shoots, including homecoming and prom photos, need a free permit form; one permit covers your whole group. Casual photos need nothing."],"zh":["天亮到天黑之间随时进，不用票也不用报名。","停车：Babcock Drive 上有 2 小时限时车位（手机付费，不收硬币），或者停 Observatory Drive 上的 Lot 36 停车楼。","园里没有公共洗手间，旁边的校园大楼对公众开放；4 月中旬到 10 月初西北角有一间移动厕所。","可以带狗，但必须牵绳、不离开小路。","摆拍、专业或商业拍摄（包括 homecoming、prom 照片）要填许可表，整个团体一张就行；随手拍不需要。"]},"cost":{"en":["Admission is free for everyone.","Parking is the only possible cost: the Babcock Drive stalls use mobile-pay meters. Ramp rates were not checked."],"zh":["门票免费，所有人都能进。","唯一可能的花费是停车：Babcock Drive 车位用手机付费的计时器。停车楼价格未核实。"]},"tips":{"en":["Walking from campus is easier than parking, since the stalls are limited to two hours.","Because there is no restroom inside, use a neighboring building first.","Sign up for the garden's monthly newsletter to see upcoming events.","The Harvest Folk Festival was held on October 4 in 2025. Check the events page for this year's date."],"zh":["从校园走过来比开车省事，路边车位只能停 2 小时。","园里没有洗手间，先用旁边大楼的。","订阅花园的月度邮件通讯，可以提前知道活动。","Harvest Folk Festival 2025 年办在 10/4。今年日期请去官网活动页确认。"]}},"src":[["Allen Centennial Garden - home","https://allencentennialgarden.wisc.edu/"],["Allen Centennial Garden - Plan Your Visit","https://allencentennialgarden.wisc.edu/plan-your-visit/"],["Allen Centennial Garden - Photo Permits","https://allencentennialgarden.wisc.edu/photo-permits/"]],"unv":[],"chk":"2026-10-08","lat":43.077048,"lng":-89.413148,"stops":[["Observatory at Babcock",58,"28 38 65 80 82"],["Babcock at Linden",197,"28 38 65 80"],["Linden at Babcock",205,"28 38 65 80 84"]]},{"id":"camp-randall-stadium","cat":"fun","n":{"en":"Camp Randall Stadium","zh":"Camp Randall 橄榄球场"},"kind":{"en":"Football stadium","zh":"橄榄球体育场"},"addr":"1440 Monroe St, Madison, WI 53711","phone":"(608) 262-1866","web":"https://uwbadgers.com/sports/2024/8/21/wisconsin-football-know-before-you-go","h":null,"ht":{"en":"Open for events only. Gates open 90 minutes before kickoff for both the public and students (Gate 5). Check the football schedule for dates and kickoff times.","zh":"只在比赛日开放。普通球迷和学生（5 号门）都是开球前 90 分钟开门。日期和开球时间看橄榄球赛程页。"},"sum":{"en":"Home of Badger football, west of central campus. Students buy a season ticket in July; this covers prices, entry and game-day rules.","zh":"Badger 橄榄球主场，在校园西侧。学生 7 月抢赛季票；这里讲价格、入场方式和比赛日规矩。"},"kw":["Camp Randall","football","Badgers","student tickets","season tickets","Jump Around","game day","橄榄球","学生票","赛季票","比赛日","Badger Bash","Gate 5"],"sec":{"about":{"en":["Camp Randall Stadium is the home of Wisconsin football, at the corner of Monroe and Regent Streets on the west side of the UW campus. Wisconsin has played football there since 1917.","Game days are a big campus tradition: pregame tailgates, the marching band, and the Jump Around song between the third and fourth quarters."],"zh":["Camp Randall 是威斯康星橄榄球队的主场，在校园西侧 Monroe 街和 Regent 街的路口，球队 1917 年起就在这里比赛。","比赛日是校园里的大传统：赛前 tailgate 聚会、校乐队，还有第三节和第四节之间放的 Jump Around。"]},"offers":{"en":["Badger home football games in the student section (north end zone)","Badger Bash: the free official pregame party at Union South, starting 2.5 hours before kickoff, with the UW Marching Band and Bucky Badger","Jump Around between the third and fourth quarters, and the Fifth Quarter band concert after the game","Bucky's Locker Room store just inside Gate 1 for official merchandise","First Game buttons at the entry gates for first-time visitors"],"zh":["在北端区的学生看台看 Badger 主场橄榄球赛","Badger Bash：Union South 的官方赛前派对，开球前 2.5 小时开始，免费，有校乐队和吉祥物 Bucky Badger","第三节和第四节之间放 Jump Around，赛后校乐队有 Fifth Quarter 演出","Gate 1 里面的 Bucky's Locker Room 卖官方周边","入口处给第一次来的人发 First Game 徽章"]},"howto":{"en":["Student tickets are sold online as a season package through your student athletic ticket account at go.wisc.edu/uwstudenttickets. Activate or verify the account before the sale (opens June 30 in 2026). Do not use Create Account.","The 2026 sale was by class standing: grad and professional students July 13, juniors and seniors July 14, freshmen and sophomores July 15, all at 7:30 a.m. CT. The 2026 sale is over; plan for the same pattern next summer.","Tickets are mobile only. Mobile vouchers (one per home game) arrive by email about two weeks before the season. Add them to Apple Wallet or Google Wallet before you leave; screenshots do not work.","Student tickets are valid only at the Gate 5 student entrance near Breese Terrace. The student gate opens 90 minutes before kickoff. Metal-detector screening at Gate 5 comes before ticket scanning.","Carry-in: only clear totes up to 12 x 6 x 12 inches, one-gallon clear plastic bags, small clutch bags up to 6.5 x 4.5 inches, and medical or diaper bags. There is no bag check, and no outside food or drinks.","No re-entry: once you leave during the game, you cannot come back in.","Ticket office: (608) 262-1440, tickets@uwbadgers.com, open Mon–Fri."],"zh":["学生票按赛季整套在网上卖，登录你的学生运动票务账号 (go.wisc.edu/uwstudenttickets) 购买。开售前要先激活或验证账号（2026 年是 6/30 开放），不要点 Create Account。","2026 年按年级分三天开售：研究生和专业学院 7/13，大三大四 7/14，大一大二 7/15，都是美中时间 7:30。2026 年的已经结束，明年大概同样安排。","只有手机票。每场一张电子票 (mobile voucher)，开赛季前约两周发到邮箱。出门前先加到 Apple Wallet 或 Google Wallet，截图无效。","学生票只能走 Breese Terrace 附近的 5 号门学生入口。学生门开球前 90 分钟开。5 号门是先过金属探测，再扫票。","随身物品：只能带不超过 12 x 6 x 12 英寸的透明手提袋、1 加仑透明密封袋、不超过 6.5 x 4.5 英寸的小手包，以及医疗或婴儿用品包。没有寄存处，也不能带外食和饮料。","不能中途出入：离场后不让再进。","票务办公室：(608) 262-1440，tickets@uwbadgers.com，周一到周五办公。"]},"cost":{"en":["2026 football student season ticket: $199 plus a $20 per ticket fee, for all six home games.","One season ticket per student, while supplies last. The athletic department expected demand to exceed supply.","Eligible: full-time degree-seeking undergraduates, and degree-seeking graduate and professional students.","Badger Bash and Jump Around cost nothing extra."],"zh":["2026 年橄榄球学生赛季票：199 美元，另加每张 20 美元手续费，含全部 6 场主场。","每个学生限买一张，卖完为止。体育部预计供不应求。","资格：全日制攻读学位的本科生，以及攻读学位的研究生和专业学院学生。","Badger Bash 和 Jump Around 都不另外收费。"]},"tips":{"en":["If you missed the July sale, call the ticket office at (608) 262-1440 to ask whether any student tickets remain. The athletics site also links to SeatGeek for buying or selling tickets.","Walk or bike in. Monroe St. and Breese Terrace close 6 hours before kickoff and campus lots fill early.","Come early. Wait times at the gates grow as kickoff approaches.","Away games and the Shamrock Series Notre Dame game at Lambeau Field had separate student ticket sales in July.","Remaining 2026 home games: Oct 24 vs USC, Nov 7 vs Rutgers, Nov 27 vs Minnesota."],"zh":["错过 7 月开售的话，打票务办公室 (608) 262-1440 问还有没有学生票。体育部官网也链接了 SeatGeek 来买卖票。","步行或骑车去。开球前 6 小时 Monroe 街和 Breese Terrace 就封路，校内停车场也很早就满。","早点到。越接近开球，入口排队越长。","客场比赛和 Lambeau Field 的 Shamrock Series 对 Notre Dame 比赛，学生票 7 月单独开售。","2026 剩余主场：10/24 对 USC、11/7 对 Rutgers、11/27 对 Minnesota。"],"exp":[null,null,null,null,"2026-11-27"]},"intl":{"en":["You need a smartphone with Apple Wallet or Google Wallet to enter, and a charged battery. Printed or screenshot tickets are not accepted."],"zh":["进场要用装了 Apple Wallet 或 Google Wallet 的手机，而且电量要够。打印和截图的票都不行。"]}},"src":[["Wisconsin Football Student Ticket Information","https://uwbadgers.com/sports/2015/8/21/GEN_20140101504"],["Wisconsin Football: Know Before You Go","https://uwbadgers.com/sports/2024/8/21/wisconsin-football-know-before-you-go"],["Wisconsin Football Gameday (2025 page)","https://uwbadgers.com/sports/2025/8/26/wisconsin-football-gameday-25"],["Wisconsin Football Schedule","https://uwbadgers.com/sports/football/schedule"],["Travel Center - Facilities Addresses","https://uwbadgers.com/sports/2015/8/21/GEN_20140101149"],["Fan Policies","https://uwbadgers.com/fanPolicies"]],"unv":[],"chk":"2026-10-08","lat":43.070053,"lng":-89.41265,"stops":[["N Breese at Hoyt",122,"82"],["Regent at S Breese",267,"E 64 82"],["Monroe at N Randall",268,"D"]]},{"id":"chazen-museum-of-art","cat":"fun","n":{"en":"Chazen Museum of Art","zh":"Chazen 艺术博物馆"},"kind":{"en":"Art museum","zh":"艺术博物馆"},"addr":"750 University Ave, Madison, WI 53706","phone":"(608) 263-2246","web":"https://chazen.wisc.edu/visit/","h":{"Mo":[[600,1140]],"Tu":[[600,1140]],"We":[[600,1140]],"Th":[[600,1140]],"Fr":[[600,1140]],"Sa":[[660,1020]],"Su":[[660,1020]]},"ht":{"en":"Galleries: Mon–Fri 10 a.m.–7 p.m., Sat–Sun 11 a.m.–5 p.m. The building itself opens at 8 a.m. on weekdays. Closed on campus holidays. Café: Mon–Wed 8:30 a.m.–5:30 p.m., Thu–Fri 8:30 a.m.–7 p.m., Sat–Sun 11 a.m.–4:30 p.m.","zh":"展厅：周一到周五 10:00–19:00，周末 11:00–17:00。楼本身工作日 8:00 开门。学校放假日闭馆。咖啡厅：周一到周三 8:30–17:30，周四、周五 8:30–19:00，周末 11:00–16:30。"},"sum":{"en":"UW–Madison's free art museum on University Ave: about 25,000 works, rotating exhibitions, a café, and no ticket needed.","zh":"校园里的免费艺术博物馆，藏品约 2.5 万件，不用买票，随时进。"},"kw":["Chazen","art museum","museum","art","gallery","free museum","Elvehjem","exhibition","艺术博物馆","博物馆","美术馆","展览","免费"],"sec":{"about":{"en":["The Chazen is the art museum of UW–Madison, on University Avenue near the Memorial Library end of campus. It holds about 25,000 works, from ancient Greece and Western Europe to Mughal India, 18th-century Japan and modern Africa, in 176,000 square feet of museum space.","It is open to everyone and never charges admission. Many UW art, history and language classes send students here for assignments."],"zh":["Chazen 是 UW–Madison 的艺术博物馆，在 University Avenue 上。馆藏约 2.5 万件，从古希腊、西欧到莫卧儿印度、18 世纪日本和现代非洲都有，展示空间 17.6 万平方英尺。","对所有人开放，从不收门票。UW 不少艺术、历史、语言课会布置来这里看展的作业。"]},"offers":{"en":["Two exhibitions on view in fall 2026: \"Recollection: Exhibiting the Collection\" and \"Pressing Issues: Printmaking as Social Justice in 1930s US\"","Chazen Café just inside the entrance, run by the Wisconsin Union: hot and cold drinks, snacks and lunch items","Museum shop with gifts based on the collection; proceeds support the museum","Free drop-in guided tours on some Sundays, plus curator talks and student events","Student Ambassadors run Late Night at the Museum, Swing Dance Night, trivia and flashlight tours"],"zh":["2026 秋季在展：「Recollection: Exhibiting the Collection」和「Pressing Issues: Printmaking as Social Justice in 1930s US」（1930 年代美国社会正义版画）","入口里面就是 Chazen Café，由 Wisconsin Union 经营，有热饮冷饮、小吃和午餐","馆内商店卖和藏品相关的礼品，收入用来支持博物馆","部分周日有免费的随到随加入导览，还有策展人讲座和学生活动","学生大使 (Student Ambassadors) 会办 Late Night at the Museum、摇摆舞之夜、问答之夜、手电筒导览"]},"howto":{"en":["Walk in. No ticket and no reservation for individuals. You can stay as long as the museum is open.","Put backpacks and large bags in the lockers and hang your coat in the coatroom.","Photos and video for personal use are fine in the permanent collection with a hand-held camera and no flash. Loaned works and temporary exhibitions need permission.","You may sketch with graphite pencils and pads no larger than 36 × 36 inches.","To join the Student Ambassadors, request membership on the Wisconsin Involvement Network."],"zh":["直接进，个人参观不用票也不用预约，开门期间想待多久都行。","背包和大包放进储物柜，外套可以挂在衣帽间。","常设展可以用手持相机拍照录像，仅限个人用途，不能开闪光灯；外借作品和临时展要先得到许可。","可以用石墨铅笔速写，画板不能超过 36 × 36 英寸。","想加入学生大使，在 Wisconsin Involvement Network 上申请。"]},"cost":{"en":["Admission is free for everyone, every day. Donations are optional.","Drop-in guided tours listed on the events page are free."],"zh":["所有人每天免费入场，捐款自愿。","活动页上列出的随到随加入导览免费。"]},"tips":{"en":["Third-floor galleries in both the Chazen and Elvehjem buildings are closed while the permanent collection is re-installed, and the museum says they reopen through the fall. Check the website before a class visit.","Early closure on Friday, Oct. 9, 2026: the museum closes at 4 p.m. for a private event.","Weekday evenings until 7 p.m. are quiet, and the café is open to 7 p.m. on Thursday and Friday.","The closest public parking is the State Street Campus Garage. The Chazen is also on several Madison Metro routes, and there are BCycle stations nearby.","There are no audio tours. Labels in the galleries give artist, date, materials and how the museum got the piece."],"zh":["Chazen 和 Elvehjem 两栋楼的三楼展厅正在重新布展，暂时关闭，馆方说秋季陆续重开。为课程去看之前先查官网。","2026 年 10 月 9 日（周五）因私人活动 16:00 提前闭馆。","工作日傍晚到 19:00 人少；咖啡厅周四、周五也开到 19:00。","最近的公共停车场是 State Street Campus Garage；公交和 BCycle 站点也都在附近。","没有语音导览。展厅里每件作品的标签写着作者、年代、材质和来源。"],"exp":["2026-12-21","2026-10-09",null,null,null]}},"src":[["Chazen Museum of Art - Visit","https://chazen.wisc.edu/visit/"],["Chazen - Hours, Location, Parking","https://chazen.wisc.edu/visit/hours-location-parking/"],["Chazen - Visitor Guide","https://chazen.wisc.edu/visit/visitor-guide/"],["Chazen - Frequently Asked Questions","https://chazen.wisc.edu/visit/visitor-guide/faqs/"],["About the Chazen","https://chazen.wisc.edu/about/"],["Chazen - Exhibitions and Events","https://chazen.wisc.edu/exhibitions-and-events/"],["Chazen - Drop-In Tour: Pressing Issues","https://chazen.wisc.edu/events/drop-in-tour-pressing-issues"]],"unv":[],"chk":"2026-10-08","lat":43.073856,"lng":-89.398655,"stops":[["East Campus",58,"B"],["University at East Campus",125,"C D R 28 38 65 81"],["N Lake at University",141,"80 82"]]},{"id":"henry-vilas-zoo","cat":"fun","n":{"en":"Henry Vilas Zoo","zh":"Henry Vilas 动物园"},"kind":{"en":"Free zoo","zh":"免费动物园"},"addr":"702 S Randall Ave, Madison, WI 53715","phone":"(608) 266-4732","web":"https://www.henryvilaszoo.gov/","h":{"Mo":[[570,1020]],"Tu":[[570,1020]],"We":[[570,1020]],"Th":[[570,1020]],"Fr":[[570,1020]],"Sa":[[570,1020]],"Su":[[570,1020]]},"ht":{"en":"Open every day of the year, 9:30 a.m.–5 p.m. Indoor exhibits (Herpetarium, Aviary, Discovery Center, Primate Building) and the Children's Zoo: 10 a.m.–4 p.m. Closes at noon on Thanksgiving, Dec 24–25 and Dec 31–Jan 1.","zh":"全年每天开放，9:30–17:00。室内馆（爬行馆、鸟舍、Discovery Center、灵长馆）和儿童动物园 10:00–16:00。感恩节、12/24–25、12/31–1/1 中午 12:00 关门。"},"sum":{"en":"Free, city-run zoo next to Vilas Park and Lake Wingra, open 365 days a year. Polar bears, giraffes and a good cheap outing between classes.","zh":"挨着 Vilas Park 和 Wingra 湖的免费动物园，全年天天开，没课时去逛一圈不花钱。"},"kw":["zoo","Henry Vilas Zoo","animals","free","polar bear","giraffe","动物园","免费","北极熊","长颈鹿","Vilas Park","date","约会"],"sec":{"about":{"en":["Henry Vilas Zoo is a city-run, accredited zoo in Vilas Park, south of the UW campus near Camp Randall Stadium. It is one of only a handful of admission-free, community-supported zoos in the country.","The zoo is surrounded by Vilas Park, Lake Wingra and the UW–Madison Arboretum, so a visit combines easily with a walk or a picnic."],"zh":["Henry Vilas 动物园是市政府运营的认证动物园，在校园南边的 Vilas Park 里，离 Camp Randall 球场不远。全美只有少数几家这样不收门票、靠社区捐款维持的动物园。","动物园周围是 Vilas Park、Wingra 湖和 UW–Madison Arboretum，可以顺便散步、野餐。"]},"offers":{"en":["Animal exhibits, including the Arctic Passage polar bears and a reticulated giraffe herd","Indoor buildings: Herpetarium (reptiles), Aviary, Discovery Center, Primate Building","Glacier Grille, a restaurant that looks out on the polar bear exhibit, and the Cup and Cone kiosk for coffee or a cold snack","Conservation Carousel and Zoo Train, $3 a ride","Giraffe Feeding, an up-close feeding encounter listed on the Visit page","Picnic areas inside the zoo; the park outside has a beach, playgrounds, a ball diamond and a lagoon kept for ice skating in winter"],"zh":["动物展区，有 Arctic Passage 北极熊馆和网纹长颈鹿群","室内馆：Herpetarium（爬行动物）、Aviary（鸟舍）、Discovery Center、灵长类馆","Glacier Grille 餐厅，窗外就是北极熊；园中间的 Cup and Cone 小亭卖咖啡和冷饮","Conservation Carousel（旋转木马）和 Zoo Train（小火车），每次 3 美元","官网 Visit 页列了 Giraffe Feeding：近距离喂长颈鹿","园内有野餐区；园外的公园有沙滩、儿童游乐场、棒球场，冬天有结冰的泻湖可以滑冰"]},"howto":{"en":["Just walk in. There is no ticket and no registration.","Two entrances: the main entrance on the north side at Drake St. and Randall Ave., and a \"bridge entrance\" on the southeast side on Vilas Park Dr., across from the beach.","Free parking in three lots with a 3-hour limit; the lots fill up on weekends. Street parking nearby is free for 2 hours.","Outside food is allowed in the zoo (coolers and picnic baskets are fine), but not inside the Glacier Grille.","Not allowed: balloons, balls, drink lids and straws, skates and skateboards, bikes and scooters (walk them), pets, smoking, carry-in alcohol. Certified service animals are fine.","Guest Services desk is near the main entrance, next to the gift shop."],"zh":["直接走进去，不用买票也不用预约。","有两个入口：北边 Drake St. 和 Randall Ave. 路口的正门，以及东南边 Vilas Park Dr. 上、海滩对面的「桥边入口」 (bridge entrance)。","三个免费停车场，限停 3 小时，周末容易满；附近街边也能免费停 2 小时。","园内可以带外食（冷藏箱、野餐篮都行），Glacier Grille 餐厅里面不行。","不能带：气球、球、饮料盖和吸管、轮滑和滑板、自行车和滑板车（可以推着走）、宠物，也不能吸烟、带酒入园。经认证的服务动物可以。","服务台 (Guest Services) 在正门附近，礼品店旁边。"]},"cost":{"en":["Admission and parking are free. The zoo asks for donations; there are donation tubes around the grounds.","Carousel and Zoo Train: $3 a ride, tokens or punch cards at the carousel building or the gift shop.","Stroller or wheelchair rental is $10, with a driver's license left as deposit (not in winter)."],"zh":["门票和停车都免费，园方希望大家捐款，园里到处有捐款筒。","旋转木马和小火车每次 3 美元，在木马楼或礼品店买代币或打孔卡。","婴儿车、轮椅租金 10 美元，要押一张驾照（冬季不租）。"]},"tips":{"en":["The zoo is open all year, including winter, unless the weather forces a closure. Closures are announced on its website and social media.","The carousel runs April 1–Oct 31 only, so it stops for the winter after the end of October.","Indoor buildings close at 4 p.m., an hour before the grounds. Go before 4 if you want to see the reptiles and primates.","Weekends and busy summer days are crowded and the lots fill; on those days go in the morning.","Vilas Park is next door, so you can pair the zoo with the park's beach or a walk in the Arboretum."],"zh":["动物园全年开放，冬天也开，除非天气太差临时关门，会在官网和社交媒体通知。","旋转木马只在 4/1–10/31 运营，10 月底之后停到明年春天。","室内馆 16:00 就关，比园区早一小时；想看爬行动物和灵长类要在 4 点前到。","周末和夏天热门日子人多，停车场会满，建议上午去。","旁边就是 Vilas Park，可以和公园的沙滩或 Arboretum 的步道排在同一天。"],"exp":[null,"2026-10-31",null,null,null]},"intl":{"en":["No ID or Wiscard check at the gate. Entry is free for everyone."],"zh":["入口不查证件，不用出示学生证，所有人免费。"]}},"src":[["Henry Vilas Zoo - Plan Your Visit","https://www.henryvilaszoo.gov/visit/"],["Henry Vilas Zoo - Zoo FAQ","https://www.henryvilaszoo.gov/about-us/zoo-faq/"],["Henry Vilas Zoo - Contact Us","https://henryvilaszoo.gov/about-us/contact-us"]],"unv":[],"chk":"2026-10-08","lat":43.059821,"lng":-89.410476,"stops":[["S Randall at Drake",285,"O"],["Erin at S Mills",539,"O"],["Drake at S Mills",557,"O"]]},{"id":"james-madison-park","cat":"fun","n":{"en":"James Madison Park","zh":"James Madison 公园"},"kind":{"en":"Lakefront park and beach","zh":"湖滨公园和沙滩"},"addr":"614 E Gorham St, Madison, WI 53703","phone":"","web":"https://www.cityofmadison.com/parks/find-a-park/james-madison","h":{"Mo":[[240,1320]],"Tu":[[240,1320]],"We":[[240,1320]],"Th":[[240,1320]],"Fr":[[240,1320]],"Sa":[[240,1320]],"Su":[[240,1320]]},"ht":{"en":"Park hours 4 a.m.–10 p.m. daily, all year. No parking in park lots 10 p.m.–4 a.m. After hours, weekends and holidays, call the Park Rangers at (608) 235-0448.","zh":"公园每天 4:00–22:00，全年开放。22:00–4:00 不能停车。非办公时间、周末和假日找公园巡警：(608) 235-0448。"},"sum":{"en":"Free 12-acre city park on Lake Mendota in downtown Madison: beach, basketball, sand volleyball, kayak launch and open lawn.","zh":"Mendota 湖边市中心的免费公园，12 英亩：沙滩、篮球场、沙地排球、皮划艇下水点和大片草坪。"},"kw":["James Madison Park","park","beach","Lake Mendota","volleyball","basketball","kayak","swimming","公园","沙滩","湖边","游泳","排球","篮球","皮划艇","downtown"],"sec":{"about":{"en":["James Madison Park is a 12.63-acre City of Madison park on the shore of Lake Mendota in downtown Madison. The city's own page says the basketball courts, volleyball court and playground are popular with students and other residents, and that pick-up soccer and Frisbee games happen on the open lawn.","The historic Gates of Heaven building at 302 E. Gorham St is part of the park and is used for weddings and other gatherings."],"zh":["James Madison 公园是 Madison 市政府管理的公园，12.63 英亩，在市中心 Mendota 湖边。市政府的介绍说，篮球场、排球场和儿童游乐场深受学生和居民欢迎，开阔的草坪上常有人踢球、玩飞盘。","公园里还有历史建筑 Gates of Heaven（302 E. Gorham St），常用来办婚礼和聚会。"]},"offers":{"en":["Beach on Lake Mendota for sunbathing and swimming in summer","2 full basketball courts and 1 sand volleyball court by the beach, first come, first served","Open grass for soccer, Frisbee and picnics","Canoe and kayak launch to Lake Mendota, and outdoor racks to store a canoe, kayak or paddleboard (reserve online)","Fishing from the shore (16 and older need a Wisconsin DNR license)","Two playgrounds and a shelter"],"zh":["Mendota 湖边的沙滩，夏天晒太阳、游泳","2 个标准篮球场和海滩边 1 个沙地排球场，先到先用","开阔草坪，可以踢球、玩飞盘、野餐","独木舟和皮划艇下水点，还有露天架子可以存放独木舟、皮划艇或桨板（网上预约）","可在岸边钓鱼（16 岁及以上需要 Wisconsin DNR 钓鱼执照）","两个儿童游乐场和一个野餐棚 (shelter)"]},"howto":{"en":["Just walk in; no ticket. Courts and fields are first come, first served. Online reservations are only for leagues, lessons and tournaments.","Swimming season is typically Memorial Day weekend through Labor Day weekend. Public Health Madison & Dane County monitors the water quality only in those months. Check the beach water-quality page before you swim.","There are no lifeguards and no swim ropes at this beach. Children under 10 need an adult caregiver (16 or older) watching at all times.","Rules for all city beaches: no dogs on the sand or in the swim area; only US Coast Guard-approved lifejackets; no boats or fishing in the swim area.","Alcohol is prohibited in this park. Glass, including glass bottles, is not allowed in any Madison park.","Personal grills are allowed in most Madison parks, but never unattended or overnight."],"zh":["直接走进去，不用票。球场和球类场地先到先用，在线预约只给联赛、课程和比赛用。","游泳季通常是阵亡将士纪念日 (Memorial Day) 那个周末到劳动节 (Labor Day) 那个周末。只有这几个月 Public Health Madison & Dane County 才会监测水质，下水前先查海滩水质页面。","这个海滩没有救生员，也没有泳道绳。10 岁以下儿童必须有 16 岁以上的成人全程看着。","所有市属海滩通用规则：沙滩和游泳区不能带狗；只能用美国海岸警卫队认证的救生衣；游泳区内禁止划船和钓鱼。","本公园禁止饮酒。玻璃（包括玻璃瓶）在 Madison 所有公园都不许带。","大部分 Madison 公园允许自带烧烤炉，但不能无人看管，也不能过夜。"]},"cost":{"en":["Free to enter and use the beach, courts and grass.","Storing a canoe, kayak or paddleboard on the racks is a reserved service; the fee was not checked.","Gates of Heaven and the shelter can be reserved for events; rates not checked."],"zh":["进园、用沙滩、球场和草坪都免费。","把独木舟、皮划艇或桨板放在架子上要预约，费用未核实。","Gates of Heaven 和野餐棚可以预约办活动，价格未核实。"]},"tips":{"en":["The 2026 swim season is over. The beach restrooms are seasonal, about 11 a.m.–7 p.m. daily Memorial Day to Labor Day.","Because there are no lifeguards, swim with a friend and stay near the shore.","The Park Rangers number, (608) 235-0448, is the one to call after hours, on weekends and on holidays.","Do not park in the park lots between 10 p.m. and 4 a.m."],"zh":["2026 年游泳季已经结束。海滩的洗手间是季节性的，阵亡将士纪念日到劳动节每天约 11:00–19:00 开放。","没有救生员，游泳要结伴，别游太远。","非办公时间、周末和假日找公园巡警：(608) 235-0448。","22:00 到 4:00 公园停车场不能停车。"]},"intl":{"en":["Wisconsin fishing license rules apply from age 16, even for international students."],"zh":["16 岁以上钓鱼需要 Wisconsin 钓鱼执照，国际学生也一样。"]}},"src":[["City of Madison Parks - James Madison Park","https://www.cityofmadison.com/parks/find-a-park/james-madison"],["City of Madison Parks - Beaches","https://www.cityofmadison.com/parks/find-a-park/water/beaches"],["City of Madison Parks - Park Rules","https://www.cityofmadison.com/parks/about/park-rules"]],"unv":["phone"],"chk":"2026-10-08","lat":43.081634,"lng":-89.382131,"stops":[["E Gorham at N Blair",71,"D 28 81"],["N Blair at E Johnson",84,"81"],["E Johnson at N Blair",120,"D 28"]]},{"id":"kohl-center","cat":"fun","n":{"en":"Kohl Center","zh":"Kohl Center 体育馆"},"kind":{"en":"Basketball and hockey arena","zh":"篮球和冰球馆"},"addr":"601 W Dayton St, Madison, WI 53715","phone":"(608) 265-4704","web":"https://uwbadgers.com/sports/2015/8/21/GEN_20140101139","h":null,"ht":{"en":"Open for events only. Student gate opens 90 minutes before tip-off (basketball) or puck drop (hockey). See the Badgers schedule for dates and times.","zh":"只在比赛日开放。学生门在开球前 90 分钟开（篮球是 tip-off，冰球是 puck drop）。日期和时间看 Badgers 赛程页。"},"sum":{"en":"Home arena of Badger men's and women's basketball and men's hockey. Students get cheap tickets through their student ticket account.","zh":"Badger 男女篮球和男子冰球的主场馆。学生用学生票务账号买便宜票。"},"kw":["Kohl Center","basketball","hockey","Badgers","student tickets","Crease Creatures","tip-off","篮球","冰球","学生票","赛季票","Kohl","体育馆"],"sec":{"about":{"en":["The Kohl Center, at 601 W. Dayton St., is the home of Wisconsin men's and women's basketball and men's hockey. It sits in the middle of campus.","Student tickets are sold through your own student athletic ticket account on UWBadgers.com. Student seats are in a dedicated student section; basketball and hockey work differently, as described below."],"zh":["Kohl Center 地址 601 W. Dayton St.，是威斯康星男女篮球和男子冰球的主场馆，位于校园中心。","学生票通过你自己的学生运动票务账号在 UWBadgers.com 购买，座位是专门的学生区。篮球和冰球的办法不一样，见下面。"]},"offers":{"en":["Men's basketball in the student section, with student season tickets and per-game student tickets for exhibition and winter-break games","Men's hockey in the Crease Creatures student section, behind the south-end goal","Women's basketball: student ticket information is on its own student page","Ticket transfer to a friend by text message or email at no charge","A Guest Services desk near Section 119"],"zh":["男子篮球学生区：可买学生赛季票，表演赛和寒假场次有单场学生票","男子冰球的 Crease Creatures 学生区，在南端球门后面","女子篮球：学生票信息在它自己的学生票页面","可以用短信或邮件免费把票转给朋友","119 区附近有 Guest Services 服务台"]},"howto":{"en":["Log in at go.wisc.edu/uwstudenttickets with your student ticket account. New students activate it with the email that received the student information; returning students verify it. Do not use Create Account.","Basketball: enter at the Student Gate between Gates A and B, which opens 90 minutes before tip-off. Your mobile voucher is scanned and swapped for a reserved-seat ticket. Friends who want to sit together should enter together. You may be asked for a valid UW–Madison student ID.","Hockey: the student gate is on the north end (Dayton Street side), right of Gate A. Ticket exchange starts 90 minutes before puck drop and the gate closes at the end of the second period. Enter together and in one line to get seats together.","Download mobile vouchers to Apple Wallet or Google Wallet before you leave home, and have the voucher open before you reach the gate.","Bags: no larger than 8.5 x 11 inches, or clear totes up to 12 x 6 x 12 inches. Backpacks are not allowed. Everyone goes through a metal detector. No outside food or drinks.","Ticket office: (608) 262-1440, tickets@uwbadgers.com. It accepts American Express, Discover, Mastercard and Visa; no cash."],"zh":["用你的学生票务账号登录 go.wisc.edu/uwstudenttickets。新生用收到学生信息的那个邮箱激活，老用户直接验证，不要点 Create Account。","篮球：走 A 门和 B 门之间的学生门 (Student Gate)，开赛前 90 分钟开。手机电子票 (mobile voucher) 会在门口扫描后换成带座位的票。想坐一起的朋友要一起进门。可能要出示有效的 UW–Madison 学生证。","冰球：学生门在北端（Dayton Street 一侧），A 门右手边。开赛前 90 分钟开始换票，第二节结束学生门关闭，之后不能入场。想坐一起就一起排成一队进。","出门前把电子票加进 Apple Wallet 或 Google Wallet，到门口前先把票打开。","包：不超过 8.5 x 11 英寸，或者不超过 12 x 6 x 12 英寸的透明手提袋；背包不能带。人人都要过金属探测，不能带外食和饮料。","票务办公室：(608) 262-1440，tickets@uwbadgers.com。接受 American Express、Discover、Mastercard、Visa，不收现金。"]},"cost":{"en":["Men's basketball exhibition game: $5 per student ticket, limit 2.","Men's basketball winter-break games in 2026-27: $14 per ticket, limit 2 (Purdue Fort Wayne Dec 22, Colorado State Dec 30, Illinois Jan 2, Minnesota Jan 9, Penn State Jan 13). These went on sale Sept 24.","Men's basketball student season ticket: the 2026-27 sale was Sept 23; the page I used shows no price.","Men's hockey student season ticket: price listed as TBA, plus a $20 processing fee. Winter-break and single-game student tickets are discounted at $12, limit 1 per student for single games.","Only degree-seeking students can buy a men's hockey student season ticket, one per student, while supplies last."],"zh":["男篮表演赛：每张学生票 5 美元，限 2 张。","2026-27 男篮寒假场次：每张 14 美元，限 2 张（12/22 Purdue Fort Wayne、12/30 Colorado State、1/2 Illinois、1/9 Minnesota、1/13 Penn State），9/24 已开售。","男篮学生赛季票：2026-27 年的开售日是 9/23，我查到的页面没写价格。","男子冰球学生赛季票：价格页面写 TBA，另加 20 美元手续费。寒假场次和单场学生票有折扣，12 美元，单场每人限 1 张。","男子冰球学生赛季票只卖给攻读学位的学生，每人一张，卖完为止。"]},"tips":{"en":["Arrival times for the basketball student gate: 90–45 minutes before tip-off has minimal waits, 45–25 minutes moderate delays, the last 25 minutes the longest delays.","Basketball season tickets are not seat-specific. Hockey tickets are handed out starting from the rows closest to the ice; you must sit in the seat printed on your ticket.","The men's basketball home exhibition vs UW-Parkside is Saturday, Oct 10, noon; the season opener vs Denver is Nov 2.","If you missed a sale, call the ticket office at (608) 262-1440 and ask if student tickets remain."],"zh":["篮球学生门的排队情况：开赛前 90–45 分钟几乎不用等，45–25 分钟有些延误，最后 25 分钟排队最长。","篮球学生赛季票不对应固定座位。冰球票从最靠近冰面的几排开始发，必须坐票上印的座位。","男篮主场表演赛对 UW-Parkside 是 10/10（周六）中午；赛季首战对 Denver 是 11/2。","错过开售的话，打票务办公室 (608) 262-1440 问问还有没有学生票。"],"exp":[null,null,"2026-10-10",null]},"intl":{"en":["You need a phone with Apple Wallet or Google Wallet for the student voucher, so charge it before the game."],"zh":["学生电子票要放在手机的 Apple Wallet 或 Google Wallet 里，比赛前把手机充好电。"]}},"src":[["Men's Basketball Student Tickets","https://uwbadgers.com/sports/2015/8/21/GEN_20140101505"],["Men's Hockey Student Season Tickets","https://uwbadgers.com/sports/2015/8/21/GEN_20140101506"],["Student Tickets - Wisconsin Athletics","https://uwbadgers.com/sports/2015/8/21/GEN_20140101139"],["Travel Center - Facilities Addresses","https://uwbadgers.com/sports/2015/8/21/GEN_20140101149"],["Fan Policies","https://uwbadgers.com/fanPolicies"],["Wisconsin men's basketball reveals tip times, TV info for 2026-27 season","https://uwbadgers.com/news/2026/10/6/mens-basketball-wisconsin-mens-basketball-reveals-tip-times-tv-info-for-2026-27-season"]],"unv":[],"chk":"2026-10-08","lat":43.069421,"lng":-89.396878,"stops":[["W Dayton at N Frances",185,"81"],["N Bedford at W Mifflin",252,"81"],["Regent at W Washington",262,"E"]]},{"id":"mmoca","cat":"fun","n":{"en":"Madison Museum of Contemporary Art (MMoCA)","zh":"麦迪逊当代艺术博物馆 (MMoCA)"},"kind":{"en":"Contemporary art museum","zh":"当代艺术博物馆"},"addr":"227 State St, Madison, WI 53703","phone":"(608) 257-0158","web":"https://www.mmoca.org/plan-your-visit/","h":{"Mo":[],"Tu":[],"We":[[720,1080]],"Th":[[720,1260]],"Fr":[[720,1080]],"Sa":[[600,1080]],"Su":[[720,1080]]},"ht":{"en":"Wed 12–6 p.m., Thu 12–9 p.m., Fri 12–6 p.m., Sat 10 a.m.–6 p.m., Sun 12–6 p.m. Closed Monday and Tuesday. Also closed on MLK Day, Memorial Day, Juneteenth, Labor Day, Thanksgiving, Christmas Eve, Christmas and New Year's Day.","zh":"周三 12:00–18:00，周四 12:00–21:00，周五 12:00–18:00，周六 10:00–18:00，周日 12:00–18:00。周一、周二闭馆。马丁·路德·金日、阵亡将士纪念日、Juneteenth、劳动节、感恩节、平安夜、圣诞节、元旦也闭馆。"},"sum":{"en":"Free contemporary art museum at the lower end of State Street, with a rooftop sculpture garden and open until 9 p.m. on Thursdays.","zh":"State Street 上的免费当代艺术博物馆，有屋顶雕塑花园，周四开到晚上 9 点。"},"kw":["MMoCA","Madison Museum of Contemporary Art","art museum","contemporary art","State Street","sculpture garden","free museum","当代艺术","艺术博物馆","博物馆","美术馆","展览","免费","屋顶花园"],"sec":{"about":{"en":["MMoCA is the contemporary art museum on State Street, right next to the Overture Center for the Arts. It has galleries across three floors, a rooftop sculpture garden and a lecture hall.","It shows modern and contemporary work in rotating exhibitions, and also hosts film screenings, talks and events."],"zh":["MMoCA 是 State Street 上的当代艺术博物馆，紧挨着 Overture Center for the Arts。三层展厅，另有屋顶雕塑花园和报告厅。","主要做现当代艺术的轮换展，也办放映、讲座和各种活动。"]},"offers":{"en":["Three exhibitions on view in fall 2026: \"Diffuse Control\" by Beeple, \"Slick\" and \"As It Seems\"","Rooftop Sculpture Garden (weather permitting)","Free, self-managed coat check with lockers behind the Lobby Desk","Learning Centers with art-making activities across the museum","MMoCA Cinema screenings, talks and other events, including venue talks for the Wisconsin Book Festival Fall Celebration on Oct. 15–18, 2026","Art Market, a weekend of handmade art and specialty foods, plus the annual Art Fair on the Square, which MMoCA presents"],"zh":["2026 秋季在展：Beeple 的「Diffuse Control」、「Slick」和「As It Seems」","屋顶雕塑花园（看天气是否开放）","大堂服务台后面有免费的自助寄存柜和衣帽间","馆内设有 Learning Center，可以动手做艺术小活动","MMoCA Cinema 放映、讲座和其他活动，包括威斯康星图书节秋季庆典（2026 年 10 月 15–18 日）的几场讲座","Art Market 是一整个周末的手工艺和特色食品集市；每年的 Art Fair on the Square 也由 MMoCA 主办"],"exp":["2027-01-10",null,null,null,"2026-10-18",null]},"howto":{"en":["Walk in through the main entrance on State Street. No ticket is needed for the exhibitions.","Use the coat check for large bags and backpacks. Larger backpacks can be left behind the Lobby Desk.","Open food and drinks, umbrellas, large bags, pens and markers are not allowed in the galleries.","Personal photography without flash is fine in the galleries, the Sculpture Garden and public spaces.","The museum has no parking of its own. It sits between the State Street Capitol Garage and the Overture Center Garage, and a Bus Rapid Transit (BRT) station is in front of the entrance."],"zh":["从 State Street 上的正门进，看展不需要票。","大包、背包放寄存柜；比较大的背包可以放在大堂服务台后面。","展厅里不能带开封的食物饮料、雨伞、大包、笔和马克笔。","展厅、雕塑花园和公共区域可以拍照，仅限个人用途，不能开闪光灯。","馆自己没有停车场，在 State Street Capitol Garage 和 Overture Center Garage 两个市政车库之间；正门前有 BRT（快速公交）站。"]},"cost":{"en":["There is no admission fee for the exhibitions. Most education programs are free too.","Some events, such as film screenings or talks, can have their own ticket. Check the event page."],"zh":["看展不收门票，大部分教育活动也免费。","放映、讲座这类活动可能单独收票，看具体活动页面。"]},"tips":{"en":["Thursday is the late night, open until 9 p.m.; Saturday opens earliest, at 10 a.m.","The museum closes when Madison Metro cancels bus service because of weather, and the rooftop garden can be shut for ice.","Group guided tours are being redesigned; the museum says to check back in fall 2026 to book.","It is next door to the Overture Center, so you can combine a museum visit with a show."],"zh":["周四是晚场，开到 21:00；周六开门最早，10:00。","遇到 Madison Metro 因天气停运，博物馆也会关门；屋顶花园结冰时会关。","团体导览正在重新设计，馆方说 2026 年秋季再来预约。","和 Overture Center 紧挨着，看展和看演出可以顺路一起安排。"],"exp":[null,null,"2026-12-21",null]}},"src":[["MMoCA - Plan Your Visit","https://mmoca.org/visit/"],["MMoCA - Plan Your Visit (final URL)","https://www.mmoca.org/plan-your-visit/"],["MMoCA - Home","https://www.mmoca.org/"]],"unv":[],"chk":"2026-10-08","lat":43.074521,"lng":-89.388908,"stops":[["State Street",57,"A B F"],["State at W Johnson",68,"R"],["W Johnson at State",70,"D 28"]]},{"id":"monona-terrace","cat":"fun","n":{"en":"Monona Terrace Community and Convention Center","zh":"Monona Terrace 会议中心和屋顶花园"},"kind":{"en":"Lakefront rooftop and tours","zh":"湖边屋顶花园和导览"},"addr":"1 John Nolen Dr, Madison, WI 53703","phone":"(608) 261-4000","web":"https://www.mononaterrace.com/","h":{"Mo":[[480,1320]],"Tu":[[480,1320]],"We":[[480,1320]],"Th":[[480,1320]],"Fr":[[480,1440]],"Sa":[[480,1440]],"Su":[[480,1320]]},"ht":{"en":"Rooftop gardens: Sun–Thu 8 a.m.–10 p.m., Fri–Sat 8 a.m.–midnight; closed in bad weather (call (608) 261-4000, 8 a.m.–5 p.m., to check). Building, exhibits and gallery: daily 8 a.m.–5 p.m. Gift shop: Tue–Sat 11 a.m.–3 p.m. Building closed Nov. 26–27, Dec. 24–25 and Dec. 31, 2026.","zh":"屋顶花园：周日到周四 8:00–22:00，周五、周六 8:00–24:00；天气不好会关（可打 (608) 261-4000，8:00–17:00 接听，确认开不开）。大楼、展览和画廊：每天 8:00–17:00。礼品店：周二到周六 11:00–15:00。2026 年 11 月 26–27 日、12 月 24–25 日、12 月 31 日大楼关闭。"},"sum":{"en":"Frank Lloyd Wright's lakefront building: rooftop gardens with lake and Capitol views, free exhibits, and a $5 public tour.","zh":"Frank Lloyd Wright 设计的湖边建筑：屋顶花园看湖景和议会大厦，展览免费，公开导览 5 美元。"},"kw":["Monona Terrace","rooftop","rooftop garden","Frank Lloyd Wright","Lake Monona","view","tour","convention center","屋顶花园","屋顶","莫诺纳","赖特","湖景","导览","景点","免费"],"sec":{"about":{"en":["Monona Terrace is a community and convention center on the shore of Lake Monona. Frank Lloyd Wright first proposed the design in 1938 as a link between the lake and the State Capitol, and it was finally built in 1997.","Most students come for the William T. Evjue Rooftop Gardens on level 6, which look over Lake Monona, the Capitol and the east and west sides of Madison."],"zh":["Monona Terrace 是 Monona 湖边的会议和社区活动中心。Frank Lloyd Wright 在 1938 年提出最初设计，想把湖和州议会大厦连起来，1997 年才真正建成。","学生多半是冲着 6 层的 William T. Evjue 屋顶花园 (Rooftop Gardens) 来的，能看到 Monona 湖、议会大厦以及东西两边的城区。"]},"offers":{"en":["Rooftop gardens with trees, plants and the lake view","Art on the Rooftop: a free public sculpture exhibit in the gardens, with different artwork each year","Otis Redding memorial on the rooftop, open in the warm months and on Dec. 10 each year, weather permitting","Free exhibits: Madison panorama photos, \"The Wright Picture\" photo exhibition, and a gallery on how Wright's design was built","Guided public tour of about an hour on Thursday, Friday and Saturday at 1 p.m.","Gift shop with Wright-inspired items"],"zh":["屋顶花园：有树和植物，能看湖景","Art on the Rooftop：花园里的免费公共雕塑展，每年作品不同","屋顶上有 Otis Redding 纪念碑，暖和的月份和每年 12 月 10 日开放，看天气","免费展览：Madison 全景照片、「The Wright Picture」摄影展，以及讲 Wright 设计如何落成的展厅","公开导览约 1 小时，周四、周五、周六下午 1 点","礼品店卖 Wright 风格的东西"]},"howto":{"en":["Walk in during building hours and go up to level 6 for the rooftop.","Rooftop is closed in bad weather. Call (608) 261-4000 between 8 a.m. and 5 p.m. to ask if it is open.","Public tours are by advance reservation only; reserve through the Monona Terrace website (\"Get Tickets\").","The venue lists 600 on-site parking spaces; see the website's Directions & Parking page."],"zh":["大楼开门时间直接进，上到 6 层就是屋顶。","天气不好屋顶会关；想确认可在 8:00–17:00 打 (608) 261-4000 问。","公开导览只能提前预约，在 Monona Terrace 官网点「Get Tickets」订。","场地有 600 个停车位，详情看官网的 Directions & Parking 页面。"]},"cost":{"en":["Exhibits are free to view. Art on the Rooftop is free, and open whenever the rooftop is open.","Public tour: $5.00 per adult, $3.00 per student aged 5–17, free for children 4 and under. The \"student\" price is for kids 5–17, so adult college students pay $5.00.","Groups of 10 or more can request their own tour."],"zh":["展览免费看；Art on the Rooftop 免费，屋顶开放时都能看。","公开导览：成人 5 美元，5–17 岁学生 3 美元，4 岁及以下免费。这里的「学生价」指 5–17 岁的孩子，大学生按成人 5 美元算。","10 人及以上的团体可以单独申请导览。"]},"tips":{"en":["Rooftop stays open later than the building: until 10 p.m. Sun–Thu and midnight Fri–Sat, so evenings and sunsets work.","Lake Vista Café, the seasonal rooftop café, was open May 19 to Sept. 27, 2026, so it is closed now.","Check the closure list before a holiday trip: closed Nov. 26–27, Dec. 24–25 and Dec. 31, 2026.","You can walk through the exhibits on levels 3 and 4 on your own, daily 8 a.m.–5 p.m."],"zh":["屋顶比大楼关得晚：周日到周四到 22:00，周五、周六到 24:00，傍晚和日落时去都行。","屋顶上的季节性咖啡厅 Lake Vista Café 今年只开到 9 月 27 日，现在已经关了。","假期去之前看一眼闭馆日：2026 年 11 月 26–27 日、12 月 24–25 日、12 月 31 日关闭。","3 层和 4 层的展览可以自己逛，每天 8:00–17:00。"],"exp":["2026-12-31","2026-12-31","2026-12-31",null]}},"src":[["Monona Terrace - Home (hours, closures)","https://www.mononaterrace.com/"],["Monona Terrace - Tours & Education","https://www.mononaterrace.com/experience-monona-terrace/tours-and-education/"],["Monona Terrace - Current Exhibits","https://www.mononaterrace.com/experience-monona-terrace/current-exhibits/"],["Monona Terrace - Other Things To See","https://www.mononaterrace.com/experience-monona-terrace/other-things/"]],"unv":[],"chk":"2026-10-08","lat":43.071638,"lng":-89.380155,"stops":[["W Wilson at M L K Junior",153,"C 38"],["E Doty at M L K Junior",232,"C 38"],["W Main at M L K Junior",338,"E R 75"]]},{"id":"olbrich-botanical-gardens","cat":"fun","n":{"en":"Olbrich Botanical Gardens","zh":"Olbrich 植物园"},"kind":{"en":"Botanical garden","zh":"植物园"},"addr":"3330 Atwood Ave, Madison, WI 53704","phone":"(608) 246-4550","web":"https://www.olbrich.org/visit","h":{"Mo":[[600,960]],"Tu":[[600,960]],"We":[[600,960]],"Th":[[600,960]],"Fr":[[600,960]],"Sa":[[600,960]],"Su":[[600,960]]},"ht":{"en":"Outdoor gardens, lobby, gift shop and Bolz Conservatory: 10 a.m.–4 p.m. daily Oct–Mar (fall 2026), 10 a.m.–6 p.m. daily Apr–Sep. Closed Thanksgiving, Christmas Day and New Year's Day; closes at 2 p.m. on Christmas Eve.","zh":"室外花园、大厅、礼品店和 Bolz 温室：10 月到 3 月（含 2026 秋季）每天 10:00–16:00，4 月到 9 月每天 10:00–18:00。感恩节、圣诞节、元旦闭园，平安夜 14:00 关门。"},"sum":{"en":"16 acres of outdoor gardens on Lake Monona, free to walk, plus a glass-pyramid tropical conservatory that costs $6.","zh":"Monona 湖边 16 英亩的室外花园，免费逛；另有玻璃金字塔热带温室，门票 6 美元。"},"kw":["Olbrich","botanical garden","gardens","Bolz Conservatory","conservatory","Thai Pavilion","free","植物园","花园","温室","泰式亭","免费","Lake Monona"],"sec":{"about":{"en":["Olbrich Botanical Gardens sits across the street from Olbrich Park on Lake Monona, about 3 miles from downtown. It has 16 acres of outdoor gardens and the Bolz Conservatory, a glass pyramid of tropical and sub-tropical plants.","The outdoor gardens are free. Only the conservatory charges admission."],"zh":["Olbrich 植物园在 Monona 湖边的 Olbrich Park 马路对面，离市中心约 3 英里。有 16 英亩的室外花园，还有 Bolz Conservatory：一座玻璃金字塔形状的温室，里面是热带和亚热带植物。","室外花园免费，只有温室收门票。"]},"offers":{"en":["Outdoor gardens to walk through, including the Royal Thai Pavilion, a gift to UW–Madison from the Thai government and the Thai Chapter of the Wisconsin Alumni Association","Bolz Conservatory: tropical and sub-tropical plants under a glass pyramid, open year-round","Lobby with a gift shop; food and drinks bought on site can be eaten in the lobby","Free tram rides around the outdoor gardens, mainly for visitors who need help getting around","Picnic tables by the main entrance and across the street in Olbrich Park, on the Lake Monona shore","Classes, exhibits and events listed on the calendar"],"zh":["室外花园可以随便逛，包括皇家泰式亭 (Royal Thai Pavilion)，它是泰国政府和威大校友会泰国分会送给 UW–Madison 的礼物","Bolz Conservatory 温室：玻璃金字塔里的热带和亚热带植物，全年开放","大厅有礼品店；在店里买的吃喝可以在大厅里享用","园里有免费电动小车 (tram) 绕室外花园，主要给行动不便的游客","大门旁和马路对面的 Olbrich Park（在 Monona 湖边）都有野餐区","官网日历上有课程、展览和活动"]},"howto":{"en":["Walk in for the outdoor gardens; no ticket needed. Pay at the lobby only if you want the Bolz Conservatory.","Parking is free; the lot has 210 spaces and can fill when other events are nearby. Carpooling or a rideshare is the backup.","Bike option: Olbrich sits on the Capital City Bike Trail, about 3 miles from downtown.","Leave pets at home. Service animals are fine; emotional support animals are not.","Do not bring a picnic into the gardens. Eat at the picnic areas by the entrance or in Olbrich Park. Only water is allowed inside the conservatory.","Keep your shirt and shoes on, and use headphones for music."],"zh":["只逛室外花园直接进，不用票。想进 Bolz 温室再去大厅付费。","停车免费，停车场 210 个位子，附近有活动时会满；满了就拼车或打车。","也可以骑车：园子在 Capital City Bike Trail 上，离市中心约 3 英里。","宠物请留在家里。服务动物可以，情感支持动物不行。","不能在花园里野餐带外食，请去大门旁或 Olbrich Park 的野餐区吃。温室里只能喝水。","要穿上衣和鞋；想听音乐请戴耳机。"]},"cost":{"en":["Outdoor gardens: free admission; donations accepted.","Bolz Conservatory: $6 adults, $3 ages 6–12, free for ages 5 and under and Botanical Society members.","The conservatory is free on Wednesday and Saturday from 10 a.m. to noon.","Museums for All: people receiving SNAP can get in free by showing an EBT card and a photo ID."],"zh":["室外花园：免费，欢迎捐款。","Bolz 温室：成人 6 美元，6–12 岁 3 美元，5 岁及以下和植物园会员 (Botanical Society) 免费。","周三和周六上午 10:00 到中午 12:00 温室免费。","Museums for All：领 SNAP 食品补助的人出示 EBT 卡和带照片的证件可免费进。"]},"tips":{"en":["Go on a Wednesday or Saturday morning to see the conservatory for free.","From October to March the grounds close at 4 p.m., two hours earlier than in summer. Plan to arrive by 2.","The conservatory sometimes closes for exhibit set-up or maintenance, so check the Visit page before a special trip.","Standard fees and times may change during special events and exhibits."],"zh":["想免费看温室就挑周三或周六的上午。","10 月到 3 月 16:00 就关门，比夏天早 2 小时，最好 14:00 前到。","温室有时因为换展或维护临时关闭，专程去之前先看官网 Visit 页。","办特别活动或展览时，门票和开放时间可能临时调整。"]},"intl":{"en":["The Visit page is also available in Traditional Chinese, and translation help is listed there."],"zh":["官网 Visit 页有繁体中文版，页面上还列了翻译协助。"]}},"src":[["Olbrich Botanical Gardens - Visit (Wayback Machine copy of olbrich.org, 3 Jun 2026)","https://web.archive.org/web/2026/https://www.olbrich.org/visit"],["Olbrich - Royal Thai Pavilion & Garden (Wayback copy, 3 Jun 2026)","https://web.archive.org/web/2026/https://www.olbrich.org/gardens/thai-pavilion-garden"],["Olbrich Botanical Gardens - Wikipedia","https://en.wikipedia.org/wiki/Olbrich_Botanical_Gardens"]],"unv":[],"chk":"2026-10-08","lat":43.092025,"lng":-89.336514,"stops":[["Atwood at Oakridge",20,"C 38"],["Atwood at Lakeland",63,"C 38"],["Atwood at S Fair Oaks",381,"C 38"]]},{"id":"overture-center-for-the-arts","cat":"fun","n":{"en":"Overture Center for the Arts","zh":"Overture 艺术中心"},"kind":{"en":"Theater and arts center","zh":"剧院和艺术中心"},"addr":"201 State St, Madison, WI 53703","phone":"(608) 258-4141","web":"https://www.overture.org/visit/","h":{"Mo":[],"Tu":[[660,1080]],"We":[[660,1080]],"Th":[[660,1080]],"Fr":[[660,1080]],"Sa":[[660,1080]],"Su":[[720,1080]]},"ht":{"en":"Building: Tue–Sat 11 a.m.–6 p.m., Sun 12–6 p.m.; closed to the public on Mondays starting Oct. 12, 2026. Ticket office: Tue–Fri 11 a.m.–5 p.m., Sat 11 a.m.–2 p.m., and longer on performance days. Performances run on their own schedule.","zh":"大楼：周二到周六 11:00–18:00，周日 12:00–18:00；从 2026 年 10 月 12 日起周一不对公众开放。售票处：周二到周五 11:00–17:00，周六 11:00–14:00，演出日会延长。演出按各自场次时间。"},"sum":{"en":"Madison's main performing arts center on State Street: Broadway and local companies, student rush tickets, and four free art galleries.","zh":"State Street 上的主要演艺中心：百老汇和本地剧团的演出、学生 rush 折扣票，还有免费的画廊。"},"kw":["Overture","Overture Center","theater","Broadway","student rush","student tickets","gallery","symphony","ballet","opera","State Street","剧院","百老汇","学生票","折扣票","画廊","交响乐","芭蕾","歌剧","演出"],"sec":{"about":{"en":["Overture Center is the big performing arts building at the top of State Street, next to MMoCA. It holds Overture Hall, the Capitol Theater, the Playhouse and several art galleries.","It is also the home of nine resident companies, including Madison Symphony Orchestra, Madison Opera, Madison Ballet, Forward Theater Company and Kanopy Dance Company, plus a Broadway season and an Overture Presents season."],"zh":["Overture Center 是 State Street 上段的大型演艺中心，紧挨 MMoCA。里面有 Overture Hall、Capitol Theater、Playhouse 几个剧场和多间画廊。","常驻的九个团体包括麦迪逊交响乐团、麦迪逊歌剧院、麦迪逊芭蕾、Forward Theater Company、Kanopy Dance Company 等，另外有百老汇系列和 Overture Presents 系列演出。"]},"offers":{"en":["Broadway tours and Overture Presents shows; the fall 2026 calendar includes The Wiz (through Oct. 11) and Colin Cloud: MASTERMIND (Oct. 10)","Resident company seasons: symphony, opera, ballet, theater, dance","Overture Galleries: five galleries with rotating exhibitions, always free, and most artworks are for sale","Free events, including Kids in the Rotunda for families","Snacks and drinks at the bars and concession stands before the show and at intermission","Coat check for events in Overture Hall, the Capitol Theater and the Playhouse"],"zh":["百老汇巡演和 Overture Presents 系列演出；2026 秋季日程有 The Wiz（到 10 月 11 日）和 Colin Cloud: MASTERMIND（10 月 10 日）","常驻团体的演出季：交响乐、歌剧、芭蕾、戏剧、舞蹈","Overture Galleries：五间画廊轮换展览，一直免费，多数作品可购买","有免费活动，比如面向家庭的 Kids in the Rotunda","开演前和中场休息时，酒吧和小卖部卖零食饮料","Overture Hall、Capitol Theater 和 Playhouse 的演出场次有衣帽寄存"],"exp":["2026-10-11",null,null,null,null,null]},"howto":{"en":["Buy tickets online, in person at the ticket office, or by phone at (608) 258-4141. Email orders are not accepted.","Student rush is set by each resident company, not by Overture. Bring a valid student ID to the box office or venue, at the time each company lists below.","To get Overture's student rush alerts, sign in to your Overture account and add \"Student Rush\" to your interests.","Everyone goes through a walk-through security scanner on arrival. There are no bag checks, but weapons are not allowed.","The Overture Hall lobby generally opens 90 minutes before showtime, the Capitol Theater 60 minutes before.","Digital tickets are at wallet.overture.org; the QR code activates two hours before the show."],"zh":["票可以网上买、去售票处买，或打 (608) 258-4141；不接受邮件订票。","学生 rush 票由各常驻团体自己定，不是 Overture 统一的。带有效学生证去售票处或演出场地，按下面各团体写的时间买。","想收到 Overture 的 student rush 提醒：登录 Overture 账户，在兴趣里加上「Student Rush」。","进门要走一遍步行式安检，不用开包检查，但不能带武器。","Overture Hall 大堂一般在开演前 90 分钟开，Capitol Theater 开演前 60 分钟开。","电子票在 wallet.overture.org，二维码演出前两小时开始生效。"]},"cost":{"en":["Overture Galleries are always free.","Student rush prices listed in Oct. 2026: Madison Symphony Orchestra $15 (organ concerts $10), in person, from the Wednesday of the performance weekend. Madison Opera $19.99, in person, from the Friday. Wisconsin Chamber Orchestra $15, from the Monday of show week.","Kanopy Dance $20 and Madison Ballet $25, day of the show only. Children's Theater of Madison $21.10–$30.88 depending on the show, also day of show. Most allow two tickets per student ID.","Forward Theater Company student and educator price is $21 in person or $20.42 online, no ID required. Not offered for the first preview performance, and only for side sections and the balcony."],"zh":["Overture Galleries 一直免费。","官网 2026 年 10 月列出的学生 rush 价：麦迪逊交响乐团 15 美元（管风琴音乐会 10 美元），现场买，演出周末的周三开卖；麦迪逊歌剧院 19.99 美元，现场买，周五开卖；威斯康星室内乐团 15 美元，演出当周周一开卖。","Kanopy Dance 20 美元、麦迪逊芭蕾 25 美元，仅演出当天买；Children's Theater of Madison 按剧目 21.10–30.88 美元，也是演出当天。多数每个学生证限买 2 张。","Forward Theater Company 学生和教师价现场 21 美元、网上 20.42 美元，不用出示证件；首场预演不适用，只限侧区和楼座。"]},"tips":{"en":["Starting Monday, Oct. 12, 2026, the building and ticket office are closed to the public on Mondays. Performances still run.","Student rush is first come, first served and varies per show, so check the Student Rush page the week of the show.","Parking: the Overture Center ramp between West Dayton and Mifflin Streets and the State Street Capitol ramp both have elevator access. Special-event garage parking starts two hours before showtime.","Fall 2026 gallery shows: Galleries I–III run Sept. 8 to Nov. 29, and the Playhouse and Rotunda galleries run Sept. 1 to Nov. 15."],"zh":["从 2026 年 10 月 12 日（周一）起，周一大楼和售票处不对公众开放，但演出照常。","学生 rush 先到先得，每场情况不同，演出当周去 Student Rush 页面看一眼。","停车：West Dayton 和 Mifflin 之间的 Overture Center 车库和 State Street Capitol 车库都有电梯；活动停车从开演前两小时开始。","2026 秋季展期：Gallery I–III 是 9 月 8 日到 11 月 29 日，Playhouse 和 Rotunda 画廊是 9 月 1 日到 11 月 15 日。"],"exp":[null,null,null,"2026-11-15"]}},"src":[["Overture Center for the Arts - Home","https://www.overture.org/"],["Overture - Visit","https://www.overture.org/visit/"],["Overture - FAQs","https://www.overture.org/visit/faqs/"],["Overture - Student Rush","https://www.overture.org/tickets-events/student-rush/"],["Overture - Galleries","https://www.overture.org/engage/galleries/"],["Overture - Galleries information for artists","https://www.overture.org/engage/galleries/information-for-artists/"]],"unv":[],"chk":"2026-10-08","lat":43.074134,"lng":-89.388277,"stops":[["State Street",121,"A B F"],["State at W Johnson",132,"R"],["W Johnson at State",137,"D 28"]]},{"id":"tenney-park","cat":"fun","n":{"en":"Tenney Park","zh":"Tenney 公园"},"kind":{"en":"Lakefront park, winter skating","zh":"湖滨公园和冬季滑冰"},"addr":"1414 E Johnson St, Madison, WI 53703","phone":"","web":"https://www.cityofmadison.com/parks/find-a-park/tenney","h":{"Mo":[[240,1320]],"Tu":[[240,1320]],"We":[[240,1320]],"Th":[[240,1320]],"Fr":[[240,1320]],"Sa":[[240,1320]],"Su":[[240,1320]]},"ht":{"en":"Park hours 4 a.m.–10 p.m. daily. Skating rinks and the lagoon open only when ice conditions allow, listed as \"Closed for Season\" in early October 2026. Call the Park Rangers after hours: (608) 235-0448.","zh":"公园每天 4:00–22:00。滑冰场和冰面泻湖要等冰况合格才开放，2026 年 10 月初显示 Closed for Season。非办公时间找公园巡警：(608) 235-0448。"},"sum":{"en":"38-acre city park on Lake Mendota with a beach, courts, and in winter free ice skating on a frozen lagoon with a staffed warming shelter.","zh":"Mendota 湖边 38 英亩的市属公园，有沙滩、球场；冬天冰面泻湖免费滑冰，有人值守的取暖棚。"},"kw":["Tenney Park","ice skating","skating","lagoon","hockey rink","beach","winter","Lake Mendota","滑冰","冰场","冰球","沙滩","公园","冬天","Tenney","skate rental"],"sec":{"about":{"en":["Tenney Park is a 38-acre City of Madison park on Lake Mendota. It has a beach, a boat launch, ball courts and fields, and a frozen lagoon for skating in winter.","In winter the city grooms the lagoon and a hockey rink for skating. Skating is free; only skate rental costs money."],"zh":["Tenney 公园是 Madison 市属公园，38 英亩，在 Mendota 湖边。有沙滩、船只下水点、球场和球场草坪，冬天有可以滑冰的冰面泻湖。","冬天市里会维护泻湖和一个冰球场供滑冰。滑冰免费，只有租冰鞋要钱。"]},"offers":{"en":["Frozen lagoon and a groomed hockey rink with boards for winter skating, and a warming shelter with skate rental and snacks","Beach on Lake Mendota with swim ropes (no lifeguards)","1 full basketball court, 3 lighted tennis and pickleball courts, 1 sand volleyball court, 2 multipurpose fields","Boat launch (Lake Access Permit required), plus a canoe and kayak launch and storage racks","Fishing from the shore; 16 and older need a Wisconsin DNR license","Free volunteer-led nature walks, monthly, all year"],"zh":["冬天有冰面泻湖和带围板的冰球场，旁边有取暖棚，可租冰鞋、买小吃","Mendota 湖边的沙滩，有泳道绳，没有救生员","1 个标准篮球场、3 个带灯的网球/匹克球场、1 个沙地排球场、2 块多功能球场","有船只下水点（要 Lake Access Permit），另有独木舟/皮划艇下水点和存放架","可在岸边钓鱼；16 岁及以上需要 Wisconsin DNR 钓鱼执照","每月一次、全年举办的免费志愿者带队自然导览"]},"howto":{"en":["Skating is free. Before you go, check the rink status on the city's ice skating page; if a rink or lagoon is listed as closed, do not go on the ice.","Warming pavilion hours when staffed: Wed–Fri 4–8 p.m., Sat 12–8 p.m., Sun 12–6 p.m. Rinks close when meltwater shows.","Rent skates at the Tenney warming shelter when it is staffed. Hockey sticks can be rented there too.","Alcohol is prohibited in this park without a permit.","Beach swimming season is typically Memorial Day weekend through Labor Day weekend."],"zh":["滑冰免费。出发前先看市政府冰场状态页；如果冰场或泻湖标 Closed，就不要上冰。","取暖棚有人值守的时间：周三到周五 16:00–20:00，周六 12:00–20:00，周日 12:00–18:00。有融水时冰场会关闭。","有人值守时，可以在 Tenney 取暖棚租冰鞋，也能租冰球杆。","没有许可证，本公园禁止饮酒。","沙滩的游泳季通常是阵亡将士纪念日那个周末到劳动节那个周末。"]},"cost":{"en":["Entering the park and skating are free.","Skate rental: $6 for the first hour for adults, $3 for youth 15 and under, $2 for each additional hour. Hockey stick rental $3.","Free loaner skates are listed only for Olbrich, Rennebohm, Warner and Westmorland Parks, not Tenney."],"zh":["进公园和滑冰都免费。","冰鞋租金：成人第一小时 6 美元，15 岁及以下 3 美元，之后每多一小时 2 美元。冰球杆 3 美元。","免费借冰鞋的只有 Olbrich、Rennebohm、Warner 和 Westmorland 公园，Tenney 没有。"]},"tips":{"en":["In early October 2026 the lagoon and rink are both listed as closed for the season. They open when the ice is safe, usually in winter.","City-run skating warming shelters are normally staffed through early to mid-February.","If you only want to skate, look at Vilas Park's lagoon too; it also has a staffed warming shelter with rentals.","The Tenney Locks are run by Dane County and typically open May through October."],"zh":["2026 年 10 月初泻湖和冰球场都显示本季已关闭，要等冰面安全才会开，通常是冬天。","市里的滑冰取暖棚一般开到 2 月上旬到中旬。","只想滑冰的话，也可以看看 Vilas Park 的泻湖，那里同样有带租鞋的取暖棚。","Tenney Locks 由 Dane County 管理，一般 5 月到 10 月开放。"]}},"src":[["City of Madison Parks - Tenney Park","https://www.cityofmadison.com/parks/find-a-park/tenney"],["City of Madison Parks - Ice Skating","https://www.cityofmadison.com/parks/find-a-park/winter/ice-skating"],["City of Madison Parks - Beaches","https://www.cityofmadison.com/parks/find-a-park/water/beaches"]],"unv":["phone"],"chk":"2026-10-08","lat":43.091055,"lng":-89.36702,"stops":[["E Johnson at N Dickinson",24,"D"],["E Johnson at N Baldwin",212,"D"],["N Baldwin at E Johnson",234,"28"]]},{"id":"uw-madison-arboretum","cat":"fun","n":{"en":"UW–Madison Arboretum","zh":"UW–Madison 树木园 (Arboretum)"},"kind":{"en":"Nature preserve and trails","zh":"自然保护区和步道"},"addr":"1207 Seminole Hwy, Madison, WI 53711","phone":"(608) 263-7888","web":"https://arboretum.wisc.edu/visit/","h":{"Mo":[[240,1320]],"Tu":[[240,1320]],"We":[[240,1320]],"Th":[[240,1320]],"Fr":[[240,1320]],"Sa":[[240,1320]],"Su":[[240,1320]]},"ht":{"en":"Grounds, trails and parking lots: 4 a.m.–10 p.m. every day, all year. Visitor Center: 9:30 a.m.–4 p.m. weekdays, 12:30–4 p.m. weekends; closed on New Year's Day, MLK Day, Easter, Memorial Day, July 4, Labor Day, Thanksgiving, Dec 24, Dec 25 and Dec 31.","zh":"园区、步道和停车场：全年每天 4:00–22:00。游客中心 (Visitor Center)：工作日 9:30–16:00，周末 12:30–16:00；元旦、MLK 日、复活节、阵亡将士纪念日、7/4、劳动节、感恩节、12/24、12/25、12/31 不开。"},"sum":{"en":"1,200 acres of prairie, woods and wetland with 17+ miles of free trails near Lake Wingra. Good for a quiet walk, fall colors and free guided hikes.","zh":"Wingra 湖边 1200 英亩的草原、树林和湿地，17 英里以上免费步道；适合散步看秋叶，还有免费导览。"},"kw":["arboretum","UW Arboretum","trails","hiking","nature","walk","fall colors","prairie","树木园","步道","徒步","散步","秋叶","Lake Wingra","free"],"sec":{"about":{"en":["The Arboretum is a 1,200-acre UW–Madison preserve on the near-west side of Madison, on the southern shore of Lake Wingra. It has ecological communities, horticultural gardens, effigy mounds, more than 17 miles of trails and a Visitor Center.","It is a research and restoration site as well as a park, so the rules are stricter than a city park: no dogs, no picnics, stay on the trails."],"zh":["Arboretum 是 UW–Madison 的 1200 英亩保护区，在 Madison 西边，南临 Wingra 湖。里面有各类生态群落、园艺花园、effigy mounds（动物形土丘）、17 英里以上步道和一个游客中心。","它同时是科研和生态修复基地，规矩比普通公园严：不能带狗、不能野餐、必须走步道。"]},"offers":{"en":["More than 17 miles of trails through prairie, woods and wetland; bird watching, wildflowers, fall colors, winter ecology","4 miles of paved road for runners and cyclists; running is also allowed on unpaved fire lanes and footpaths","Longenecker Horticultural Gardens and other gardens near the Visitor Center","Visitor Center: free maps and brochures, a bookstore, water bottle refill, restrooms, exhibits","Free guided nature walks and talks, listed on the events calendar; most are free with no registration, some need an Eventbrite sign-up","Skiing and snowshoeing on designated trails in winter"],"zh":["17 英里以上步道，穿过草原、树林和湿地；可以看鸟、野花、秋叶，冬天看冰雪生态","4 英里柏油路给跑步和骑车；未铺装的防火道 (fire lane) 和小径也能跑步","Longenecker Horticultural Gardens 等花园就在游客中心附近","游客中心：免费地图和宣传册、书店、接水、洗手间、展览","活动日历上有免费导览步行和讲座，大多免费且不用报名，少数要在 Eventbrite 上预约","冬天在指定步道上可以滑雪、穿雪鞋徒步"]},"howto":{"en":["Walk or drive in; no ticket or sign-up. The main entrance is 1207 Seminole Highway. The Visitor Center and main lots are 1 mile in from there and 2.3 miles from the Wingra Drive / Mills Street entrance.","There is no bus to the Visitor Center. The east and west entrances and the Wingra Oak Savanna lot are on or near Metro bus stops, and there is a BCycle station at the Visitor Center lot.","Bike on the paved drives only. Bikes are not allowed on trails or in gardens. Speed limit on the drive is 20 mph, bikes included.","Walkers and runners on the road: stay on the shoulder and face oncoming traffic.","Wear closed-toe shoes; trails can be uneven, muddy, icy or flooded.","Not allowed: dogs and other pets (service dogs are OK), picnics, alcohol, hammocks and tree climbing, foraging, fishing, drones, campfires, amplified sound, skateboards, rollerblades and e-scooters.","Questions: Visitor Center, (608) 263-7888."],"zh":["走路或开车进去都行，不用票也不用报名。正门地址是 1207 Seminole Highway，游客中心和主停车场从那里再往里 1 英里；从 Wingra Drive / Mills Street 入口进则是 2.3 英里。","游客中心没有公交直达。东、西入口和 Wingra Oak Savanna 停车场在 Metro 公交站点上或附近，游客中心停车场里有 BCycle 共享单车站。","骑车只能走柏油路，步道和花园里禁止骑车。园内车道限速 20 英里/小时，自行车也算。","在路上跑步、走路要靠路边，面向来车。","穿包脚趾的鞋；步道可能不平、泥泞、结冰或积水。","禁止：狗和其他宠物（服务犬可以）、野餐、喝酒、挂吊床和爬树、采摘、钓鱼、无人机、生火、外放声音、滑板、轮滑和电动滑板车。","有问题打游客中心电话 (608) 263-7888。"]},"cost":{"en":["Free to visit.","Most walks, talks and tours are free; a few need advance registration but are still free."],"zh":["免费参观。","大多数步行导览和讲座免费；少数要提前报名，但也不收费。"]},"tips":{"en":["The Visitor Center opens late on weekends (12:30 p.m.), but the trails are open from 4 a.m., so early walks are fine.","The gate that stops cars at the Visitor Center is open on Sunday afternoons from 12 to 5 p.m.","Outdoor public walks are canceled for 10 °F or colder with wind chill, heavy snow or ice, thunderstorms, heat index above 100 °F, or air quality index above 200.","Leave the dog at home even if you only stay on the road; pets are banned on the drives too.","Henry Vilas Zoo and Vilas Park are next door, so the two combine into one afternoon."],"zh":["周末游客中心 12:30 才开，但步道早上 4:00 就开放，早起散步没问题。","游客中心处拦车的闸门，周日 12:00–17:00 会打开。","户外公开导览遇到体感 10°F 以下、大雪或结冰、雷暴、热指数超过 100°F 或空气质量指数超过 200 时取消。","只走车道也不能带狗，车道上同样禁止宠物。","旁边就是 Henry Vilas 动物园和 Vilas Park，可以合并成一个下午。"]},"intl":{"en":["Picnics and dogs are banned, which surprises many visitors. Use Vilas Park next door for a picnic."],"zh":["这里禁止野餐和带狗，很多人第一次来不知道。想野餐可以去旁边的 Vilas Park。"]}},"src":[["UW–Madison Arboretum - Visit","https://arboretum.wisc.edu/visit/"],["UW–Madison Arboretum - Getting Here","https://arboretum.wisc.edu/visit/getting-here/"],["UW–Madison Arboretum - Visitor Etiquette","https://arboretum.wisc.edu/visit/etiquette/"],["UW–Madison Arboretum - Events","https://arboretum.wisc.edu/visit/events/"]],"unv":[],"chk":"2026-10-08","lat":43.03964,"lng":-89.443755,"stops":[["Nakoma at Waban",325,"D 63"],["Nakoma at Seminole",459,"D 63"],["Nakoma at Mohawk",512,"D 63"]]},{"id":"uw-geology-museum","cat":"fun","n":{"en":"UW–Madison Geology Museum","zh":"UW–Madison 地质博物馆"},"kind":{"en":"Geology museum","zh":"地质博物馆"},"addr":"1215 W Dayton St, Madison, WI 53706","phone":"(608) 262-1412","web":"https://museum.geoscience.wisc.edu/visit/","h":{"Mo":[[510,990]],"Tu":[[510,990]],"We":[[510,990]],"Th":[[510,990]],"Fr":[[510,990]],"Sa":[[540,780]],"Su":[]},"ht":{"en":"Mon–Fri 8:30 a.m.–4:30 p.m., Sat 9 a.m.–1 p.m., closed Sunday. The museum says it is open over 300 days a year, so check the website before going on a holiday.","zh":"周一到周五 8:30–16:30，周六 9:00–13:00，周日闭馆。馆方说全年开放 300 多天，节假日去之前先看官网。"},"sum":{"en":"Free museum in Weeks Hall with a mastodon skeleton, dinosaur bones, meteorites and glowing minerals, a short walk from Union South.","zh":"Weeks Hall 里的免费地质博物馆：乳齿象骨架、恐龙骨头、陨石、荧光矿物，离 Union South 很近。"},"kw":["geology museum","Weeks Hall","mastodon","dinosaur","fossils","minerals","meteorite","free museum","地质博物馆","博物馆","恐龙","化石","矿物","乳齿象","免费"],"sec":{"about":{"en":["The UW Geology Museum is on one level of Weeks Hall, two blocks east of Camp Randall Stadium at the corner of Charter Street and Dayton Street. The university's geology collection goes back to the first Board of Regents meeting in 1848.","It is a small museum on a single level, and it is free."],"zh":["地质博物馆在 Weeks Hall 的一层，Camp Randall 体育场往东两个路口，Charter Street 和 Dayton Street 的拐角。学校的地质标本收藏可以追溯到 1848 年第一次校董会。","馆不大，只有一层，而且免费。"]},"offers":{"en":["The Boaz mastodon skeleton, found in a Wisconsin streambed in 1897: 9.5 feet tall and 15 feet long","Rocks you can touch, including rock from when there were volcanoes in Wisconsin","Rocks and minerals that glow under black light (fluorescent minerals)","Meteorites, dinosaurs and fossil vertebrates, plus corals, jellyfish and other sea-creature fossils","A model of a Wisconsin cave"],"zh":["Boaz 乳齿象骨架，1897 年在威斯康星的一条溪床里发现，高 9.5 英尺、长 15 英尺","可以上手摸的岩石，包括威斯康星有过火山时期的岩石","黑光灯下会发光的岩石和矿物（荧光矿物）","陨石、恐龙和脊椎动物化石，还有珊瑚、水母等海洋生物化石","一个威斯康星洞穴的模型"]},"howto":{"en":["Walk in during open hours. No ticket, no reservation for individuals.","Copies of a self-guided tour booklet (also in Spanish) are just inside the doors.","Groups of 10 or more should contact the museum in advance. Email tours@geology.wisc.edu or call (608) 262-1412 at least two weeks ahead.","The museum is on a single level, wheelchair accessible, and has stools you can use."],"zh":["开馆时间直接进，个人参观不用票、不用预约。","门里放着自助参观小册子（有西班牙语版），自己拿。","10 人及以上的团体要提前联系：发邮件到 tours@geology.wisc.edu 或打 (608) 262-1412，至少提前两周。","馆在同一层，轮椅可以进，有凳子可以坐。"]},"cost":{"en":["Admission is free.","A staff-led group tour costs $3 per person (about one hour, minimum 10 people)."],"zh":["免费入场。","团体导览收费每人 3 美元（约 1 小时，至少 10 人）。"]},"tips":{"en":["Spring (March–June) is the busiest season for visiting school and group tours, so expect more people then.","The nearest UW parking is Lot 80 under Union South and Lot 17 off Engineering Drive. Street parking south of the museum is two-hour and hard to find. Union South, one block away, has a BCycle station.","Guided tours are for groups of 10 or more. On your own, use the self-guided booklet inside the door."],"zh":["春季（3–6 月）校外团体最多，那段时间会更挤。","最近的校内停车场是 Union South 下面的 Lot 80 和 Engineering Drive 边的 Lot 17；馆南边街上的免费位限停两小时，很难找。一个路口外的 Union South 有 BCycle 站。","导览是给 10 人以上团体的；一个人去就拿门口的自助参观小册子。"]}},"src":[["UW Geology Museum - Home","https://museum.geoscience.wisc.edu/"],["UW Geology Museum - Visit","https://museum.geoscience.wisc.edu/visit/"],["UW Geology Museum - Tours","https://museum.geoscience.wisc.edu/tours/"],["UW Geology Museum - Contact","https://museum.geoscience.wisc.edu/contact/"],["UW Geology Museum - About","https://museum.geoscience.wisc.edu/about/"]],"unv":[],"chk":"2026-10-08","lat":43.070526,"lng":-89.405939,"stops":[["W Dayton at N Orchard",97,"80"],["W Dayton at N Mills",187,"80"],["Orchard",199,"A F"]]},{"id":"washburn-observatory","cat":"fun","n":{"en":"Washburn Observatory Open House","zh":"Washburn 天文台公开观星夜"},"kind":{"en":"Free stargazing night","zh":"免费观星夜"},"addr":"1401 Observatory Dr, Madison, WI 53706","phone":"","web":"https://www.astro.wisc.edu/outreach/washburn/","h":null,"ht":{"en":"Open House nights only: the first and third Wednesday of each month, 7–9 p.m. from October through March (9–11 p.m. from April through September), weather permitting. Every Wednesday in June, July and August.","zh":"只在公开观星夜开放：每月第一个和第三个周三，10 月到次年 3 月 19:00–21:00（4 月到 9 月是 21:00–23:00），看天气。6、7、8 月每个周三都有。"},"sum":{"en":"Free telescope nights at UW's 1878 observatory on Observatory Drive, run by astronomy grad students on the 1st and 3rd Wednesday.","zh":"UW 1878 年建的天文台，每月第 1、第 3 个周三晚上免费用望远镜看星星，天文研究生带着看。"},"kw":["Washburn Observatory","observatory","telescope","stargazing","astronomy","open house","free","night","天文台","观星","望远镜","星空","天文","免费","晚上"],"sec":{"about":{"en":["Washburn Observatory is the university's first scientific research facility. Cadwallader Washburn began building it in 1878 and gave it to the university and the state.","On set nights the Astronomy Department opens the dome for public observing. Astronomy graduate students run the sessions."],"zh":["Washburn 天文台是学校第一座科研设施，Cadwallader Washburn 1878 年开始建，建成后送给了学校和州政府。","在固定的晚上，天文系会开放圆顶供公众观测，由天文系研究生带着看。"]},"offers":{"en":["Looking through the observatory's telescope at whatever the sky offers that night","Informal sessions: no lecture and no tour, you just come up and look","Sessions hosted by UW astronomy graduate students"],"zh":["用天文台的望远镜看当晚天上有什么","形式随意，没有讲座也没有导览，上去看就行","由 UW 天文系研究生主持"]},"howto":{"en":["Come on a scheduled Wednesday during the listed hours. No ticket or sign-up is mentioned.","Enter at the south door (the one facing away from the lake), go up the stairs to your right, then through the door in front of you into the dome.","Check the Washburn Twitter feed (X) for go or no-go; it is usually updated about 30 minutes before the start.","Questions or private events: email washburn@astro.wisc.edu. The dome has no phone line."],"zh":["按日程在周三晚上的开放时间来，页面没提到要票或报名。","从南门（背对湖的那一侧）进，右手边上楼，再穿过面前的门进圆顶。","是否照常开放看 Washburn 的 Twitter (X)，一般在开始前约 30 分钟更新。","有问题或想包场：发邮件到 washburn@astro.wisc.edu。圆顶里没有电话。"]},"cost":{"en":["Free public observing."],"zh":["公开观测免费。"]},"tips":{"en":["Sessions depend on the weather, so cloudy nights are likely to be called off. Check the Twitter feed before walking over.","The dome is open to the outside air, so dress warmly for a Wednesday in November.","No food, drinks or flash photography inside.","The telescope is up a flight of stairs and is not wheelchair accessible.","Free public parking after 4:30 p.m. on the street in front and in lot 26; lot 34 if you need more.","Dates from the rule for the rest of 2026: Oct. 21, Nov. 4, Nov. 18, Dec. 2 and Dec. 16.","UW Space Place, the department's outreach center at 2300 S. Park Street, has free guest presentations on the 2nd Tuesday of the month at 7 p.m."],"zh":["看天气，多云的晚上多半取消。走过去之前先看 Twitter。","圆顶是露天通风的，11 月的周三晚上要穿暖和点。","里面不能带食物饮料，不能用闪光灯拍照。","望远镜在楼梯上面，没有轮椅通道。","下午 4:30 之后门前街边和 26 号停车场可免费停车，不够再用 34 号场。","按规则算出的 2026 年剩余日期：10 月 21 日、11 月 4 日、11 月 18 日、12 月 2 日、12 月 16 日。","UW Space Place 是天文系的科普中心，在 2300 S. Park Street，每月第二个周二 19:00 有免费的嘉宾讲座。"],"exp":[null,null,null,null,null,"2026-12-16",null]}},"src":[["UW Astronomy - Washburn Observatory","https://www.astro.wisc.edu/outreach/washburn/"],["UW Space Place - Location & Hours","https://spaceplace.wisc.edu/"]],"unv":["address","phone"],"chk":"2026-10-08","lat":43.076197,"lng":-89.409039,"stops":[["Linden at Henry",131,"28 38 65 80"],["Observatory at Liz Waters",162,"82"],["Linden at N Charter",177,"28 38 65 80 84"]]},{"id":"wisconsin-state-capitol","cat":"fun","n":{"en":"Wisconsin State Capitol","zh":"威斯康星州议会大厦 (State Capitol)"},"kind":{"en":"Landmark and free tours","zh":"地标和免费导览"},"addr":"2 E Main St, Madison, WI 53703","phone":"(608) 266-0382","web":"https://capitoltours.wi.gov/","h":{"Mo":[[480,1080]],"Tu":[[480,1080]],"We":[[480,1080]],"Th":[[480,1080]],"Fr":[[480,1080]],"Sa":[[480,960]],"Su":[[480,960]]},"ht":{"en":"Building: Mon–Fri 8 a.m.–6 p.m., Sat–Sun 8 a.m.–4 p.m.; on state and federal holidays it closes at 4 p.m. Free guided tours start at the Rotunda information desk: Mon–Sat at 9, 10, 11 a.m. and 1, 2, 3 p.m.; Sun at 1, 2, 3 p.m. Observation deck (mid-April to December): Mon–Fri 9 a.m.–5 p.m., Sat 9 a.m.–3:30 p.m., Sun noon–3:30 p.m.","zh":"大楼：周一到周五 8:00–18:00，周六、周日 8:00–16:00；州和联邦假日 16:00 关门。免费导览从大厅 (Rotunda) 服务台出发：周一到周六 9:00、10:00、11:00、13:00、14:00、15:00；周日 13:00、14:00、15:00。观景台（4 月中到 12 月）：周一到周五 9:00–17:00，周六 9:00–15:30，周日 12:00–15:30。"},"sum":{"en":"Madison's domed landmark on the Capitol Square: free tours, a free observation deck in season, and a Supreme Court and legislature to see.","zh":"Capitol Square 上的圆顶地标：免费导览，季节性开放的免费观景台，能看议会和最高法院。"},"kw":["State Capitol","Capitol Square","capitol tour","observation deck","dome","landmark","Madison","州议会大厦","议会大厦","国会大厦","观景台","导览","景点","免费"],"sec":{"about":{"en":["The State Capitol sits in the middle of the Capitol Square, the downtown block at the top of State Street. It is a working building: the Legislature, the Governor's office and the Supreme Court are inside.","It is open to the public all year and has free guided tours. A walk from campus down State Street ends here."],"zh":["州议会大厦在市中心的 Capitol Square 中央，就是 State Street 走到头的地方。这是一栋还在办公的大楼，立法机构、州长办公室和最高法院都在里面。","全年对公众开放，导览免费。从校园沿 State Street 走过来就是这里。"]},"offers":{"en":["Free guided tour of 45–50 minutes covering Capitol history, art, architecture and state government","Tour stops usually include the Rotunda, Assembly Chamber, Senate Chamber, North Hearing Room, Governor's Conference Room and Supreme Court","Outdoor observation deck 92 feet above the ground, with views of the lakes, the UW campus and Monona Terrace","A small museum up by the deck: displays on how the current Capitol was built, and a view of the inner dome from the Rotunda viewing deck","Watching the Assembly or Senate from the public galleries when the Legislature is in session"],"zh":["免费导览，45–50 分钟，讲大厦的历史、艺术、建筑和州政府运作","导览一般会经过大厅 (Rotunda)、众议院厅 (Assembly)、参议院厅 (Senate)、North Hearing Room、州长会议室和最高法院","室外观景台离地 92 英尺，能看到湖、UW 校园和 Monona Terrace","观景台旁有个小博物馆，展示现在这座大厦的建造过程，还能从 Rotunda 观景平台近看内圆顶","议会开会期间可以在旁听席看众议院或参议院开会"]},"howto":{"en":["For fewer than 10 people, just show up at the tour time. Go to the information desk in the Rotunda on the ground floor.","Any of the eight entrances works. Walk toward the center of the building.","Groups of 10 or more must reserve: book online or call (608) 266-0382, Mon–Fri 7:30 a.m.–4:30 p.m.","To reach the observation deck, take an elevator to floor 4, then follow the signs up two more flights of stairs.","Public parking ramps are within one block of the Capitol Square."],"zh":["不到 10 个人不用预约，按导览时间到一楼 Rotunda 的服务台集合就行。","八个入口随便走哪个，往大楼中心走。","10 人及以上团体必须预约：网上订，或周一到周五 7:30–16:30 打 (608) 266-0382。","去观景台：坐电梯到 4 楼，再跟着指示牌上两段楼梯。","一个街区内就有公共停车楼。"]},"cost":{"en":["Guided tours are free.","The official pages list no fee for the observation deck or the museum."],"zh":["导览免费。","官方页面没有写观景台和小博物馆要收费。"]},"tips":{"en":["The observation deck needs about 48 steps and has no ADA access. The deck can close for bad weather or construction, so look at the sky before you go.","The Assembly and Senate are not part of the tour while the Legislature is in session, but you can watch from the galleries. Some rooms can also be closed for official business.","No tours on Easter Sunday, Thanksgiving, Christmas Eve, Christmas Day and New Year's Day. The deck and museum are closed on the same days.","The Rotunda viewing deck, reached by the same stairs as the observation deck, gives a close-up view of the inner dome."],"zh":["去观景台要爬约 48 级台阶，没有无障碍通道。天气不好或施工时可能关，出发前看看天。","议会开会期间导览不进众议院和参议院，但可以在旁听席看；有些房间也会因公务关闭。","复活节周日、感恩节、平安夜、圣诞节、元旦没有导览，观景台和小博物馆同样几天关闭。","Rotunda 观景平台和观景台走同一段楼梯，可以近距离看内圆顶。"],"exp":["2026-12-31",null,null,null]}},"src":[["Wisconsin State Capitol Tour Information","https://capitoltours.wi.gov/"],["Capitol Tours - Tour & Visitor Information","https://doa.wi.gov/Pages/CapitolTours/TourVisit-Info.aspx"],["Capitol Tours - Observation Deck & Museum","https://doa.wi.gov/Pages/CapitolTours/Observation-Deck.aspx"],["Destination Madison - Wisconsin State Capitol","https://www.visitmadison.com/listings/wisconsin-state-capitol/176634/"],["Wisconsin Legislature - Visit the Capitol","https://legis.wisconsin.gov/about/visit"]],"unv":["phone"],"chk":"2026-10-08","lat":43.074692,"lng":-89.384166,"stops":[["W Main at M L K Junior",135,"E R 75"],["Capitol Square",137,"A B F"],["E Mifflin at N Pinckney",154,"E R 75"]]}]};